/** Bust stale canvas preview — today's elapsed resets at local midnight. */
const GMAIL_DUAL_NAV_BUILD = "v717-2026-10-13-android-preview-v1-key";
/** Persisted Android phone-preview toggle (useCanvasState key + localStorage). */
const ANDROID_PREVIEW_LS_KEY = "crmAndroidPreview.v1";
/** Default AppPrimaryRail module + landing view — Home (Clients modules). */
const DEFAULT_PRIMARY_CATEGORY = "client";
/**
 * Landing persistence keys (bumped when stale LS stole first paint).
 * v716 failed: screen.v2 / selectedCategory.v2 / crmHelpFabTab.v1 still
 * hydrated last session (often Chats or Help → Messages) before any coerce.
 */
const SCREEN_STATE_KEY = "screen.v3";
const SELECTED_CATEGORY_STATE_KEY = "selectedCategory.v3";
const HELP_FAB_TAB_STATE_KEY = "crmHelpFabTab.v2";
/** Reopen seed — must match GMAIL_DUAL_NAV_BUILD so each ship re-forces Home. */
const DEFAULT_LANDING_SEED_KEY = "crmDefaultLandingSeed.v2";

/**
 * Systemadmin primary id is exactly "systemadmin" (not Admin / system-admin).
 * Also treat Systemadmin hover-flyout and Systemadmin-only screens as that surface.
 */
const SYSTEMADMIN_HELP_HIDE_SCREENS = new Set([
  "help-feedback",
  "ai-maintenance",
  "api-connections",
  "company-settings",
  "company-docs-folders",
  "template-merge-fields",
  "trello-import",
  "wave-import",
  "users-rights",
  "files-root",
]);

/**
 * Effective primary for Help gating — ignore stale selectedCategory values that
 * are not on this role's rail (rail UI already falls back to Clients, but the
 * raw state can stay "systemadmin" after a role switch and wrongly hide Help).
 */
function effectivePrimaryCategoryForHelp(
  role: Role,
  selectedCategory: string,
  deptIds: string | string[] = [],
): string {
  const allowed = categoryIdsForUser(role, deptIds);
  const cat = normalizePrimaryCategory(selectedCategory);
  return allowed.includes(cat) ? cat : DEFAULT_PRIMARY_CATEGORY;
}

function isSystemadminNavSurface(
  role: Role,
  selectedCategory: string,
  hoverKey?: string | null,
  screen?: string,
  deptIds: string | string[] = [],
): boolean {
  const effectiveCat = effectivePrimaryCategoryForHelp(
    role,
    selectedCategory,
    deptIds,
  );
  if (effectiveCat === "systemadmin") return true;
  const allowed = categoryIdsForUser(role, deptIds);
  if (
    hoverKey != null &&
    normalizePrimaryCategory(hoverKey) === "systemadmin" &&
    allowed.includes("systemadmin")
  ) {
    return true;
  }
  /**
   * Systemadmin-only screens hide Help while open — but not when the effective
   * primary is already a staff module (Clients/Worker/…). That stale-screen
   * case happens after role switch or Clients fallback while screen state still
   * points at help-feedback / ai-maintenance / company-settings.
   */
  if (
    screen &&
    SYSTEMADMIN_HELP_HIDE_SCREENS.has(screen) &&
    effectiveCat === "systemadmin"
  ) {
    return true;
  }
  return false;
}

/**
 * Staff Help ? on AppPrimaryRail. Hidden when:
 * - demo role is System Admin (`role === "systemadmin"` / isSystemAdmin), OR
 * - Systemadmin primary / hover / inbox screens are active (effective rail).
 * Manager (`admin`) and Worker still see Help on Clients and other staff primaries.
 */
function showWorkerHelpFeedbackFab(
  role: Role,
  selectedCategory: string,
  hoverKey?: string | null,
  screen?: string,
  deptIds: string | string[] = [],
): boolean {
  /** Demo System Admin uses Systemadmin → Help & feedback inbox — no rail ?. */
  if (isSystemAdmin(role)) return false;
  const effectiveCat = effectivePrimaryCategoryForHelp(
    role,
    selectedCategory,
    deptIds,
  );
  /** Staff primaries (Clients / Worker / Admin / …) always keep Help. */
  if (effectiveCat !== "systemadmin") {
    const allowed = categoryIdsForUser(role, deptIds);
    if (
      hoverKey != null &&
      normalizePrimaryCategory(hoverKey) === "systemadmin" &&
      allowed.includes("systemadmin")
    ) {
      return false;
    }
    return true;
  }
  return !isSystemadminNavSurface(
    role,
    selectedCategory,
    hoverKey,
    screen,
    deptIds,
  );
}

/**
 * Firm CRM chrome — NO GREY. Use these for every new field / surface.
 * Primary purple rail keeps its own constants (sibling-owned).
 */
const CHROME_WHITE = "#FFFFFF";
const CHROME_PANE_BG = "#F3F9FF";
const CHROME_SOFT_BLUE = "#D9EAF8";
const CHROME_SELECTED_BLUE = "#C5DFF5";
const CHROME_HOVER_CYAN = "#D8F3EF";
const CHROME_BORDER_BLUE = "#8EB8DC";
/**
 * Firm table header — stronger clear blue than washed #C5DFF5 / host greys.
 * Paint on each <th> (sticky thead alone often fails to show color).
 */
const CHROME_TABLE_HEADER = "#B5D4ED";
/** Alternating body row — soft firm blue, never near-grey pane wash. */
const CHROME_TABLE_ZEBRA = CHROME_SOFT_BLUE;
const CHROME_INK = "#152536";
const CHROME_INK_MUTED = "#2F455A";
const CHROME_TABSTRIP_BG = CHROME_WHITE;
/** Default for TextInput / Select / idle pills / secondary buttons. */
const CHROME_FIELD_BG = CHROME_WHITE;
const CHROME_FIELD_BORDER = `1px solid ${CHROME_BORDER_BLUE}`;

/** Default field surface style — merge into TextInput / Select / filters. */
function chromeFieldStyle(extra?: CSSProperties): CSSProperties {
  return {
    background: CHROME_FIELD_BG,
    backgroundColor: CHROME_FIELD_BG,
    color: CHROME_INK,
    border: CHROME_FIELD_BORDER,
    borderRadius: 8,
    ...extra,
  };
}

/** Text — map washed secondary/tertiary tones to dark chrome ink (never grey). */
function ChromeText(props: {
  children?: TextProps["children"];
  tone?: "primary" | "secondary" | "tertiary" | "quaternary";
  size?: "body" | "small";
  weight?: "normal" | "medium" | "semibold" | "bold";
  italic?: boolean;
  as?: "p" | "span";
  truncate?: boolean | "start" | "end";
  style?: CSSProperties;
}) {
  const muted =
    props.tone === "secondary" ||
    props.tone === "tertiary" ||
    props.tone === "quaternary";
  const { tone: _tone, style, ...rest } = props;
  return (
    <Text
      {...rest}
      style={{
        color: muted ? CHROME_INK_MUTED : CHROME_INK,
        ...style,
      }}
    />
  );
}

function ChromeTextInput(props: {
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  type?: "text" | "email" | "password" | "number" | "url" | "search";
  style?: CSSProperties;
}) {
  const { style, ...rest } = props;
  return <TextInput {...rest} style={chromeFieldStyle(style)} />;
}

/**
 * Toggle with brand chrome — SDK Toggle uses a flat grey "off" track.
 * Off = soft blue/purple track; on = accent.
 */
function ChromeToggle(props: {
  checked?: boolean;
  onChange?: (checked: boolean) => void;
  disabled?: boolean;
  size?: "sm" | "md";
}) {
  const theme = useHostTheme();
  const checked = !!props.checked;
  const size = props.size ?? "sm";
  const trackW = size === "md" ? 36 : 28;
  const trackH = size === "md" ? 20 : 16;
  const knob = size === "md" ? 16 : 12;
  const pad = 2;
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      disabled={props.disabled}
      onClick={() => {
        if (props.disabled) return;
        props.onChange?.(!checked);
      }}
      style={{
        position: "relative",
        width: trackW,
        height: trackH,
        flexShrink: 0,
        padding: 0,
        borderRadius: 999,
        border: `1px solid ${
          checked ? theme.accent.primary : CHROME_BORDER_BLUE
        }`,
        background: checked ? theme.accent.primary : CHROME_SOFT_BLUE,
        cursor: props.disabled ? "not-allowed" : "pointer",
        opacity: props.disabled ? 0.5 : 1,
        boxSizing: "border-box",
      }}
    >
      <span
        aria-hidden
        style={{
          position: "absolute",
          top: (trackH - knob) / 2 - 1,
          left: checked ? trackW - knob - pad - 1 : pad,
          width: knob,
          height: knob,
          borderRadius: "50%",
          background: CHROME_WHITE,
          transition: "left 120ms ease",
          boxSizing: "border-box",
        }}
      />
    </button>
  );
}

function ChromeTextArea(props: {
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  rows?: number;
  style?: CSSProperties;
}) {
  const { style, ...rest } = props;
  return <TextArea {...rest} style={chromeFieldStyle(style)} />;
}

/** Firm WhatsApp desk: Enter sends (default ON). Legacy persisted state without the field stays ON. */
function waEnterIsSendEnabled(settings: { enterIsSend?: boolean }): boolean {
  return settings.enterIsSend !== false;
}

/**
 * Per-worker Enter-is-send preference.
 * "default" = follow firm Chats / WhatsApp desk setting; "on" / "off" override it.
 */
type EnterIsSendPref = "default" | "on" | "off";

type ChatComposerPrefsByWorker = Record<string, { enterIsSend: EnterIsSendPref }>;

function normalizeEnterIsSendPref(v: unknown): EnterIsSendPref {
  if (v === "on" || v === "off" || v === "default") return v;
  return "default";
}

function workerEnterIsSendPref(
  prefs: ChatComposerPrefsByWorker | undefined,
  workerId: string | undefined,
): EnterIsSendPref {
  if (!workerId) return "default";
  return normalizeEnterIsSendPref(prefs?.[workerId]?.enterIsSend);
}

/** Effective Enter-is-send: worker override if set, else firm default. */
function effectiveEnterIsSend(
  firmSettings: { enterIsSend?: boolean },
  workerPref: EnterIsSendPref | undefined,
): boolean {
  const pref = normalizeEnterIsSendPref(workerPref);
  if (pref === "on") return true;
  if (pref === "off") return false;
  return waEnterIsSendEnabled(firmSettings);
}

type ChatComposerKeyEvent = {
  key: string;
  shiftKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  preventDefault: () => void;
};

/** Enter-is-send ON: Enter sends, Shift+Enter newline. OFF: Enter newline, Ctrl/Cmd+Enter sends. */
function handleChatComposerKeyDown(
  e: ChatComposerKeyEvent,
  enterIsSend: boolean,
  onSend: () => void,
) {
  if (e.key !== "Enter") return;
  const mod = e.ctrlKey || e.metaKey;
  if (enterIsSend) {
    if (e.shiftKey) return;
    e.preventDefault();
    onSend();
    return;
  }
  if (mod) {
    e.preventDefault();
    onSend();
  }
}

/** Native textarea so Enter / Shift+Enter / Ctrl+Enter work (SDK TextArea has no onKeyDown). */
function ChatComposerTextArea(props: {
  value: string;
  onChange: (value: string) => void;
  onSend: () => void;
  enterIsSend: boolean;
  placeholder?: string;
  disabled?: boolean;
  rows?: number;
  style?: CSSProperties;
}) {
  const rows = props.rows ?? 2;
  return (
    <textarea
      value={props.value}
      disabled={props.disabled}
      placeholder={props.placeholder}
      rows={rows}
      onChange={(e: { target: { value: string } }) =>
        props.onChange(e.target.value)
      }
      onKeyDown={(e: ChatComposerKeyEvent) =>
        handleChatComposerKeyDown(e, props.enterIsSend, props.onSend)
      }
      style={chromeFieldStyle({
        width: "100%",
        flex: 1,
        minWidth: 0,
        resize: "vertical",
        minHeight: 36,
        padding: "8px 10px",
        font: "inherit",
        lineHeight: 1.35,
        boxSizing: "border-box",
        outline: "none",
        ...props.style,
      })}
    />
  );
}

/** Pill — never SDK grey fill; soft blue when active, white when idle. */
/** Semantic pill fills — chrome navy/soft colors, never grey. */
function pillToneColors(tone?: string): {
  color: string;
  background: string;
  border: string;
} {
  switch ((tone || "neutral").toLowerCase()) {
    case "success":
      return {
        color: "#1F7A4D",
        background: "#E4F6EC",
        border: "1px solid #7BC49A",
      };
    case "warning":
      return {
        color: "#8A6410",
        background: "#FFF4D6",
        border: "1px solid #E0B84A",
      };
    case "danger":
      return {
        color: "#A33B4A",
        background: "#FCE8EC",
        border: "1px solid #E08A96",
      };
    case "info":
      return {
        color: "#1F4F7A",
        background: "#D9EAF8",
        border: "1px solid #8EB8DC",
      };
    case "neutral":
    default:
      return {
        color: CHROME_INK,
        background: CHROME_WHITE,
        border: CHROME_FIELD_BORDER,
      };
  }
}

function Pill(props: {
  children?: unknown;
  active?: boolean;
  size?: "sm" | "md";
  tone?: string;
  style?: CSSProperties;
  onClick?: () => void;
  title?: string;
  disabled?: boolean;
}) {
  const { children, active, style, onClick, title, disabled } = props;
  const label =
    children == null || children === false || children === true
      ? ""
      : Array.isArray(children)
        ? children.map((c) => String(c)).join("")
        : String(children);
  const tones = pillToneColors(props.tone);
  return (
    <span
      title={title}
      onClick={disabled ? undefined : onClick}
      style={{
        display: "inline-flex",
        alignItems: "center",
        padding: props.size === "sm" ? "2px 8px" : "4px 12px",
        borderRadius: 999,
        fontSize: props.size === "sm" ? 11 : 12,
        fontWeight: 600,
        lineHeight: "18px",
        color: tones.color,
        background: active ? CHROME_SOFT_BLUE : tones.background,
        border: active ? CHROME_FIELD_BORDER : tones.border,
        boxSizing: "border-box",
        whiteSpace: "nowrap",
        cursor: onClick && !disabled ? "pointer" : undefined,
        opacity: disabled ? 0.5 : 1,
        ...style,
      }}
    >
      {label}
    </span>
  );
}

/**
 * Stage chevron tip depth (%) for Audit/Tax/monthly ChevronBarSegment rows.
 * Arrow-in notch + arrow-out tip use this exact value.
 * 16 = Audit stage ribbon angle (prior soft-9 was silently clamped to 16–24).
 */
const CHEVRON_TIP_PCT = 16;

/**
 * OverallProgressBar fill tip only — barely a hint of notch/tip (not needle-sharp).
 * Stage bars keep CHEVRON_TIP_PCT (~16). Width inflate ≈ 100/(100−tip) → ~102.6%.
 */
const OVERALL_CHEVRON_TIP_PCT = 2.5;

/** How far from tip/notch apex to start the quadratic round (0=sharp, 1=flat). */
const OVERALL_CHEVRON_ROUND = 0.42;

/**
 * Stage ChevronBarSegment outer height + inset pad.
 * Visible fill = 12 − 1.5×2 ≈ 9px (matches selected “Monthly reporting” strip).
 * All stage slots share this — active never grows taller.
 */
const STAGE_CHEVRON_BAR_HEIGHT = 12;
const STAGE_CHEVRON_BAR_PAD = 1.5;

/**
 * Leave-delay so pointer can bridge primary rail → hover flyout without collapsing.
 * Matched to Sumit-style clip: short enough to feel instant, long enough to cross the gap.
 */
const SECONDARY_HOVER_LEAVE_MS = 160;

/** Compact ephemeral flyout width (Sumit clip: floating panel beside rail). */
const TEMP_TAB_FLYOUT_WIDTH = 228;
/** Max flyout height before inner scroll (viewport clamp may be tighter). */
const TEMP_TAB_FLYOUT_MAX_HEIGHT = 420;

const MOBILE_BREAKPOINT = 720;

/**
 * Cursor-style app chrome: viewport-bound shell, fixed side rails,
 * independently scrolling main panes (never grow the whole page).
 */
const SHELL_FILL = {
  flex: 1,
  minHeight: 0,
  height: "100%" as const,
  overflow: "hidden" as const,
  boxSizing: "border-box" as const,
};

const SHELL_SCROLL = {
  flex: 1,
  minWidth: 0,
  minHeight: 0,
  overflowY: "auto" as const,
  WebkitOverflowScrolling: "touch" as const,
  boxSizing: "border-box" as const,
};

const SHELL_SPLIT = {
  flex: 1,
  minHeight: 0,
  width: "100%" as const,
  overflow: "hidden" as const,
  alignItems: "stretch" as const,
};

/** Fixed side rail: viewport-bound; scrolls only when its own content overflows. */
const SHELL_RAIL = {
  flexShrink: 0,
  alignSelf: "stretch" as const,
  minHeight: 0,
  maxHeight: "100%" as const,
  overflowY: "auto" as const,
  overflowX: "hidden" as const,
  WebkitOverflowScrolling: "touch" as const,
  boxSizing: "border-box" as const,
};

/** Canvas SDK has no viewport hook — track width with resize listener. */
function useIsMobile(breakpoint = MOBILE_BREAKPOINT): boolean {
  const [isMobile, setIsMobile] = useState(() => {
    if (typeof window === "undefined") return false;
    return window.innerWidth < breakpoint;
  });
  useEffect(() => {
    if (typeof window === "undefined") return;
    const onResize = () => setIsMobile(window.innerWidth < breakpoint);
    onResize();
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [breakpoint]);
  return isMobile;
}

/**
 * Fixed-position frame for a trigger: viewport, or a transform/filter
 * ancestor that becomes the containing block for `position:fixed`.
 * Coords from getBoundingClientRect must be subtracted by origin*.
 */
function fixedPositionFrame(fromEl: Element): {
  originTop: number;
  originLeft: number;
  width: number;
  height: number;
} {
  if (typeof window === "undefined") {
    return { originTop: 0, originLeft: 0, width: 0, height: 0 };
  }
  let node: HTMLElement | null = fromEl.parentElement;
  while (node && node !== document.documentElement) {
    const cs = getComputedStyle(node);
    const filter = cs.filter;
    const createsFixedCb =
      (cs.transform && cs.transform !== "none") ||
      (cs.perspective && cs.perspective !== "none") ||
      (filter != null && filter !== "none" && filter !== "") ||
      (cs.backdropFilter != null &&
        cs.backdropFilter !== "none" &&
        cs.backdropFilter !== "") ||
      (cs.contain != null &&
        /\b(paint|layout|strict|content)\b/.test(cs.contain)) ||
      cs.willChange
        .split(",")
        .some((w) =>
          ["transform", "perspective", "filter"].includes(w.trim()),
        );
    if (createsFixedCb) {
      const r = node.getBoundingClientRect();
      return {
        originTop: r.top,
        originLeft: r.left,
        width: r.width,
        height: r.height,
      };
    }
    node = node.parentElement;
  }
  return {
    originTop: 0,
    originLeft: 0,
    width: window.innerWidth,
    height: window.innerHeight,
  };
}

/** Only one custom Select listbox open at a time (chevron + menu stay in sync). */
let activeSelectToken: object | null = null;
let activeSelectClose: (() => void) | null = null;

function claimSelectOpen(token: object, close: () => void) {
  if (activeSelectToken && activeSelectToken !== token && activeSelectClose) {
    activeSelectClose();
  }
  activeSelectToken = token;
  activeSelectClose = close;
}

function releaseSelectOpen(token: object) {
  if (activeSelectToken === token) {
    activeSelectToken = null;
    activeSelectClose = null;
  }
}

type SelectMenuBox = {
  /** When openUp, use CSS `bottom` so short menus hug the trigger. */
  openUp: boolean;
  top: number;
  bottom: number;
  left: number;
  minWidth: number;
  maxWidth: number;
  maxHeight: number;
};

/**
 * Global Select: keeps the selected label + chevron as a tight inline-start
 * group. The SDK native `<select>` stretches in Grid/Stack and parks the
 * OS chevron at the far trailing edge (~400px gap). Callers may still pass
 * `width` / `maxWidth`; justify-content stays flex-start so the chevron never
 * floats to the opposite edge.
 *
 * Open list is a viewport popover via position:fixed (getBoundingClientRect).
 * Do NOT reparent onto document.body — moving React-owned nodes causes
 * removeChild crashes when the canvas host reconciles. Repositions on
 * capture-phase scroll + resize; click-outside checks trigger + menu.
 * Opens above the trigger with CSS `bottom` when near the viewport edge
 * (never `top = rect.top - maxHeight`, which parked short menus far away).
 */
function Select({
  value,
  onChange,
  options,
  placeholder,
  disabled,
  style,
}: SelectProps) {
  const theme = useHostTheme();
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const menuRef = useRef<HTMLDivElement | null>(null);
  const selectTokenRef = useRef<object>({});
  /** Blocks capture-phase outside-close from racing a just-picked option. */
  const pickingRef = useRef(false);
  const [menuBox, setMenuBox] = useState<SelectMenuBox | null>(null);

  const closeMenu = () => {
    setOpen(false);
    setMenuBox(null);
    releaseSelectOpen(selectTokenRef.current);
  };

  const computeMenuBox = (): SelectMenuBox | null => {
    const trigger = triggerRef.current ?? rootRef.current;
    if (!trigger || typeof window === "undefined") return null;
    const rect = trigger.getBoundingClientRect();
    const frame = fixedPositionFrame(trigger);
    const gap = 4;
    const pad = 8;
    const maxMenuH = 240;
    const maxMenuW = 360;
    const spaceBelow =
      frame.originTop + frame.height - rect.bottom - gap - pad;
    const spaceAbove = rect.top - frame.originTop - gap - pad;
    const openUp =
      spaceBelow < Math.min(maxMenuH, 120) && spaceAbove > spaceBelow;
    const maxHeight = Math.max(
      96,
      Math.min(maxMenuH, openUp ? spaceAbove : spaceBelow),
    );
    const minWidth = Math.max(rect.width, 112);
    const rawLeft = rect.left - frame.originLeft;
    const left = Math.min(
      Math.max(pad, rawLeft),
      Math.max(pad, frame.width - minWidth - pad),
    );
    const maxWidth = Math.min(
      maxMenuW,
      Math.max(minWidth, frame.width - left - pad),
    );
    if (openUp) {
      return {
        openUp: true,
        top: 0,
        bottom: frame.originTop + frame.height - rect.top + gap,
        left,
        minWidth,
        maxWidth,
        maxHeight,
      };
    }
    return {
      openUp: false,
      top: rect.bottom - frame.originTop + gap,
      bottom: 0,
      left,
      minWidth,
      maxWidth,
      maxHeight,
    };
  };

  useEffect(() => {
    if (!open) {
      setMenuBox(null);
      releaseSelectOpen(selectTokenRef.current);
      return;
    }
    claimSelectOpen(selectTokenRef.current, closeMenu);
    const place = () => {
      const next = computeMenuBox();
      if (next) setMenuBox(next);
    };
    place();
    window.addEventListener("resize", place);
    // Capture: nested SHELL_SCROLL panes scroll without bubbling to window.
    window.addEventListener("scroll", place, true);
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
      releaseSelectOpen(selectTokenRef.current);
    };
  }, [open, options.length]);

  useEffect(() => {
    if (!open) return;
    const onDocDown = (event: Event) => {
      // Option pick sets pickingRef so a late outside-close cannot win the race.
      if (pickingRef.current) return;
      const root = rootRef.current;
      const menu = menuRef.current;
      const target = event.target;
      if (!(target instanceof Node)) return;
      if (root?.contains(target) || menu?.contains(target)) return;
      closeMenu();
    };
    // Bubble only — capture-phase outside-close can unmount the menu before
    // the option's activate handler runs (Actions value="" menus looked dead).
    document.addEventListener("mousedown", onDocDown);
    document.addEventListener("touchstart", onDocDown);
    return () => {
      document.removeEventListener("mousedown", onDocDown);
      document.removeEventListener("touchstart", onDocDown);
    };
  }, [open]);

  const selected = options.find((opt) => opt.value === value);
  const label = selected?.label ?? placeholder ?? "";

  // Layout stays on the root; paint (bg/color/border/…) must hit the trigger
  // button — spreading style only on the wrapper left Actions looking pale.
  const {
    width: rootWidth,
    minWidth: rootMinWidth,
    maxWidth: rootMaxWidth,
    flex: rootFlex,
    flexGrow: rootFlexGrow,
    flexShrink: rootFlexShrink,
    flexBasis: rootFlexBasis,
    alignSelf: rootAlignSelf,
    margin: rootMargin,
    marginTop: rootMarginTop,
    marginRight: rootMarginRight,
    marginBottom: rootMarginBottom,
    marginLeft: rootMarginLeft,
    marginInline: rootMarginInline,
    marginBlock: rootMarginBlock,
    ...triggerStyle
  } = style ?? {};
  const triggerColor =
    typeof triggerStyle.color === "string" ? triggerStyle.color : undefined;
  const triggerWeight = triggerStyle.fontWeight;

  const pickOption = (nextValue: string) => {
    pickingRef.current = true;
    try {
      onChange?.(nextValue);
    } finally {
      closeMenu();
      if (typeof queueMicrotask === "function") {
        queueMicrotask(() => {
          pickingRef.current = false;
        });
      } else {
        window.setTimeout(() => {
          pickingRef.current = false;
        }, 0);
      }
    }
  };

  return (
    <div
      ref={rootRef}
      style={{
        position: "relative",
        display: "inline-block",
        width: rootWidth ?? "fit-content",
        minWidth: rootMinWidth,
        maxWidth: rootMaxWidth ?? "100%",
        flex: rootFlex,
        flexGrow: rootFlexGrow,
        flexShrink: rootFlexShrink,
        flexBasis: rootFlexBasis,
        alignSelf: rootAlignSelf ?? "flex-start",
        margin: rootMargin,
        marginTop: rootMarginTop,
        marginRight: rootMarginRight,
        marginBottom: rootMarginBottom,
        marginLeft: rootMarginLeft,
        marginInline: rootMarginInline,
        marginBlock: rootMarginBlock,
        verticalAlign: "top",
        boxSizing: "border-box",
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={() => {
          if (disabled) return;
          if (open) {
            closeMenu();
            return;
          }
          const next = computeMenuBox();
          if (next) setMenuBox(next);
          claimSelectOpen(selectTokenRef.current, closeMenu);
          setOpen(true);
        }}
        style={{
          all: "unset",
          boxSizing: "border-box",
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "flex-start",
          gap: 6,
          width: "100%",
          maxWidth: "100%",
          padding: "6px 10px",
          borderRadius: 8,
          border: `1px solid ${CHROME_BORDER_BLUE}`,
          background: CHROME_WHITE,
          color: theme.text.primary,
          cursor: disabled ? "not-allowed" : "pointer",
          opacity: disabled ? 0.55 : 1,
          fontSize: 13,
          lineHeight: 1.35,
          ...triggerStyle,
        }}
      >
        <span
          style={{
            flex: 1,
            minWidth: 0,
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
            textAlign: "start",
            fontWeight: triggerWeight,
          }}
        >
          {label}
        </span>
        <span
          aria-hidden
          style={{
            flexShrink: 0,
            display: "inline-block",
            marginInlineStart: "auto",
            fontSize: 9,
            lineHeight: 1,
            fontWeight: triggerWeight,
            color: triggerColor ?? CHROME_INK_MUTED,
            transform: open ? "rotate(180deg)" : undefined,
          }}
        >
          ▼
        </span>
      </button>
      {open && menuBox ? (
        <div
          ref={menuRef}
          role="listbox"
          style={{
            position: "fixed",
            zIndex: 10000,
            top: menuBox.openUp ? undefined : menuBox.top,
            bottom: menuBox.openUp ? menuBox.bottom : undefined,
            left: menuBox.left,
            minWidth: menuBox.minWidth,
            width: "max-content",
            maxWidth: menuBox.maxWidth,
            maxHeight: menuBox.maxHeight,
            overflowY: "auto",
            borderRadius: 8,
            border: `1px solid ${CHROME_BORDER_BLUE}`,
            background: CHROME_WHITE,
            boxSizing: "border-box",
          }}
        >
          {options.map((opt) => {
            const active = opt.value === value;
            const activate = (event: {
              preventDefault(): void;
              stopPropagation(): void;
            }) => {
              event.preventDefault();
              event.stopPropagation();
              if (opt.disabled) return;
              // Dedupe pointerdown + mousedown + click on the same gesture.
              if (pickingRef.current) return;
              pickOption(opt.value);
            };
            return (
              <button
                key={opt.value}
                type="button"
                role="option"
                aria-selected={active}
                disabled={opt.disabled}
                onPointerDown={activate}
                onMouseDown={activate}
                onClick={activate}
                style={{
                  all: "unset",
                  boxSizing: "border-box",
                  display: "block",
                  width: "100%",
                  padding: "7px 10px",
                  cursor: opt.disabled ? "not-allowed" : "pointer",
                  opacity: opt.disabled ? 0.5 : 1,
                  background: active ? chromeSoftFill(theme) : "transparent",
                  color: theme.text.primary,
                  fontSize: 13,
                  whiteSpace: "nowrap",
                }}
              >
                {opt.label}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

/** Framed tables already scroll; force a min width on phone so columns stay readable. */
function ScrollTable(
  props: Pick<TableProps, "headers" | "rows" | "striped" | "emptyMessage"> & {
    minWidth?: number;
    /** Per-column min widths (px), aligned with headers. */
    columnMinWidths?: Array<number | undefined>;
  },
) {
  const isMobile = useIsMobile();
  const minWidth = props.minWidth ?? (isMobile ? 560 : undefined);
  /**
   * Viewport-bound scrollport: flex:1 + minHeight:0 fills the pane below
   * header/search so H+V scrollbars sit at the visible panel edge (RTL-safe),
   * not after the full table content height. FirmDataTable overflow is visible
   * here so sticky headers stick to this scroll ancestor.
   */
  return (
    <div
      style={{
        width: "100%",
        flex: 1,
        minWidth: 0,
        minHeight: 0,
        overflow: "auto",
        WebkitOverflowScrolling: "touch",
      }}
    >
      <div style={minWidth ? { minWidth } : undefined}>
        <FirmDataTable
          headers={props.headers}
          rows={props.rows}
          emptyMessage={props.emptyMessage}
          columnMinWidths={props.columnMinWidths}
          overflow="visible"
        />
      </div>
    </div>
  );
}

type Role = "worker" | "admin" | "systemadmin";

/** Logged-in staff is a Worker (own time/files only). */
function isWorker(role: Role): boolean {
  return role === "worker";
}
/** Manager / Admin role only (not System Admin). */
function isManager(role: Role): boolean {
  return role === "admin";
}
/** System Admin role. */
function isSystemAdmin(role: Role): boolean {
  return role === "systemadmin";
}
/**
 * Manager OR System Admin — use for all managerial features
 * (team time, approvals, billing ops, worker files for others, Admin Modules).
 * System Admin always passes; never gate Manager-only UI away from System Admin.
 */
function isAdminLike(role: Role): boolean {
  return role === "admin" || role === "systemadmin";
}
/** Alias — Manager or above (includes System Admin). */
function isManagerOrAbove(role: Role): boolean {
  return isAdminLike(role);
}

