/** One child from Excel Name/DOB/ID Child 1…11 — repeatable, not fixed columns. */
type ClientChild = {
  id: string;
  name: string;
  dob: string;
  idNumber: string;
};

/**
 * Excel “2nd ID Number” is ambiguous — never treat as an unlabeled blob.
 * spouse = wife/spouse ID (link spouseName / spouseId);
 * passport = foreign passport; other = unclassified secondary.
 */
type SecondIdKind = "spouse" | "passport" | "other" | "";

/** Excel DOB sheet had Child 1…11; CRM uses the same cap. */
const MAX_CLIENT_CHILDREN = 11;

function createClientChild(): ClientChild {
  return {
    id: `child-${Date.now()}-${Math.floor(Math.random() * 1e6)}`,
    name: "",
    dob: "",
    idNumber: "",
  };
}

function normalizeChildrenForSave(children: ClientChild[]): ClientChild[] | undefined {
  const cleaned = children
    .map((c) => ({
      id: c.id,
      name: c.name.trim(),
      dob: c.dob.trim(),
      idNumber: c.idNumber.trim(),
    }))
    .filter((c) => c.name || c.dob || c.idNumber);
  return cleaned.length > 0 ? cleaned : undefined;
}

/** Whether Additional / family shows spouse + children (not pure Company). */
function showsFamilySpouseFields(type: EngagementType | ""): boolean {
  return (
    type === "individuals" ||
    type === "osek" ||
    type === "bookkeeping" ||
    !type
  );
}

/**
 * Billing “Date Of Birth” tab fields (DOB, spouse DOB, aliyah, status, death dates,
 * children) — person-oriented types only; hidden for pure Company.
 */
function showsDobAdditionalFields(type: EngagementType | ""): boolean {
  return showsFamilySpouseFields(type);
}

/** Whether Additional details shows the Add child UI (Excel DOB / family sheets). */
function showsChildrenFields(type: EngagementType | ""): boolean {
  return showsDobAdditionalFields(type);
}

/** Map client kind → engagement type for Overview field gating. */
function engagementTypeFromClientKind(
  kind: string | undefined,
): EngagementType | "" {
  if (
    kind === "company" ||
    kind === "bookkeeping" ||
    kind === "osek" ||
    kind === "individuals"
  ) {
    return kind;
  }
  return "";
}

/** Title / first / family EN+HE for people; company / trust use legal name EN/HE. */
function showsPersonNameParts(type: EngagementType | ""): boolean {
  return type !== "company" && type !== "trust";
}

