/** Engagement type for New client / Convert (maps to ClientFilter). */
type EngagementType =
  | "company"
  | "bookkeeping"
  | "trust"
  | "osek"
  | "individuals";
type NewClientFormMode = "new" | "convert" | "prospect" | "edit";
type InvoiceSchedule = "monthly" | "quarterly" | "biannual" | "one-off";
/** Per fee-line cadence (extends invoice schedules with yearly). */
type FeeLineFrequency =
  | "monthly"
  | "quarterly"
  | "biannual"
  | "yearly"
  | "one-off"
  | "when_necessary"
  | "with_service"
  | "no_pay"
  | "other";
/**
 * How `amountIls` should be read:
 * - period: amount is already the charge for one period (e.g. ₪1,000/month)
 * - annual_total: amount is the full-year total; period = total ÷ periods/year
 */
type FeeAmountBasis = "period" | "annual_total";
/** One categorized agreed-fee row on a client profile. */
type ClientFeeLine = {
  id: string;
  /** Firm service / category label (EN catalog key, e.g. "Bookkeeping"). */
  service: string;
  amountIls: string;
  frequency: FeeLineFrequency;
  /** Defaults to period when omitted (legacy rows). */
  amountBasis?: FeeAmountBasis;
  /** Defaults to included when omitted (legacy rows). */
  vatMode?: "included" | "excluded";
  /**
   * When frequency is `with_service`, host service(s) this fee is billed with.
   * Prefer `chargedWithServices`; `chargedWithService` kept for legacy single value.
   */
  chargedWithService?: string;
  chargedWithServices?: string[];
  /** When frequency is `other`, the custom cadence label (also saved to firm options). */
  frequencyOtherLabel?: string;
};
type PreferredLang = "he" | "en";

/** Firm catalog EN key for capital/assets declaration (הצהרת הון). */
const SERVICE_DECLARATION_OF_ASSETS = "Declaration of assets";

/**
 * Demo deep link for רשות המיסים (Tax Authority) after Convert / stage 3.
 * Prefer the URL on the `tax-authority` prospect stage when configured.
 */
const RESHUT_HAMISIM_OPEN_FILE_URL =
  "https://www.gov.il/he/departments/israel_tax_authority";

/** Demo-only fee-terms phrase map (not a real translator). */
const FEE_TERMS_DEMO_PHRASES: Array<{ en: string; he: string }> = [
  { en: "Net 30", he: "שוטף + 30" },
  { en: "net 30", he: "שוטף + 30" },
  { en: "standing order", he: "הוראת קבע" },
  { en: "Standing order", he: "הוראת קבע" },
  { en: "bank transfer", he: "העברה בנקאית" },
  { en: "Bank transfer", he: "העברה בנקאית" },
  { en: "monthly retainer", he: "ריטיינר חודשי" },
  { en: "Monthly retainer", he: "ריטיינר חודשי" },
  { en: "upon invoice", he: "עם קבלת חשבונית" },
  { en: "Upon invoice", he: "עם קבלת חשבונית" },
  { en: "VAT included", he: "כולל מע״מ" },
  { en: "VAT excluded", he: "לא כולל מע״מ" },
];

function looksMostlyHebrew(text: string): boolean {
  const he = (text.match(/[\u0590-\u05FF]/g) ?? []).join("").length;
  const la = (text.match(/[A-Za-z]/g) ?? []).join("").length;
  return he > la;
}

/** Canvas demo translation — phrase dictionary + honest preview fallback. */
function demoTranslateFeeTerms(text: string, from: PreferredLang): string {
  const trimmed = text.trim();
  if (!trimmed) return "";
  let out = trimmed;
  if (from === "en") {
    for (const phrase of FEE_TERMS_DEMO_PHRASES) {
      out = out.split(phrase.en).join(phrase.he);
    }
    if (out === trimmed) return `[HE · preview] ${trimmed}`;
    return out;
  }
  for (const phrase of FEE_TERMS_DEMO_PHRASES) {
    out = out.split(phrase.he).join(phrase.en);
  }
  if (out === trimmed) return `[EN · preview] ${trimmed}`;
  return out;
}

function inferFeeTermsLang(
  text: string,
  preferred: PreferredLang | "",
): PreferredLang {
  if (text.trim()) {
    return looksMostlyHebrew(text) ? "he" : "en";
  }
  return preferred === "en" ? "en" : "he";
}
/** Staff CRM chrome language (distinct from client preferredLang). */
type UiLang = "en" | "he";

/** Shell / track writing direction. Prefer this over `row-reverse` (shell is already RTL). */
function uiDir(lang: UiLang): "rtl" | "ltr" {
  return lang === "he" ? "rtl" : "ltr";
}

/** Sequence / stage flow arrow: EN → , HE ← (right-to-left). */
function flowArrow(lang: UiLang): "→" | "←" {
  return lang === "he" ? "←" : "→";
}

/** Nav back chevron: points toward previous side (HE → , EN ← ). */
function navBackArrow(lang: UiLang): "→" | "←" {
  return lang === "he" ? "→" : "←";
}
