type CrmUiKey = keyof typeof CRM_UI;

function t(lang: UiLang, key: CrmUiKey): string {
  return CRM_UI[key][lang];
}

/** Deduplicate search suggestion strings (case-insensitive). */
function uniqSearchCandidates(
  items: Array<string | undefined | null>,
): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of items) {
    const s = (raw ?? "").trim();
    if (!s) continue;
    const key = s.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(s);
  }
  return out;
}

/**
 * Rank completions for Tab-to-complete search: prefix matches first, then
 * substring matches. Shortest (most specific) wins within each group.
 */
function rankSearchCompletions(query: string, candidates: string[]): string[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const starts: string[] = [];
  const includes: string[] = [];
  for (const c of candidates) {
    const lower = c.toLowerCase();
    if (lower === q) continue;
    if (lower.startsWith(q)) starts.push(c);
    else if (lower.includes(q)) includes.push(c);
  }
  const byLen = (a: string, b: string) =>
    a.length - b.length ||
    a.localeCompare(b, undefined, { sensitivity: "base" });
  return [...starts.sort(byLen), ...includes.sort(byLen)].slice(0, 8);
}

/** Inline gray suffix only when the top match continues what was typed. */
function prefixGhostSuffix(
  query: string,
  completion: string | undefined,
): string {
  if (!completion || !query) return "";
  if (!completion.toLowerCase().startsWith(query.toLowerCase())) return "";
  return completion.slice(query.length);
}

type SearchAutocompleteProps = {
  value: string;
  onChange: (value: string) => void;
  /** Entity labels matched for ghost + dropdown (invoice #, names, etc.). */
  candidates: string[];
  placeholder?: string;
  style?: CSSProperties;
  lang?: UiLang;
  /** Optional side-effect when Tab / click accepts a suggestion. */
  onAccept?: (accepted: string) => void;
};

/**
 * Email-style search autocomplete: gray ghost suffix + optional match list.
 * Tab accepts the top suggestion; Escape dismisses; ignore = keep typing.
 * Uses a native input because canvas TextInput has no keyboard handlers.
 */
function SearchAutocomplete({
  value,
  onChange,
  candidates,
  placeholder,
  style,
  lang,
  onAccept,
}: SearchAutocompleteProps) {
  const theme = useHostTheme();
  const [uiLangPersist] = useCanvasState<UiLang>("crmUiLang", "en");
  const uiLang = lang ?? uiLangPersist;
  const [focused, setFocused] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  const [highlight, setHighlight] = useState(0);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const listboxId = `crm-search-suggest-${Math.abs(
    (placeholder ?? "search").length + candidates.length * 17,
  )}`;

  useEffect(() => {
    setDismissed(false);
    setHighlight(0);
  }, [value]);

  const matches = rankSearchCompletions(value, candidates);
  const showPanel =
    focused && !dismissed && value.trim().length > 0 && matches.length > 0;
  const topMatch = matches[0];
  const ghost =
    !dismissed && value.length > 0 ? prefixGhostSuffix(value, topMatch) : "";
  const safeHighlight = Math.min(
    highlight,
    Math.max(0, matches.length - 1),
  );

  const accept = (text: string) => {
    onChange(text);
    onAccept?.(text);
    setDismissed(true);
  };

  const onKeyDown = (e: {
    key: string;
    shiftKey: boolean;
    preventDefault: () => void;
  }) => {
    if (e.key === "Escape" && (ghost || matches.length > 0) && !dismissed) {
      e.preventDefault();
      setDismissed(true);
      return;
    }
    if (
      e.key === "Tab" &&
      !e.shiftKey &&
      !dismissed &&
      topMatch &&
      value.trim().toLowerCase() !== topMatch.toLowerCase()
    ) {
      e.preventDefault();
      accept(topMatch);
      return;
    }
    if (!showPanel) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setHighlight((i) => Math.min(i + 1, matches.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlight((i) => Math.max(i - 1, 0));
    }
  };

  const inputFont = {
    fontSize: 13,
    fontFamily: "inherit" as const,
    letterSpacing: "inherit" as const,
  };

  return (
    <div ref={rootRef} style={{ position: "relative", ...style }}>
      <div
        style={{
          position: "relative",
          height: 28,
          borderRadius: 6,
          border: `1px solid ${
            focused ? theme.accent.control : CHROME_BORDER_BLUE
          }`,
          background: CHROME_WHITE,
          boxSizing: "border-box",
          overflow: "hidden",
        }}
      >
        <div
          aria-hidden
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            padding: "0 10px",
            pointerEvents: "none",
            whiteSpace: "pre",
            overflow: "hidden",
            ...inputFont,
            color: theme.text.primary,
          }}
        >
          <span style={{ visibility: "hidden" }}>{value}</span>
          {ghost ? (
            <span style={{ color: CHROME_INK_MUTED }}>{ghost}</span>
          ) : null}
        </div>
        <input
          type="search"
          value={value}
          placeholder={placeholder}
          autoComplete="off"
          spellCheck={false}
          aria-autocomplete="list"
          aria-expanded={showPanel}
          aria-controls={showPanel ? listboxId : undefined}
          onChange={(e: { target: { value: string } }) =>
            onChange(e.target.value)
          }
          onKeyDown={onKeyDown}
          onFocus={() => setFocused(true)}
          onBlur={() => {
            // Delay so suggestion clicks register before panel unmounts.
            window.setTimeout(() => setFocused(false), 120);
          }}
          style={{
            position: "relative",
            zIndex: 1,
            width: "100%",
            height: "100%",
            margin: 0,
            padding: "0 10px",
            border: "none",
            outline: "none",
            background: "transparent",
            color: theme.text.primary,
            boxSizing: "border-box",
            ...inputFont,
          }}
        />
      </div>
      {ghost && focused && !dismissed ? (
        <ChromeText size="small" tone="tertiary" style={{ marginTop: 4 }}>
          {t(uiLang, "searchTabCompleteHint")}
          {" · "}
          {t(uiLang, "searchTabDismissHint")}
        </ChromeText>
      ) : null}
      {showPanel ? (
        <div
          id={listboxId}
          role="listbox"
          style={{
            position: "absolute",
            zIndex: 20,
            top: "100%",
            left: 0,
            right: 0,
            marginTop: 4,
            maxHeight: 200,
            overflowY: "auto",
            borderRadius: 8,
            border: `1px solid ${CHROME_BORDER_BLUE}`,
            background: CHROME_WHITE,
            boxSizing: "border-box",
          }}
        >
          {matches.map((m, i) => {
            const active = i === safeHighlight;
            return (
              <button
                key={`${m}-${i}`}
                type="button"
                role="option"
                aria-selected={active}
                onMouseDown={(ev: { preventDefault: () => void }) => {
                  ev.preventDefault();
                  accept(m);
                }}
                style={{
                  all: "unset",
                  boxSizing: "border-box",
                  cursor: "pointer",
                  display: "block",
                  width: "100%",
                  padding: "7px 10px",
                  background: active ? chromeSelectedFill(theme) : "transparent",
                  color: theme.text.primary,
                  fontSize: 13,
                }}
              >
                {m}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

/** Option for CRM-wide client pickers — searchText should include EN + HE names. */
type ClientPickerOption = {
  value: string;
  label: string;
  searchText: string;
};

function clientSearchBlob(parts: Array<string | undefined | null>): string {
  return parts
    .map((p) => (p ?? "").trim())
    .filter(Boolean)
    .join(" ");
}

function matchesClientPickerQuery(searchText: string, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  const hay = searchText.toLowerCase();
  return q.split(/\s+/).every((token) => token.length > 0 && hay.includes(token));
}

function clientPickerOptionFromRow(
  row: {
    id: string;
    name: string;
    nameHe?: string;
    email?: string;
    identity?: string;
    phone?: string;
  },
  lang: UiLang,
  groupPrefix?: string,
): ClientPickerOption {
  const label = groupPrefix
    ? `${groupPrefix} · ${displayClientName(row, lang)}`
    : displayClientName(row, lang);
  return {
    value: row.id,
    label,
    searchText: clientSearchBlob([
      groupPrefix,
      row.name,
      row.nameHe,
      row.email,
      row.identity,
      row.phone,
      label,
    ]),
  };
}

const CLIENT_PICKER_RESULT_CAP = 40;

/**
 * Type-to-find client control for large lists (EN + HE names, email, ID, phone).
 * Replaces plain Select wherever a client must be chosen from hundreds/thousands.
 */
function ClientSearchSelect({
  value,
  onChange,
  options,
  placeholder,
  style,
}: {
  value: string;
  onChange: (value: string) => void;
  options: ClientPickerOption[];
  placeholder?: string;
  style?: CSSProperties;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const accent = theme.accent.primary;
  const selected = options.find((o) => o.value === value);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const rootRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!open) setQuery("");
  }, [open, value]);

  const filtered = options.filter((o) =>
    matchesClientPickerQuery(o.searchText, query),
  );
  const shown = filtered.slice(0, CLIENT_PICKER_RESULT_CAP);
  const ph = placeholder ?? t(uiLang, "clientSearchPlaceholder");

  const pick = (id: string) => {
    onChange(id);
    setOpen(false);
    setQuery("");
  };

  return (
    <div ref={rootRef} style={{ position: "relative", width: "100%", ...style }}>
      {!open ? (
        <button
          type="button"
          onClick={() => setOpen(true)}
          aria-haspopup="listbox"
          aria-expanded={false}
          style={{
            all: "unset",
            boxSizing: "border-box",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            gap: 8,
            width: "100%",
            minHeight: 31,
            padding: "4px 10px",
            borderRadius: 6,
            border: `1px solid ${CHROME_BORDER_BLUE}`,
            background: CHROME_WHITE,
            color: theme.text.primary,
            fontSize: 13,
          }}
        >
          <ChromeText
            size="small"
            style={{
              flex: 1,
              minWidth: 0,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
              color: selected ? theme.text.primary : CHROME_INK_MUTED,
            }}
          >
            {selected?.label ?? ph}
          </ChromeText>
          <ChromeText size="small" tone="tertiary" style={{ flexShrink: 0 }}>
            ▼
          </ChromeText>
        </button>
      ) : (
        <Stack gap={4}>
          <input
            type="search"
            autoFocus
            value={query}
            placeholder={ph}
            autoComplete="off"
            spellCheck={false}
            aria-autocomplete="list"
            aria-expanded
            onChange={(e: { target: { value: string } }) =>
              setQuery(e.target.value)
            }
            onBlur={() => {
              window.setTimeout(() => setOpen(false), 140);
            }}
            onKeyDown={(e: {
              key: string;
              preventDefault: () => void;
            }) => {
              if (e.key === "Escape") {
                e.preventDefault();
                setOpen(false);
              }
              if (e.key === "Enter" && shown[0]) {
                e.preventDefault();
                pick(shown[0]!.value);
              }
            }}
            style={{
              width: "100%",
              height: 31,
              margin: 0,
              padding: "0 10px",
              borderRadius: 6,
              border: `1px solid ${accent}`,
              outline: "none",
              background: CHROME_WHITE,
              color: theme.text.primary,
              boxSizing: "border-box",
              fontSize: 13,
              fontFamily: "inherit",
            }}
          />
          <div
            role="listbox"
            style={{
              position: "absolute",
              zIndex: 30,
              top: 36,
              left: 0,
              right: 0,
              maxHeight: 260,
              overflowY: "auto",
              borderRadius: 8,
              border: `1px solid ${CHROME_BORDER_BLUE}`,
              background: CHROME_WHITE,
              boxSizing: "border-box",
            }}
          >
            {shown.length === 0 ? (
              <div style={{ padding: "10px 12px" }}>
                <ChromeText size="small" tone="secondary">
                  {t(uiLang, "clientSearchNoMatches")}
                </ChromeText>
              </div>
            ) : (
              <>
                {filtered.length > CLIENT_PICKER_RESULT_CAP ? (
                  <div
                    style={{
                      padding: "6px 12px",
                      borderBottom: `1px solid ${chromeBorder(theme)}`,
                    }}
                  >
                    <ChromeText size="small" tone="tertiary">
                      {t(uiLang, "clientSearchShowing")
                        .replace("{shown}", String(shown.length))
                        .replace("{total}", String(filtered.length))}
                    </ChromeText>
                  </div>
                ) : null}
                {shown.map((opt) => {
                  const active = opt.value === value;
                  return (
                    <button
                      key={opt.value}
                      type="button"
                      role="option"
                      aria-selected={active}
                      onMouseDown={(ev: { preventDefault: () => void }) => {
                        ev.preventDefault();
                        pick(opt.value);
                      }}
                      style={{
                        all: "unset",
                        boxSizing: "border-box",
                        cursor: "pointer",
                        display: "block",
                        width: "100%",
                        padding: "8px 12px",
                        background: active
                          ? chromeSelectedFill(theme)
                          : "transparent",
                        borderInlineStart: active
                          ? `3px solid ${accent}`
                          : "3px solid transparent",
                        color: theme.text.primary,
                        fontSize: 13,
                      }}
                    >
                      {opt.label}
                    </button>
                  );
                })}
              </>
            )}
          </div>
        </Stack>
      )}
    </div>
  );
}

