/**
 * One-time / one-off clients (Excel “לקוחות חד פעמים”, Billing “One Off Clients”).
 * Active only — potentials stay under Potential. Detected via invoice schedule
 * `one-off` and/or explicit `oneTime` on the list row.
 */
function isOneTimeClient(row: DemoRow): boolean {
  if (row.isPotential) return false;
  if (row.oneTime === true) return true;
  return row.profile?.invoiceSchedule === "one-off";
}

function rowSecondId(row: DemoRow): string {
  return resolveSecondIdInfo(row.profile).value || "—";
}

/** Resolved secondary-ID display for list cells (value + contextual sublabel). */
function resolveSecondIdInfo(profile?: ClientProfile): {
  value: string;
  kind: SecondIdKind;
  sublabel: string;
} {
  if (!profile) return { value: "", kind: "", sublabel: "" };
  const kind = (profile.secondIdKind ?? "") as SecondIdKind;
  if (kind === "spouse") {
    const value =
      profile.spouseId?.trim() ||
      profile.secondId?.trim() ||
      "";
    const spouse = profile.spouseName?.trim();
    return {
      value,
      kind,
      sublabel: spouse ? spouse : "",
    };
  }
  if (kind === "passport") {
    return {
      value:
        profile.passportNumber?.trim() ||
        profile.secondId?.trim() ||
        "",
      kind,
      sublabel: "",
    };
  }
  if (kind === "other") {
    return {
      value: profile.secondId?.trim() || "",
      kind,
      sublabel: "",
    };
  }
  // Unset kind: show raw secondId, or passport / spouse if only those exist
  const raw = profile.secondId?.trim() || "";
  if (raw) return { value: raw, kind: "", sublabel: "" };
  if (profile.passportNumber?.trim()) {
    return {
      value: profile.passportNumber.trim(),
      kind: "passport",
      sublabel: "",
    };
  }
  if (profile.spouseId?.trim()) {
    return {
      value: profile.spouseId.trim(),
      kind: "spouse",
      sublabel: profile.spouseName?.trim() || "",
    };
  }
  return { value: "", kind: "", sublabel: "" };
}

function secondIdKindLabel(lang: UiLang, kind: SecondIdKind): string {
  switch (kind) {
    case "spouse":
      return t(lang, "secondIdKindSpouse");
    case "passport":
      return t(lang, "secondIdKindPassport");
    case "other":
      return t(lang, "secondIdKindOther");
    default:
      return t(lang, "secondIdKindUnset");
  }
}

function secondIdListSublabel(
  lang: UiLang,
  info: { kind: SecondIdKind; sublabel: string },
): string {
  if (info.kind === "spouse") {
    const base = t(lang, "secondIdSublabelSpouse");
    return info.sublabel ? `${base} · ${info.sublabel}` : base;
  }
  if (info.kind === "passport") return t(lang, "secondIdSublabelPassport");
  if (info.kind === "other") return t(lang, "secondIdSublabelOther");
  return "";
}

function secondIdListCell(lang: UiLang, row: DemoRow) {
  const info = resolveSecondIdInfo(row.profile);
  if (!info.value) return "—";
  const sub = secondIdListSublabel(lang, info);
  if (!sub) return info.value;
  return (
    <Stack gap={0}>
      <ChromeText>{info.value}</ChromeText>
      <ChromeText size="small" tone="tertiary">
        {sub}
      </ChromeText>
    </Stack>
  );
}

function rowCity(row: DemoRow): string {
  const v = row.profile?.city?.trim();
  return v || "—";
}

