/** Longer labels for System Admin list-column picker. */
function listColumnPickerLabel(
  lang: UiLang,
  id: ListColumnId,
  customColumns: CustomListColumn[] = [],
): string {
  if (isCustomListColumnId(id)) {
    return listColumnHeader(lang, id, customColumns);
  }
  if (id === "secondId") return t(lang, "colSecondIdPicker");
  if (id === "identity") return t(lang, "colIdentityPicker");
  return listColumnHeader(lang, id, customColumns);
}

/**
 * Built-ins stay in ALL_LIST_COLUMN_IDS order; enabled custom ids append in
 * `customColumnIds` order. Unknown / deleted custom ids are dropped.
 */
function normalizeVisibleListColumns(
  cols: readonly ListColumnId[],
  customColumnIds: readonly string[] = [],
): ListColumnId[] {
  const set = new Set(cols);
  for (const id of ALWAYS_ON_LIST_COLUMNS) set.add(id);
  const builtins = ALL_LIST_COLUMN_IDS.filter((id) => set.has(id));
  const customKnown = new Set(customColumnIds.filter(isCustomListColumnId));
  const customs = customColumnIds.filter(
    (id) => customKnown.has(id) && set.has(id),
  );
  return [...builtins, ...customs];
}

function stripCustomColumnFromVisibility(
  visibility: ListColumnVisibility,
  customId: string,
): ListColumnVisibility {
  const next = { ...visibility };
  for (const key of Object.keys(next) as ClientListModuleKey[]) {
    next[key] = (next[key] ?? []).filter((id) => id !== customId);
  }
  return next;
}

