function displayClientName(
  row: { name: string; nameHe?: string },
  lang: UiLang,
): string {
  if (lang === "he" && row.nameHe?.trim()) return row.nameHe.trim();
  return row.name;
}

/** True when `name` is the legal/business entity label, not a person contact. */
function isEntityKindForListName(
  kind: DemoRow["kind"],
): kind is "company" | "trust" | "bookkeeping" | "osek" {
  return (
    kind === "company" ||
    kind === "trust" ||
    kind === "bookkeeping" ||
    kind === "osek"
  );
}

/** All clients / one-time: person rows only — entities live on their own tabs. */
function isPersonClientRow(row: DemoRow): boolean {
  if (row.isPotential || row.kind === "potential") return false;
  return row.kind === "individuals";
}

/**
 * Person / contact name for list display (All clients).
 * Never returns company / trust / bookkeeping entity `name` — only a real person.
 */
function personContactNameForList(
  row: DemoRow,
  lang: UiLang,
  allRows?: DemoRow[],
): string | undefined {
  const p = row.profile;
  const entity = displayClientName(row, lang);
  const linkedPerson = (): string | undefined => {
    if (!allRows?.length) return undefined;
    const linked = allRows.find(
      (r) =>
        !r.isPotential &&
        r.kind === "individuals" &&
        r.companyId === row.id,
    );
    if (!linked) return undefined;
    return (
      personContactNameForList(linked, lang) ?? displayClientName(linked, lang)
    );
  };

  if (row.kind === "company" || row.kind === "trust") {
    const contact =
      p?.contactName?.trim() ||
      p?.signatoryName?.trim() ||
      p?.partnerOwner?.trim() ||
      p?.sendTo?.trim();
    if (contact && contact !== entity) return contact;
    // Never fall back to the trust/company name as the person header.
    return linkedPerson();
  }

  const personEn = composeDisplayName(p?.firstEn ?? "", p?.familyEn ?? "", "");
  const personHe = composeDisplayName(p?.firstHe ?? "", p?.familyHe ?? "", "");
  const person =
    lang === "he"
      ? personHe || personEn || undefined
      : personEn || personHe || undefined;

  if (row.kind === "bookkeeping" || row.kind === "osek") {
    const biz = p?.businessName?.trim() || entity;
    if (person && person !== entity && person !== biz) return person;
    const contact = p?.contactName?.trim() || p?.signatoryName?.trim();
    if (contact && contact !== entity && contact !== biz) return contact;
    return linkedPerson();
  }

  // Individuals / potential: the row itself is the person.
  if (person) return person;
  return displayClientName(row, lang);
}

/** Entity / business name under the person line on All clients (when distinct). */
function relatedEntityNameForList(
  row: DemoRow,
  lang: UiLang,
  resolveCompany?: (id: string | undefined) => DemoRow | undefined,
): string | undefined {
  if (row.kind === "company" || row.kind === "trust") {
    return displayClientName(row, lang);
  }
  if (row.kind === "bookkeeping" || row.kind === "osek") {
    const biz = row.profile?.businessName?.trim();
    return biz || displayClientName(row, lang);
  }
  if (row.kind === "individuals" && row.companyId && resolveCompany) {
    const linked = resolveCompany(row.companyId);
    if (linked) return displayClientName(linked, lang);
  }
  return undefined;
}

/**
 * Name cell content by Clients sidebar filter.
 * All / one-time: person/contact only (no type/entity stack).
 * Specialized tabs: that entity/person name first.
 */
function clientListNameContent(
  row: DemoRow,
  filter: ClientFilter,
  lang: UiLang,
  _resolveCompany?: (id: string | undefined) => DemoRow | undefined,
  allRows?: DemoRow[],
): { primary: string; secondary: string[] } {
  const entity = displayClientName(row, lang);
  const person = personContactNameForList(row, lang, allRows);

  if (filter === "potential" || row.isPotential) {
    return { primary: entity, secondary: [] };
  }

  /** Tabs keyed to an engagement type: show that entity/person name as primary. */
  if (
    filter === "company" ||
    filter === "bookkeeping" ||
    filter === "trust" ||
    filter === "osek" ||
    filter === "individuals"
  ) {
    if (filter === "individuals") {
      return { primary: person ?? entity, secondary: [] };
    }
    return { primary: entity, secondary: [] };
  }

  // All clients + one-time: person name only — entity lives in department columns.
  let primary = person;
  if (
    !primary ||
    (isEntityKindForListName(row.kind) && primary === entity)
  ) {
    primary = undefined;
  }
  return { primary: primary ?? "—", secondary: [] };
}

/**
 * Display label for a firm service / catalog string.
 * Keeps English internal keys; maps for HE UI (lists, chips, tabs, tiles).
 */
function serviceLabel(lang: UiLang, serviceName: string): string {
  const key = serviceName.trim().toLowerCase().replace(/\s+/g, " ");
  if (!key) return serviceName.trim();
  if (key === "bookkeeping") return t(lang, "bookkeeping");
  if (key === "billing") return t(lang, "billing");
  if (key === "audit") return t(lang, "audit");
  if (key === "tax return" || key === "tax return (individual)") {
    return t(lang, "taxReturn");
  }
  if (key === "vat") return t(lang, "vat");
  if (key === "payroll") return t(lang, "payroll");
  if (key === "consulting") return t(lang, "consulting");
  if (key === "company secretary") return t(lang, "companySecretary");
  if (
    key === "declaration of assets" ||
    key === "הצהרת הון" ||
    key === "הצהרת נכסים"
  ) {
    return t(lang, "declarationOfAssets");
  }
  if (
    key === "annual accounts / audit" ||
    key === "annual accounts" ||
    key === "annual account"
  ) {
    return t(lang, "annualAccounts");
  }
  if (key === "invoices") return t(lang, "invoices");
  if (key === "docs" || key === "documents") return t(lang, "docs");
  if (key === "services") return t(lang, "services");
  return serviceName.trim();
}

/** Alias used by stream / tab wiring. */
function streamServiceLabel(lang: UiLang, serviceName: string): string {
  return serviceLabel(lang, serviceName);
}

/** Map comma-separated catalog services for table cells / filters. */
function servicesDisplayLabel(lang: UiLang, servicesCsv: string): string {
  return servicesCsv
    .split(",")
    .map((part) => serviceLabel(lang, part.trim()))
    .filter(Boolean)
    .join(lang === "he" ? ", " : ", ");
}

function isClientOnHoldStatus(status: string): boolean {
  const key = status.trim().toLowerCase().replace(/_/g, " ");
  return key === "on hold";
}

function normalizeClientStatusKey(status: string): string {
  return status.trim().toLowerCase().replace(/_/g, " ");
}

/**
 * Client / list status → Pill tone.
 * Active green · On hold red · Inactive/Archived muted blue · Closed rose.
 */
function clientStatusPillTone(
  status: string,
): "neutral" | "success" | "warning" | "info" | "danger" {
  const key = normalizeClientStatusKey(status);
  if (key === "active") return "success";
  if (key === "on hold") return "danger";
  if (key === "closed" || key === "left") return "danger";
  if (
    key === "inactive" ||
    key === "archived" ||
    key === "hidden" ||
    key === "prospect"
  ) {
    return "info";
  }
  return "info";
}

function clientStatusLabel(lang: UiLang, status: string): string {
  const key = normalizeClientStatusKey(status);
  if (key === "active") return t(lang, "active");
  if (key === "prospect") return t(lang, "prospectStatus");
  if (key === "hidden") return t(lang, "hidden");
  if (key === "on hold") return t(lang, "clientOnHoldStatus");
  return status;
}

/**
 * Client card panels. Profile header stays at top.
 * Default panel on every open: Overview (reset; do not keep last process tab).
 * Horizontal tabs (shared RaisedTabBar / GmailTabBar): folder-tab raised
 * chrome by default on the client card; ModuleSectionTabs share that raised
 * look. Other RaisedTabBar call sites may keep variant="gmail" underline.
 * Always: Overview, Docs, Invoices,
 * Client WhatsApp, Portal, Client email. Process tabs are driven by the firm
 * Services catalog — each firm service is a tab type; a tab appears on a client
 * card only when that client has the service (service-gated). Known streams
 * (Bookkeeping, Billing, Audit, Tax return, Payroll) keep dedicated
 * workspaces; VAT nests under Bookkeeping as an inner tab + checklist row when
 * the client also has Bookkeeping (otherwise VAT stays a top-level tab).
 * Brand-new custom services open a generic service workspace.
 * Optional status dot on process tabs (not Docs). Tabs wrap when tight.
 *
 * Comment streams (never mixed across tabs):
 * - Overview → General comments only (+ Things to do). No process chats.
 * - Bookkeeping / Tax return → full workspace; that stream's comments only.
 * - Billing → billing workspace + billing comments only.
 * - Audit / Payroll → that stream's chat only (no General, no others).
 * - VAT → under Bookkeeping (inner tab) when Bookkeeping is present; else chat.
 * - Custom services → generic workspace (status + notes + files).
 * General comments never appear on Bookkeeping or other process tabs.
 * Client WhatsApp / Portal / Client email are per-client only (not firm-wide).
 */
type AlwaysOnPanel =
  | "overview"
  | "prospect-checklist"
