/**
 * Resolve BK+Audit working year: shared key first, then legacy
 * bkWorkingYear / auditWorkingYear (migrated into shared on write).
 */
function resolveClientBkAuditYear(
  shared: string,
  legacyBk: string,
  legacyAudit: string,
  fallback: BkAuditYear = "2024",
): BkAuditYear {
  if (isBkAuditYear(shared)) return shared;
  if (isBkAuditYear(legacyBk)) return legacyBk;
  if (isBkAuditYear(legacyAudit)) return legacyAudit;
  return fallback;
}

/** Migrate legacy bare stage string into `{ [currentYear]: stage }` once. */
function normalizeYearStageMap<T extends string>(
  raw: unknown,
  currentYear: string,
  isStage: (v: unknown) => v is T,
): Partial<Record<string, T>> {
  if (isStage(raw)) return { [currentYear]: raw };
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    const out: Partial<Record<string, T>> = {};
    for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
      if (isStage(v)) out[k] = v;
    }
    return out;
  }
  return {};
}

