function resolveClientDeptComments(
  map: ClientDeptCommentsMap,
  clientId: string,
  stream: ClientCommentStreamId,
  fallback: ClientDeptSyncedComment[],
): ClientDeptSyncedComment[] {
  const key = deptCommentMapEntryKey(clientId, stream);
  if (Object.prototype.hasOwnProperty.call(map, key)) {
    const rows = map[key];
    return Array.isArray(rows) ? rows : [];
  }
  return fallback;
}

function appendClientDeptComment(
  map: ClientDeptCommentsMap,
  clientId: string,
  stream: ClientCommentStreamId,
  comment: ClientDeptSyncedComment,
  fallback: ClientDeptSyncedComment[],
): ClientDeptCommentsMap {
  const key = deptCommentMapEntryKey(clientId, stream);
  const existing = resolveClientDeptComments(map, clientId, stream, fallback);
  return { ...map, [key]: [...existing, comment] };
}

function patchClientDeptComment(
  map: ClientDeptCommentsMap,
  clientId: string,
  stream: ClientCommentStreamId,
  commentId: string,
  body: string,
  fallback: ClientDeptSyncedComment[],
): ClientDeptCommentsMap {
  const key = deptCommentMapEntryKey(clientId, stream);
  const existing = resolveClientDeptComments(map, clientId, stream, fallback);
  return {
    ...map,
    [key]: existing.map((c) => (c.id === commentId ? { ...c, body } : c)),
  };
}

function removeClientDeptComment(
  map: ClientDeptCommentsMap,
  clientId: string,
  stream: ClientCommentStreamId,
  commentId: string,
  fallback: ClientDeptSyncedComment[],
): ClientDeptCommentsMap {
  const key = deptCommentMapEntryKey(clientId, stream);
  const existing = resolveClientDeptComments(map, clientId, stream, fallback);
  return {
    ...map,
    [key]: existing.filter((c) => c.id !== commentId),
  };
}

