/**
 * Default worker for “Send to worker chat”:
 * 1) client.profile.managedBy matched to a firm worker (EN/HE name or id)
 * 2) first Accounting-dept worker
 * 3) signed-in worker (if still on roster)
 * 4) DEMO_WORKER / first roster row
 */
function resolveClientBookkeeperWorkerId(
  client: DemoRow,
  workers: FirmWorker[] = DEMO_STAFF,
  signedInWorkerId: string = DEMO_WORKER.id,
): string {
  const list = normalizeFirmWorkers(
    Array.isArray(workers) && workers.length > 0 ? workers : DEMO_STAFF,
  );
  const managed = client.profile?.managedBy?.trim();
  if (managed) {
    const key = normalizePersonKey(managed);
    const byName = list.find(
      (w) =>
        w.id === managed ||
        normalizePersonKey(w.name) === key ||
        normalizePersonKey(w.nameHe) === key,
    );
    if (byName) return byName.id;
  }
  const accounting = list.find((w) =>
    workerBelongsToDept(w.id, "reportDeptAccounting", list),
  );
  if (accounting) return accounting.id;
  if (list.some((w) => w.id === signedInWorkerId)) return signedInWorkerId;
  return list[0]?.id ?? DEMO_WORKER.id;
}

/** Append a demo note on the internal staff thread targeting a worker. */
function appendInternalWorkerDocRequestNote(
  setThreads: (
    next: ChatThread[] | ((prev: ChatThread[]) => ChatThread[]),
  ) => void,
  opts: {
    targetWorkerId: string;
    fromWorkerId: string;
    body: string;
    workers: FirmWorker[];
    lang: UiLang;
  },
) {
  const time = clockNow();
  const fromName = staffDisplayName(
    opts.lang,
    opts.fromWorkerId,
    opts.workers,
  );
  const targetName = staffDisplayName(
    opts.lang,
    opts.targetWorkerId,
    opts.workers,
  );
  const msg: ChatMessage = {
    id: `doc-req-chat-${Date.now()}`,
    from: "me",
    author: fromName,
    body: opts.body,
    time,
    workerId: opts.fromWorkerId,
    kind: "text",
  };
  setThreads((prev) => {
    const threads = Array.isArray(prev) ? prev : DEFAULT_THREADS;
    const existingIdx = threads.findIndex(
      (th) =>
        th.channel === "internal" &&
        (th.id === opts.targetWorkerId ||
          (th.participantIds ?? []).includes(opts.targetWorkerId)),
    );
    if (existingIdx >= 0) {
      return threads.map((th, i) =>
        i !== existingIdx
          ? th
          : {
              ...th,
              preview: opts.body,
              time,
              unread: true,
              messages: [...th.messages, msg],
            },
      );
    }
    const created: ChatThread = {
      id: opts.targetWorkerId,
      title: targetName,
      channel: "internal",
      channelLabel: "Staff chat",
      preview: opts.body,
      time,
      unread: true,
      participantIds: [opts.fromWorkerId, opts.targetWorkerId],
      messages: [msg],
    };
    return [created, ...threads];
  });
}

