/**
 * Process status for work streams on the client card.
 * Red = Not started · Yellow = In process · Green = Finished.
 * Docs lists documents only — no process status.
 */
type WorkFlowStatus = "not-started" | "in-process" | "finished";

/** Panels that show a color-coded process status (workspaces + Invoices). */
type StatusPanel = KnownStreamPanel | CustomStreamPanel | "invoices";

const WORK_FLOW_STEPS: WorkFlowStatus[] = [
  "not-started",
  "in-process",
  "finished",
];

function workFlowLabel(lang: UiLang, status: WorkFlowStatus): string {
  if (status === "not-started") return lang === "he" ? "לא התחיל" : "Not started";
  if (status === "in-process") return lang === "he" ? "בתהליך" : "In process";
  return lang === "he" ? "הסתיים" : "Finished";
}

/** Weighted score: Finished=1, In process=0.5, Not started=0. */
function workFlowProgressWeight(status: WorkFlowStatus): number {
  if (status === "finished") return 1;
  if (status === "in-process") return 0.5;
  return 0;
}

/** Overall % from tab/service process statuses (0–100). */
function computeOverallProgress(statuses: WorkFlowStatus[]): {
  percent: number;
  scored: number;
  total: number;
} {
  if (statuses.length === 0) return { percent: 0, scored: 0, total: 0 };
  const scored = statuses.reduce(
    (sum, s) => sum + workFlowProgressWeight(s),
    0,
  );
  const percent = Math.round((scored / statuses.length) * 100);
  return { percent, scored, total: statuses.length };
}

function workFlowColor(
  theme: { category: { red: string; yellow: string; green: string } },
  status: WorkFlowStatus,
): string {
  if (status === "not-started") return theme.category.red;
  if (status === "in-process") return theme.category.yellow;
  return theme.category.green;
}

function isStatusPanel(panel: ClientCardPanel): panel is StatusPanel {
  return panel === "invoices" || panel.startsWith("stream-");
}

function isKnownStreamPanel(panel: ClientCardPanel): panel is KnownStreamPanel {
  return (
    panel === "stream-bookkeeping" ||
    panel === "stream-tax-return" ||
    panel === "stream-billing" ||
    panel === "stream-audit" ||
    panel === "stream-vat" ||
    panel === "stream-payroll"
  );
}

function isCustomStreamPanel(panel: ClientCardPanel): panel is CustomStreamPanel {
  return typeof panel === "string" && panel.startsWith("stream-custom:");
}

/**
 * Override / demo map key. Tax return / audit stages are per working year so
 * year A edits never overwrite year B: `stream-tax-return:2024`.
 * Other panels stay panel-only: `stream-billing`.
 */
function workStatusOverrideKey(panel: StatusPanel, year?: string): string {
  if (
    year &&
    (panel === "stream-tax-return" || panel === "stream-audit")
  ) {
    return `${panel}:${year}`;
  }
  return panel;
}

function isWorkFlowStatus(v: unknown): v is WorkFlowStatus {
  return v === "not-started" || v === "in-process" || v === "finished";
}

function isTaxReturnProcessStage(v: unknown): v is TaxReturnProcessStage {
  return (
    v === "materials" ||
    v === "filing" ||
    v === "client-signature" ||
    v === "transmission" ||
    v === "further-handling"
  );
}

function taxReturnProcessLabel(
  lang: UiLang,
  stage: TaxReturnProcessStage,
): string {
  if (stage === "materials") return t(lang, "taxReturnStageMaterials");
  if (stage === "filing") return t(lang, "taxReturnStageFiling");
  if (stage === "client-signature") return t(lang, "taxReturnStageSignature");
  if (stage === "transmission") return t(lang, "taxReturnStageTransmission");
  return t(lang, "taxReturnStageFurther");
}

/** Compact under-bar labels; full name stays on title / aria. */
function taxReturnProcessBarLabel(
  lang: UiLang,
  stage: TaxReturnProcessStage,
): string {
  const he = lang === "he";
  if (stage === "materials") return he ? "קבלת חומר" : "Materials";
  if (stage === "filing") return he ? "הגשת דוח" : "Filing";
  if (stage === "client-signature") return he ? "חתימת לקוח" : "Signature";
  if (stage === "transmission") return he ? "שידור" : "Transmit";
  return he ? "המשך טיפול" : "Further?";
}

function taxReturnProcessIndex(stage: TaxReturnProcessStage): number {
  return Math.max(0, TAX_RETURN_PROCESS_STEPS.indexOf(stage));
}

/** 0–100 from discrete stage index only (legacy / stage floor). */
function taxReturnProcessPercent(stage: TaxReturnProcessStage): number {
  const n = TAX_RETURN_PROCESS_STEPS.length;
  if (n <= 1) return 0;
  return Math.round((taxReturnProcessIndex(stage) / (n - 1)) * 100);
}

/**
 * Progress bar % from checklist + doc requests for this client/year:
 * (completed stage checklist items + uploaded requests) / (checklist items + all requests).
 * Stage label stays independent; fill rises as materials are given in / items checked.
 */
function taxReturnChecklistProgressPercent(
  stage: TaxReturnProcessStage,
  docRequests: { status: "pending" | "uploaded" }[],
  checklistDoneOverrides: Record<string, boolean> = {},
  customItemIds: string[] = [],
): number {
  const activeIdx = taxReturnProcessIndex(stage);
  const checklistIds = [
    "tr-c-materials",
    "tr-c-filing",
    "tr-c-signature",
    "tr-c-transmission",
    "tr-c-further",
  ];
  let checklistDone = 0;
  for (let i = 0; i < checklistIds.length; i++) {
    const id = checklistIds[i];
    const autoDone = i < activeIdx;
    const done = checklistDoneOverrides[id] ?? autoDone;
    if (done) checklistDone += 1;
  }
  for (const id of customItemIds) {
    if (checklistDoneOverrides[id]) checklistDone += 1;
  }
  const uploadedDocs = docRequests.filter((r) => r.status === "uploaded").length;
  const completed = checklistDone + uploadedDocs;
  const total = checklistIds.length + docRequests.length + customItemIds.length;
  if (total <= 0) return 0;
  return Math.round((completed / total) * 100);
}

const TAX_RETURN_CHECKLIST_IDS = [
  "tr-c-materials",
  "tr-c-filing",
  "tr-c-signature",
  "tr-c-transmission",
  "tr-c-further",
] as const;

/**
 * Per-stage chevron fill (0–1) for personal tax:
 * — stages before the pointer = full when that checklist row is done
 * — active stage = climbs with that checklist row + docs uploaded / requested
 *   (+ custom checklist rows)
 * — later stages = empty
 */
function taxReturnProcessStageFillRatios(
  stage: TaxReturnProcessStage,
  docRequests: { status: "pending" | "uploaded" }[],
  checklistDoneOverrides: Record<string, boolean> = {},
  customItemIds: string[] = [],
): number[] {
  const activeIdx = taxReturnProcessIndex(stage);
  const uploaded = docRequests.filter((r) => r.status === "uploaded").length;
  const totalDocs = docRequests.length;
  const docPct = totalDocs > 0 ? uploaded / totalDocs : 0;
  let customDone = 0;
  for (const id of customItemIds) {
    if (checklistDoneOverrides[id]) customDone += 1;
  }
  const customPct =
    customItemIds.length > 0 ? customDone / customItemIds.length : 0;

  return TAX_RETURN_PROCESS_STEPS.map((step, i) => {
    const id = TAX_RETURN_CHECKLIST_IDS[i]!;
    const autoDone = i < activeIdx;
    const checkDone = checklistDoneOverrides[id] ?? autoDone;

    if (i < activeIdx) return checkDone ? 1 : 0;
    if (i > activeIdx) return 0;

    // Active stage: checklist + docs given in (+ custom rows) drive the fill.
    const parts: number[] = [checkDone ? 1 : 0];
    if (totalDocs > 0) parts.push(docPct);
    if (customItemIds.length > 0) parts.push(customPct);
    // Materials stage weights docs more when requests exist.
    if (step === "materials" && totalDocs > 0) {
      return Math.max(0, Math.min(1, (checkDone ? 0.35 : 0) + docPct * 0.65));
    }
    const avg = parts.reduce((a, b) => a + b, 0) / parts.length;
    return Math.max(0, Math.min(1, avg));
  });
}

/** Map 5-stage process → tab blob red/yellow/green. */
function taxReturnStageToWorkFlowStatus(
  stage: TaxReturnProcessStage,
): WorkFlowStatus {
  if (stage === "materials") return "not-started";
  if (stage === "further-handling") return "finished";
  return "in-process";
}

function taxReturnStageDocsHintKey(
  stage: TaxReturnProcessStage,
): CrmUiKey {
  if (stage === "materials") return "taxReturnDocsHintMaterials";
  if (stage === "filing") return "taxReturnDocsHintFiling";
  if (stage === "client-signature") return "taxReturnDocsHintSignature";
  if (stage === "transmission") return "taxReturnDocsHintTransmission";
  return "taxReturnDocsHintFurther";
}

