function demoAuditYearStage(
  clientId: string,
  year: string,
  kind: string,
): AuditProcessStage {
  const steps =
    kind === "bookkeeping"
      ? AUDIT_PROCESS_STEPS_BOOKKEEPING
      : AUDIT_PROCESS_STEPS_COMPANY;
  const byClient: Record<string, Partial<Record<string, AuditProcessStage>>> = {
    "c-greenleaf": {
      "2025": "bk-close",
      "2024": "fieldwork",
      "2023": "sign-submit",
    },
    "c-sharontech": {
      "2025": "import-konto",
      "2024": "report-1214",
      "2023": "sign-submit",
    },
    "c-cohen": {
      "2025": "reporting",
      "2024": "bk-banks",
      "2023": "bank-confirm",
    },
    "c-malki": {
      "2025": "reporting",
      "2024": "year-transfer",
      "2023": "audit-ready",
    },
  };
  const saved = byClient[clientId]?.[year];
  if (saved && steps.includes(saved)) return saved;
  return steps[0]!;
}

function resolveAuditProcessStage(
  clientId: string,
  year: string,
  kind: string,
  overrides: Partial<Record<string, AuditProcessStage>>,
): AuditProcessStage {
  const steps =
    kind === "bookkeeping"
      ? AUDIT_PROCESS_STEPS_BOOKKEEPING
      : AUDIT_PROCESS_STEPS_COMPANY;
  const saved = overrides[year];
  if (isAuditProcessStage(saved) && steps.includes(saved)) return saved;
  return demoAuditYearStage(clientId, year, kind);
}

function defaultAuditMonthlyPct(
  clientId: string,
  year: string,
): Record<string, number> {
  const out: Record<string, number> = {};
  /** ~52% year average (5×100 + 75 + 50) / 12 — verify Audit first chevron. */
  const midYear52 = [100, 100, 100, 100, 100, 75, 50, 0, 0, 0, 0, 0];
  const base =
    year === "2025"
      ? midYear52
      : clientId === "c-cohen" && year === "2024"
        ? [100, 100, 100, 100, 100, 90, 80, 70, 40, 20, 0, 0]
        : clientId === "c-malki" && year === "2024"
          ? [100, 100, 100, 100, 100, 100, 100, 100, 100, 85, 60, 30]
          : clientId === "c-cohen"
            ? [100, 100, 80, 60, 40, 20, 0, 0, 0, 0, 0, 0]
            : [100, 100, 100, 90, 80, 70, 50, 30, 10, 0, 0, 0];
  AUDIT_MONTH_KEYS.forEach((m, i) => {
    out[m] = base[i] ?? 0;
  });
  return out;
}

function auditMonthlyYearAverage(monthly: Record<string, number>): number {
  let sum = 0;
  for (const m of AUDIT_MONTH_KEYS) {
    sum += Math.max(0, Math.min(100, monthly[m] ?? 0));
  }
  return Math.round(sum / AUDIT_MONTH_KEYS.length);
}

/**
 * Bookkeeping / monthly-reporting checklist item ids.
 * Default template (20% each): import → match → reconcile → VAT reported → close.
 */
const BK_VAT_CHECK_ID = "bk-c5";
const BK_MONTH_CHECKLIST_IDS = [
  "bk-c1",
  "bk-c2",
  "bk-c3",
  BK_VAT_CHECK_ID,
  "bk-c4",
] as const;
const BK_CORE_CHECKLIST_IDS = BK_MONTH_CHECKLIST_IDS;

type BkMonthKey = (typeof AUDIT_MONTH_KEYS)[number];

const BOOKKEEPING_YEARS = BK_AUDIT_YEARS;
type BookkeepingYear = BkAuditYear;

function isBkMonthKey(v: string): v is BkMonthKey {
  return (AUDIT_MONTH_KEYS as readonly string[]).includes(v);
}

function bkMonthChecklistIds(_includeVat = true): string[] {
  // VAT reported is part of the default month template for every BK client.
  return [...BK_MONTH_CHECKLIST_IDS];
}

function bkChecklistDoneKey(month: string, itemId: string): string {
  return `${month}:${itemId}`;
}

function progressPctToWorkFlowStatus(pct: number): WorkFlowStatus {
  if (pct <= 0) return "not-started";
  if (pct >= 100) return "finished";
  return "in-process";
}

/** Worse of two statuses (not-started < in-process < finished) for attention dots. */
function worseWorkFlowStatus(
  a: WorkFlowStatus,
  b: WorkFlowStatus,
): WorkFlowStatus {
  const rank: Record<WorkFlowStatus, number> = {
    "not-started": 0,
    "in-process": 1,
    finished: 2,
  };
  return rank[a] <= rank[b] ? a : b;
}

/** How many checklist rows a demo % implies (step = 100 / itemCount). */
function bkChecklistDoneCountFromPct(pct: number, itemCount = 5): number {
  if (itemCount <= 0) return 0;
  const step = 100 / itemCount;
  return Math.round(Math.max(0, Math.min(100, pct)) / step);
}

function defaultBkMonthChecklistDone(
  clientId: string,
  year: string,
): Record<string, boolean> {
  const monthly = defaultAuditMonthlyPct(clientId, year);
  const out: Record<string, boolean> = {};
  const ids = [...BK_MONTH_CHECKLIST_IDS];
  for (const m of AUDIT_MONTH_KEYS) {
    const n = bkChecklistDoneCountFromPct(monthly[m] ?? 0, ids.length);
    ids.forEach((id, i) => {
      out[bkChecklistDoneKey(m, id)] = i < n;
    });
  }
  return out;
}

function bookkeepingMonthPctFromChecklist(
  month: string,
  done: Record<string, boolean>,
  extraItemIds: string[] = [],
  includeVat = false,
): number {
  const ids = [...bkMonthChecklistIds(includeVat), ...extraItemIds];
  if (ids.length === 0) return 0;
  let completed = 0;
  for (const id of ids) {
    if (done[bkChecklistDoneKey(month, id)]) completed += 1;
  }
  return Math.round((completed / ids.length) * 100);
}

function bookkeepingAllMonthsPct(
  done: Record<string, boolean>,
  customItems: { id: string; monthKey: string }[] = [],
  includeVat = false,
): Record<string, number> {
  const out: Record<string, number> = {};
  for (const m of AUDIT_MONTH_KEYS) {
    const extra = customItems
      .filter((c) => c.monthKey === m)
      .map((c) => c.id);
    out[m] = bookkeepingMonthPctFromChecklist(m, done, extra, includeVat);
  }
  return out;
}

/** True when every Jan–Dec month checklist is 100% for the year. */
function bookkeepingYearFullyComplete(
  done: Record<string, boolean>,
  customItems: { id: string; monthKey: string }[] = [],
  includeVat = false,
): boolean {
  const monthly = bookkeepingAllMonthsPct(done, customItems, includeVat);
  return AUDIT_MONTH_KEYS.every((m) => (monthly[m] ?? 0) >= 100);
}

/**
 * Audit stage whose checklist / fill is gated by Jan–Dec bookkeeping months
 * (company: Books to 31/12; bookkeeping client: Monthly reporting).
 */
function auditBkMonthGateStage(
  steps: AuditProcessStage[],
): AuditProcessStage | null {
  if (steps.includes("bk-close")) return "bk-close";
  if (steps.includes("reporting")) return "reporting";
  return null;
}

/**
 * Per-stage ChevronBarSegment fill (0–1).
 * Close books / Monthly = Jan–Dec bookkeeping year average (matches the % above
 * the monthly bar). All later stages = that stage’s checklist item only (0 or 1)
 * — not auto-filled just because the process pointer moved past them.
 */
function auditProcessStageFillRatios(
  processStage: AuditProcessStage,
  steps: AuditProcessStage[],
  checklistDoneOverrides: Record<string, boolean>,
  bkMonthlyPct: Record<string, number>,
): number[] {
  void processStage;
  const yearAvg01 = Math.max(
    0,
    Math.min(1, auditMonthlyYearAverage(bkMonthlyPct) / 100),
  );
  return steps.map((step) => {
    if (step === "bk-close" || step === "reporting") {
      return yearAvg01;
    }
    const id = auditChecklistIdForStage(step);
    return checklistDoneOverrides[id] ? 1 : 0;
  });
}

