function defaultBkActiveMonth(
  clientId: string,
  year: string,
  includeVat = false,
): BkMonthKey {
  const monthly = bookkeepingAllMonthsPct(
    defaultBkMonthChecklistDone(clientId, year),
    [],
    includeVat,
  );
  for (const m of AUDIT_MONTH_KEYS) {
    const pct = monthly[m] ?? 0;
    if (pct < 100) return m;
  }
  return "12";
}

