function demoAuditChecklist(
  lang: UiLang,
  stage: AuditProcessStage,
  steps: AuditProcessStage[],
  doneOverrides: Record<string, boolean> = {},
): WorkspaceChecklistItem[] {
  const activeIdx = auditProcessIndex(stage, steps);
  return steps.map((step, i) => {
    const id = auditChecklistIdForStage(step);
    const autoDone = i < activeIdx;
    return {
      id,
      stageId: step,
      label: t(lang, auditCheckLabelKey(step)),
      done: doneOverrides[id] ?? autoDone,
    };
  });
}

function auditChecklistProgressPercent(
  stage: AuditProcessStage,
  steps: AuditProcessStage[],
  docRequests: { status: "pending" | "uploaded" }[],
  checklistDoneOverrides: Record<string, boolean> = {},
  monthlyPct?: Record<string, number>,
  customItemIds: string[] = [],
): number {
  const activeIdx = auditProcessIndex(stage, steps);
  let checklistDone = 0;
  for (let i = 0; i < steps.length; i++) {
    const id = auditChecklistIdForStage(steps[i]!);
    const autoDone = i < activeIdx;
    if (checklistDoneOverrides[id] ?? autoDone) checklistDone += 1;
  }
  for (const id of customItemIds) {
    if (checklistDoneOverrides[id]) checklistDone += 1;
  }
  const uploadedDocs = docRequests.filter((r) => r.status === "uploaded").length;
  let completed = checklistDone + uploadedDocs;
  let total = steps.length + docRequests.length + customItemIds.length;
  if (monthlyPct && (steps.includes("reporting") || steps.includes("bk-close"))) {
    const yearAvg = auditMonthlyYearAverage(monthlyPct);
    completed += yearAvg;
    total += 100;
  }
  if (total <= 0) return 0;
  return Math.round((completed / total) * 100);
}

