/** Progress fill color bands — changes every 25%. Unfilled stays empty. */
const OVERALL_PROGRESS_BANDS: { maxPct: number; key: string }[] = [
  { maxPct: 25, key: "red" },
  { maxPct: 50, key: "yellow" },
  { maxPct: 75, key: "blue" },
  { maxPct: 100, key: "green" },
];

function overallProgressBandColor(
  theme: ReturnType<typeof useHostTheme>,
  key: string,
): string {
  if (key === "red") return theme.category.red;
  if (key === "yellow") return theme.category.yellow;
  if (key === "blue") return theme.accent.primary;
  return theme.category.green;
}

/**
 * Shared stage chevron clip-path: EVERY piece uses middle interlocking geometry —
 * concave V-notch on inline-start (“arrow in”) + tip on inline-end (“arrow out”).
 * Notch vertex is inset at tipPct/50% (not an outward left tip). `kind` ignored.
 * tipPct is used exactly (no 16–24 clamp); stages pass CHEVRON_TIP_PCT (~16).
 * Overall fill uses overallRoundedChevronPath (quadratic apexes) instead.
 * Points toward inline-end: LTR → right, RTL → left.
 */
function chevronSegmentClipPath(
  dir: "ltr" | "rtl",
  _kind: "first" | "middle" | "last" | "only" = "middle",
  tipPct: number = CHEVRON_TIP_PCT,
): string {
  const tip = tipPct;
  const tipEnd = 100 - tip;
  /**
   * Sharp polygon (stage bars). LTR tipPct=16:
   * polygon(0% 0%, 84% 0%, 100% 50%, 84% 100%, 0% 100%, 16% 50%)
   */
  const pts: [number, number][] = [
    [0, 0],
    [tipEnd, 0],
    [100, 50],
    [tipEnd, 100],
    [0, 100],
    [tip, 50],
  ];
  const mapped =
    dir === "rtl"
      ? pts.map(([x, y]) => [100 - x, y] as [number, number])
      : pts;
  return `polygon(${mapped.map(([x, y]) => `${x}% ${y}%`).join(", ")})`;
}

/**
 * Overall-only chevron in objectBoundingBox units (0–1): same arrow-in + arrow-out
 * as stages, but tip + notch apexes use quadratic curves so corners are slightly rounded.
 */
function overallRoundedChevronPath(
  dir: "ltr" | "rtl",
  tipPct: number = OVERALL_CHEVRON_TIP_PCT,
  round: number = OVERALL_CHEVRON_ROUND,
): string {
  const tip = Math.max(0.001, Math.min(0.2, tipPct / 100));
  const tipEnd = 1 - tip;
  const soft = Math.max(0.08, Math.min(0.55, round));
  const tipApex: [number, number] = [1, 0.5];
  const notchApex: [number, number] = [tip, 0.5];
  const tr: [number, number] = [tipEnd, 0];
  const br: [number, number] = [tipEnd, 1];
  const tl: [number, number] = [0, 0];
  const bl: [number, number] = [0, 1];
  const lerp = (
    a: [number, number],
    b: [number, number],
    t: number,
  ): [number, number] => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
  // Inset from sharp apex along each edge; Q control stays at the apex.
  const pTipTop = lerp(tipApex, tr, soft);
  const pTipBot = lerp(tipApex, br, soft);
  const pNotchTop = lerp(notchApex, tl, soft);
  const pNotchBot = lerp(notchApex, bl, soft);
  const mapX = (x: number) => (dir === "rtl" ? 1 - x : x);
  const fmt = (p: [number, number]) =>
    `${mapX(p[0]).toFixed(4)} ${p[1].toFixed(4)}`;
  return [
    `M ${fmt(tl)}`,
    `L ${fmt(tr)}`,
    `L ${fmt(pTipTop)}`,
    `Q ${fmt(tipApex)} ${fmt(pTipBot)}`,
    `L ${fmt(br)}`,
    `L ${fmt(bl)}`,
    `L ${fmt(pNotchBot)}`,
    `Q ${fmt(notchApex)} ${fmt(pNotchTop)}`,
    "Z",
  ].join(" ");
}

/**
 * Shared nest depth for every ChevronBarSegment row (gap 0 + negative margin).
 * tipPct is % of each equal-width segment; segment ≈ 100/n % of the row, so tip
 * ≈ (tipPct/n)% of the row. Nest ≈ 1.0 so the tip sits in the next notch without
 * overshooting into the next segment’s solid body (avoids neighbor-color needles).
 */
function chevronOverlapAmount(segmentCount: number): string {
  if (segmentCount <= 1) return "0px";
  const nestFactor = 1.0;
  const pct = (CHEVRON_TIP_PCT / segmentCount) * nestFactor;
  return `-${pct.toFixed(3)}%`;
}

/** Stage bars only — Overall uses OVERALL_CHEVRON_TIP_PCT. */
function chevronTipPctForCount(_segmentCount: number): number {
  return CHEVRON_TIP_PCT;
}

/**
 * Soft linear-gradient so adjacent Overall band colors flow into each other
 * instead of hard flat cuts. Optional widths weight each color stop.
 * Stage ChevronBarSegments use solid fills — not this helper.
 */
function blendProgressGradient(
  colors: string[],
  dir: "ltr" | "rtl",
  widths?: number[],
): string {
  if (colors.length === 0) return "transparent";
  const angle = dir === "rtl" ? "to left" : "to right";
  if (colors.length === 1) {
    const c = colors[0]!;
    return `linear-gradient(${angle}, ${c} 0%, ${c} 100%)`;
  }
  const total =
    widths && widths.length === colors.length
      ? widths.reduce((sum, w) => sum + Math.max(0.001, w), 0)
      : colors.length;
  const stops: string[] = [];
  let acc = 0;
  for (let i = 0; i < colors.length; i++) {
    const w = Math.max(0.001, widths?.[i] ?? 1);
    const start = (acc / total) * 100;
    const end = ((acc + w) / total) * 100;
    const span = Math.max(0.001, end - start);
    const blend = Math.min(span * 0.48, 18);
    const c = colors[i]!;
    if (i === 0) {
      stops.push(`${c} ${start}%`);
      stops.push(`${c} ${Math.max(start, end - blend)}%`);
    } else {
      const prev = colors[i - 1]!;
      stops.push(`${prev} ${start}%`);
      stops.push(`${c} ${Math.min(100, start + blend)}%`);
      if (i === colors.length - 1) {
        stops.push(`${c} ${end}%`);
      } else {
        stops.push(`${c} ${Math.max(start + blend, end - blend)}%`);
      }
    }
    acc += w;
  }
  return `linear-gradient(${angle}, ${stops.join(", ")})`;
}

type ChevronSegKind = "first" | "middle" | "last" | "only";

/** All indices use middle geometry (kind ignored by clip-path). */
function chevronKindForIndex(_i: number, _n: number): ChevronSegKind {
  return "middle";
}

/**
 * Labeled stage chevron: solid per-stage color + same interlocking shape on every index.
 * Arrow-in (concave V) on inline-start, slight arrow-out tip on inline-end. No neighbor blend.
 * Clip only on the outer shell so descendants inherit one clean chevron (no flat mid segments).
 * Fill + track are opaque solids; later slots stack above earlier (see chevronSlotStyle) so the
 * next body covers any tip overshoot instead of painting a previous-color needle inside.
 */
function ChevronBarSegment({
  dir,
  kind: _kind,
  tipPct,
  height,
  color,
  fillRatio,
  active,
  empty,
  stroke,
  trackBg,
}: {
  dir: "ltr" | "rtl";
  kind: ChevronSegKind;
  tipPct: number;
  height: number;
  color: string;
  /** 0–1 how much of this segment is filled. */
  fillRatio: number;
  active?: boolean;
  empty?: boolean;
  stroke: string;
  trackBg: string;
}) {
  const clip = chevronSegmentClipPath(dir, "middle", tipPct);
  const filled = Math.max(0, Math.min(1, fillRatio));
  const showFill = filled > 0.001 && !empty;
  /** Constant inset so every stage strip is the same ~9px fill (not taller when active). */
  const pad = STAGE_CHEVRON_BAR_PAD;

  return (
    <div
      aria-hidden
      style={{
        position: "relative",
        height,
        width: "100%",
        boxSizing: "border-box",
        background: stroke,
        clipPath: clip,
        WebkitClipPath: clip,
        isolation: "isolate",
        opacity: empty && !active ? 0.55 : 1,
        transition: "opacity 120ms ease",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: pad,
          background: trackBg,
          boxSizing: "border-box",
        }}
      />
      {showFill ? (
        <div
          style={{
            position: "absolute",
            inset: pad,
            overflow: "hidden",
            boxSizing: "border-box",
          }}
        >
          <div
            style={{
              height: "100%",
              width: "100%",
              background: color,
              transform: `scaleX(${filled >= 0.995 ? 1 : filled})`,
              transformOrigin: dir === "rtl" ? "100% 50%" : "0% 50%",
              transition: "transform 160ms ease",
            }}
          />
        </div>
      ) : null}
    </div>
  );
}

/** Flex row styles for nesting chevron segments (gap 0; slots pull together). */
function chevronRowStyle(
  dir: "ltr" | "rtl",
  _segmentCount: number,
): CSSProperties {
  return {
    direction: dir,
    display: "flex",
    flexDirection: "row",
    alignItems: "stretch",
    width: "100%",
    gap: 0,
    columnGap: 0,
    // Negative so each tip nests into the next segment’s notch.
    ["--chevron-overlap" as string]: chevronOverlapAmount(_segmentCount),
  };
}

function chevronSlotStyle(index: number, count: number): CSSProperties {
  const overlap = chevronOverlapAmount(count);
  return {
    // Equal stage widths matching first segment — labels cannot grow the slot.
    flex: "1 1 0",
    flexGrow: 1,
    flexShrink: 1,
    flexBasis: 0,
    width: 0,
    minWidth: 0,
    maxWidth: "100%",
    // Allow tip to nest into the next slot; next slot paints above (higher zIndex).
    overflow: "visible",
    position: "relative",
    // Later segments above earlier — next opaque body covers prior tip overshoot
    // so neighbor color never appears as a needle inside this stage.
    zIndex: index + 1,
    marginInlineEnd: index === count - 1 ? 0 : overlap,
  };
}

/**
 * Clickable stage slot: nesting styles last so they win over `all: unset`.
 * Used by Tax / Audit / WorkFlow / Monthly chevron rows.
 */
function chevronStageButtonStyle(
  index: number,
  count: number,
  opts?: { cursor?: string; gap?: number },
): CSSProperties {
  return {
    all: "unset",
    boxSizing: "border-box",
    cursor: opts?.cursor ?? "default",
    display: "flex",
    flexDirection: "column",
    gap: opts?.gap ?? 6,
    // Nest + equal-width last — must follow `all: unset`.
    ...chevronSlotStyle(index, count),
  };
}

/**
 * Labels sit under the bar and never affect slot width.
 * Two-line wrap + clamp so long stage names stay readable without
 * colliding into the next equal-width chevron slot (slots use overflow:visible
 * for tip nesting).
 */
function chevronStageLabelStyle(opts?: {
  color?: string;
  fontSize?: number;
  lineHeight?: string;
}): CSSProperties {
  const fontSize = opts?.fontSize ?? 10;
  const lineHeight = opts?.lineHeight ?? "13px";
  return {
    display: "-webkit-box",
    WebkitBoxOrient: "vertical",
    WebkitLineClamp: 2,
    width: "100%",
    minWidth: 0,
    maxWidth: "100%",
    boxSizing: "border-box",
    textAlign: "center",
    overflow: "hidden",
    whiteSpace: "normal",
    overflowWrap: "anywhere",
    wordBreak: "break-word",
    // Slight gutter so neighbor labels don’t kiss at the chevron overlap.
    paddingInline: 4,
    color: opts?.color,
    fontSize,
    lineHeight,
    maxHeight: `calc(${lineHeight} * 2)`,
  };
}

/**
 * Overall progress: invisible full-width layout track (no box). Fill grows as
 * a single piece with red→yellow→blue→green blend mapped to absolute %;
 * arrow-in + arrow-out via rounded SVG clip (Overall only — stages stay sharp).
 */
function OverallProgressBar({
  statuses,
  yearLines = [],
}: {
  statuses: WorkFlowStatus[];
  /** Which working years feed this average (shown under the title). */
  yearLines?: string[];
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const dir = uiDir(uiLang);
  const { percent } = computeOverallProgress(statuses);
  const clamped = Math.max(0, Math.min(100, percent));
  const n = OVERALL_PROGRESS_BANDS.length;
  const activeBandKey =
    OVERALL_PROGRESS_BANDS.find((b) => clamped <= b.maxPct)?.key ??
    OVERALL_PROGRESS_BANDS[n - 1]!.key;
  const bandColors = OVERALL_PROGRESS_BANDS.map((b) =>
    overallProgressBandColor(theme, b.key),
  );
  const fullGradient = blendProgressGradient(bandColors, dir);
  const barH = 18;
  /** Shallow tip for Overall fill only — stages keep CHEVRON_TIP_PCT. */
  const tipPct = OVERALL_CHEVRON_TIP_PCT;
  const clipId = "crm-overall-progress-rounded-chevron";
  const roundedPath = overallRoundedChevronPath(dir, tipPct);
  /**
   * Tip depth is tipPct% of the fill box; inflate so the apex tracks progress.
   * tipPct=2.5 → factor ≈ 1.0256 (≈102.6%), well under prior ~120% misread.
   */
  const tipWidthFactor = 100 / (100 - tipPct);
  const fillWidthPct =
    clamped > 0 ? Math.min(clamped * tipWidthFactor, 100 + tipPct) : 0;
  /** Expand gradient layer to full-track width so color stops stay absolute. */
  const gradientWidthPct =
    fillWidthPct > 0 ? (100 / fillWidthPct) * 100 : 100;

  return (
    <Stack gap={4} style={{ width: "100%" }}>
      <Row align="center" gap={8} wrap={false} style={{ width: "100%", minWidth: 0 }}>
        <ChromeText size="small" weight="semibold" tone="secondary" style={{ flexShrink: 0 }}>
          {t(uiLang, "overallProgress")}
        </ChromeText>
        {yearLines.length > 0 ? (
          <Row align="center" gap={4} wrap={false} style={{ flexShrink: 1, minWidth: 0, overflow: "hidden" }}>
            {yearLines.map((line) => (
              <Pill key={line} size="sm" tone="neutral">
                {line}
              </Pill>
            ))}
          </Row>
        ) : (
          <ChromeText size="small" tone="tertiary" style={{ flexShrink: 1, minWidth: 0 }}>
            {t(uiLang, "overallProgressHint")}
          </ChromeText>
        )}
        <Spacer />
        <ChromeText
          size="small"
          weight="semibold"
          style={{
            flexShrink: 0,
            color:
              clamped <= 0
                ? CHROME_INK_MUTED
                : overallProgressBandColor(theme, activeBandKey),
          }}
        >
          {clamped}%
        </ChromeText>
      </Row>
      <div
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={clamped}
        aria-label={t(uiLang, "overallProgress")}
        dir={dir}
        style={{
          direction: dir,
          position: "relative",
          width: "100%",
          height: barH,
          boxSizing: "border-box",
        }}
      >
        <svg
          aria-hidden
          width={0}
          height={0}
          style={{ position: "absolute", overflow: "hidden" }}
        >
          <defs>
            <clipPath id={clipId} clipPathUnits="objectBoundingBox">
              <path d={roundedPath} />
            </clipPath>
          </defs>
        </svg>
        {clamped > 0 ? (
          <div
            aria-hidden
            style={{
              position: "absolute",
              insetBlockStart: 0,
              insetBlockEnd: 0,
              insetInlineStart: 0,
              width: `${fillWidthPct}%`,
              maxWidth: `${100 + tipPct}%`,
              boxSizing: "border-box",
              clipPath: `url(#${clipId})`,
              WebkitClipPath: `url(#${clipId})`,
              overflow: "hidden",
              transition: "width 160ms ease",
            }}
          >
            <div
              style={{
                position: "absolute",
                insetBlockStart: 0,
                insetBlockEnd: 0,
                insetInlineStart: 0,
                width: `${gradientWidthPct}%`,
                height: "100%",
                background: fullGradient,
              }}
            />
          </div>
        ) : null}
      </div>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          flexWrap: "wrap",
          alignItems: "center",
          justifyContent: "flex-start",
          gap: 16,
          width: "100%",
          boxSizing: "border-box",
        }}
      >
        {OVERALL_PROGRESS_BANDS.map((band, i) => {
          const from = i === 0 ? 0 : OVERALL_PROGRESS_BANDS[i - 1]!.maxPct;
          return (
            <div
              key={band.key}
              style={{
                display: "inline-flex",
                flexDirection: "row",
                alignItems: "center",
                gap: 6,
                flexShrink: 0,
              }}
            >
              <span
                aria-hidden
                style={{
                  width: 8,
                  height: 8,
                  borderRadius: 2,
                  background: overallProgressBandColor(theme, band.key),
                  flexShrink: 0,
                }}
              />
              <ChromeText size="small" tone="tertiary" style={{ whiteSpace: "nowrap" }}>
                {from}–{band.maxPct}%
              </ChromeText>
            </div>
          );
        })}
      </div>
    </Stack>
  );
}

/**
 * In-module section nav. Default `layout="side"` = department side pane
 * (Bookkeeping / Audit / Tax). `layout="top"` = horizontal raised tabs
 * (Clients landing Inbox & tasks). ModuleSectionFrame always uses the side pane.
 */
type ModuleSectionTabItem = {
  id: string;
  label: string;
  badge?: string;
  /** Optional red/yellow/green status dot (e.g. Bookkeeping → VAT). */
  status?: WorkFlowStatus;
};

type TabBarVariant = "raised" | "gmail";

const RAISED_TAB_ACCENT_BAR_PX = 3;
/** Shared department subsection side pane width (~160–200px). */
const MODULE_SECTION_PANE_WIDTH = 180;

/**
 * Shared tab face — `raised` = classic folder tabs; `gmail` = underline only.
 */
function raisedTabFaceStyle(
  theme: ReturnType<typeof useHostTheme>,
  selected: boolean,
  opts?: { compact?: boolean; variant?: TabBarVariant },
): CSSProperties {
  const variant = opts?.variant ?? "raised";
  if (variant === "gmail") {
    const accent = theme.accent.primary;
    return {
      appearance: "none",
      WebkitAppearance: "none",
      background: "transparent",
      backgroundColor: "transparent",
      borderStyle: "solid",
      borderWidth: 0,
      borderTopWidth: 0,
      borderLeftWidth: 0,
      borderRightWidth: 0,
      borderBottomWidth: 3,
      borderTopColor: "transparent",
      borderLeftColor: "transparent",
      borderRightColor: "transparent",
      borderBottomColor: selected ? accent : "transparent",
      borderRadius: 0,
      transform: "none",
      zIndex: 0,
      marginBottom: -1,
      boxShadow: "none",
      paddingBlock: opts?.compact ? 8 : undefined,
      paddingInline: opts?.compact ? 10 : undefined,
    };
  }
  const topHighlight = selected
    ? theme.accent.primary
    : CHROME_BORDER_BLUE;
  const sideEdge = CHROME_BORDER_BLUE;
  return {
    appearance: "none",
    WebkitAppearance: "none",
    /** Selected = soft blue face; idle = white (never muddy grey). */
    background: selected ? CHROME_SOFT_BLUE : CHROME_WHITE,
    borderBlockStartWidth: selected ? 2 : 1,
    borderInlineStartWidth: 1,
    borderInlineEndWidth: 1,
    borderBlockEndWidth: 0,
    borderStyle: "solid",
    borderBlockStartColor: topHighlight,
    borderInlineStartColor: sideEdge,
    borderInlineEndColor: sideEdge,
    borderBlockEndColor: "transparent",
    borderStartStartRadius: selected ? 9 : 7,
    borderStartEndRadius: selected ? 9 : 7,
    borderEndStartRadius: 0,
    borderEndEndRadius: 0,
    transform: selected ? "translateY(-2px)" : "none",
    zIndex: selected ? 1 : 0,
    marginBottom: selected ? -1 : 0,
    boxShadow: "none",
    paddingBlock: opts?.compact ? 5 : undefined,
    paddingInline: opts?.compact ? 10 : undefined,
  };
}

/** Solid accent Pop out / Put back pill — card tabs + process ModuleSectionTabs. */
function ChromePopOutPillButton({
  active,
  onClick,
  fullWidth = false,
}: {
  active?: boolean;
  onClick: () => void;
  /** Optional full-width stretch (unused for content-header placement). */
  fullWidth?: boolean;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const popTitle = active
    ? t(uiLang, "putBackTabTitle")
    : t(uiLang, "popOutTabTitle");
  const popLabel = active ? t(uiLang, "putBackTab") : t(uiLang, "popOutTab");
  return (
    <button
      type="button"
      title={popTitle}
      aria-label={popTitle}
      aria-pressed={!!active}
      onClick={onClick}
      style={{
        all: "unset",
        cursor: "pointer",
        boxSizing: "border-box",
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        height: 30,
        paddingBlock: 0,
        paddingInline: 12,
        borderRadius: 16,
        border: "1px solid transparent",
        background: theme.accent.control,
        color: theme.text.onAccent,
        font: "inherit",
        fontSize: 12,
        fontWeight: 600,
        letterSpacing: 0.1,
        whiteSpace: "nowrap",
        flexShrink: 0,
        userSelect: "none",
        width: fullWidth ? "100%" : undefined,
      }}
    >
      {popLabel}
    </button>
  );
}

function ModuleSectionTabs({
  ariaLabel,
  title,
  items,
  activeId,
  onSelect,
  popOutDragPanelId,
  layout = "side",
}: {
  ariaLabel: string;
  title?: string;
  items: ModuleSectionTabItem[];
  activeId: string;
  onSelect: (id: string) => void;
  /** When set, section tabs drag to pop this process into dual-pane. */
  popOutDragPanelId?: string;
  /**
   * `side` = department left/right pane (default).
   * `top` = horizontal raised folder tabs (Boards Inbox & tasks).
   */
  layout?: "side" | "top";
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const accent = theme.accent.primary;
  const dir = uiDir(uiLang);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  if (layout === "top") {
    return (
      <nav
        aria-label={ariaLabel}
        dir={dir}
        style={{
          boxSizing: "border-box",
          overflowX: "auto",
          width: "100%",
        }}
      >
        <Stack gap={6}>
          {title ? (
            <ChromeText
              size="small"
              weight="semibold"
              style={{ color: theme.category.blue }}
            >
              {title}
            </ChromeText>
          ) : null}
          <div
            role="tablist"
            aria-orientation="horizontal"
            style={{
              display: "flex",
              flexDirection: "row",
              flexWrap: "wrap",
              alignItems: "flex-end",
              gap: 0,
              columnGap: 0,
              rowGap: 2,
              width: "100%",
              paddingTop: 6,
              borderBottom: `1px solid ${CHROME_BORDER_BLUE}`,
              background: CHROME_TABSTRIP_BG,
              boxSizing: "border-box",
            }}
          >
            {items.map((item) => {
              const active = activeId === item.id;
              const face = raisedTabFaceStyle(theme, active, {
                variant: "raised",
              });
              return (
                <button
                  key={item.id}
                  type="button"
                  role="tab"
                  aria-selected={active}
                  onClick={() => onSelect(item.id)}
                  aria-current={active ? "page" : undefined}
                  style={{
                    ...face,
                    boxSizing: "border-box",
                    cursor: "pointer",
                    position: "relative",
                    display: "inline-flex",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: 6,
                    margin: 0,
                    marginInlineEnd: -1,
                    padding: "0 12px",
                    height: 40,
                    minWidth: 80,
                    flex: "1 0 auto",
                    flexShrink: 0,
                    outline: "none",
                    color: active ? accent : chromeReadableIdle(theme),
                    font: "inherit",
                  }}
                >
                  {item.status ? (
                    <StatusBlob status={item.status} size={8} />
                  ) : null}
                  <span
                    style={{
                      color: active ? accent : chromeReadableIdle(theme),
                      fontSize: 13,
                      fontWeight: active ? 600 : 400,
                      lineHeight: 1.3,
                    }}
                  >
                    {item.label}
                  </span>
                  {item.badge ? (
                    <Pill size="sm" tone="warning">
                      {item.badge}
                    </Pill>
                  ) : null}
                  {active ? (
                    <span
                      aria-hidden
                      style={{
                        position: "absolute",
                        left: 0,
                        right: 0,
                        bottom: 0,
                        height: RAISED_TAB_ACCENT_BAR_PX,
                        background: accent,
                        borderTopLeftRadius: 2,
                        borderTopRightRadius: 2,
                      }}
                    />
                  ) : null}
                </button>
              );
            })}
          </div>
        </Stack>
      </nav>
    );
  }

  return (
    <nav
      aria-label={ariaLabel}
      dir={dir}
      style={{
        boxSizing: "border-box",
        width: MODULE_SECTION_PANE_WIDTH,
        minWidth: MODULE_SECTION_PANE_WIDTH,
        maxWidth: MODULE_SECTION_PANE_WIDTH,
        flexShrink: 0,
        alignSelf: "stretch",
        padding: "10px 8px",
        borderRadius: 10,
        border: `1px solid ${CHROME_BORDER_BLUE}`,
        background: CHROME_PANE_BG,
        overflowY: "auto",
      }}
    >
      <Stack gap={8}>
        {title ? (
          <ChromeText
            size="small"
            weight="semibold"
            style={{ color: theme.category.blue, paddingInline: 6 }}
          >
            {title}
          </ChromeText>
        ) : null}
        <div
          role="tablist"
          aria-orientation="vertical"
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "stretch",
            gap: 2,
            width: "100%",
            boxSizing: "border-box",
          }}
        >
          {items.map((item) => {
            const active = activeId === item.id;
            return (
              <button
                key={item.id}
                type="button"
                role="tab"
                aria-selected={active}
                title={
                  popOutDragPanelId
                    ? `${item.label} — ${t(uiLang, "dragTabToPopOut")}`
                    : item.label
                }
                draggable={!!popOutDragPanelId}
                onDragStart={(e: DragEvent) => {
                  if (!popOutDragPanelId || !e.dataTransfer) return;
                  beginPopOutTabDrag(popOutDragPanelId, e.dataTransfer);
                  setDraggingId(item.id);
                }}
                onDragEnd={(e: DragEvent) => {
                  setDraggingId(null);
                  endPopOutTabDrag(e.clientX);
                }}
                onClick={() => onSelect(item.id)}
                aria-current={active ? "page" : undefined}
                style={{
                  appearance: "none",
                  WebkitAppearance: "none",
                  boxSizing: "border-box",
                  cursor: popOutDragPanelId
                    ? draggingId === item.id
                      ? "grabbing"
                      : "grab"
                    : "pointer",
                  position: "relative",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "flex-start",
                  gap: 6,
                  margin: 0,
                  width: "100%",
                  padding: "8px 10px",
                  minHeight: 36,
                  outline: "none",
                  font: "inherit",
                  textAlign: "start",
                  color: active ? accent : chromeReadableIdle(theme),
                  background: active ? CHROME_SOFT_BLUE : CHROME_WHITE,
                  borderStyle: "solid",
                  borderWidth: 1,
                  borderColor: active ? CHROME_BORDER_BLUE : "transparent",
                  borderInlineStartWidth: active
                    ? RAISED_TAB_ACCENT_BAR_PX
                    : 1,
                  borderInlineStartColor: active ? accent : "transparent",
                  borderRadius: 8,
                  opacity: draggingId === item.id ? 0.72 : 1,
                  userSelect: "none",
                }}
              >
                {item.status ? (
                  <StatusBlob status={item.status} size={8} />
                ) : null}
                <span
                  style={{
                    flex: 1,
                    minWidth: 0,
                    color: active ? accent : chromeReadableIdle(theme),
                    fontSize: 13,
                    fontWeight: active ? 600 : 400,
                    lineHeight: 1.3,
                  }}
                >
                  {item.label}
                </span>
                {item.badge ? (
                  <Pill size="sm" tone="warning">
                    {item.badge}
                  </Pill>
                ) : null}
              </button>
            );
          })}
        </div>
      </Stack>
    </nav>
  );
}


/**
 * Side pane + main content. `dir` from UI lang puts the pane on the logical
 * start (left in EN, right in HE) and pushes Overview / section body over.
 */
function ModuleSectionFrame({
  ariaLabel,
  title,
  items,
  activeId,
  onSelect,
  children,
  contentStyle,
  minHeight = 360,
  popOutActive,
  onTogglePopOut,
  popOutPanelId,
}: {
  ariaLabel: string;
  title?: string;
  items: ModuleSectionTabItem[];
  activeId: string;
  onSelect: (id: string) => void;
  children?: Parameters<typeof Stack>[0]["children"];
  contentStyle?: CSSProperties;
  minHeight?: number | string;
  /** Process dual-pane — solid blue Pop out at top-trailing of content pane. */
  popOutActive?: boolean;
  onTogglePopOut?: () => void;
  /** Client-card panel id dragged from section tabs (e.g. stream-audit). */
  popOutPanelId?: string;
}) {
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const dir = uiDir(uiLang);
  return (
    <div
      dir={dir}
      style={{
        display: "flex",
        flexDirection: "row",
        flexWrap: "nowrap",
        alignItems: "stretch",
        gap: 12,
        minHeight,
        width: "100%",
        boxSizing: "border-box",
      }}
    >
      <ModuleSectionTabs
        ariaLabel={ariaLabel}
        title={title}
        items={items}
        activeId={activeId}
        onSelect={onSelect}
        popOutDragPanelId={
          onTogglePopOut && popOutPanelId ? popOutPanelId : undefined
        }
      />
      <div
        style={{
          flex: "1 1 0",
          minWidth: 0,
          minHeight: 0,
          alignSelf: "stretch",
          boxSizing: "border-box",
          ...contentStyle,
        }}
      >
        {onTogglePopOut ? (
          <div
            dir={dir}
            style={{
              direction: dir,
              display: "flex",
              flexDirection: "row",
              justifyContent: "flex-end",
              alignItems: "center",
              width: "100%",
              flexShrink: 0,
              marginBottom: 8,
              boxSizing: "border-box",
            }}
          >
            <ChromePopOutPillButton
              active={popOutActive}
              onClick={onTogglePopOut}
            />
          </div>
        ) : null}
        {children}
      </div>
    </div>
  );
}

type RaisedTabItem = {
  id: string;
  label: string;
  /** Optional count (e.g. Overview to-dos) shown inline after the label. */
  badgeCount?: number;
  /** Optional red/yellow/green status dot beside the label. */
  status?: WorkFlowStatus;
  /** Important process mark (!). */
  important?: boolean;
};

type GmailTabItem = RaisedTabItem & {
  id: ClientCardPanel;
};

/**
 * Shared horizontal tab bar (client card, leave admin, billing, time clock).
 * `variant="raised"` = classic folder tabs; `variant="gmail"` = underline.
 * Default stays gmail for billing/boards call sites; client card passes raised.
 * Optional `trailingAction` sits on the inline-end (right in LTR) opposite the tabs.
 */
function RaisedTabBar({
  tabs,
  activeId,
  onSelect,
  ariaLabel,
  variant = "gmail",
  compact = false,
  trailingAction,
  enablePopOutTabDrag = false,
}: {
  tabs: RaisedTabItem[];
  activeId: string;
  onSelect: (id: string) => void;
  ariaLabel: string;
  variant?: TabBarVariant;
  /** Tighter padding / height (Docs folder tabs, dense strips). */
  compact?: boolean;
  trailingAction?: {
    label: string;
    title: string;
    pressed?: boolean;
    onClick: () => void;
  } | null;
  /** Client-card: drag a tab toward the second pane to pop it out. */
  enablePopOutTabDrag?: boolean;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const accent = theme.accent.primary;
  const raised = variant === "raised";
  const [draggingTabId, setDraggingTabId] = useState<string | null>(null);
  /**
   * Keep DOM order (Overview first). With dir=rtl + flex, the first tab
   * paints on the RIGHT; wrap still starts each new row from the right.
   * Never use row-reverse under the RTL shell — that double-flips to LTR.
   */
  const tabDir = uiDir(uiLang);

  return (
    <div
      dir={tabDir}
      style={{
        direction: tabDir,
        display: "flex",
        flexDirection: "row",
        flexWrap: "nowrap",
        alignItems: "flex-end",
        justifyContent: "flex-start",
        columnGap: compact ? 4 : 8,
        width: "100%",
        paddingTop: raised ? (compact ? 2 : 6) : 0,
        paddingInline: 0,
        borderBottom: `1px solid ${CHROME_BORDER_BLUE}`,
        background: raised ? CHROME_TABSTRIP_BG : "transparent",
        boxSizing: "border-box",
      }}
    >
      <div
        role="tablist"
        aria-label={ariaLabel}
        aria-orientation="horizontal"
        style={{
          direction: tabDir,
          display: "flex",
          flexDirection: "row",
          flexWrap: "wrap",
          alignItems: "flex-end",
          justifyContent: "flex-start",
          columnGap: 0,
          rowGap: raised ? 2 : 0,
          flex: "1 1 auto",
          minWidth: 0,
          /* overflow-x:hidden computes overflow-y to clip — cuts raised tab labels */
          overflow: raised ? "visible" : "auto",
          boxSizing: "border-box",
        }}
      >
        {tabs.map((tab) => {
          const selected = activeId === tab.id;
          const face = raisedTabFaceStyle(theme, selected, {
            variant,
            compact,
          });
          return (
            <button
              key={tab.id}
              type="button"
              role="tab"
              aria-selected={selected}
              title={
                enablePopOutTabDrag
                  ? `${
                      tab.status
                        ? `${tab.label} — ${workFlowLabel(uiLang, tab.status)}`
                        : tab.label
                    } — ${t(uiLang, "dragTabToPopOut")}`
                  : tab.status
                    ? `${tab.label} — ${workFlowLabel(uiLang, tab.status)}`
                    : tab.label
              }
              draggable={enablePopOutTabDrag}
              onDragStart={(e: DragEvent) => {
                if (!enablePopOutTabDrag || !e.dataTransfer) return;
                beginPopOutTabDrag(tab.id, e.dataTransfer);
                setDraggingTabId(tab.id);
              }}
              onDragEnd={(e: DragEvent) => {
                setDraggingTabId(null);
                endPopOutTabDrag(e.clientX);
              }}
              onClick={() => onSelect(tab.id)}
              style={{
                ...face,
                cursor: enablePopOutTabDrag
                  ? draggingTabId === tab.id
                    ? "grabbing"
                    : "grab"
                  : "pointer",
                opacity: draggingTabId === tab.id ? 0.72 : 1,
                userSelect: enablePopOutTabDrag ? "none" : undefined,
                position: raised ? "relative" : undefined,
                display: "inline-flex",
                flexDirection: "row",
                flex: raised ? "0 0 auto" : undefined,
                flexGrow: raised ? 0 : undefined,
                flexShrink: 0,
                alignItems: "center",
                justifyContent: "center",
                gap: compact ? 4 : 6,
                margin: 0,
                marginInlineEnd: raised ? -1 : 0,
                minWidth: raised ? (compact ? 56 : 80) : undefined,
                minHeight: raised ? (compact ? 28 : 36) : undefined,
                height: raised ? "auto" : undefined,
                padding: raised
                  ? compact
                    ? "4px 10px"
                    : "8px 12px"
                  : compact
                    ? "6px 10px 5px"
                    : "10px 12px 8px",
                boxSizing: "border-box",
                outline: "none",
                overflow: "visible",
                font: "inherit",
                fontSize: compact ? 12 : undefined,
                color: selected ? accent : chromeReadableIdle(theme),
                whiteSpace: "nowrap",
                writingMode: "horizontal-tb",
                textOrientation: "mixed",
              }}
            >
              {tab.status ? <StatusBlob status={tab.status} size={8} /> : null}
              {tab.important ? (
                <ChromeText
                  as="span"
                  size="small"
                  weight="semibold"
                  style={{ color: theme.category.red, lineHeight: 1, margin: 0 }}
                >
                  !
                </ChromeText>
              ) : null}
              <ChromeText
                as="span"
                size="small"
                weight={selected ? "semibold" : "normal"}
                style={{
                  margin: 0,
                  whiteSpace: "nowrap",
                  writingMode: "horizontal-tb",
                  lineHeight: 1.25,
                  color: selected ? accent : chromeReadableIdle(theme),
                }}
              >
                {tab.label}
              </ChromeText>
              {tab.badgeCount != null ? (
                <span
                  style={{
                    minWidth: compact ? 16 : 18,
                    height: compact ? 14 : 16,
                    padding: compact ? "0 4px" : "0 5px",
                    borderRadius: 4,
                    background: selected
                      ? accent
                      : waveChipAlpha(theme.category.blue, "22"),
                    color: selected
                      ? theme.text.onAccent
                      : theme.category.blue,
                    fontSize: compact ? 9 : 10,
                    fontWeight: 600,
                    lineHeight: compact ? "14px" : "16px",
                    textAlign: "center",
                    boxSizing: "border-box",
                  }}
                >
                  {tab.badgeCount}
                </span>
              ) : null}
              {raised && selected ? (
                <span
                  aria-hidden
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 0,
                    bottom: 0,
                    height: RAISED_TAB_ACCENT_BAR_PX,
                    background: accent,
                    borderTopLeftRadius: 2,
                    borderTopRightRadius: 2,
                  }}
                />
              ) : null}
            </button>
          );
        })}
      </div>
      {trailingAction ? (
        <button
          type="button"
          title={trailingAction.title}
          aria-label={trailingAction.title}
          aria-pressed={trailingAction.pressed}
          onClick={trailingAction.onClick}
          style={{
            all: "unset",
            cursor: "pointer",
            boxSizing: "border-box",
            flexShrink: 0,
            alignSelf: "center",
            marginInlineStart: "auto",
            marginInlineEnd: 12,
            marginBottom: raised ? 6 : 8,
            height: 28,
            padding: "0 10px",
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            borderRadius: 6,
            border: trailingAction.pressed
              ? `1px solid ${accent}`
              : `1px solid ${CHROME_BORDER_BLUE}`,
            background: trailingAction.pressed ? CHROME_SOFT_BLUE : CHROME_WHITE,
            color: trailingAction.pressed ? accent : CHROME_INK_MUTED,
            fontWeight: 600,
            fontSize: 12,
            whiteSpace: "nowrap",
          }}
        >
          {trailingAction.label}
        </button>
      ) : null}
    </div>
  );
}

/**
 * Client-card tabs — raised folder chrome (typed to ClientCardPanel).
 * One Pop out / Put back control sits below the tab strip (trailing end),
 * styled as a solid accent pill like Compose — not inline with the tabs.
 */
function GmailTabBar({
  tabs,
  activeId,
  onSelect,
  popOutActive,
  onTogglePopOut,
}: {
  tabs: GmailTabItem[];
  activeId: ClientCardPanel;
  onSelect: (id: ClientCardPanel) => void;
  /** Dual-pane is showing — button label becomes Put back. */
  popOutActive?: boolean;
  onTogglePopOut?: () => void;
}) {
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const tabDir = uiDir(uiLang);

  return (
    <div
      style={{
        width: "100%",
        display: "flex",
        flexDirection: "column",
        boxSizing: "border-box",
      }}
    >
      <RaisedTabBar
        tabs={tabs}
        activeId={activeId}
        onSelect={(id) => onSelect(id as ClientCardPanel)}
        ariaLabel={t(uiLang, "clientCard")}
        variant="raised"
        enablePopOutTabDrag={!!onTogglePopOut}
      />
      {onTogglePopOut ? (
        <div
          dir={tabDir}
          style={{
            direction: tabDir,
            display: "flex",
            flexDirection: "row",
            justifyContent: "flex-end",
            alignItems: "center",
            width: "100%",
            paddingBlock: 8,
            paddingInline: 12,
            boxSizing: "border-box",
            background: CHROME_TABSTRIP_BG,
          }}
        >
          <ChromePopOutPillButton
            active={popOutActive}
            onClick={onTogglePopOut}
          />
        </div>
      ) : null}
    </div>
  );
}


