/** Derive a stable demo send-from address from worker id / name. */
function deriveWorkerEmail(id: string, name: string): string {
  const fromName = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ".")
    .replace(/^\.+|\.+$/g, "");
  const fromId = id
    .replace(/^staff-/, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ".");
  const local = fromName || fromId || "worker";
  return `${local}@intertax.example`;
}

function deriveWorkerSignatureName(name: string): string {
  return name.trim() || "Staff";
}

function deriveWorkerSignatureBody(
  name: string,
  nameHe: string,
  email: string,
): string {
  const lines = [
    name.trim(),
    nameHe.trim() && nameHe.trim() !== name.trim() ? nameHe.trim() : "",
    "Intertax",
    email,
  ].filter(Boolean);
  return lines.join("\n");
}

