function normalizeFirmWorker(w: {
  id: string;
  name: string;
  nameHe: string;
  deptId?: string;
  deptIds?: string[];
  employeeTag: string;
  email?: string;
  phone?: string;
  emailSignatureName?: string;
  emailSignatureBody?: string;
  photoUrl?: string;
}): FirmWorker {
  const fallback = "reportDeptAccounting";
  let deptIds = (w.deptIds ?? []).filter(Boolean);
  if (deptIds.length === 0 && w.deptId) deptIds = [w.deptId];
  if (deptIds.length === 0) deptIds = [fallback];
  const primary =
    w.deptId && deptIds.includes(w.deptId) ? w.deptId : deptIds[0]!;
  deptIds = [primary, ...deptIds.filter((id) => id !== primary)];
  const seed = DEMO_WORKER_EMAIL_SEED[w.id];
  const email =
    (w.email ?? "").trim() ||
    seed?.email ||
    deriveWorkerEmail(w.id, w.name);
  const emailSignatureName =
    (w.emailSignatureName ?? "").trim() ||
    seed?.emailSignatureName ||
    deriveWorkerSignatureName(w.name);
  const emailSignatureBody =
    (w.emailSignatureBody ?? "").trim() ||
    seed?.emailSignatureBody ||
    deriveWorkerSignatureBody(w.name, w.nameHe, email);
  const phone =
    (w.phone ?? "").trim() ||
    seed?.phone ||
    deriveWorkerPhoneFromSignature(emailSignatureBody);
  const photoUrl =
    (w.photoUrl ?? "").trim() || DEMO_STAFF_PHOTO_SEED[w.id] || "";
  return {
    id: w.id,
    name: w.name,
    nameHe: w.nameHe,
    deptId: primary,
    deptIds,
    employeeTag: w.employeeTag,
    email,
    phone,
    emailSignatureName,
    emailSignatureBody,
    photoUrl,
  };
}

function deriveWorkerPhoneFromSignature(signatureBody: string): string {
  const lines = signatureBody
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  const last = lines[lines.length - 1] ?? "";
  if (/^\+?\d[\d\s\-()]{6,}$/.test(last)) return last;
  return "";
}

function normalizeFirmWorkers(
  workers: Array<{
    id: string;
    name: string;
    nameHe: string;
    deptId?: string;
    deptIds?: string[];
    employeeTag: string;
    email?: string;
    phone?: string;
    emailSignatureName?: string;
    emailSignatureBody?: string;
    photoUrl?: string;
  }>,
): FirmWorker[] {
  return workers.map(normalizeFirmWorker);
}

