/** Profile photo URL from firm roster (shared CRM staff avatar source). */
function staffPhotoUrl(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): string {
  const row =
    workers.find((s) => s.id === workerId) ??
    DEMO_STAFF.find((s) => s.id === workerId);
  return (row?.photoUrl ?? "").trim();
}

/** Resolve signed-in worker send-from + signature (normalized). */
function resolveWorkerEmailProfile(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): FirmWorker {
  const row =
    workers.find((w) => w.id === workerId) ??
    DEMO_STAFF.find((w) => w.id === workerId) ??
    DEMO_STAFF[0]!;
  return normalizeFirmWorker(row);
}

/** Signature block appended under template body when sending. */
function formatWorkerEmailSignatureBlock(worker: FirmWorker): string {
  const name = worker.emailSignatureName.trim() || worker.name;
  const body = worker.emailSignatureBody.trim();
  if (!body) return name;
  if (body.toLowerCase().startsWith(name.toLowerCase())) return body;
  return `${name}\n${body}`;
}

