/**
 * Firm profile board tabs (one per department membership).
 * Billing → Billing board; Audit → Audit board; etc.
 */
type FirmDeptBoardView =
  | "billingBoard"
  | "officeBoard"
  | "accountingBoard"
  | "taxBoard"
  | "auditBoard"
  | "managementBoard"
  | "individualTaxBoard";

function deptIdToFirmBoardView(deptId: string): FirmDeptBoardView | null {
  switch (deptId) {
    case "reportDeptBilling":
      return "billingBoard";
    case "reportDeptSecretariat":
      return "officeBoard";
    case "reportDeptAccounting":
      return "accountingBoard";
    case "reportDeptTax":
      return "taxBoard";
    case "reportDeptAuditCompanies":
      return "auditBoard";
    case "reportDeptManagement":
      return "managementBoard";
    case "reportDeptIndividualTaxReturn":
      return "individualTaxBoard";
    default:
      return null;
  }
}

function firmBoardViewToDeptId(view: FirmDeptBoardView): string {
  switch (view) {
    case "billingBoard":
      return "reportDeptBilling";
    case "officeBoard":
      return "reportDeptSecretariat";
    case "accountingBoard":
      return "reportDeptAccounting";
    case "taxBoard":
      return "reportDeptTax";
    case "auditBoard":
      return "reportDeptAuditCompanies";
    case "managementBoard":
      return "reportDeptManagement";
    case "individualTaxBoard":
      return "reportDeptIndividualTaxReturn";
  }
}

function firmBoardViewLabel(lang: UiLang, view: FirmDeptBoardView): string {
  switch (view) {
    case "billingBoard":
      return t(lang, "billingBoard");
    case "officeBoard":
      return t(lang, "officeBoards");
    case "accountingBoard":
      return t(lang, "accountingBoard");
    case "taxBoard":
      return t(lang, "taxBoard");
    case "auditBoard":
      return t(lang, "auditBoard");
    case "managementBoard":
      return t(lang, "managementBoard");
    case "individualTaxBoard":
      return t(lang, "individualTaxBoard");
  }
}

/** Ordered firm board tabs for this worker — one per deptIds entry. */
function workerFirmBoardViews(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): FirmDeptBoardView[] {
  const out: FirmDeptBoardView[] = [];
  const seen = new Set<FirmDeptBoardView>();
  for (const deptId of workerDeptIds(workerId, workers)) {
    const view = deptIdToFirmBoardView(deptId);
    if (!view || seen.has(view)) continue;
    seen.add(view);
    out.push(view);
  }
  return out;
}

/** Open Work → Boards on the worker’s first dept default tab (else My Boards). */
function preferredBoardsViewForWorker(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): FirmDeptBoardView | "board" {
  return workerFirmBoardViews(workerId, workers)[0] ?? "board";
}

function isFirmDeptBoardView(view: string): view is FirmDeptBoardView {
  return (
    view === "billingBoard" ||
    view === "officeBoard" ||
    view === "accountingBoard" ||
    view === "taxBoard" ||
    view === "auditBoard" ||
    view === "managementBoard" ||
    view === "individualTaxBoard"
  );
}

function workerCanSeeFirmBoardView(
  view: FirmDeptBoardView,
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): boolean {
  return workerFirmBoardViews(workerId, workers).includes(view);
}

