/** Demo module-access keys for Users & rights (not a full ACL). */
type StaffRightsModuleKey =
  | "clientWorkerTasks"
  | "adminModules"
  | "systemadminModules"
  | "timeClockTeam"
  | "billingOps";

type StaffRightsEntry = {
  workerId: string;
  role: Role;
  active: boolean;
  moduleAccess: Record<StaffRightsModuleKey, boolean>;
};

type StaffRightsMap = Record<string, StaffRightsEntry>;

const STAFF_RIGHTS_MODULE_KEYS: StaffRightsModuleKey[] = [
  "clientWorkerTasks",
  "adminModules",
  "systemadminModules",
  "timeClockTeam",
  "billingOps",
];

function defaultModuleAccessForRole(
  role: Role,
): Record<StaffRightsModuleKey, boolean> {
  if (role === "systemadmin") {
    return {
      clientWorkerTasks: true,
      adminModules: true,
      systemadminModules: true,
      timeClockTeam: true,
      billingOps: true,
    };
  }
  if (role === "admin") {
    return {
      clientWorkerTasks: true,
      adminModules: true,
      systemadminModules: false,
      timeClockTeam: true,
      billingOps: true,
    };
  }
  return {
    clientWorkerTasks: true,
    adminModules: false,
    systemadminModules: false,
    timeClockTeam: false,
    billingOps: false,
  };
}

/**
 * Demo System Admins who staff Help & feedback (can reply).
 * Same role gate as Systemadmin → Help & feedback inbox.
 */
const DEMO_HELP_SYSADMIN_IDS = [
  "staff-dana",
  "staff-noa",
  "staff-secretariat",
  "staff-audit",
  "staff-billing",
] as const;

/** Seed role: demo Help sysadmins → System Admin; Management → Manager; else Worker. */
function defaultRoleForWorker(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): Role {
  if (
    (DEMO_HELP_SYSADMIN_IDS as readonly string[]).includes(workerId)
  ) {
    return "systemadmin";
  }
  const row =
    workers.find((s) => s.id === workerId) ??
    DEMO_STAFF.find((s) => s.id === workerId);
  if (!row) return "worker";
  if (normalizeFirmWorker(row).deptIds.includes("reportDeptManagement")) {
    return "admin";
  }
  return "worker";
}

/** Persisted demo / future real presence for staff (Help FAB sysadmin faces). */
type StaffPresenceEntry = {
  online: boolean;
  /** ISO-ish timestamp of last online / login activity. */
  lastOnlineAt: string;
};

type StaffPresenceMap = Record<string, StaffPresenceEntry>;

const DEFAULT_STAFF_PRESENCE: StaffPresenceMap = {
  "staff-dana": { online: true, lastOnlineAt: "2026-10-13T00:52:00" },
  "staff-noa": { online: true, lastOnlineAt: "2026-10-13T00:50:00" },
  "staff-secretariat": { online: false, lastOnlineAt: "2026-10-12T18:20:00" },
  "staff-audit": { online: true, lastOnlineAt: "2026-10-13T00:41:00" },
  "staff-billing": { online: false, lastOnlineAt: "2026-10-12T16:05:00" },
  "staff-avi": { online: true, lastOnlineAt: "2026-10-13T00:55:00" },
};

function normalizeStaffPresenceMap(
  raw: StaffPresenceMap | null | undefined,
): StaffPresenceMap {
  const base: StaffPresenceMap = { ...DEFAULT_STAFF_PRESENCE };
  if (!raw || typeof raw !== "object") return base;
  for (const [id, entry] of Object.entries(raw)) {
    if (!entry || typeof entry !== "object") continue;
    base[id] = {
      online: Boolean(entry.online),
      lastOnlineAt:
        typeof entry.lastOnlineAt === "string" && entry.lastOnlineAt.trim()
          ? entry.lastOnlineAt.trim()
          : base[id]?.lastOnlineAt ?? "",
    };
  }
  return base;
}

function staffPresenceFor(
  workerId: string,
  presence: StaffPresenceMap | null | undefined,
  signedInWorkerId?: string,
): StaffPresenceEntry {
  const map = normalizeStaffPresenceMap(presence);
  const me = (signedInWorkerId || "").trim();
  if (me && workerId === me) {
    const prev = map[workerId];
    return {
      online: true,
      lastOnlineAt:
        prev?.lastOnlineAt || new Date().toISOString().slice(0, 19),
    };
  }
  return (
    map[workerId] ?? {
      online: false,
      lastOnlineAt: "",
    }
  );
}

function staffRightsRoleLabel(lang: UiLang, role: Role): string {
  if (role === "systemadmin") return t(lang, "systemAdmin");
  if (role === "admin") return t(lang, "roleAdminFull");
  return t(lang, "roleWorkerFull");
}

function normalizeStaffRightsEntry(
  entry: Partial<StaffRightsEntry> | null | undefined,
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): StaffRightsEntry {
  const role =
    entry?.role === "worker" ||
    entry?.role === "admin" ||
    entry?.role === "systemadmin"
      ? entry.role
      : defaultRoleForWorker(workerId, workers);
  const defaults = defaultModuleAccessForRole(role);
  const rawAccess = entry?.moduleAccess;
  const moduleAccess = { ...defaults };
  for (const key of STAFF_RIGHTS_MODULE_KEYS) {
    if (rawAccess && typeof rawAccess[key] === "boolean") {
      moduleAccess[key] = rawAccess[key];
    }
  }
  return {
    workerId,
    role,
    active: entry?.active !== false,
    moduleAccess,
  };
}

function resolveStaffRightsEntry(
  workerId: string,
  rightsMap: StaffRightsMap | null | undefined,
  workers: FirmWorker[] = DEMO_STAFF,
): StaffRightsEntry {
  return normalizeStaffRightsEntry(rightsMap?.[workerId], workerId, workers);
}

/** Demo role for directory: rights map → else Management dept → Manager. */
function staffDemoRoleLabel(
  lang: UiLang,
  workerId: string,
  rightsByWorker?: StaffRightsMap | null,
): string {
  return staffRightsRoleLabel(
    lang,
    resolveStaffRightsEntry(workerId, rightsByWorker).role,
  );
}

/** Firm worker treated as demo worker-admin (Management dept, else Dana, else first). */
function resolveDemoWorkerAdmin(
  workers: FirmWorker[] = DEMO_STAFF,
): FirmWorker {
  const list = normalizeFirmWorkers(
    Array.isArray(workers) && workers.length > 0 ? workers : DEMO_STAFF,
  );
  const mgmt = list.find((w) =>
    normalizeFirmWorker(w).deptIds.includes("reportDeptManagement"),
  );
  if (mgmt) return normalizeFirmWorker(mgmt);
  const dana = list.find((w) => w.id === "staff-dana");
  if (dana) return normalizeFirmWorker(dana);
  return normalizeFirmWorker(list[0] ?? DEMO_STAFF[0]!);
}

/** Latin initials for avatar circle (stable across EN|HE display name). */
function staffInitials(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): string {
  const row =
    workers.find((s) => s.id === workerId) ??
    DEMO_STAFF.find((s) => s.id === workerId);
  if (!row) return "?";
  return row.name
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

/**
 * Shared firm email template editor — Billing → Email templates and Template settings.
 * When `lockedCategory` is set, only that group is shown (Billing nav locks to billing).
 */
function BillingEmailTemplatesEditor({
  compact = false,
  lockedCategory,
}: {
  compact?: boolean;
  lockedCategory?: FirmEmailTemplateCategory;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [templatesRaw, setTemplates] = useCanvasState<BillingEmailTemplate[]>(
    "firmEmailTemplates.v1",
    DEFAULT_FIRM_EMAIL_TEMPLATES,
  );
  const allTemplates = templatesRaw.map(normalizeBillingEmailTemplate);
  const templates = lockedCategory
    ? allTemplates.filter((tpl) => tpl.category === lockedCategory)
    : allTemplates;
  const [selectedId, setSelectedId] = useCanvasState(
    "billingEmailTemplateSelected.v1",
    DEFAULT_BILLING_EMAIL_TEMPLATES[0]?.id ?? "",
  );
  const [flash, setFlash] = useCanvasState("billingEmailTemplateFlash.v1", "");
  const [formatTone, setFormatTone] = useCanvasState<BillingEmailColorTone>(
    "billingEmailFormatTone.v1",
    "accent",
  );
  const [previewLang, setPreviewLang] = useCanvasState<UiLang>(
    "billingEmailPreviewLang.v1",
    "en",
  );
  const [activeBodyLang, setActiveBodyLang] = useCanvasState<"en" | "he">(
    "billingEmailActiveBodyLang.v1",
    "en",
  );
  const [tplSearch, setTplSearch] = useCanvasState(
    "billingEmailTemplateSearch.v1",
    "",
  );
  const [mergeFieldsRaw] = useCanvasState<TemplateMergeField[]>(
    "templateMergeFields.v1",
    DEFAULT_TEMPLATE_MERGE_FIELDS,
  );
  const mergeFields = mergeTemplateMergeFieldsWithDefaults(mergeFieldsRaw);
  const [firmWorkers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const [signedInWorkerId] = useCanvasState(
    "signedInWorkerId.v1",
    DEMO_WORKER.id,
  );
  const senderProfile = resolveWorkerEmailProfile(
    signedInWorkerId,
    firmWorkers,
  );
  const senderSignatureBlock = formatWorkerEmailSignatureBlock(senderProfile);
  const logoFileRef = useRef<HTMLInputElement | null>(null);
  const bodyEnRef = useRef<HTMLTextAreaElement | null>(null);
  const bodyHeRef = useRef<HTMLTextAreaElement | null>(null);
  const selected =
    templates.find((tpl) => tpl.id === selectedId) ?? templates[0];

  const patchSelected = (patch: Partial<BillingEmailTemplate>) => {
    if (!selected) return;
    setTemplates((prev) =>
      prev.map((tpl) =>
        tpl.id === selected.id
          ? normalizeBillingEmailTemplate({ ...tpl, ...patch })
          : normalizeBillingEmailTemplate(tpl),
      ),
    );
  };

  const insertMergeToken = (key: string) => {
    if (!selected) return;
    const token = mergeFieldToken(key);
    if (!token || token === "{}") return;
    const ref = activeBodyLang === "en" ? bodyEnRef : bodyHeRef;
    const el = ref.current;
    const value = activeBodyLang === "en" ? selected.bodyEn : selected.bodyHe;
    const start = el?.selectionStart ?? value.length;
    const end = el?.selectionEnd ?? value.length;
    const next = value.slice(0, start) + token + value.slice(end);
    patchSelected(
      activeBodyLang === "en" ? { bodyEn: next } : { bodyHe: next },
    );
    requestAnimationFrame(() => {
      const node = ref.current;
      if (!node) return;
      node.focus();
      const pos = start + token.length;
      node.setSelectionRange(pos, pos);
    });
  };

  const addTemplate = () => {
    const id = `tpl-custom-${Date.now()}`;
    const category = lockedCategory ?? selected?.category ?? "billing";
    const next: BillingEmailTemplate = normalizeBillingEmailTemplate({
      id,
      nameEn: "New template",
      nameHe: "תבנית חדשה",
      subjectEn: "Subject — {client}",
      subjectHe: "נושא — {client}",
      bodyEn: "Hello {client},\n\n…\n",
      bodyHe: "שלום {client},\n\n…\n",
      ...DEFAULT_BILLING_EMAIL_STYLE,
      category,
      isDefault: templates.length === 0,
    });
    setTemplates((prev) => [
      ...prev.map(normalizeBillingEmailTemplate),
      next,
    ]);
    setSelectedId(id);
    setFlash("");
  };

  const deleteSelected = () => {
    if (!selected || templates.length <= 1) return;
    const nextAll = allTemplates.filter((tpl) => tpl.id !== selected.id);
    setTemplates(nextAll);
    const nextVisible = lockedCategory
      ? nextAll.filter((tpl) => tpl.category === lockedCategory)
      : nextAll;
    setSelectedId(nextVisible[0]?.id ?? "");
    setFlash("");
  };

  const onLogoFile = (file: File | null | undefined) => {
    if (!file || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = () => {
      const result = typeof reader.result === "string" ? reader.result : "";
      if (result) patchSelected({ logoDataUrl: result });
    };
    reader.readAsDataURL(file);
  };

  const applyBodyWrap = (
    lang: "en" | "he",
    before: string,
    after: string,
  ) => {
    if (!selected) return;
    const ref = lang === "en" ? bodyEnRef : bodyHeRef;
    const el = ref.current;
    const value = lang === "en" ? selected.bodyEn : selected.bodyHe;
    const start = el?.selectionStart ?? value.length;
    const end = el?.selectionEnd ?? value.length;
    const { next, selStart, selEnd } = wrapEmailBodySelection(
      value,
      start,
      end,
      before,
      after,
    );
    patchSelected(lang === "en" ? { bodyEn: next } : { bodyHe: next });
    requestAnimationFrame(() => {
      const node = ref.current;
      if (!node) return;
      node.focus();
      node.setSelectionRange(selStart, selEnd);
    });
  };

  const toolbarSelectStyle = {
    minWidth: 0,
    width: "auto",
    maxWidth: 140,
  } as const;

  const toolbarBtnStyle = {
    padding: "4px 8px",
    minWidth: 28,
    fontWeight: 600 as const,
  };

  if (!selected) return null;

  const colorToneOptions = [
    {
      value: "default",
      label: t(uiLang, "billingTemplateColorDefault"),
    },
    {
      value: "accent",
      label: t(uiLang, "billingTemplateColorAccent"),
    },
    {
      value: "secondary",
      label: t(uiLang, "billingTemplateColorSecondary"),
    },
    { value: "link", label: t(uiLang, "billingTemplateColorLink") },
    { value: "muted", label: t(uiLang, "billingTemplateColorMuted") },
  ];

  const composerToolbar = (
    <Row
      gap={6}
      align="center"
      wrap
      style={{
        width: "100%",
        padding: "6px 8px",
        borderRadius: 8,
        border: `1px solid ${chromeBorder(theme)}`,
        background: chromeSoftFill(theme),
        boxSizing: "border-box",
      }}
    >
      <Select
        value={selected.bodyFontFamily}
        onChange={(v) => patchSelected({ bodyFontFamily: v })}
        options={BILLING_EMAIL_FONT_OPTIONS}
        style={{ ...toolbarSelectStyle, maxWidth: 150 }}
      />
      <Select
        value={String(selected.bodyFontSizePx)}
        onChange={(v) => patchSelected({ bodyFontSizePx: Number(v) || 14 })}
        options={BILLING_EMAIL_SIZE_OPTIONS.map((s) => ({
          value: s,
          label: s,
        }))}
        style={{ ...toolbarSelectStyle, maxWidth: 64 }}
      />
      <Select
        value={selected.bodyTextTone}
        onChange={(v) =>
          patchSelected({ bodyTextTone: v as BillingEmailColorTone })
        }
        options={colorToneOptions.map((o) => ({
          ...o,
          label: `${t(uiLang, "billingTemplateTextColor")}: ${o.label}`,
        }))}
        style={{ ...toolbarSelectStyle, maxWidth: 150 }}
      />
      <Select
        value={selected.bodyBgTone}
        onChange={(v) =>
          patchSelected({
            bodyBgTone: v as BillingEmailColorTone | "none",
          })
        }
        options={[
          {
            value: "none",
            label: `${t(uiLang, "billingTemplateBgColor")}: ${t(uiLang, "billingTemplateNone")}`,
          },
          ...colorToneOptions
            .filter((o) => o.value !== "link")
            .map((o) => ({
              ...o,
              label: `${t(uiLang, "billingTemplateBgColor")}: ${o.label}`,
            })),
        ]}
        style={{ ...toolbarSelectStyle, maxWidth: 150 }}
      />
      <Select
        value={selected.bodyAlign}
        onChange={(v) =>
          patchSelected({ bodyAlign: v as BillingEmailBodyAlign })
        }
        options={[
          {
            value: "start",
            label: t(uiLang, "billingTemplateAlignStart"),
          },
          {
            value: "center",
            label: t(uiLang, "billingTemplateAlignCenter"),
          },
          {
            value: "end",
            label: t(uiLang, "billingTemplateAlignEnd"),
          },
        ]}
        style={{ ...toolbarSelectStyle, maxWidth: 96 }}
      />
      <div
        style={{
          width: 1,
          alignSelf: "stretch",
          background: chromeBorder(theme),
          marginInline: 2,
        }}
      />
      <button
        type="button"
        title={t(uiLang, "billingTemplateBold")}
        onClick={() => applyBodyWrap(activeBodyLang, "<b>", "</b>")}
        style={{
          all: "unset",
          boxSizing: "border-box",
          cursor: "pointer",
          borderRadius: 6,
          border: `1px solid ${CHROME_BORDER_BLUE}`,
          background: CHROME_WHITE,
          color: theme.text.primary,
          ...toolbarBtnStyle,
        }}
      >
        B
      </button>
      <button
        type="button"
        title={t(uiLang, "billingTemplateItalic")}
        onClick={() => applyBodyWrap(activeBodyLang, "<i>", "</i>")}
        style={{
          all: "unset",
          boxSizing: "border-box",
          cursor: "pointer",
          borderRadius: 6,
          border: `1px solid ${CHROME_BORDER_BLUE}`,
          background: CHROME_WHITE,
          color: theme.text.primary,
          fontStyle: "italic",
          ...toolbarBtnStyle,
        }}
      >
        I
      </button>
      <button
        type="button"
        title={t(uiLang, "billingTemplateUnderline")}
        onClick={() => applyBodyWrap(activeBodyLang, "<u>", "</u>")}
        style={{
          all: "unset",
          boxSizing: "border-box",
          cursor: "pointer",
          borderRadius: 6,
          border: `1px solid ${CHROME_BORDER_BLUE}`,
          background: CHROME_WHITE,
          color: theme.text.primary,
          textDecoration: "underline",
          ...toolbarBtnStyle,
        }}
      >
        U
      </button>
      <Select
        value={formatTone}
        onChange={(v) => setFormatTone(v as BillingEmailColorTone)}
        options={colorToneOptions}
        style={{ ...toolbarSelectStyle, maxWidth: 110 }}
      />
      <button
        type="button"
        title={t(uiLang, "billingTemplateApplyColor")}
        onClick={() => {
          const color = billingEmailToneColor(theme, formatTone);
          applyBodyWrap(
            activeBodyLang,
            `<span style="color:${color}">`,
            "</span>",
          );
        }}
        style={{
          all: "unset",
          boxSizing: "border-box",
          cursor: "pointer",
          borderRadius: 6,
          border: `1px solid ${CHROME_BORDER_BLUE}`,
          background: CHROME_WHITE,
          color: billingEmailToneColor(theme, formatTone),
          ...toolbarBtnStyle,
          minWidth: 32,
        }}
      >
        A
      </button>
      <ChromeText size="small" tone="tertiary" style={{ marginInlineStart: 4 }}>
        {activeBodyLang === "he" ? "HE" : "EN"}
      </ChromeText>
    </Row>
  );

  const previewBody = applyTemplateMergeFields(
    previewLang === "he" ? selected.bodyHe : selected.bodyEn,
    mergeFields,
    previewLang,
  );
  const previewSubject = applyTemplateMergeFields(
    previewLang === "he" ? selected.subjectHe : selected.subjectEn,
    mergeFields,
    previewLang,
  );
  const textColor = billingEmailToneColor(theme, selected.bodyTextTone);
  const bgColor =
    selected.bodyBgTone === "none"
      ? CHROME_WHITE
      : billingEmailToneColor(theme, selected.bodyBgTone);
  const logoJustify =
    selected.logoAlign === "center"
      ? "center"
      : selected.logoAlign === "end"
        ? "flex-end"
        : "flex-start";
  const bodyTextAlign =
    selected.bodyAlign === "center"
      ? "center"
      : selected.bodyAlign === "end"
        ? "right"
        : "left";

  const textareaStyle = {
    width: "100%",
    minHeight: compact ? 72 : 100,
    boxSizing: "border-box" as const,
    padding: "8px 10px",
    borderRadius: 8,
    border: `1px solid ${CHROME_BORDER_BLUE}`,
    background: chromeSoftFill(theme),
    color: theme.text.primary,
    fontFamily: selected.bodyFontFamily,
    fontSize: selected.bodyFontSizePx,
    lineHeight: 1.45,
    resize: "vertical" as const,
  };

  return (
    <Stack gap={compact ? 8 : 12} style={{ width: "100%" }}>
      {!compact ? (
        <Stack gap={4}>
          <H2>{t(uiLang, "billingTemplatesTitle")}</H2>
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "billingTemplatesHint")}
          </ChromeText>
        </Stack>
      ) : (
        <ChromeText size="small" tone="secondary">
          {t(uiLang, "userSettingsEmailTemplatesHint")}
        </ChromeText>
      )}
      {flash ? (
        <Callout tone="success" title={t(uiLang, "billingNavTemplates")}>
          {flash}
        </Callout>
      ) : null}
      <Stack gap={4}>
        <FieldLabel>{t(uiLang, "billingTemplatePick")}</FieldLabel>
        <SearchAutocomplete
          value={tplSearch}
          onChange={setTplSearch}
          placeholder={t(uiLang, "templatesSearchPlaceholder")}
          lang={uiLang}
          style={{ maxWidth: 420, width: "100%" }}
          candidates={uniqSearchCandidates(
            templates.flatMap((tpl) => [
              billingTemplateLabel(uiLang, tpl),
              tpl.nameEn,
              tpl.nameHe,
              tpl.subjectEn,
              tpl.subjectHe,
            ]),
          )}
          onAccept={(accepted) => {
            const q = accepted.trim().toLowerCase();
            const hit = templates.find((tpl) =>
              [
                billingTemplateLabel(uiLang, tpl),
                tpl.nameEn,
                tpl.nameHe,
                tpl.subjectEn,
                tpl.subjectHe,
              ].some((s) => s.trim().toLowerCase() === q),
            );
            if (hit) setSelectedId(hit.id);
          }}
        />
        <Select
          value={selected.id}
          onChange={setSelectedId}
          options={(tplSearch.trim()
            ? templates.filter((tpl) => {
                const q = tplSearch.trim().toLowerCase();
                return [
                  billingTemplateLabel(uiLang, tpl),
                  tpl.nameEn,
                  tpl.nameHe,
                  tpl.subjectEn,
                  tpl.subjectHe,
                ].some((s) => s.toLowerCase().includes(q));
              })
            : templates
          ).map((tpl) => ({
            value: tpl.id,
            label: billingTemplateLabel(uiLang, tpl),
          }))}
        />
      </Stack>
      <Grid columns={compact ? 1 : 2} gap={10}>
        <Stack gap={4}>
          <FieldLabel>{`${t(uiLang, "billingTemplateName")} (EN)`}</FieldLabel>
          <ChromeTextInput
            value={selected.nameEn}
            onChange={(v) => patchSelected({ nameEn: v })}
          />
        </Stack>
        <Stack gap={4}>
          <FieldLabel>{`${t(uiLang, "billingTemplateName")} (HE)`}</FieldLabel>
          <ChromeTextInput
            value={selected.nameHe}
            onChange={(v) => patchSelected({ nameHe: v })}
          />
        </Stack>
        <Stack gap={4}>
          <FieldLabel>{`${t(uiLang, "billingTemplateSubject")} (EN)`}</FieldLabel>
          <ChromeTextInput
            value={selected.subjectEn}
            onChange={(v) => patchSelected({ subjectEn: v })}
          />
        </Stack>
        <Stack gap={4}>
          <FieldLabel>{`${t(uiLang, "billingTemplateSubject")} (HE)`}</FieldLabel>
          <ChromeTextInput
            value={selected.subjectHe}
            onChange={(v) => patchSelected({ subjectHe: v })}
          />
        </Stack>
      </Grid>

      <Stack
        gap={10}
        style={{
          padding: compact ? 10 : 14,
          borderRadius: 10,
          border: `1px solid ${chromeBorder(theme)}`,
          background: chromeSoftFill(theme),
        }}
      >
        <Stack gap={4}>
          <ChromeText weight="semibold">{t(uiLang, "billingTemplateLogo")}</ChromeText>
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "billingTemplateLogoHint")}
          </ChromeText>
        </Stack>
        <input
          ref={logoFileRef}
          type="file"
          accept="image/*"
          style={{ display: "none" }}
          onChange={(e) => {
            onLogoFile(e.target.files?.[0]);
            e.target.value = "";
          }}
        />
        <Row gap={8} wrap>
          <Button
            variant="secondary"
            onClick={() => logoFileRef.current?.click()}
          >
            {t(uiLang, "billingTemplateLogoUpload")}
          </Button>
          <Button
            variant="ghost"
            onClick={() =>
              patchSelected({ logoDataUrl: SAMPLE_BILLING_EMAIL_LOGO })
            }
          >
            {t(uiLang, "billingTemplateLogoSample")}
          </Button>
          <Button
            variant="ghost"
            disabled={!selected.logoDataUrl}
            onClick={() => patchSelected({ logoDataUrl: "" })}
          >
            {t(uiLang, "billingTemplateLogoClear")}
          </Button>
        </Row>
        <Stack gap={4}>
          <FieldLabel>{t(uiLang, "billingTemplateLogoUrl")}</FieldLabel>
          <ChromeTextInput
            value={selected.logoDataUrl.startsWith("data:") ? "" : selected.logoDataUrl}
            onChange={(v) => patchSelected({ logoDataUrl: v.trim() })}
            placeholder="https://…"
          />
        </Stack>
        <Stack gap={4}>
          <FieldLabel>{t(uiLang, "billingTemplateLogoAlign")}</FieldLabel>
          <Select
            value={selected.logoAlign}
            onChange={(v) =>
              patchSelected({ logoAlign: v as BillingEmailLogoAlign })
            }
            options={[
              {
                value: "start",
                label: t(uiLang, "billingTemplateAlignStart"),
              },
              {
                value: "center",
                label: t(uiLang, "billingTemplateAlignCenter"),
              },
              { value: "end", label: t(uiLang, "billingTemplateAlignEnd") },
            ]}
          />
        </Stack>
        {selected.logoDataUrl ? (
          <div
            style={{
              display: "flex",
              justifyContent: logoJustify,
              padding: 8,
              borderRadius: 8,
              border: `1px solid ${chromeBorder(theme)}`,
              background: CHROME_WHITE,
            }}
          >
            <img
              src={selected.logoDataUrl}
              alt=""
              style={{ maxHeight: 48, maxWidth: "100%", objectFit: "contain" }}
            />
          </div>
        ) : null}
      </Stack>

      {composerToolbar}

      <Stack
        gap={6}
        style={{
          padding: compact ? 8 : 10,
          borderRadius: 8,
          border: `1px solid ${chromeBorder(theme)}`,
          background: chromeSoftFill(theme),
        }}
      >
        <Row gap={8} align="center" wrap>
          <ChromeText weight="semibold" size="small">
            {t(uiLang, "templateMergeFieldsAvailable")}
          </ChromeText>
          <ChromeText size="small" tone="tertiary">
            ({activeBodyLang === "he" ? "HE" : "EN"})
          </ChromeText>
        </Row>
        <ChromeText size="small" tone="secondary">
          {t(uiLang, "templateMergeFieldsInsertHint")}
        </ChromeText>
        <Row gap={6} wrap>
          {mergeFields.map((field) => (
            <button
              key={field.id}
              type="button"
              title={`${mergeFieldLabel(uiLang, field)} · ${t(uiLang, MERGE_SOURCE_UI_KEY[field.source])}`}
              onClick={() => insertMergeToken(field.key)}
              style={{
                all: "unset",
                boxSizing: "border-box",
                cursor: "pointer",
                borderRadius: 6,
                border: `1px solid ${CHROME_BORDER_BLUE}`,
                background: CHROME_WHITE,
                color: theme.accent.primary,
                padding: "4px 8px",
                fontSize: 12,
                fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
              }}
            >
              {mergeFieldToken(field.key)}
            </button>
          ))}
        </Row>
      </Stack>

      <Stack gap={4}>
        <FieldLabel>{`${t(uiLang, "billingTemplateBody")} (EN)`}</FieldLabel>
        <textarea
          ref={bodyEnRef}
          value={selected.bodyEn}
          onChange={(e) => patchSelected({ bodyEn: e.target.value })}
          onFocus={() => setActiveBodyLang("en")}
          style={textareaStyle}
        />
      </Stack>
      <Stack gap={4}>
        <FieldLabel>{`${t(uiLang, "billingTemplateBody")} (HE)`}</FieldLabel>
        <textarea
          ref={bodyHeRef}
          value={selected.bodyHe}
          onChange={(e) => patchSelected({ bodyHe: e.target.value })}
          onFocus={() => setActiveBodyLang("he")}
          dir="rtl"
          style={textareaStyle}
        />
      </Stack>

      {!compact ? (
        <Stack
          gap={10}
          style={{
            padding: 14,
            borderRadius: 10,
            border: `1px solid ${CHROME_BORDER_BLUE}`,
            background: CHROME_WHITE,
          }}
        >
          <Row gap={8} align="center" wrap>
            <ChromeText weight="semibold">{t(uiLang, "billingTemplatePreview")}</ChromeText>
            <Spacer />
            <Select
              value={previewLang}
              onChange={(v) => setPreviewLang(v as UiLang)}
              options={[
                { value: "en", label: t(uiLang, "langEnglish") },
                { value: "he", label: t(uiLang, "langHebrew") },
              ]}
              style={{ minWidth: 120 }}
            />
          </Row>
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "billingTemplateFrom")}: {senderProfile.email}
          </ChromeText>
          <ChromeText size="small" tone="tertiary">
            {t(uiLang, "billingTemplateSenderHint")}
          </ChromeText>
          <ChromeText size="small" tone="secondary">
            {previewSubject}
          </ChromeText>
          <div
            style={{
              padding: 14,
              borderRadius: 8,
              border: `1px solid ${chromeBorder(theme)}`,
              background: bgColor,
              color: textColor,
              fontFamily: selected.bodyFontFamily,
              fontSize: selected.bodyFontSizePx,
              lineHeight: 1.5,
              textAlign: bodyTextAlign,
              direction: previewLang === "he" ? "rtl" : "ltr",
            }}
          >
            {selected.logoDataUrl ? (
              <div
                style={{
                  display: "flex",
                  justifyContent: logoJustify,
                  marginBottom: 12,
                }}
              >
                <img
                  src={selected.logoDataUrl}
                  alt=""
                  style={{
                    maxHeight: 52,
                    maxWidth: "100%",
                    objectFit: "contain",
                  }}
                />
              </div>
            ) : null}
            <div
              dangerouslySetInnerHTML={{
                __html: billingEmailBodyToPreviewHtml(previewBody),
              }}
            />
            {senderSignatureBlock ? (
              <div
                style={{
                  marginTop: 16,
                  paddingTop: 12,
                  borderTop: `1px solid ${chromeBorder(theme)}`,
                }}
              >
                <ChromeText
                  size="small"
                  tone="tertiary"
                  style={{ marginBottom: 6, display: "block" }}
                >
                  {t(uiLang, "billingTemplateSignature")}
                </ChromeText>
                <div
                  dangerouslySetInnerHTML={{
                    __html: billingEmailBodyToPreviewHtml(senderSignatureBlock),
                  }}
                />
              </div>
            ) : null}
          </div>
        </Stack>
      ) : null}

      <Row gap={8} wrap>
        <Button
          variant="primary"
          onClick={() => setFlash(t(uiLang, "billingTemplateSaved"))}
        >
          {t(uiLang, "saveBillingTemplate")}
        </Button>
        <Button
          variant="secondary"
          onClick={() => {
            const fromLine = `${t(uiLang, "billingTemplateFrom")}: ${senderProfile.email}`;
            const sigPreview = senderSignatureBlock
              ? `\n${t(uiLang, "billingTemplateSignature")}:\n${senderSignatureBlock}`
              : "";
            setFlash(
              `${t(uiLang, "billingTemplateSendDemoDone")} ${fromLine}${sigPreview}`,
            );
          }}
        >
          {t(uiLang, "billingTemplateSendDemo")}
        </Button>
        <Button variant="secondary" onClick={addTemplate}>
          {t(uiLang, "addBillingTemplate")}
        </Button>
        <Button
          variant="ghost"
          disabled={templates.length <= 1}
          onClick={deleteSelected}
        >
          {t(uiLang, "deleteBillingTemplate")}
        </Button>
      </Row>
      {compact ? (
        <ChromeText size="small" tone="tertiary">
          {t(uiLang, "billingTemplateFrom")}: {senderProfile.email}
        </ChromeText>
      ) : null}
      {!compact ? (
        <ChromeText size="small" tone="tertiary">
          {t(uiLang, "billingTemplatesHint")}
        </ChromeText>
      ) : null}
    </Stack>
  );
}

/**
 * Logged-in user chip — initials avatar + name + department memberships.
 * Settings gear opens the User settings page (email/phone editable there only).
 *
 * `railCompact`: primary-rail only — avatar + short name + gear.
 * Clicking the chip or gear pins secondary and opens User settings.
 */
function HeaderUserChip({
  stacked = false,
  railCompact = false,
}: {
  stacked?: boolean;
  railCompact?: boolean;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [firmWorkers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const [firmDepartments] = useCanvasState<FirmDepartment[]>(
    "firmDepartments.v3",
    DEFAULT_FIRM_DEPARTMENTS,
  );
  const [signedInWorkerId] = useCanvasState(
    "signedInWorkerId.v1",
    DEMO_WORKER.id,
  );
  const [screen, setScreen] = useCanvasState<Screen>(SCREEN_STATE_KEY, "home");
  const [, setNavSecondaryOpen] = useCanvasState(
    "crmGmailNavSecondaryOpen.v3",
    true,
  );
  const name = staffDisplayName(uiLang, signedInWorkerId, firmWorkers);
  const shortName = name.trim().split(/\s+/)[0] || name;
  const deptLabels = workerDepartmentLabels(
    uiLang,
    signedInWorkerId,
    firmDepartments,
    firmWorkers,
  );
  const initials = staffInitials(signedInWorkerId, firmWorkers);
  const photoUrl = staffPhotoUrl(signedInWorkerId, firmWorkers);
  const avatarSize = stacked ? 36 : 28;
  const screenActive = screen === "user-settings";

  const openUserSettings = () => {
    setNavSecondaryOpen(true);
    setScreen("user-settings");
  };

  const profileAccent = theme.category.blue;
  /** Primary-rail chip sits on dark navy — light identity chrome. */
  const onDarkRail = railCompact;
  const avatar = (
    <div
      aria-hidden
      style={{
        width: avatarSize,
        height: avatarSize,
        borderRadius: 999,
        background: photoUrl
          ? "transparent"
          : onDarkRail
            ? "rgba(255,255,255,0.14)"
            : waveChipAlpha(profileAccent, "33"),
        border: onDarkRail
          ? `1px solid ${CHROME_PRIMARY_RAIL_MENU_BORDER}`
          : `1px solid ${waveChipAlpha(profileAccent, "66")}`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color: onDarkRail ? CHROME_PRIMARY_RAIL_FG : profileAccent,
        fontSize: stacked ? 12 : 11,
        fontWeight: 600,
        lineHeight: 1,
        flexShrink: 0,
        overflow: "hidden",
      }}
    >
      {photoUrl ? (
        <img
          src={photoUrl}
          alt=""
          draggable={false}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            display: "block",
          }}
        />
      ) : (
        initials
      )}
    </div>
  );

  const settingsGear = (
    <IconButton
      title={t(uiLang, "userSettingsIconTitle")}
      variant="circle"
      size="sm"
      onClick={openUserSettings}
    >
      <svg
        width={16}
        height={16}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={1.75}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden
      >
        {/* Gmail-style settings gear */}
        <circle cx="12" cy="12" r="3" />
        <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z" />
      </svg>
    </IconButton>
  );

  const identityBlock = stacked ? (
    <div
      style={{
        position: "relative",
        width: "100%",
        boxSizing: "border-box",
        borderRadius: 8,
        padding: "10px 8px",
        background: onDarkRail
          ? CHROME_PRIMARY_RAIL_MENU_BG
          : waveChipAlpha(profileAccent, "1F"),
        border: onDarkRail
          ? `1px solid ${
              screenActive
                ? CHROME_PRIMARY_RAIL_ACCENT
                : CHROME_PRIMARY_RAIL_MENU_BORDER
            }`
          : screenActive
            ? `1px solid ${waveChipAlpha(profileAccent, "88")}`
            : `1px solid ${waveChipAlpha(profileAccent, "44")}`,
      }}
    >
      <div
        style={{
          position: "absolute",
          top: 2,
          insetInlineEnd: 2,
          zIndex: 2,
          lineHeight: 0,
        }}
      >
        {settingsGear}
      </div>
      <button
        type="button"
        onClick={openUserSettings}
        title={t(uiLang, "userSettingsOpenHint")}
        aria-label={`${name} · ${deptLabels} — ${t(uiLang, "userSettings")}`}
        style={{
          all: "unset",
          cursor: "pointer",
          display: "block",
          width: "100%",
          boxSizing: "border-box",
        }}
      >
        <Stack
          gap={railCompact ? 4 : 6}
          style={{ alignItems: "center", width: "100%" }}
        >
          {avatar}
          <Stack gap={2} style={{ alignItems: "center", width: "100%" }}>
            <ChromeText
              as="span"
              size="small"
              weight="semibold"
              style={{
                textAlign: "center",
                maxWidth: "100%",
                overflow: "hidden",
                textOverflow: "ellipsis",
                whiteSpace: "nowrap",
                color: onDarkRail ? CHROME_PRIMARY_RAIL_FG : undefined,
              }}
            >
              {railCompact ? shortName : name}
            </ChromeText>
            {railCompact ? null : (
              <ChromeText
                as="span"
                size="small"
                tone="secondary"
                style={{ textAlign: "center", lineHeight: 1.25 }}
              >
                {deptLabels}
              </ChromeText>
            )}
          </Stack>
        </Stack>
      </button>
    </div>
  ) : (
    <div
      style={{
        position: "relative",
        boxSizing: "border-box",
        borderRadius: 8,
        padding: "4px 6px",
        background: waveChipAlpha(profileAccent, "1F"),
        border: screenActive
          ? `1px solid ${waveChipAlpha(profileAccent, "88")}`
          : `1px solid ${waveChipAlpha(profileAccent, "44")}`,
      }}
    >
      <Row gap={8} align="center" style={{ flexShrink: 0 }}>
        <button
          type="button"
          onClick={openUserSettings}
          title={t(uiLang, "userSettingsOpenHint")}
          aria-label={`${name} · ${deptLabels} — ${t(uiLang, "userSettings")}`}
          style={{
            all: "unset",
            cursor: "pointer",
            display: "block",
            boxSizing: "border-box",
            minWidth: 0,
            flex: 1,
          }}
        >
          <Row gap={8} align="center" style={{ flexShrink: 0 }}>
            {avatar}
            <Stack gap={0} style={{ minWidth: 0 }}>
              <ChromeText as="span" size="small" weight="semibold">
                {name}
              </ChromeText>
              <ChromeText as="span" size="small" tone="secondary">
                {deptLabels}
              </ChromeText>
            </Stack>
          </Row>
        </button>
        {settingsGear}
      </Row>
    </div>
  );

  if (stacked) {
    return (
      <Stack gap={0} style={{ width: "100%", alignItems: "center" }}>
        {identityBlock}
      </Stack>
    );
  }
  return (
    <Row gap={0} align="center" style={{ flexShrink: 0 }}>
      {identityBlock}
    </Row>
  );
}

/**
 * Personal User settings — profile (email + phone editable here only),
 * language, notifications, and link to firm Template settings.
 */
function UserSettingsScreen() {
  const [uiLang, setUiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [notifyDemo, setNotifyDemo] = useCanvasState(
    "homeUserNotifyDemo.v1",
    true,
  );
  const [deskSettings] = useCanvasState<WhatsAppDeskSettings>(
    "whatsappDeskSettings.v1",
    DEFAULT_WHATSAPP_DESK_SETTINGS,
  );
  const [chatComposerPrefs, setChatComposerPrefs] =
    useCanvasState<ChatComposerPrefsByWorker>(
      "chatComposerPrefsByWorker.v1",
      {},
    );
  const [firmWorkers, setFirmWorkers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const [firmDepartments] = useCanvasState<FirmDepartment[]>(
    "firmDepartments.v3",
    DEFAULT_FIRM_DEPARTMENTS,
  );
  const [signedInWorkerId, setSignedInWorkerId] = useCanvasState(
    "signedInWorkerId.v1",
    DEMO_WORKER.id,
  );
  const [, setScreen] = useCanvasState<Screen>(SCREEN_STATE_KEY, "home");
  const [, setSelectedCategory] = useCanvasState(SELECTED_CATEGORY_STATE_KEY, DEFAULT_PRIMARY_CATEGORY);
  const [role] = useCanvasState<Role>("role", "worker");
  const [, setTemplateScope] = useCanvasState<FirmEmailTemplateScope>(
    "templateSettingsScope.v1",
    "all",
  );
  const [, setTemplateView] = useCanvasState<"hub" | "edit">(
    "templateSettingsView.v1",
    "hub",
  );
  const [, setNavSecondaryOpen] = useCanvasState(
    "crmGmailNavSecondaryOpen.v3",
    true,
  );

  const name = staffDisplayName(uiLang, signedInWorkerId, firmWorkers);
  const deptLabels = workerDepartmentLabels(
    uiLang,
    signedInWorkerId,
    firmDepartments,
    firmWorkers,
  );
  const signedInProfile = resolveWorkerEmailProfile(
    signedInWorkerId,
    firmWorkers,
  );

  const patchSignedInProfile = (
    patch: Partial<
      Pick<
        FirmWorker,
        "email" | "phone" | "emailSignatureName" | "emailSignatureBody"
      >
    >,
  ) => {
    setFirmWorkers((prev) =>
      normalizeFirmWorkers(Array.isArray(prev) ? prev : DEMO_STAFF).map((w) =>
        w.id === signedInWorkerId
          ? normalizeFirmWorker({ ...w, ...patch })
          : w,
      ),
    );
  };

  const openTemplateSettings = () => {
    setTemplateScope("all");
    setTemplateView("hub");
    setSelectedCategory(templateSettingsCategoryForRole(role));
    setNavSecondaryOpen(true);
    setScreen("template-settings");
  };

  return (
    <Stack gap={16} style={{ paddingInlineEnd: 4 }}>
      <Stack gap={4}>
        <H1 style={{ margin: 0 }}>{t(uiLang, "userSettings")}</H1>
        <ChromeText tone="secondary">{t(uiLang, "userSettingsProfileHint")}</ChromeText>
      </Stack>

      <FormSection
        title={t(uiLang, "userSettingsProfile")}
        hint={t(uiLang, "userSettingsProfileHint")}
      >
        <Stack gap={12}>
          <Stack gap={4}>
            <FieldLabel>{t(uiLang, "userSettingsSignedIn")}</FieldLabel>
            <Select
              value={signedInWorkerId}
              onChange={setSignedInWorkerId}
              options={firmWorkers.map((w) => ({
                value: w.id,
                label: `${staffDisplayName(uiLang, w.id, firmWorkers)} · ${workerDepartmentLabels(uiLang, w.id, firmDepartments, firmWorkers)}`,
              }))}
            />
            <ChromeText size="small" tone="tertiary">
              {t(uiLang, "signedInWorkerHint")}
            </ChromeText>
          </Stack>

          <Grid columns={2} gap={12}>
            <Stack gap={4}>
              <FieldLabel>{t(uiLang, "userSettingsDisplayName")}</FieldLabel>
              <ChromeText size="small" weight="semibold">
                {name}
              </ChromeText>
              <ChromeText size="small" tone="tertiary">
                {deptLabels}
              </ChromeText>
            </Stack>
            <Stack gap={4}>
              <FieldLabel>{t(uiLang, "userSettingsPhone")}</FieldLabel>
              <ChromeText size="small" tone="tertiary">
                {t(uiLang, "userSettingsPhoneHint")}
              </ChromeText>
              <ChromeTextInput
                value={signedInProfile.phone}
                onChange={(v) => patchSignedInProfile({ phone: v })}
                placeholder="+972-…"
              />
            </Stack>
            <Stack gap={4} style={{ gridColumn: "1 / -1" }}>
              <FieldLabel>{t(uiLang, "userSettingsEmail")}</FieldLabel>
              <ChromeText size="small" tone="tertiary">
                {t(uiLang, "userSettingsEmailHint")}
              </ChromeText>
              <ChromeTextInput
                value={signedInProfile.email}
                onChange={(v) => patchSignedInProfile({ email: v })}
                placeholder="name@intertax.example"
              />
            </Stack>
            <Stack gap={4}>
              <FieldLabel>
                {t(uiLang, "userSettingsEmailSignatureName")}
              </FieldLabel>
              <ChromeTextInput
                value={signedInProfile.emailSignatureName}
                onChange={(v) =>
                  patchSignedInProfile({ emailSignatureName: v })
                }
              />
            </Stack>
            <Stack gap={4} style={{ gridColumn: "1 / -1" }}>
              <FieldLabel>
                {t(uiLang, "userSettingsEmailSignatureBody")}
              </FieldLabel>
              <ChromeText size="small" tone="tertiary">
                {t(uiLang, "userSettingsEmailSignatureHint")}
              </ChromeText>
              <ChromeTextArea
                value={signedInProfile.emailSignatureBody}
                onChange={(v) =>
                  patchSignedInProfile({ emailSignatureBody: v })
                }
              />
            </Stack>
          </Grid>
        </Stack>
      </FormSection>

      <FormSection title={t(uiLang, "userSettingsDefaultLang")}>
        <Select
          value={uiLang}
          onChange={(v) => setUiLang(v as UiLang)}
          options={[
            { value: "en", label: t(uiLang, "langEnglish") },
            { value: "he", label: t(uiLang, "langHebrew") },
          ]}
        />
      </FormSection>

      <FormSection title={t(uiLang, "userSettingsNotifications")}>
        <Checkbox
          checked={notifyDemo}
          onChange={setNotifyDemo}
          label={t(uiLang, "userSettingsNotifications")}
        />
      </FormSection>

      <FormSection
        title={t(uiLang, "userSettingsChat")}
        hint={t(uiLang, "userSettingsChatHint")}
      >
        <Stack gap={8} style={{ maxWidth: 420 }}>
          <FieldLabel>{t(uiLang, "userSettingsEnterIsSend")}</FieldLabel>
          <Select
            value={workerEnterIsSendPref(chatComposerPrefs, signedInWorkerId)}
            onChange={(v) => {
              const next = normalizeEnterIsSendPref(v);
              setChatComposerPrefs((prev) => ({
                ...prev,
                [signedInWorkerId]: { enterIsSend: next },
              }));
            }}
            options={[
              {
                value: "default",
                label: t(uiLang, "userSettingsEnterIsSendDefault"),
              },
              {
                value: "on",
                label: t(uiLang, "userSettingsEnterIsSendOn"),
              },
              {
                value: "off",
                label: t(uiLang, "userSettingsEnterIsSendOff"),
              },
            ]}
          />
          <ChromeText size="small" tone="tertiary">
            {waEnterIsSendEnabled(deskSettings)
              ? t(uiLang, "userSettingsEnterIsSendFirmOn")
              : t(uiLang, "userSettingsEnterIsSendFirmOff")}
          </ChromeText>
        </Stack>
      </FormSection>

      <FormSection
        title={t(uiLang, "userSettingsEmailTemplates")}
        hint={t(uiLang, "userSettingsEmailTemplatesHint")}
      >
        <Button variant="secondary" onClick={openTemplateSettings}>
          {t(uiLang, "templateSettingsOpen")}
        </Button>
      </FormSection>
    </Stack>
  );
}

/**
 * Template settings hub — All (default) + Billing / Bookkeeping / Worker / Tax / General.
 * Edit opens the shared firm email template editor for that group.
 */
function TemplateSettingsScreen() {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [scope, setScope] = useCanvasState<FirmEmailTemplateScope>(
    "templateSettingsScope.v1",
    "all",
  );
  const [view, setView] = useCanvasState<"hub" | "edit">(
    "templateSettingsView.v1",
    "hub",
  );
  const [templatesRaw, setTemplates] = useCanvasState<BillingEmailTemplate[]>(
    "firmEmailTemplates.v1",
    DEFAULT_FIRM_EMAIL_TEMPLATES,
  );
  const templates = templatesRaw.map(normalizeBillingEmailTemplate);
  const [editId, setEditId] = useCanvasState(
    "templateSettingsEditId.v1",
    "",
  );
  const [, setSelectedId] = useCanvasState(
    "billingEmailTemplateSelected.v1",
    DEFAULT_BILLING_EMAIL_TEMPLATES[0]?.id ?? "",
  );

  const scopes: FirmEmailTemplateScope[] = [
    "all",
    ...FIRM_EMAIL_TEMPLATE_CATEGORIES,
  ];

  const setDefault = (id: string, category: FirmEmailTemplateCategory) => {
    setTemplates((prev) =>
      prev.map((raw) => {
        const tpl = normalizeBillingEmailTemplate(raw);
        if (tpl.category !== category) return tpl;
        return normalizeBillingEmailTemplate({
          ...tpl,
          isDefault: tpl.id === id,
        });
      }),
    );
  };

  const openEdit = (tpl: BillingEmailTemplate) => {
    setEditId(tpl.id);
    setSelectedId(tpl.id);
    setView("edit");
  };

  const editTpl =
    templates.find((tpl) => tpl.id === editId) ??
    templates.find((tpl) => tpl.id === templates[0]?.id);

  if (view === "edit" && editTpl) {
    return (
      <Stack gap={14}>
        <Row align="center" gap={12} wrap>
          <Spacer />
          <Pill tone="info">{t(uiLang, "systemAdminPill")}</Pill>
        </Row>
        <Row gap={8} align="center" wrap>
          <Button variant="ghost" onClick={() => setView("hub")}>
            {t(uiLang, "templateSettingsBackList")}
          </Button>
          <ChromeText size="small" tone="secondary">
            {firmEmailCategoryLabel(uiLang, editTpl.category)}
          </ChromeText>
        </Row>
        <BillingEmailTemplatesEditor lockedCategory={editTpl.category} />
      </Stack>
    );
  }

  const renderTemplateRow = (tpl: BillingEmailTemplate) => (
    <Row
      key={tpl.id}
      gap={10}
      align="center"
      wrap
      style={{
        padding: "10px 12px",
        borderRadius: 8,
        border: `1px solid ${chromeBorder(theme)}`,
        background: CHROME_WHITE,
      }}
    >
      <Stack gap={2} style={{ flex: 1, minWidth: 160 }}>
        <ChromeText weight="semibold">{billingTemplateLabel(uiLang, tpl)}</ChromeText>
        <ChromeText size="small" tone="tertiary">
          {firmEmailCategoryLabel(uiLang, tpl.category)}
        </ChromeText>
      </Stack>
      {tpl.isDefault ? (
        <Pill tone="success">{t(uiLang, "templateSettingsDefault")}</Pill>
      ) : (
        <Button
          variant="ghost"
          onClick={() => setDefault(tpl.id, tpl.category)}
        >
          {t(uiLang, "templateSettingsSetDefault")}
        </Button>
      )}
      <Button variant="secondary" onClick={() => openEdit(tpl)}>
        {t(uiLang, "templateSettingsEdit")}
      </Button>
    </Row>
  );

  const renderCategoryBlock = (category: FirmEmailTemplateCategory) => {
    const rows = templates.filter((tpl) => tpl.category === category);
    return (
      <FormSection
        key={category}
        title={firmEmailCategoryLabel(uiLang, category)}
        hint={`${rows.length} ${t(uiLang, "templateSettingsCount")}`}
      >
        <Stack gap={8}>
          {rows.length === 0 ? (
            <ChromeText size="small" tone="secondary">
              {t(uiLang, "templateSettingsEmpty")}
            </ChromeText>
          ) : (
            rows.map(renderTemplateRow)
          )}
        </Stack>
      </FormSection>
    );
  };

  const visibleCategories: FirmEmailTemplateCategory[] =
    scope === "all" ? FIRM_EMAIL_TEMPLATE_CATEGORIES : [scope];

  return (
    <Stack gap={16}>
      <Row align="center" gap={12} wrap>
        <Spacer />
        <Pill tone="info">{t(uiLang, "systemAdminPill")}</Pill>
      </Row>

      <Stack gap={4}>
        <H1>{t(uiLang, "templateSettingsTitle")}</H1>
        <ChromeText tone="secondary">{t(uiLang, "templateSettingsHint")}</ChromeText>
      </Stack>

      <Row gap={8} wrap>
        {scopes.map((id) => {
          const active = scope === id;
          return (
            <button
              key={id}
              type="button"
              onClick={() => setScope(id)}
              style={{
                all: "unset",
                boxSizing: "border-box",
                cursor: "pointer",
                padding: "6px 12px",
                borderRadius: 8,
                border: `1px solid ${
                  active ? theme.accent.primary : CHROME_BORDER_BLUE
                }`,
                background: active ? chromeSelectedFill(theme) : CHROME_WHITE,
                color: active ? theme.accent.primary : theme.text.primary,
                fontSize: 13,
                fontWeight: active ? 600 : 500,
              }}
            >
              {firmEmailScopeLabel(uiLang, id)}
            </button>
          );
        })}
      </Row>

      <ChromeText size="small" tone="tertiary">
        {scope === "all"
          ? t(uiLang, "templateSettingsAll")
          : firmEmailCategoryLabel(uiLang, scope)}
        {" · "}
        {
          (scope === "all"
            ? templates
            : templates.filter((tpl) => tpl.category === scope)
          ).length
        }{" "}
        {t(uiLang, "templateSettingsCount")}
      </ChromeText>

      <Stack gap={8}>{visibleCategories.map(renderCategoryBlock)}</Stack>
    </Stack>
  );
}

