function fieldAppliesToType(
  field: ConfigurableField,
  type: FieldConfigType | "",
): boolean {
  if (field.clientTypes.length === 0) return true;
  if (!type) return false;
  return field.clientTypes.includes(type);
}

function isFieldRequired(
  catalog: ConfigurableField[],
  fieldId: string,
  type: FieldConfigType | "",
): boolean {
  const field = catalog.find((f) => f.id === fieldId);
  if (!field || !fieldAppliesToType(field, type)) return false;
  return field.required;
}

