/** Configurable prospect pipeline stages (Admin / System Admin). */
type ProspectStageDef = {
  id: string;
  labelEn: string;
  labelHe: string;
  /** Optional external URL — shown as a clickable link on the stage (e.g. רשות המיסים). */
  linkUrl?: string;
  order: number;
};

const DEFAULT_PROSPECT_STAGES: ProspectStageDef[] = [
  {
    id: "prospect",
    labelEn: "Prospect",
    labelHe: "פוטנציאלי",
    order: 0,
  },
  {
    id: "open-file",
    labelEn: "Open file",
    labelHe: "פתיחת תיק",
    order: 1,
  },
  {
    id: "tax-authority",
    labelEn: "Opened file in Tax Authority",
    labelHe: "נפתח תיק ברשות המיסים",
    linkUrl: "https://www.gov.il/he/departments/israel_tax_authority",
    order: 2,
  },
  {
    id: "active",
    labelEn: "Active",
    labelHe: "פעיל",
    order: 3,
  },
];

function sortProspectStages(stages: ProspectStageDef[]): ProspectStageDef[] {
  return [...stages].sort(
    (a, b) => a.order - b.order || a.id.localeCompare(b.id),
  );
}

function prospectStageLabel(lang: UiLang, stage: ProspectStageDef): string {
  // Migrate default Tax Authority checklist wording (imperative → past for checklists).
  if (stage.id === "tax-authority") {
    const en = (stage.labelEn || "").trim();
    if (!en || en === "Open file in Tax Authority") {
      return lang === "he" ? "נפתח תיק ברשות המיסים" : "Opened file in Tax Authority";
    }
    if (en === "Opened file in Tax Authority") {
      return lang === "he"
        ? stage.labelHe && stage.labelHe !== "פתיחת תיק ברשות המיסים"
          ? stage.labelHe
          : "נפתח תיק ברשות המיסים"
        : en;
    }
  }
  return lang === "he" ? stage.labelHe || stage.labelEn : stage.labelEn || stage.labelHe;
}

function resolveProspectStageId(
  stages: ProspectStageDef[],
  current?: string,
): string {
  const sorted = sortProspectStages(stages);
  if (current && sorted.some((s) => s.id === current)) return current;
  return sorted[0]?.id ?? "prospect";
}

/** Built-in prospect pipeline ids (Admin may rename labels; ids stay stable). */
const PROSPECT_STAGE_PROSPECT = "prospect";
const PROSPECT_STAGE_OPEN_FILE = "open-file";
const PROSPECT_STAGE_TAX_AUTHORITY = "tax-authority";
const PROSPECT_STAGE_ACTIVE = "active";

function isProspectListRow(row: DemoRow): boolean {
  return (
    !!row.isPotential ||
    row.kind === "potential" ||
    row.status.trim().toLowerCase() === "prospect"
  );
}

/**
 * Compact Status-column label for a prospect pipeline stage.
 * Shortens the default Tax Authority wording so the clients table stays readable.
 */
function prospectStageListLabel(lang: UiLang, stage: ProspectStageDef): string {
  if (stage.id === PROSPECT_STAGE_TAX_AUTHORITY) {
    const en = (stage.labelEn || "").trim();
    if (
      !en ||
      en === "Open file in Tax Authority" ||
      en === "Opened file in Tax Authority"
    ) {
      return lang === "he" ? "רשות המיסים" : "Tax Authority";
    }
  }
  return prospectStageLabel(lang, stage);
}

/** Clients list Status: prospect pipeline stage, else Active/Hidden/etc. */
function clientListStatusLabel(
  lang: UiLang,
  row: DemoRow,
  stages: ProspectStageDef[],
): string {
  if (isProspectListRow(row)) {
    const sorted = sortProspectStages(stages);
    const stageId = resolveProspectStageId(
      sorted,
      row.profile?.prospectStageId,
    );
    const stage = sorted.find((s) => s.id === stageId);
    if (stage) return prospectStageListLabel(lang, stage);
    return t(lang, "prospectStatus");
  }
  return clientStatusLabel(lang, row.status);
}

function clientListStatusPillTone(
  row: DemoRow,
  stages: ProspectStageDef[],
): "neutral" | "success" | "warning" | "info" | "danger" {
  if (isProspectListRow(row)) {
    const stageId = resolveProspectStageId(
      sortProspectStages(stages),
      row.profile?.prospectStageId,
    );
    if (stageId === PROSPECT_STAGE_ACTIVE) return "success";
    if (stageId === PROSPECT_STAGE_TAX_AUTHORITY) return "warning";
    if (stageId === PROSPECT_STAGE_OPEN_FILE) return "info";
    return "info";
  }
  return clientStatusPillTone(row.status);
}

function isProspectTaxAuthorityStage(stageId: string): boolean {
  return stageId === PROSPECT_STAGE_TAX_AUTHORITY;
}

/** Stage 3 (Tax Authority) is the only manual checklist row. */
function isProspectManualChecklistStage(stageId: string): boolean {
  return isProspectTaxAuthorityStage(stageId);
}

function prospectStageIndex(
  stages: ProspectStageDef[],
  stageId?: string,
): number {
  const sorted = sortProspectStages(stages);
  const id = resolveProspectStageId(sorted, stageId);
  const idx = sorted.findIndex((s) => s.id === id);
  return idx >= 0 ? idx : 0;
}

function taxAuthorityUrlFromStages(stages: ProspectStageDef[]): string {
  const sorted = sortProspectStages(stages);
  const tax =
    sorted.find((s) => s.id === PROSPECT_STAGE_TAX_AUTHORITY && s.linkUrl) ??
    sorted.find((s) => !!s.linkUrl?.trim());
  return (tax?.linkUrl || RESHUT_HAMISIM_OPEN_FILE_URL).trim();
}

function demoProspectWorkingFilePath(name: string): string {
  const safe = name.trim() || "Prospect";
  return `Working files / Prospects / ${safe} / Client file`;
}

/** Demo working-folder path for New client (Clients tree, not Prospects). */
function demoClientWorkingFilePath(name: string): string {
  const safe = name.trim() || "New client";
  return `Working files / Clients / ${safe} / Client file`;
}

/**
 * New client uses the full prospect pipeline including Active (4th stage).
 * Active completes when the saved client is Active — not stripped from the bar.
 */
function newClientPipelineStages(
  stages: ProspectStageDef[],
): ProspectStageDef[] {
  return sortProspectStages(stages).map((s, i) => ({ ...s, order: i }));
}

function openProspectTaxAuthorityUrl(url: string): boolean {
  const trimmed = url.trim();
  if (!trimmed) return false;
  try {
    if (typeof window !== "undefined" && typeof window.open === "function") {
      window.open(trimmed, "_blank", "noopener,noreferrer");
      return true;
    }
  } catch {
    // Canvas host may block popups.
  }
  return false;
}

/**
 * Checklist completion for the four default prospect stages.
 * Prospect only after create/save; Open file after persisted working file
 * (Save client / Convert); Tax Authority manual; Active auto when converted.
 */
function prospectChecklistDoneMap(opts: {
  stages: ProspectStageDef[];
  stageId?: string;
  workingFile?: string;
  taxAuthorityDone?: boolean;
  isActiveClient?: boolean;
  /** True once a prospect record exists (saved), not merely when the form is open. */
  prospectCreated?: boolean;
}): Record<string, boolean> {
  const sorted = sortProspectStages(opts.stages);
  const idx = prospectStageIndex(sorted, opts.stageId);
  const hasFile = !!opts.workingFile?.trim();
  const taxDone = !!opts.taxAuthorityDone;
  const isActive = !!opts.isActiveClient;
  const prospectCreated = !!opts.prospectCreated;
  const out: Record<string, boolean> = {};
  for (let i = 0; i < sorted.length; i++) {
    const stage = sorted[i]!;
    // Only the Active id is convert-complete — not “last stage” (New client omits Active).
    if (stage.id === PROSPECT_STAGE_ACTIVE) {
      out[stage.id] = isActive || idx >= i;
      continue;
    }
    if (isProspectManualChecklistStage(stage.id)) {
      out[stage.id] = taxDone || isActive;
      continue;
    }
    if (stage.id === PROSPECT_STAGE_OPEN_FILE) {
      // Stage 2 only after a persisted working file (Save client / Save as new client).
      // Do not treat Tax Authority done as completing Open file.
      out[stage.id] = hasFile || isActive;
      continue;
    }
    if (stage.id === PROSPECT_STAGE_PROSPECT) {
      // Stage 1 only after the prospect is created/saved — not on open form.
      out[stage.id] = prospectCreated || hasFile || taxDone || isActive;
      continue;
    }
    // Any other non-manual stage before active: auto once reached / later stages done.
    out[stage.id] = idx >= i || hasFile || taxDone || isActive;
  }
  return out;
}

/** Highest completed checklist stage → `prospectStageId` for the chevron bar. */
function deriveProspectStageIdFromChecklist(opts: {
  stages: ProspectStageDef[];
  workingFile?: string;
  taxAuthorityDone?: boolean;
  isActiveClient?: boolean;
  prospectCreated?: boolean;
  fallbackStageId?: string;
}): string {
  const sorted = sortProspectStages(opts.stages);
  if (!sorted.length) return PROSPECT_STAGE_PROSPECT;
  if (opts.isActiveClient) {
    return (
      sorted.find((s) => s.id === PROSPECT_STAGE_ACTIVE)?.id ??
      sorted[sorted.length - 1]!.id
    );
  }
  const done = prospectChecklistDoneMap({
    stages: sorted,
    stageId: opts.fallbackStageId,
    workingFile: opts.workingFile,
    taxAuthorityDone: opts.taxAuthorityDone,
    isActiveClient: false,
    prospectCreated: opts.prospectCreated,
  });
  // Current work = first incomplete stage before Active (Prospect skipped when already done).
  for (const stage of sorted) {
    if (stage.id === PROSPECT_STAGE_ACTIVE) break;
    if (!done[stage.id]) return stage.id;
  }
  // All pre-active stages complete — land on Active if present, else last.
  return (
    sorted.find((s) => s.id === PROSPECT_STAGE_ACTIVE)?.id ??
    sorted[sorted.length - 1]!.id
  );
}

function buildProspectChecklistItems(
  lang: UiLang,
  stages: ProspectStageDef[],
  opts: {
    stageId?: string;
    workingFile?: string;
    taxAuthorityDone?: boolean;
    isActiveClient?: boolean;
    prospectCreated?: boolean;
  },
): WorkspaceChecklistItem[] {
  const sorted = sortProspectStages(stages);
  const done = prospectChecklistDoneMap({
    stages: sorted,
    stageId: opts.stageId,
    workingFile: opts.workingFile,
    taxAuthorityDone: opts.taxAuthorityDone,
    isActiveClient: opts.isActiveClient,
    prospectCreated: opts.prospectCreated,
  });
  return sorted.map((stage, i) => {
    const manual = isProspectManualChecklistStage(stage.id);
    const autoBadge = manual
      ? t(lang, "prospectStageManualBadge")
      : t(lang, "prospectStageAutoBadge");
    const label = `${i + 1}. ${prospectStageLabel(lang, stage)} · ${autoBadge}`;
    return {
      id: stage.id,
      label,
      done: !!done[stage.id],
      stageId: stage.id,
    };
  });
}

function fieldsForType(
  catalog: ConfigurableField[],
  type: FieldConfigType | "",
  section?: FieldSection,
): ConfigurableField[] {
  return catalog.filter((f) => {
    if (section && f.section !== section) return false;
    return fieldAppliesToType(f, type || "individuals");
  });
}

function formatAddressBlock(p?: ClientProfile): string {
  if (!p) return "";
  const line1 = [p.houseNo, p.addrLine1].filter(Boolean).join(" ").trim();
  const line2 = [p.apartment, p.addrLine2].filter(Boolean).join(" ").trim();
  const cityLine = [p.city, p.postCode || p.addrLine3]
    .filter(Boolean)
    .join(" ")
    .trim();
  return [line1, line2, cityLine].filter(Boolean).join(", ");
}

function composeDisplayName(
  first: string,
  family: string,
  fallback: string,
): string {
  const parts = [first.trim(), family.trim()].filter(Boolean).join(" ");
  return parts || fallback.trim();
}


