function sanitizeMergeFieldKey(raw: string): string {
  return raw.trim().replace(/^\{|\}$/g, "").replace(/[^a-zA-Z0-9_]/g, "");
}

function normalizeTemplateMergeField(
  raw: Partial<TemplateMergeField> | null | undefined,
): TemplateMergeField {
  const key = sanitizeMergeFieldKey(String(raw?.key ?? "")) || "customToken";
  const source = TEMPLATE_MERGE_FIELD_SOURCES.includes(
    raw?.source as TemplateMergeFieldSource,
  )
    ? (raw!.source as TemplateMergeFieldSource)
    : "customDefault";
  return {
    id: String(raw?.id || "").trim() || `mf-${key}-${Date.now()}`,
    key,
    labelEn: String(raw?.labelEn ?? "").trim() || key,
    labelHe: String(raw?.labelHe ?? "").trim() || key,
    description: String(raw?.description ?? "").trim(),
    source,
    defaultValue: String(raw?.defaultValue ?? ""),
    builtIn: Boolean(raw?.builtIn),
  };
}

function mergeTemplateMergeFieldsWithDefaults(
  stored: TemplateMergeField[] | null | undefined,
): TemplateMergeField[] {
  const list = (stored ?? []).map(normalizeTemplateMergeField);
  const byKey = new Map(list.map((f) => [f.key, f]));
  for (const seed of DEFAULT_TEMPLATE_MERGE_FIELDS) {
    if (!byKey.has(seed.key)) {
      list.push(seed);
      byKey.set(seed.key, seed);
    } else {
      const existing = byKey.get(seed.key)!;
      if (existing.builtIn || seed.builtIn) {
        const merged = normalizeTemplateMergeField({
          ...seed,
          ...existing,
          id: existing.id || seed.id,
          builtIn: true,
          key: seed.key,
          source: existing.source || seed.source,
        });
        const idx = list.findIndex((f) => f.key === seed.key);
        if (idx >= 0) list[idx] = merged;
        byKey.set(seed.key, merged);
      }
    }
  }
  return list;
}

function mergeFieldToken(key: string): string {
  return `{${sanitizeMergeFieldKey(key)}}`;
}

function mergeFieldLabel(lang: UiLang, field: TemplateMergeField): string {
  return lang === "he"
    ? field.labelHe || field.labelEn || field.key
    : field.labelEn || field.key;
}

function demoValueForMergeSource(
  source: TemplateMergeFieldSource,
  lang: UiLang,
  defaultValue: string,
): string {
  const fallback = defaultValue.trim();
  switch (source) {
    case "clientName":
      return fallback || (lang === "he" ? "יוסי כהן" : "Yossi Cohen");
    case "clientId":
      return fallback || "CLT-1042";
    case "companyName":
      return (
        fallback || (lang === "he" ? "כהן ייעוץ בע״מ" : "Cohen Consulting Ltd")
      );
    case "firmName":
      return (
        fallback ||
        (lang === "he" ? "אינטרטקס הנהלת חשבונות בע״מ" : "Intertax Accounting Ltd")
      );
    case "firmEmail":
      return fallback || "office@intertax.example";
    case "firmPhone":
      return fallback || "03-555-1200";
    case "invoiceNumber":
      return fallback || "227001";
    case "amount":
      return fallback || (lang === "he" ? "₪1,180.00" : "₪1,180.00");
    case "dueDate":
      return fallback || (lang === "he" ? "01/10/2026" : "1 Oct 2026");
    case "year":
      return fallback || "2025";
    case "portalLink":
      return fallback || "https://portal.intertax.example/c/CLT-1042";
    case "workerName":
      return fallback || (lang === "he" ? "אבי לוי" : "Avi Levy");
    case "today":
      return fallback || (lang === "he" ? "17/09/2026" : "17 Sep 2026");
    case "customDefault":
      return fallback || (lang === "he" ? "טקסט לדוגמה" : "Sample text");
    default:
      return fallback;
  }
}

function demoValueForMergeField(
  field: TemplateMergeField,
  lang: UiLang,
): string {
  return demoValueForMergeSource(field.source, lang, field.defaultValue);
}

/** Substitute {tokens} with demo/preview values from System Admin merge fields. */
function applyTemplateMergeFields(
  text: string,
  fields: TemplateMergeField[],
  lang: UiLang,
): string {
  let out = text;
  const sorted = [...fields].sort((a, b) => b.key.length - a.key.length);
  for (const field of sorted) {
    const token = mergeFieldToken(field.key);
    if (!token || token === "{}" || !out.includes(token)) continue;
    out = out.split(token).join(demoValueForMergeField(field, lang));
  }
  return out;
}

