const DEFAULT_FIRM_EMAIL_TEMPLATES = DEFAULT_BILLING_EMAIL_TEMPLATES;

function normalizeFirmEmailCategory(
  raw: string | null | undefined,
): FirmEmailTemplateCategory {
  if (
    raw === "billing" ||
    raw === "bookkeeping" ||
    raw === "worker" ||
    raw === "tax" ||
    raw === "general"
  ) {
    return raw;
  }
  return "billing";
}

function normalizeBillingEmailTemplate(
  raw: Partial<BillingEmailTemplate> | null | undefined,
): BillingEmailTemplate {
  const base = DEFAULT_BILLING_EMAIL_TEMPLATES[0];
  return {
    id: raw?.id ?? base.id,
    nameEn: raw?.nameEn ?? "",
    nameHe: raw?.nameHe ?? "",
    subjectEn: raw?.subjectEn ?? "",
    subjectHe: raw?.subjectHe ?? "",
    bodyEn: raw?.bodyEn ?? "",
    bodyHe: raw?.bodyHe ?? "",
    logoDataUrl: raw?.logoDataUrl ?? "",
    logoAlign:
      raw?.logoAlign === "center" || raw?.logoAlign === "end"
        ? raw.logoAlign
        : "start",
    bodyFontFamily: raw?.bodyFontFamily || DEFAULT_BILLING_EMAIL_STYLE.bodyFontFamily,
    bodyFontSizePx: Math.max(
      10,
      Math.min(36, Number(raw?.bodyFontSizePx) || 14),
    ),
    bodyTextTone:
      raw?.bodyTextTone === "accent" ||
      raw?.bodyTextTone === "secondary" ||
      raw?.bodyTextTone === "link" ||
      raw?.bodyTextTone === "muted"
        ? raw.bodyTextTone
        : "default",
    bodyBgTone:
      raw?.bodyBgTone === "accent" ||
      raw?.bodyBgTone === "secondary" ||
      raw?.bodyBgTone === "link" ||
      raw?.bodyBgTone === "muted" ||
      raw?.bodyBgTone === "default"
        ? raw.bodyBgTone
        : "none",
    bodyAlign:
      raw?.bodyAlign === "center" || raw?.bodyAlign === "end"
        ? raw.bodyAlign
        : "start",
    category: normalizeFirmEmailCategory(raw?.category),
    isDefault: Boolean(raw?.isDefault),
  };
}

function firmEmailCategoryLabel(
  lang: UiLang,
  category: FirmEmailTemplateCategory,
): string {
  switch (category) {
    case "billing":
      return t(lang, "templateSettingsBilling");
    case "bookkeeping":
      return t(lang, "templateSettingsBookkeeping");
    case "worker":
      return t(lang, "templateSettingsWorker");
    case "tax":
      return t(lang, "templateSettingsTax");
    case "general":
      return t(lang, "templateSettingsGeneral");
  }
}

function firmEmailScopeLabel(lang: UiLang, scope: FirmEmailTemplateScope): string {
  if (scope === "all") return t(lang, "templateSettingsScopeAll");
  return firmEmailCategoryLabel(lang, scope);
}

function billingEmailToneColor(
  theme: ReturnType<typeof useHostTheme>,
  tone: BillingEmailColorTone | "none",
): string {
  if (tone === "none") return "transparent";
  if (tone === "accent") return theme.accent.primary;
  if (tone === "secondary") return CHROME_INK_MUTED;
  if (tone === "link") return theme.text.link;
  if (tone === "muted") return CHROME_INK_MUTED;
  return theme.text.primary;
}

function escapeEmailPreviewText(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function billingEmailBodyToPreviewHtml(body: string): string {
  const looksHtml = /<\/?[a-z][\s\S]*>/i.test(body);
  if (looksHtml) {
    return body.replace(/\n/g, "<br/>");
  }
  return escapeEmailPreviewText(body).replace(/\n/g, "<br/>");
}

function wrapEmailBodySelection(
  value: string,
  start: number,
  end: number,
  before: string,
  after: string,
): { next: string; selStart: number; selEnd: number } {
  const a = Math.max(0, Math.min(start, value.length));
  const b = Math.max(a, Math.min(end, value.length));
  const selected = value.slice(a, b) || "text";
  const next = value.slice(0, a) + before + selected + after + value.slice(b);
  const selStart = a + before.length;
  const selEnd = selStart + selected.length;
  return { next, selStart, selEnd };
}

function billingTemplateLabel(
  lang: UiLang,
  tpl: BillingEmailTemplate,
): string {
  return lang === "he" ? tpl.nameHe || tpl.nameEn : tpl.nameEn;
}

const INVOICE_CURRENCIES: InvoiceCurrency[] = ["ILS", "GBP", "USD", "EUR"];
const DEMO_FX_TO_ILS: Record<InvoiceCurrency, number> = {
  ILS: 1,
  GBP: 4.7,
  USD: 3.7,
  EUR: 4.05,
};

function parseInvoiceCurrency(value: unknown): InvoiceCurrency {
  return INVOICE_CURRENCIES.includes(value as InvoiceCurrency)
    ? (value as InvoiceCurrency)
    : "ILS";
}

function parseInvoiceVatMode(value: unknown): InvoiceVatMode {
  return value === "included" ? "included" : "add";
}

function parseInvoiceRounding(value: unknown): InvoiceRounding {
  if (value === "whole" || value === "ten" || value === "nine99") return value;
  return "none";
}

const DEFAULT_BILLING_SETTINGS: BillingSettings = {
  invoicePrefix: "",
  numberPattern: "{seq}",
  nextSequence: 227001,
  includeYearMonth: false,
  sequencePad: 1,
  vatRatePct: 18,
  vatEnabled: true,
  defaultCurrency: "ILS",
  defaultDisplayCurrency: "GBP",
  defaultVatMode: "add",
  defaultRounding: "none",
  invoiceLayout: "standard",
  showFirmLogo: true,
  showVatBreakdown: true,
  footerNoteEn: "Payment due within 14 days. Thank you for your business.",
  footerNoteHe: "יש לשלם תוך 14 יום. תודה על העסקים עמנו.",
  thankYouEn: "Thank you",
  thankYouHe: "תודה רבה",
  paymentRequestPrefix: "",
  paymentRequestPattern: "{seq}",
  paymentRequestNextSequence: 2260478,
  paymentRequestSequencePad: 1,
};

/** True when stored settings still use dashed / date-token invoice numbers. */
function isLegacyDashedInvoiceNumbering(settings: BillingSettings): boolean {
  const pattern = settings.numberPattern.trim();
  if (pattern === "{seq}") return false;
  if (
    pattern === "" ||
    pattern === "{prefix}-{YY}{MM}-{seq}" ||
    pattern === "{prefix}-{seq}"
  ) {
    return true;
  }
  return settings.includeYearMonth && /\{YY\}|\{MM\}|\{YYYY\}/i.test(pattern);
}

/**
 * Retire `{prefix}-{YY}{MM}-{seq}` style. Numeric prefixes (e.g. 227001) become
 * the sequence base so next preview is base+1 as plain digits.
 */
function migrateToPlainInvoiceSequence(
  settings: BillingSettings,
): BillingSettings {
  if (!isLegacyDashedInvoiceNumbering(settings)) {
    return {
      ...settings,
      numberPattern: settings.numberPattern.trim() || "{seq}",
      sequencePad: Math.max(1, Math.min(8, settings.sequencePad || 1)),
    };
  }
  const prefix = settings.invoicePrefix.trim();
  const prefixNum = /^\d+$/.test(prefix) ? Number(prefix) : NaN;
  let nextSequence = Math.max(1, Number(settings.nextSequence) || 1);
  if (Number.isFinite(prefixNum) && prefixNum > 0) {
    nextSequence = Math.max(nextSequence, prefixNum + 1);
  } else if (
    nextSequence < 227001 &&
    (prefix === "" || prefix.toUpperCase() === "CRM")
  ) {
    nextSequence = 227001;
  }
  return {
    ...settings,
    invoicePrefix: Number.isFinite(prefixNum) ? "" : prefix,
    numberPattern: "{seq}",
    includeYearMonth: false,
    sequencePad: 1,
    nextSequence,
  };
}

function normalizeBillingSettings(
  raw: Partial<BillingSettings> | null | undefined,
): BillingSettings {
  const merged = { ...DEFAULT_BILLING_SETTINGS, ...(raw ?? {}) };
  const migrated = migrateToPlainInvoiceSequence(merged);
  return {
    ...migrated,
    defaultCurrency: parseInvoiceCurrency(migrated.defaultCurrency),
    defaultDisplayCurrency: parseInvoiceCurrency(migrated.defaultDisplayCurrency),
    defaultVatMode: parseInvoiceVatMode(migrated.defaultVatMode),
    defaultRounding: parseInvoiceRounding(migrated.defaultRounding),
    paymentRequestPrefix: String(migrated.paymentRequestPrefix ?? ""),
    paymentRequestPattern:
      String(migrated.paymentRequestPattern ?? "").trim() || "{seq}",
    paymentRequestNextSequence: Math.max(
      1,
      Number(migrated.paymentRequestNextSequence) || 2260478,
    ),
    paymentRequestSequencePad: Math.max(
      1,
      Math.min(8, Number(migrated.paymentRequestSequencePad) || 1),
    ),
  };
}

function round2(n: number): number {
  return Math.round((Number(n) || 0) * 100) / 100;
}

function roundInvoiceAmount(n: number, mode: InvoiceRounding): number {
  const x = Math.max(0, Number(n) || 0);
  if (mode === "whole") return Math.round(x);
  if (mode === "ten") return Math.round(x * 10) / 10;
  if (mode === "nine99") return Math.max(0, round2(Math.ceil(x) - 0.01));
  return round2(x);
}

function fxRateToIls(
  currency: InvoiceCurrency,
  override?: number,
): number {
  if (currency === "ILS") return 1;
  const n = Number(override);
  if (n > 0) return n;
  return DEMO_FX_TO_ILS[currency];
}

function toIlsAmount(
  amount: number,
  currency: InvoiceCurrency,
  override?: number,
): number {
  return round2(amount * fxRateToIls(currency, override));
}

function fromIlsAmount(
  amountIls: number,
  currency: InvoiceCurrency,
  override?: number,
): number {
  const rate = fxRateToIls(currency, override);
  return rate === 0 ? 0 : round2(amountIls / rate);
}

/** Clamp discount input: 0–100 for %, non-negative for fixed amount. */
function normalizeDiscountValue(
  type: InvoiceDiscountType,
  value: number | string,
): number {
  const n = Math.max(0, Number(String(value).replace(/[^\d.]/g, "")) || 0);
  return type === "percent" ? Math.min(100, n) : n;
}

function computeInvoiceMoney(opts: {
  subtotalIls: number;
  discountType: InvoiceDiscountType;
  discountValue: number;
  vatEnabled: boolean;
  vatRatePct: number;
  vatMode?: InvoiceVatMode;
  rounding?: InvoiceRounding;
}): {
  subtotalIls: number;
  discountIls: number;
  afterDiscountIls: number;
  vatRatePct: number;
  vatIls: number;
  netIls: number;
  totalOwedIls: number;
  vatMode: InvoiceVatMode;
  rounding: InvoiceRounding;
} {
  const vatMode = parseInvoiceVatMode(opts.vatMode);
  const rounding = parseInvoiceRounding(opts.rounding);
  const subtotalIls = round2(Math.max(0, Number(opts.subtotalIls) || 0));
  const rawDisc = normalizeDiscountValue(opts.discountType, opts.discountValue);
  const discountIls = round2(
    opts.discountType === "percent"
      ? Math.min(subtotalIls, (subtotalIls * rawDisc) / 100)
      : Math.min(subtotalIls, rawDisc),
  );
  const afterDiscountIls = round2(Math.max(0, subtotalIls - discountIls));
  const vatRatePct =
    opts.vatEnabled && opts.vatRatePct > 0 ? opts.vatRatePct : 0;
  let vatIls = 0;
  let netIls = afterDiscountIls;
  let totalOwedIls = afterDiscountIls;
  if (vatRatePct > 0) {
    if (vatMode === "included") {
      vatIls = round2((afterDiscountIls * vatRatePct) / (100 + vatRatePct));
      netIls = round2(afterDiscountIls - vatIls);
      totalOwedIls = afterDiscountIls;
    } else {
      vatIls = round2((afterDiscountIls * vatRatePct) / 100);
      netIls = afterDiscountIls;
      totalOwedIls = round2(afterDiscountIls + vatIls);
    }
  }
  totalOwedIls = roundInvoiceAmount(totalOwedIls, rounding);
  return {
    subtotalIls,
    discountIls,
    afterDiscountIls,
    vatRatePct,
    vatIls,
    netIls,
    totalOwedIls,
    vatMode,
    rounding,
  };
}

