/** Current calendar month as YYYY-MM (demo clock follows the machine). */
function currentYearMonth(): string {
  return todayLocalIso().slice(0, 7);
}

function formatYearMonthLabel(ym: string, lang: UiLang): string {
  const [y, m] = ym.split("-");
  const mi = Number(m) - 1;
  if (!y || Number.isNaN(mi) || mi < 0 || mi > 11) return ym;
  return lang === "he"
    ? `${MONTH_LABELS_HE[mi]} ${y}`
    : `${MONTH_LABELS_EN[mi]} ${y}`;
}

function depositMatchesMonthFilter(
  depositDate: string,
  monthFilter: string,
): boolean {
  if (!monthFilter || monthFilter === "all") return true;
  return depositDate.startsWith(monthFilter);
}

/** Month key used for the Word report when filter is All → current month. */
function bankCheckReportMonthKey(monthFilter: string): string {
  if (!monthFilter || monthFilter === "all") return currentYearMonth();
  return monthFilter;
}

function collectBankCheckMonthKeys(
  reviews: BankIncomeReviewItem[],
): string[] {
  const months = new Set<string>();
  months.add(currentYearMonth());
  for (const item of reviews) {
    if (item.depositDate.length >= 7) months.add(item.depositDate.slice(0, 7));
  }
  for (const seed of DEFAULT_BANK_INCOME_SEED) {
    if (seed.depositDate.length >= 7) months.add(seed.depositDate.slice(0, 7));
  }
  return [...months].sort().reverse();
}

function downloadBlobFile(
  filename: string,
  content: string,
  mime: string,
): void {
  if (typeof document === "undefined") return;
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function buildPaymentMatchingWordHtml(args: {
  lang: UiLang;
  monthKey: string;
  pending: BankIncomeReviewItem[];
  unmatched: BankIncomeReviewItem[];
  confirmed: BankIncomeReviewItem[];
  accounts: BillingCheckerBank[];
  lastRun: string;
  updatedAt: string;
}): string {
  const {
    lang,
    monthKey,
    pending,
    unmatched,
    confirmed,
    accounts,
    lastRun,
    updatedAt,
  } = args;
  const dir = lang === "he" ? "rtl" : "ltr";
  const titleBase = t(lang, "bankCheckingTitle");
  const monthLabel = formatYearMonthLabel(monthKey, lang);
  const docTitle = `${titleBase} — ${monthLabel}`;
  const accountLabel = (id: string) => {
    const account = accounts.find((b) => b.id === id);
    if (!account) return id;
    return account.nickname
      ? `${account.name} (${account.nickname}) · ${account.mask}`
      : `${account.name} · ${account.mask}`;
  };
  const rowHtml = (item: BankIncomeReviewItem, extra: string) =>
    `<tr>
      <td>${escapeHtml(item.depositDate)}</td>
      <td>${escapeHtml(item.payerName)}</td>
      <td>${escapeHtml(accountLabel(item.accountId))}</td>
      <td>${escapeHtml(formatIls(item.amountIls))}</td>
      <td>${escapeHtml(extra)}</td>
    </tr>`;
  const pendingRows =
    pending.length === 0
      ? `<tr><td colspan="5">${escapeHtml(t(lang, "bankCheckingEmptyPending"))}</td></tr>`
      : pending
          .map((item) =>
            rowHtml(
              item,
              item.invoiceNumber
                ? `${item.invoiceNumber} · ${item.clientName ?? ""}`
                : "—",
            ),
          )
          .join("\n");
  const unmatchedRows =
    unmatched.length === 0
      ? `<tr><td colspan="5">${escapeHtml(t(lang, "bankCheckingEmptyUnmatched"))}</td></tr>`
      : unmatched.map((item) => rowHtml(item, "—")).join("\n");
  const confirmedRows =
    confirmed.length === 0
      ? `<tr><td colspan="5">—</td></tr>`
      : confirmed
          .map((item) =>
            rowHtml(
              item,
              item.invoiceNumber
                ? `${item.invoiceNumber} · ${item.clientName ?? item.payerName}`
                : item.clientName ?? item.payerName,
            ),
          )
          .join("\n");
  const colDeposit = escapeHtml(t(lang, "bankCheckingDepositCol"));
  const colPayer = escapeHtml(t(lang, "bankCheckingPayerCol"));
  const colAccount = escapeHtml(t(lang, "bankCheckingAccountCol"));
  const colAmount = escapeHtml(lang === "he" ? "סכום" : "Amount");
  const colDetail = escapeHtml(lang === "he" ? "פרטים" : "Detail");
  const thead = `<tr><th>${colDeposit}</th><th>${colPayer}</th><th>${colAccount}</th><th>${colAmount}</th><th>${colDetail}</th></tr>`;
  return `<html xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:w="urn:schemas-microsoft-com:office:word"
 xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta charset="utf-8" />
<title>${escapeHtml(docTitle)}</title>
<!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View></w:WordDocument></xml><![endif]-->
<style>
  body { font-family: "Segoe UI", Arial, sans-serif; font-size: 11pt; color: #111; }
  h1 { font-size: 18pt; margin: 0 0 8pt; }
  h2 { font-size: 13pt; margin: 16pt 0 6pt; }
  .meta { color: #444; margin-bottom: 12pt; }
  table { border-collapse: collapse; width: 100%; margin: 0 0 12pt; }
  th, td { border: 1px solid #999; padding: 4pt 6pt; text-align: ${dir === "rtl" ? "right" : "left"}; }
  th { background: ; }
</style>
</head>
<body dir="${dir}" lang="${lang}">
  <h1>${escapeHtml(docTitle)}</h1>
  <div class="meta">
    ${escapeHtml(t(lang, "bankCheckingReportUpdated"))}: ${escapeHtml(updatedAt || t(lang, "bankCheckingReportNever"))}
    &nbsp;|&nbsp;
    ${escapeHtml(t(lang, "bankCheckingLastRun"))}: ${escapeHtml(lastRun || t(lang, "bankCheckingNeverRun"))}
    &nbsp;|&nbsp;
    ${escapeHtml(t(lang, "bankCheckingReviewQueue"))}: ${pending.length}
    · ${escapeHtml(t(lang, "bankCheckingUnmatched"))}: ${unmatched.length}
    · ${escapeHtml(t(lang, "bankCheckingConfirmed"))}: ${confirmed.length}
  </div>
  <h2>${escapeHtml(t(lang, "bankCheckingReviewQueue"))}</h2>
  <table><thead>${thead}</thead><tbody>${pendingRows}</tbody></table>
  <h2>${escapeHtml(t(lang, "bankCheckingUnmatched"))}</h2>
  <table><thead>${thead}</thead><tbody>${unmatchedRows}</tbody></table>
  <h2>${escapeHtml(t(lang, "bankCheckingConfirmed"))}</h2>
  <table><thead>${thead}</thead><tbody>${confirmedRows}</tbody></table>
</body>
</html>`;
}

function runBankIncomeMatchEngine(
  invoices: FirmInvoice[],
  accounts: BillingCheckerBank[],
  prior: BankIncomeReviewItem[],
): BankIncomeReviewItem[] {
  const accountIds = new Set(accounts.map((a) => a.id));
  const kept = prior.filter(
    (item) =>
      item.status === "confirmed" ||
      item.status === "rejected" ||
      !accountIds.has(item.accountId),
  );
  const decidedDepositIds = new Set(
    prior
      .filter((item) => item.status === "confirmed" || item.status === "rejected")
      .map((item) => item.depositId),
  );
  const usedInvoiceIds = new Set(
    prior
      .filter((item) => item.status === "confirmed" && item.invoiceId)
      .map((item) => item.invoiceId as string),
  );
  const fresh: BankIncomeReviewItem[] = [];
  for (const seed of DEFAULT_BANK_INCOME_SEED) {
    if (!accountIds.has(seed.accountId)) continue;
    if (decidedDepositIds.has(seed.depositId)) continue;
    const available = outstandingInvoicesForBankMatch(invoices).filter(
      (inv) => !usedInvoiceIds.has(inv.id),
    );
    const match = findInvoiceMatchByClientName(
      seed.payerName,
      available,
      seed.amountIls,
    );
    if (match) usedInvoiceIds.add(match.id);
    fresh.push({
      id: `bir-${seed.depositId}`,
      depositId: seed.depositId,
      accountId: seed.accountId,
      depositDate: seed.depositDate,
      amountIls: seed.amountIls,
      payerName: seed.payerName,
      branchNote: seed.branchNote,
      orderNumber: seed.orderNumber,
      invoiceId: match?.id ?? null,
      invoiceNumber: match?.number ?? null,
      clientName: match?.clientName ?? null,
      status: match ? "pending" : "unmatched",
      matchSource: match ? "auto" : undefined,
    });
  }
  const freshIds = new Set(fresh.map((f) => f.depositId));
  return [
    ...fresh,
    ...kept.filter((k) => !freshIds.has(k.depositId)),
  ];
}

function checkerBankDisplayLabel(bank: BillingCheckerBank): string {
  const nick = bank.nickname.trim();
  if (nick) return `${nick} · ${bank.name} ${bank.mask}`.trim();
  return `${bank.name} ${bank.mask}`.trim();
}

/** Label shown in manual-match SearchAutocomplete (invoice / deposit pickers). */
function bankMatchInvoiceCandidateLabel(inv: FirmInvoice): string {
  return `${inv.number} · ${inv.clientName} · ILS ${inv.amountIls.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function bankMatchDepositCandidateLabel(item: BankIncomeReviewItem): string {
  return `${item.depositDate} · ${item.payerName} · ILS ${item.amountIls.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function findInvoiceByMatchCandidateLabel(
  label: string,
  invoices: FirmInvoice[],
): FirmInvoice | undefined {
  const trimmed = label.trim();
  if (!trimmed) return undefined;
  const byExact = invoices.find(
    (inv) => bankMatchInvoiceCandidateLabel(inv) === trimmed,
  );
  if (byExact) return byExact;
  const lower = trimmed.toLowerCase();
  return invoices.find((inv) => {
    const cand = bankMatchInvoiceCandidateLabel(inv).toLowerCase();
    return (
      cand === lower ||
      inv.number.toLowerCase() === lower ||
      inv.clientName.toLowerCase() === lower ||
      cand.includes(lower)
    );
  });
}

function findDepositByMatchCandidateLabel(
  label: string,
  deposits: BankIncomeReviewItem[],
): BankIncomeReviewItem | undefined {
  const trimmed = label.trim();
  if (!trimmed) return undefined;
  const byExact = deposits.find(
    (d) => bankMatchDepositCandidateLabel(d) === trimmed,
  );
  if (byExact) return byExact;
  const lower = trimmed.toLowerCase();
  return deposits.find((d) => {
    const cand = bankMatchDepositCandidateLabel(d).toLowerCase();
    return (
      cand === lower ||
      d.payerName.toLowerCase() === lower ||
      d.depositId.toLowerCase() === lower ||
      cand.includes(lower)
    );
  });
}

