function filterFirmInvoices(
  invoices: FirmInvoice[],
  nav: BillingNavId,
): FirmInvoice[] {
  switch (nav) {
    case "overview":
    case "all":
    case "create":
    case "reminders":
    case "settings":
    case "templates":
    case "bank_checking":
      return invoices;
    case "payment_requests":
    case "create_payment_request":
    case "pay_pages":
      return invoices;
    case "outstanding":
      return invoices.filter((inv) => inv.status === "open");
    case "overdue":
      return invoices.filter((inv) => inv.status === "overdue");
    case "drafts":
      return invoices.filter((inv) => inv.status === "draft");
    case "paid":
      return invoices.filter((inv) => inv.status === "paid");
    case "on_hold":
      return invoices.filter((inv) => inv.status === "on_hold");
    case "trelloOutstanding":
      return invoices;
  }
}

function normalizeInvoicesSubTab(
  raw: string | undefined,
): BillingInvoicesSubTab {
  if (raw === "outstanding") return "open";
  if (
    raw === "all" ||
    raw === "open" ||
    raw === "overdue" ||
    raw === "sent" ||
    raw === "partial" ||
    raw === "paid" ||
    raw === "draft" ||
    raw === "on_hold" ||
    raw === "wont_pay"
  ) {
    return raw;
  }
  return "all";
}

/** See-first scopes using CRM names (Open / Sent / Overdue / …) — counts + sort key. */
function invoiceMatchesScope(
  inv: FirmInvoice,
  sub: BillingInvoicesSubTab,
): boolean {
  if (sub === "all") return true;
  if (sub === "draft") return inv.status === "draft";
  if (sub === "paid") return inv.status === "paid";
  if (sub === "overdue") return inv.status === "overdue";
  if (sub === "partial") return inv.status === "partial";
  if (sub === "on_hold") return inv.status === "on_hold";
  if (sub === "wont_pay") return inv.status === "wont_pay";
  if (sub === "sent") {
    return (
      isInvoiceSentToClient(inv) &&
      (inv.status === "open" || inv.status === "partial")
    );
  }
  return inv.status === "open" && !isInvoiceSentToClient(inv);
}

/**
 * Prefer matching-scope rows first; keep relative order within each group.
 * Does not hide non-matching invoices (chips = see-first, not filter).
 */
function prioritizeInvoicesByScope(
  invoices: FirmInvoice[],
  sub: BillingInvoicesSubTab,
): FirmInvoice[] {
  if (sub === "all") return invoices;
  const preferred: FirmInvoice[] = [];
  const rest: FirmInvoice[] = [];
  for (const inv of invoices) {
    if (invoiceMatchesScope(inv, sub)) preferred.push(inv);
    else rest.push(inv);
  }
  return preferred.concat(rest);
}

