/**
 * Wave invoice UI chip radii (tour 2026-09-25): status tabs + row tags are
 * rounded-rects, not stadium pills (borderRadius 999). Counts stay circular.
 */
const WAVE_SCOPE_CHIP_RADIUS = 6;
const WAVE_STATUS_CHIP_RADIUS = 4;

/** Soften a theme color for Wave-style pastel status chip fills. */
function waveChipAlpha(color: string, alphaHex: string): string {
  if (!color.startsWith("#")) return color;
  if (color.length === 7) return `${color}${alphaHex}`;
  if (color.length === 9) return `${color.slice(0, 7)}${alphaHex}`;
  return color;
}

/**
 * Wave Invoicing status chip colors — same semantic map as WaveInvoiceStatusPills
 * (paid green, overdue red, sent blue, open/partial warm, on hold yellow,
 * no pay pink, draft gray). Soft pastel fill + colored label/count.
 */
function invoiceScopeChipColors(
  id: BillingInvoicesSubTab,
  theme: ReturnType<typeof useHostTheme>,
  selected: boolean,
): {
  accent: string;
  background: string;
  border: string;
  label: string;
  countBg: string;
  countFg: string;
} {
  const c = theme.category;
  let accent: string;
  switch (id) {
    case "paid":
      accent = c.green;
      break;
    case "overdue":
      accent = c.red;
      break;
    case "sent":
      accent = c.blue;
      break;
    case "open":
      accent = c.cyan;
      break;
    case "partial":
      accent = c.orange;
      break;
    case "on_hold":
      accent = c.yellow;
      break;
    case "wont_pay":
      accent = c.pink;
      break;
    case "draft":
      accent = c.gray;
      break;
    case "all":
    default:
      accent = c.purple;
      break;
  }
  return {
    accent,
    background: waveChipAlpha(accent, selected ? "38" : "1A"),
    border: waveChipAlpha(accent, selected ? "C0" : "66"),
    label: accent,
    countBg: waveChipAlpha(accent, selected ? "55" : "2E"),
    countFg: accent,
  };
}

/**
 * Wave-style see-first shortcuts under All invoices (Open / Overdue / Sent / …).
 * Reorders list so that status appears first — does not filter. Real filter =
 * Status dropdown above. No "All" chip (click selected chip to clear sort).
 * Shape matches Wave Sales → Invoices scope tabs: rounded-rect (not pills);
 * category colors stay from invoiceScopeChipColors.
 */
function WaveInvoiceScopeChips({
  lang,
  active,
  counts,
  onSelect,
}: {
  lang: UiLang;
  active: BillingInvoicesSubTab;
  counts: Record<BillingInvoicesSubTab, number>;
  onSelect: (id: BillingInvoicesSubTab) => void;
}) {
  const theme = useHostTheme();
  const items: BillingInvoicesSubTab[] = [
    "open",
    "overdue",
    "sent",
    "partial",
    "on_hold",
    "wont_pay",
    "paid",
    "draft",
  ];
  return (
    <div
      role="tablist"
      aria-label={t(lang, "billingInvoicesTabsAria")}
      style={{
        display: "flex",
        flexWrap: "wrap",
        alignItems: "center",
        gap: 6,
        padding: "6px 8px",
        borderRadius: WAVE_SCOPE_CHIP_RADIUS,
        background: CHROME_TABSTRIP_BG,
        border: `1px solid ${CHROME_BORDER_BLUE}`,
        boxSizing: "border-box",
      }}
    >
      {items.map((id) => {
        const selected = active === id;
        const count = counts[id];
        const colors = invoiceScopeChipColors(id, theme, selected);
        return (
          <button
            key={id}
            type="button"
            role="tab"
            aria-selected={selected}
            onClick={() => onSelect(selected ? "all" : id)}
            style={{
              all: "unset",
              cursor: "pointer",
              display: "inline-flex",
              alignItems: "center",
              gap: 8,
              padding: "5px 11px",
              borderRadius: WAVE_SCOPE_CHIP_RADIUS,
              background: selected
                ? CHROME_WHITE
                : colors.background,
              border: `${selected ? 2 : 1}px solid ${
                selected ? waveChipAlpha(colors.accent, "99") : colors.border
              }`,
              boxSizing: "border-box",
            }}
          >
            <ChromeText
              size="small"
              weight={selected ? "semibold" : "normal"}
              style={{ color: colors.label }}
            >
              {invoiceScopeChipLabel(lang, id)}
            </ChromeText>
            {count != null ? (
              <span
                style={{
                  minWidth: 20,
                  height: 20,
                  padding: "0 5px",
                  borderRadius: 999,
                  background: selected
                    ? waveChipAlpha(colors.accent, "22")
                    : colors.countBg,
                  border: `1px solid ${colors.border}`,
                  fontSize: 11,
                  fontWeight: 700,
                  lineHeight: "18px",
                  textAlign: "center",
                  color: colors.countFg,
                  boxSizing: "border-box",
                }}
              >
                {count}
              </span>
            ) : null}
          </button>
        );
      })}
    </div>
  );
}

