function formatCrmInvoiceNumber(
  settings: BillingSettings,
  isoDate: string,
  sequence: number,
): string {
  const prefix = settings.invoicePrefix.trim();
  const pad = Math.max(1, Math.min(8, settings.sequencePad || 1));
  const seq = String(Math.max(1, sequence)).padStart(pad, "0");
  const yy = isoDate.slice(2, 4);
  const mm = isoDate.slice(5, 7);
  const yyyy = isoDate.slice(0, 4);
  const pattern =
    settings.numberPattern.trim() ||
    defaultInvoiceNumberPattern(settings.includeYearMonth);
  return pattern
    .replace(/\{prefix\}/gi, prefix)
    .replace(/\{YYYY\}/g, yyyy)
    .replace(/\{YY\}/g, yy)
    .replace(/\{MM\}/g, mm)
    .replace(/\{seq\}/gi, seq);
}

/**
 * Next CRM invoice number from billing settings + existing CRM rows.
 * Wave numbers are ignored. Default: plain integer sequence (last + 1).
 */
function suggestNextCrmInvoiceNumber(
  invoices: FirmInvoice[],
  isoDate: string,
  settings: BillingSettings = DEFAULT_BILLING_SETTINGS,
): string {
  const pattern =
    settings.numberPattern.trim() ||
    defaultInvoiceNumberPattern(settings.includeYearMonth);
  const usesPrefix = /\{prefix\}/i.test(pattern);
  const prefix = settings.invoicePrefix.trim().toUpperCase();
  const yymm = isoDate.slice(2, 4) + isoDate.slice(5, 7);
  const usesYearMonth =
    settings.includeYearMonth && /\{YY\}|\{MM\}|\{YYYY\}/i.test(pattern);
  let maxSeq = Math.max(0, settings.nextSequence - 1);
  for (const inv of invoices) {
    if (inv.source !== "crm") continue;
    const upper = inv.number.toUpperCase();
    if (usesPrefix && prefix && !upper.startsWith(prefix)) continue;
    if (usesYearMonth && !inv.number.includes(yymm)) continue;
    const plain = /^\d+$/.exec(inv.number.trim());
    if (plain) {
      const n = Number(plain[0]);
      if (Number.isFinite(n) && n > maxSeq) maxSeq = n;
      continue;
    }
    const match = /(\d+)\s*$/.exec(inv.number);
    if (!match) continue;
    const n = Number(match[1]);
    if (Number.isFinite(n) && n > maxSeq) maxSeq = n;
  }
  return formatCrmInvoiceNumber(settings, isoDate, maxSeq + 1);
}

function sequenceFromSuggestedNumber(number: string): number | null {
  const match = /(\d+)\s*$/.exec(number.trim());
  if (!match) return null;
  const n = Number(match[1]);
  return Number.isFinite(n) ? n : null;
}

function formatPaymentRequestNumber(
  settings: BillingSettings,
  isoDate: string,
  sequence: number,
): string {
  const prefix = settings.paymentRequestPrefix.trim();
  const pad = Math.max(1, Math.min(8, settings.paymentRequestSequencePad || 1));
  const seq = String(Math.max(1, sequence)).padStart(pad, "0");
  const yy = isoDate.slice(2, 4);
  const mm = isoDate.slice(5, 7);
  const yyyy = isoDate.slice(0, 4);
  const pattern = settings.paymentRequestPattern.trim() || "{seq}";
  return pattern
    .replace(/\{prefix\}/gi, prefix)
    .replace(/\{YYYY\}/g, yyyy)
    .replace(/\{YY\}/g, yy)
    .replace(/\{MM\}/g, mm)
    .replace(/\{seq\}/gi, seq);
}

function suggestNextPaymentRequestNumber(
  requests: CrmPaymentRequest[],
  isoDate: string,
  settings: BillingSettings = DEFAULT_BILLING_SETTINGS,
): string {
  let maxSeq = Math.max(0, settings.paymentRequestNextSequence - 1);
  for (const row of requests) {
    const plain = /^\d+$/.exec(row.number.trim());
    if (plain) {
      const n = Number(plain[0]);
      if (Number.isFinite(n) && n > maxSeq) maxSeq = n;
      continue;
    }
    const match = /(\d+)\s*$/.exec(row.number);
    if (!match) continue;
    const n = Number(match[1]);
    if (Number.isFinite(n) && n > maxSeq) maxSeq = n;
  }
  return formatPaymentRequestNumber(settings, isoDate, maxSeq + 1);
}

