function newEmptyInvoiceLine(): FirmInvoiceLine {
  return {
    id: `line-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    serviceName: "",
    description: "",
    quantity: 1,
    unitPrice: 0,
    amountIls: 0,
  };
}

function lineQuantity(line: FirmInvoiceLine): number {
  const q = Number(line.quantity);
  return q > 0 ? q : 1;
}

function lineUnitPrice(line: FirmInvoiceLine): number {
  const u = Number(line.unitPrice);
  if (Number.isFinite(u) && (line.unitPrice != null || u > 0)) {
    return u;
  }
  return round2((Number(line.amountIls) || 0) / lineQuantity(line));
}

function lineDocAmount(line: FirmInvoiceLine): number {
  if (line.quantity != null || line.unitPrice != null) {
    return round2(lineQuantity(line) * lineUnitPrice(line));
  }
  return Number(line.amountIls) || 0;
}

function finalizeInvoiceLine(line: FirmInvoiceLine): FirmInvoiceLine {
  const quantity = lineQuantity(line);
  const unitPrice = lineUnitPrice(line);
  return {
    ...line,
    serviceName: line.serviceName.trim(),
    description: line.description.trim(),
    quantity,
    unitPrice,
    amountIls: round2(quantity * unitPrice),
  };
}

function patchInvoiceLine(
  line: FirmInvoiceLine,
  patch: Partial<FirmInvoiceLine>,
): FirmInvoiceLine {
  const next = { ...line, ...patch };
  if (patch.quantity != null || patch.unitPrice != null) {
    const quantity = lineQuantity(next);
    const unitPrice = Number(next.unitPrice) || 0;
    return {
      ...next,
      quantity,
      unitPrice,
      amountIls: round2(quantity * unitPrice),
    };
  }
  if (patch.amountIls != null) {
    const quantity = lineQuantity(next);
    const amountIls = Number(patch.amountIls) || 0;
    return {
      ...next,
      quantity,
      unitPrice: quantity ? round2(amountIls / quantity) : amountIls,
      amountIls,
    };
  }
  return next;
}

function invoiceLinesTotal(lines: FirmInvoiceLine[]): number {
  return round2(lines.reduce((sum, line) => sum + lineDocAmount(line), 0));
}

function invoiceLinesSummary(lines: FirmInvoiceLine[]): string {
  const parts = lines
    .map((line) => {
      const label = (line.description || line.serviceName).trim();
      return label;
    })
    .filter(Boolean);
  return parts.join(" · ") || "Professional services";
}

function searchFilterFirmInvoices(
  invoices: FirmInvoice[],
  opts: {
    query: string;
    status: InvoiceListStatusFilter;
    source: InvoiceListSourceFilter;
    dateFrom: string;
    dateTo: string;
  },
): FirmInvoice[] {
  const q = opts.query.trim().toLowerCase();
  return invoices.filter((inv) => {
    if (opts.status !== "all" && inv.status !== opts.status) return false;
    if (opts.source !== "all" && inv.source !== opts.source) return false;
    if (opts.dateFrom && inv.date < opts.dateFrom) return false;
    if (opts.dateTo && inv.date > opts.dateTo) return false;
    if (!q) return true;
    return (
      inv.number.toLowerCase().includes(q) ||
      inv.clientName.toLowerCase().includes(q) ||
      inv.lineDescription.toLowerCase().includes(q)
    );
  });
}

function firmInvoiceListKpis(invoices: FirmInvoice[]) {
  let total = 0;
  let outstanding = 0;
  let overdue = 0;
  let paid = 0;
  let drafts = 0;
  for (const inv of invoices) {
    total += inv.amountIls;
    if (inv.status === "open") outstanding += inv.amountIls;
    else if (inv.status === "overdue") overdue += inv.amountIls;
    else if (inv.status === "paid") paid += inv.amountIls;
    else if (inv.status === "draft") drafts += 1;
  }
  return { total, outstanding, overdue, paid, drafts };
}

