/** Firm service offerings (not client types). */
const DEFAULT_SERVICES: string[] = [
  "Bookkeeping",
  "VAT",
  "Audit",
  "Payroll",
  "Tax return",
  "Consulting",
  "Billing",
  "Company secretary",
  SERVICE_DECLARATION_OF_ASSETS,
];

const FEE_LINE_FREQUENCIES: FeeLineFrequency[] = [
  "monthly",
  "quarterly",
  "biannual",
  "yearly",
  "one-off",
  "when_necessary",
  "with_service",
  "no_pay",
  "other",
];

/** Select value prefix for firm-saved custom frequency labels. */
const FEE_CUSTOM_FREQ_PREFIX = "c:";

function newFeeLineId(prefix = "fl"): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 7)}`;
}

function defaultFrequencyForService(service: string): FeeLineFrequency {
  const key = service.trim().toLowerCase().replace(/\s+/g, " ");
  if (key === "declaration of assets") return "one-off";
  if (
    key === "tax return" ||
    key === "tax return (individual)" ||
    key === "audit" ||
    key === "consulting" ||
    key === "annual accounts / audit" ||
    key === "annual accounts"
  ) {
    return "yearly";
  }
  return "monthly";
}

function parseFeeAmountNumber(raw: string | undefined | null): number {
  if (!raw) return 0;
  const n = Number(String(raw).replace(/[^\d.]/g, ""));
  return Number.isFinite(n) && n >= 0 ? n : 0;
}

/** Explicit 0 (not blank) → packaged / charged with another service. */
function feeAmountIsExplicitZero(raw: string | undefined | null): boolean {
  const s = String(raw ?? "").trim();
  if (!s) return false;
  return parseFeeAmountNumber(s) === 0;
}

function feeLineFrequencyLabel(
  lang: UiLang,
  frequency: FeeLineFrequency,
  otherLabel?: string,
): string {
  switch (frequency) {
    case "monthly":
      return t(lang, "monthly");
    case "quarterly":
      return t(lang, "quarterly");
    case "biannual":
      return t(lang, "biannual");
    case "yearly":
      return t(lang, "yearly");
    case "one-off":
      return t(lang, "oneOff");
    case "when_necessary":
      return t(lang, "whenNecessary");
    case "with_service":
      return t(lang, "withService");
    case "no_pay":
      return t(lang, "feeFrequencyNoPay");
    case "other":
      return otherLabel?.trim() || t(lang, "feeFrequencyOther");
  }
}

function feeFrequencySelectValue(line: ClientFeeLine): string {
  if (line.frequency === "other" && line.frequencyOtherLabel?.trim()) {
    return `${FEE_CUSTOM_FREQ_PREFIX}${line.frequencyOtherLabel.trim()}`;
  }
  return line.frequency;
}

function buildFeeFrequencySelectOptions(
  lang: UiLang,
  customLabels: string[],
): Array<{ value: string; label: string }> {
  const builtins = FEE_LINE_FREQUENCIES.map((f) => ({
    value: f,
    label: feeLineFrequencyLabel(lang, f),
  }));
  const customs = customLabels
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l) => ({
      value: `${FEE_CUSTOM_FREQ_PREFIX}${l}`,
      label: l,
    }));
  return [...builtins, ...customs];
}

function feeAmountBasisOf(line: ClientFeeLine): FeeAmountBasis {
  return line.amountBasis === "annual_total" ? "annual_total" : "period";
}

function feeVatModeOf(line: ClientFeeLine): "included" | "excluded" {
  return line.vatMode === "excluded" ? "excluded" : "included";
}

function feeVatModeLabel(
  lang: UiLang,
  mode: "included" | "excluded",
): string {
  return mode === "excluded"
    ? t(lang, "feeLineVatExcluded")
    : t(lang, "feeLineVatIncluded");
}

/** Billing periods per year for recurring cadences; null = not recurring. */
function feePeriodsPerYear(frequency: FeeLineFrequency): number | null {
  switch (frequency) {
    case "monthly":
      return 12;
    case "quarterly":
      return 4;
    case "biannual":
      return 2;
    case "yearly":
      return 1;
    case "one-off":
    case "when_necessary":
    case "with_service":
    case "no_pay":
    case "other":
      return null;
  }
}

/**
 * Amount charged for one period (or the one-off / when-necessary fee).
 * Annual-total lines are divided by periods/year.
 */
function feeLinePeriodIls(line: ClientFeeLine): number {
  const amt = parseFeeAmountNumber(line.amountIls);
  if (feeAmountBasisOf(line) === "period") return amt;
  const periods = feePeriodsPerYear(line.frequency);
  if (periods == null || periods <= 0) return amt;
  return amt / periods;
}

/**
 * Year-equivalent for totals.
 * when_necessary / with_service / no_pay excluded.
 * other counted once (like one-off). Annual-total lines use entered year total.
 */
function feeLineAnnualIls(line: ClientFeeLine): number | null {
  if (
    line.frequency === "when_necessary" ||
    line.frequency === "with_service" ||
    line.frequency === "no_pay"
  ) {
    return null;
  }
  const amt = parseFeeAmountNumber(line.amountIls);
  if (line.frequency === "one-off" || line.frequency === "other") return amt;
  if (feeAmountBasisOf(line) === "annual_total") return amt;
  const periods = feePeriodsPerYear(line.frequency);
  if (periods == null) return amt;
  return amt * periods;
}

/**
 * Side preview: payment for the selected Frequency cadence.
 * Per year + ₪6,000 + Quarterly → ₪1,500 (not always /12).
 */
function feeLinePeriodPreviewIls(line: ClientFeeLine): number | null {
  if (
    line.frequency === "one-off" ||
    line.frequency === "other" ||
    line.frequency === "when_necessary" ||
    line.frequency === "with_service" ||
    line.frequency === "no_pay"
  ) {
    return null;
  }
  const annual = feeLineAnnualIls(line);
  if (annual == null || annual <= 0) return null;
  const periods = feePeriodsPerYear(line.frequency);
  if (periods == null || periods <= 0) return null;
  return Math.round(annual / periods);
}

/**
 * Monthly run-rate preview (year ÷ 12). Shown under period when Frequency ≠ monthly.
 */
function feeLineMonthlyPreviewIls(line: ClientFeeLine): number | null {
  if (
    line.frequency === "one-off" ||
    line.frequency === "other" ||
    line.frequency === "when_necessary" ||
    line.frequency === "with_service" ||
    line.frequency === "no_pay"
  ) {
    return null;
  }
  const annual = feeLineAnnualIls(line);
  if (annual == null || annual <= 0) return null;
  return Math.round(annual / 12);
}

function feeLinePeriodPaymentLabel(
  lang: UiLang,
  frequency: FeeLineFrequency,
): string {
  switch (frequency) {
    case "monthly":
      return t(lang, "feeLineMonthlyPayment");
    case "quarterly":
      return t(lang, "feeLineQuarterlyPayment");
    case "biannual":
      return t(lang, "feeLineBiannualPayment");
    case "yearly":
      return t(lang, "feeLineYearlyPayment");
    default:
      return t(lang, "feeLineMonthlyPayment");
  }
}

/** Amount-field side numbers: period (follows Frequency) + monthly/year extras. */
function FeeLineAmountPreview({
  line,
  lang,
}: {
  line: ClientFeeLine;
  lang: UiLang;
}) {
  const period = feeLinePeriodPreviewIls(line);
  const monthly = feeLineMonthlyPreviewIls(line);
  const annual = feeLineAnnualIls(line);
  if (period == null && monthly == null && (annual == null || annual <= 0)) {
    return null;
  }
  return (
    <Stack gap={2}>
      {period != null ? (
        <ChromeText size="small" tone="secondary">
          {feeLinePeriodPaymentLabel(lang, line.frequency)}:{" "}
          {formatIls(period)}
        </ChromeText>
      ) : null}
      {monthly != null && line.frequency !== "monthly" ? (
        <ChromeText size="small" tone="tertiary">
          {t(lang, "feeLineMonthlyPayment")}: {formatIls(monthly)}
        </ChromeText>
      ) : null}
      {annual != null &&
      annual > 0 &&
      feeAmountBasisOf(line) !== "annual_total" &&
      line.frequency !== "yearly" ? (
        <ChromeText size="small" tone="tertiary">
          {t(lang, "feeLineYearTotal")}: {formatIls(Math.round(annual))}
        </ChromeText>
      ) : null}
    </Stack>
  );
}

/** Circular radio pair: Per month | Per year (clearer than a toggle). */
function FeeAmountBasisChoice({
  value,
  onChange,
  lang,
}: {
  value: FeeAmountBasis;
  onChange: (next: FeeAmountBasis) => void;
  lang: UiLang;
}) {
  const theme = useHostTheme();
  const options: Array<{ id: FeeAmountBasis; label: string }> = [
    { id: "period", label: t(lang, "feeAmountBasisPeriod") },
    { id: "annual_total", label: t(lang, "feeAmountBasisAnnualTotal") },
  ];
  return (
    <Stack gap={6} style={{ marginTop: 8 }}>
      {options.map((opt) => {
        const selected = value === opt.id;
        return (
          <button
            key={opt.id}
            type="button"
            role="radio"
            aria-checked={selected}
            onClick={() => onChange(opt.id)}
            style={{
              all: "unset",
              boxSizing: "border-box",
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              cursor: "pointer",
              color: CHROME_INK_MUTED,
              fontSize: 12,
              lineHeight: 1.2,
              width: "fit-content",
            }}
          >
            <span
              aria-hidden
              style={{
                width: 14,
                height: 14,
                borderRadius: 999,
                border: `2px solid ${
                  selected ? theme.accent.primary : CHROME_BORDER_BLUE
                }`,
                background: CHROME_WHITE,
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
                boxSizing: "border-box",
              }}
            >
              {selected ? (
                <span
                  style={{
                    width: 6,
                    height: 6,
                    borderRadius: 999,
                    background: theme.accent.primary,
                  }}
                />
              ) : null}
            </span>
            {opt.label}
          </button>
        );
      })}
    </Stack>
  );
}

/** Host-service choices for “charged with another service” (excludes the line itself). */
function feeChargedWithOptions(
  lines: ClientFeeLine[],
  lineId: string,
  extraServices: string[],
  excludeSelected: string[] = [],
): string[] {
  const self = lines.find((l) => l.id === lineId);
  const selfKey = (self?.service ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
  const excluded = new Set(
    excludeSelected.map((s) => s.trim().toLowerCase().replace(/\s+/g, " ")),
  );
  const seen = new Set<string>();
  const out: string[] = [];
  const push = (raw: string) => {
    const trimmed = raw.trim();
    if (!trimmed) return;
    const key = trimmed.toLowerCase().replace(/\s+/g, " ");
    if (key === selfKey || excluded.has(key) || seen.has(key)) return;
    seen.add(key);
    out.push(trimmed);
  };
  for (const l of lines) {
    if (l.id === lineId) continue;
    push(l.service);
  }
  for (const s of extraServices) push(s);
  return out;
}

/** Resolve host services (supports legacy single `chargedWithService`). */
function feeChargedWithList(line: ClientFeeLine): string[] {
  if (line.chargedWithServices && line.chargedWithServices.length > 0) {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const raw of line.chargedWithServices) {
      const s = raw.trim();
      if (!s) continue;
      const key = s.toLowerCase().replace(/\s+/g, " ");
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(s);
    }
    return out;
  }
  const legacy = line.chargedWithService?.trim();
  return legacy ? [legacy] : [];
}

function feeChargedWithDisplay(lang: UiLang, line: ClientFeeLine): string {
  const list = feeChargedWithList(line);
  if (list.length === 0) return "—";
  return list.map((s) => serviceLabel(lang, s)).join(" · ");
}

function scheduleToFeeFrequency(
  schedule?: InvoiceSchedule | "",
): FeeLineFrequency {
  if (
    schedule === "monthly" ||
    schedule === "quarterly" ||
    schedule === "biannual" ||
    schedule === "one-off"
  ) {
    return schedule;
  }
  return "monthly";
}

function inferFrequencyFromFeesDisplay(
  feesDisplay: string | undefined,
  schedule?: InvoiceSchedule,
): FeeLineFrequency {
  const lower = (feesDisplay ?? "").toLowerCase();
  if (lower.includes("year")) return "yearly";
  if (lower.includes("one-off") || lower.includes("one off")) return "one-off";
  if (lower.includes("when necessary") || lower.includes("as needed")) {
    return "when_necessary";
  }
  if (lower.includes("quarter")) return "quarterly";
  if (lower.includes("biannual") || lower.includes("semi")) return "biannual";
  if (lower.includes("month")) return "monthly";
  return scheduleToFeeFrequency(schedule);
}

/** Monthly period charges only — excludes non-monthly and when-necessary. */
function monthlyRecurringTotalIls(lines: ClientFeeLine[]): number {
  return Math.round(
    lines
      .filter((l) => l.frequency === "monthly")
      .reduce((sum, l) => sum + feeLinePeriodIls(l), 0),
  );
}

/**
 * Monthly run-rate of all recurring cadences.
 * when_necessary and one-off excluded. Respects amountBasis.
 */
function monthlyEquivalentIls(lines: ClientFeeLine[]): number {
  let sum = 0;
  for (const line of lines) {
    if (
      line.frequency === "when_necessary" ||
      line.frequency === "one-off" ||
      line.frequency === "with_service" ||
      line.frequency === "no_pay" ||
      line.frequency === "other"
    ) {
      continue;
    }
    const annual = feeLineAnnualIls(line);
    if (annual == null) continue;
    sum += annual / 12;
  }
  return Math.round(sum);
}

/**
 * Year view of all included lines. when_necessary excluded.
 * one-offs counted once.
 */
function annualEquivalentIls(lines: ClientFeeLine[]): number {
  let sum = 0;
  for (const line of lines) {
    const annual = feeLineAnnualIls(line);
    if (annual == null) continue;
    sum += annual;
  }
  return Math.round(sum);
}

function migrateLegacyToFeeLines(
  servicesCsv: string,
  feeAmount?: string,
  schedule?: InvoiceSchedule,
  feesDisplay?: string,
): ClientFeeLine[] {
  let amount = (feeAmount ?? "").trim().replace(/,/g, "");
  if (!amount) {
    const match = (feesDisplay ?? "").match(/([\d,]+(?:\.\d+)?)/);
    amount = match?.[1]?.replace(/,/g, "") ?? "";
  }
  if (!amount || parseFeeAmountNumber(amount) <= 0) return [];
  const services = servicesCsv
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const primary =
    services.find(
      (s) => s.toLowerCase().replace(/\s+/g, " ") === "bookkeeping",
    ) ||
    services.find(
      (s) => s.toLowerCase().replace(/\s+/g, " ") === "tax return",
    ) ||
    services.find(
      (s) => s.toLowerCase().replace(/\s+/g, " ") === "audit",
    ) ||
    services[0] ||
    "Agreed fees";
  return [
    {
      id: "fl-legacy",
      service: primary,
      amountIls: amount,
      frequency: inferFrequencyFromFeesDisplay(feesDisplay, schedule),
    },
  ];
}

function resolveClientFeeLines(client: DemoRow): ClientFeeLine[] {
  const profile = client.profile;
  if (profile?.feeLines && profile.feeLines.length > 0) {
    return profile.feeLines;
  }
  return migrateLegacyToFeeLines(
    client.services,
    profile?.feeAmount,
    profile?.invoiceSchedule,
    client.fees,
  );
}

function syncFeeLinesWithServices(
  lines: ClientFeeLine[],
  selectedServices: string[],
): ClientFeeLine[] {
  const selectedKeys = new Set(
    selectedServices.map((s) => s.trim().toLowerCase().replace(/\s+/g, " ")),
  );
  const knownKeys = new Set(
    DEFAULT_SERVICES.map((s) => s.trim().toLowerCase().replace(/\s+/g, " ")),
  );
  const kept = lines.filter((line) => {
    const key = line.service.trim().toLowerCase().replace(/\s+/g, " ");
    if (selectedKeys.has(key)) return true;
    if (knownKeys.has(key)) return false;
    return true;
  });
  const out = [...kept];
  for (const svc of selectedServices) {
    const key = svc.trim().toLowerCase().replace(/\s+/g, " ");
    if (out.some((l) => l.service.trim().toLowerCase().replace(/\s+/g, " ") === key)) {
      continue;
    }
    out.push({
      id: newFeeLineId("fl"),
      service: svc,
      amountIls: "",
      frequency: defaultFrequencyForService(svc),
      amountBasis: "period",
      vatMode: "included",
    });
  }
  return out;
}

function formatFeeLinesSummary(
  lang: UiLang,
  lines: ClientFeeLine[],
): string {
  const parts = lines
    .filter((l) => parseFeeAmountNumber(l.amountIls) > 0)
    .map((l) => {
      const amt = parseFeeAmountNumber(l.amountIls);
      const basis =
        feeAmountBasisOf(l) === "annual_total"
          ? ` (${t(lang, "feeAmountBasisAnnualTotal")})`
          : "";
      return `${serviceLabel(lang, l.service)} ${formatIls(amt)}${basis} / ${feeLineFrequencyLabel(lang, l.frequency)} · ${feeVatModeLabel(lang, feeVatModeOf(l))}`;
    });
  return parts.join(" · ");
}

/** Compact per-line fees list for module headers (not a run-on sentence). */
function FeeLinesSummaryList({
  lang,
  lines,
  fallback,
}: {
  lang: UiLang;
  lines: ClientFeeLine[];
  fallback?: string;
}) {
  const theme = useHostTheme();
  const visible = lines.filter((l) => parseFeeAmountNumber(l.amountIls) > 0);
  if (visible.length === 0) {
    const short =
      fallback?.trim() && !fallback.includes(" · ")
        ? fallback.trim()
        : "—";
    return <ChromeText weight="semibold">{short}</ChromeText>;
  }
  const yearTotal = annualEquivalentIls(visible);
  return (
    <Stack gap={4} style={{ width: "100%" }}>
      {visible.map((l, i) => {
        const amt = parseFeeAmountNumber(l.amountIls);
        const basis =
          feeAmountBasisOf(l) === "annual_total"
            ? ` · ${t(lang, "feeAmountBasisAnnualTotal")}`
            : "";
        return (
          <Stack
            key={l.id}
            gap={2}
            style={{
              width: "100%",
              paddingBottom: i === visible.length - 1 ? 0 : 6,
              borderBottom:
                i === visible.length - 1
                  ? undefined
                  : `1px solid ${chromeBorder(theme)}`,
            }}
          >
            <Row
              align="baseline"
              gap={8}
              style={{ width: "100%", justifyContent: "space-between" }}
            >
              <ChromeText weight="semibold" style={{ minWidth: 0, flex: 1 }}>
                {serviceLabel(lang, l.service)}
              </ChromeText>
              <ChromeText weight="semibold" style={{ flexShrink: 0 }}>
                {formatIls(amt)}
              </ChromeText>
            </Row>
            <ChromeText size="small" tone="secondary">
              {feeLineFrequencyLabel(lang, l.frequency)}
              {basis}
              {" · "}
              {feeVatModeLabel(lang, feeVatModeOf(l))}
            </ChromeText>
          </Stack>
        );
      })}
      {yearTotal > 0 ? (
        <Stack
          align="center"
          style={{
            width: "100%",
            marginTop: 6,
            paddingTop: 8,
            borderTop: `1px solid ${chromeBorder(theme)}`,
          }}
        >
          <ChromeText
            weight="semibold"
            style={{
              textDecoration: "underline",
              textUnderlineOffset: 3,
            }}
          >
            {t(lang, "feeSummaryTotal")}: {formatIls(yearTotal)}
          </ChromeText>
        </Stack>
      ) : null}
    </Stack>
  );
}

function formatFeesCsvFromLines(lines: ClientFeeLine[]): string {
  const withAmt = lines.filter((l) => parseFeeAmountNumber(l.amountIls) > 0);
  if (withAmt.length === 0) return "";
  if (withAmt.length === 1) {
    const line = withAmt[0];
    const amt = parseFeeAmountNumber(line.amountIls);
    return `ILS ${amt.toLocaleString("en-US")} / ${line.frequency}`;
  }
  const annual = annualEquivalentIls(withAmt);
  return `ILS ${annual.toLocaleString("en-US")} / year-equiv (${withAmt.length} lines)`;
}

function feeLinesHaveAmount(lines: ClientFeeLine[]): boolean {
  return lines.some((l) => parseFeeAmountNumber(l.amountIls) > 0);
}

function legacyFeeAmountFromLines(lines: ClientFeeLine[]): string {
  const monthly = monthlyRecurringTotalIls(lines);
  if (monthly > 0) return String(monthly);
  const annual = annualEquivalentIls(lines);
  return annual > 0 ? String(annual) : "";
}

