/** Trailing 5 calendar years ending at `endYear` (demo; pre-2024 synthesized). */
function yearlyMonthSeriesEndingAt(
  byYear: Record<BillingRevenueYear, number[]>,
  endYear: BillingRevenueYear,
): {
  categories: string[];
  data: number[];
} {
  const end = Number(endYear);
  const categories: string[] = [];
  const data: number[] = [];
  const base2024 = sumMonthSeries(byYear["2024"]);
  for (let y = end - 4; y <= end; y++) {
    const key = String(y);
    const isYtd = key === "2026";
    categories.push(isYtd ? "2026 YTD" : key);
    if (key === "2024" || key === "2025" || key === "2026") {
      data.push(sumMonthSeries(byYear[key as BillingRevenueYear]));
    } else {
      data.push(Math.round(base2024 * Math.pow(0.92, 2024 - y)));
    }
  }
  return { categories, data };
}

/** Trailing 5 calendar years ending at `endYear` (demo; pre-2024 synthesized). */
function yearlyRevenueSeriesEndingAt(endYear: BillingRevenueYear): {
  categories: string[];
  data: number[];
} {
  return yearlyMonthSeriesEndingAt(REVENUE_MONTH_BY_YEAR, endYear);
}

function isBillingRevenueYear(value: string): value is BillingRevenueYear {
  return (BILLING_REVENUE_YEARS as readonly string[]).includes(value);
}

