function billingOverviewYearCaptionSuffix(
  year: BillingRevenueYear,
  lang: UiLang,
): string {
  if (year === "2026") {
    return ` · ${year} ${t(lang, "pieYearYtdSuffix")}`;
  }
  return ` · ${year}`;
}

function formatIls(amount: number): string {
  return formatMoney(amount, "ILS");
}

function formatMoney(amount: number, currency: InvoiceCurrency): string {
  const n = Number(amount) || 0;
  return `${currency} ${n.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

function formatInvoiceDate(iso: string): string {
  const parts = parseIsoDateParts(iso);
  if (!parts) return iso.trim() || "—";
  return `${parts.d}/${parts.m}/${parts.y}`;
}

function addDaysIso(iso: string, days: number): string {
  const parts = parseIsoDateParts(iso);
  if (!parts) return iso;
  const d = new Date(
    Date.UTC(Number(parts.y), Number(parts.m) - 1, Number(parts.d)),
  );
  d.setUTCDate(d.getUTCDate() + days);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function defaultInvoiceDueDate(issueIso: string, client?: DemoRow): string {
  const fromProfile = client?.profile?.paymentDue?.trim();
  if (fromProfile && parseIsoDateParts(fromProfile)) return fromProfile;
  return addDaysIso(issueIso, 14);
}

function normalizeVatOsekDigits(raw: string | undefined): string {
  const trimmed = (raw ?? "").trim();
  if (!trimmed) return "";
  const digits = trimmed.replace(/\D/g, "");
  return digits.length === 9 ? digits : trimmed;
}

function vatOsekFromCrmClient(client: DemoRow | undefined): string {
  if (!client) return "";
  const profile = client.profile;
  const fromVatFile = normalizeVatOsekDigits(profile?.vatFileNumber);
  if (fromVatFile) return fromVatFile;
  const fromHp = normalizeVatOsekDigits(profile?.companyNumber);
  if (fromHp) return fromHp;
  if (
    client.kind === "company" ||
    client.kind === "osek" ||
    client.kind === "bookkeeping" ||
    client.kind === "trust"
  ) {
    return normalizeVatOsekDigits(client.identity);
  }
  return "";
}

function lookupClientVatNumber(
  clientId: string,
  crmClients: DemoRow[],
  billingOnly: BillingOnlyClient[] = [],
): string {
  const crm = crmClients.find((row) => row.id === clientId);
  if (crm) return vatOsekFromCrmClient(crm);
  const bill = billingOnly.find((row) => row.id === clientId);
  return normalizeVatOsekDigits(bill?.vatNumber);
}

function invoiceCurrencyOf(inv: FirmInvoice): InvoiceCurrency {
  return parseInvoiceCurrency(inv.currency);
}

function invoiceDocTotal(inv: FirmInvoice): number {
  return inv.amountDoc != null ? inv.amountDoc : inv.amountIls;
}

function invoiceAmountPaidOf(inv: FirmInvoice): number {
  const n = Number(inv.amountPaid);
  return Number.isFinite(n) && n > 0 ? n : 0;
}

/** Remaining ILS balance after amounts already paid. */
function invoiceOutstandingIls(inv: FirmInvoice): number {
  return round2(Math.max(0, inv.amountIls - invoiceAmountPaidOf(inv)));
}

function formatInvoiceListAmount(inv: FirmInvoice): string {
  const currency = invoiceCurrencyOf(inv);
  const total = invoiceDocTotal(inv);
  const paid = invoiceAmountPaidOf(inv);
  if (inv.status === "partial" && paid > 0) {
    const remaining = round2(Math.max(0, total - paid));
    return `${formatMoney(total, currency)} · ${formatMoney(paid, currency)} / ${formatMoney(remaining, currency)}`;
  }
  return formatMoney(total, currency);
}

function InvoiceListAmountCell({
  lang,
  inv,
}: {
  lang: UiLang;
  inv: FirmInvoice;
}) {
  const currency = invoiceCurrencyOf(inv);
  const total = invoiceDocTotal(inv);
  const paid = invoiceAmountPaidOf(inv);
  if (inv.status === "partial" && paid > 0) {
    const remaining = round2(Math.max(0, total - paid));
    return (
      <Stack gap={2}>
        <ChromeText size="small" style={{ fontVariantNumeric: "tabular-nums" }}>
          {formatMoney(total, currency)}
        </ChromeText>
        <ChromeText size="small" tone="secondary">
          {t(lang, "invoicePaidOfRemaining")
            .replace("{paid}", formatMoney(paid, currency))
            .replace("{remaining}", formatMoney(remaining, currency))}
        </ChromeText>
      </Stack>
    );
  }
  return (
    <ChromeText size="small" style={{ fontVariantNumeric: "tabular-nums" }}>
      {formatMoney(total, currency)}
    </ChromeText>
  );
}

function currencySelectOptions(): { value: string; label: string }[] {
  return INVOICE_CURRENCIES.map((c) => ({ value: c, label: c }));
}

