/** Chart axis / footer totals — matches BarChart valuePrefix ₪. */
function formatIlsChart(amount: number): string {
  return `₪${amount.toLocaleString("en-US")}`;
}

/** Axis tick like QuickBooks Cash flow (₪450K). */
function formatIlsCashFlowAxis(amount: number): string {
  const abs = Math.abs(amount);
  if (abs >= 1000) return `₪${Math.round(abs / 1000)}K`;
  return `₪${abs}`;
}

/** Rounded corners on the free end of a bar (top for inflow, bottom for outflow). */
function cashFlowBarPath(
  x: number,
  yZero: number,
  width: number,
  height: number,
  direction: "up" | "down",
  radius: number,
): string {
  const w = Math.max(0, width);
  const h = Math.max(0, height);
  if (h < 0.5 || w < 0.5) return "";
  const r = Math.min(radius, w / 2, h);
  if (direction === "up") {
    const top = yZero - h;
    return [
      `M ${x} ${yZero}`,
      `L ${x} ${top + r}`,
      `Q ${x} ${top} ${x + r} ${top}`,
      `L ${x + w - r} ${top}`,
      `Q ${x + w} ${top} ${x + w} ${top + r}`,
      `L ${x + w} ${yZero}`,
      "Z",
    ].join(" ");
  }
  const bottom = yZero + h;
  return [
    `M ${x} ${yZero}`,
    `L ${x + w} ${yZero}`,
    `L ${x + w} ${bottom - r}`,
    `Q ${x + w} ${bottom} ${x + w - r} ${bottom}`,
    `L ${x + r} ${bottom}`,
    `Q ${x} ${bottom} ${x} ${bottom - r}`,
    "Z",
  ].join(" ");
}

/**
 * QuickBooks-style combo cash-flow chart (inflow/outflow bars + net line).
 * SDK BarChart/LineChart cannot do bidirectional bars, hatch fill, or custom markers.
 */
function niceCashFlowYMax(rawMax: number): number {
  if (rawMax <= CF_QB_Y_MAX) return CF_QB_Y_MAX;
  const step = 50_000;
  return Math.ceil(rawMax / step) * step;
}

function CashFlowQbChart({
  points,
  lang,
  height = 280,
  yMax,
}: {
  points: CashFlowQbPoint[];
  lang: UiLang;
  height?: number;
  /** Override symmetric axis max (defaults to ₪450K QuickBooks scale). */
  yMax?: number;
}) {
  const font =
    "Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif";
  const width = 720;
  const padL = 52;
  const padR = 12;
  const padT = 8;
  const padB = 40;
  const plotW = width - padL - padR;
  const plotH = height - padT - padB;
  const yZero = padT + plotH / 2;
  const dataMax = points.reduce(
    (m, p) => Math.max(m, p.inflow, p.outflow, Math.abs(p.inflow - p.outflow)),
    0,
  );
  const axisMax = yMax ?? niceCashFlowYMax(dataMax);
  const yScale = plotH / 2 / axisMax;
  const n = Math.max(points.length, 1);
  const slot = plotW / n;
  // Gap ≈ half bar width → bar = slot / 1.5
  const barW = slot / 1.5;
  const barGap = barW / 2;
  const ticks = [axisMax, axisMax / 2, 0, -axisMax / 2, -axisMax];

  const netPts = points.map((p, i) => {
    const cx = padL + i * slot + barGap + barW / 2;
    const net = p.inflow - p.outflow;
    const cy = yZero - net * yScale;
    return { cx, cy, net };
  });
  const lineD = netPts
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.cx} ${p.cy}`)
    .join(" ");

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={lang === "he" ? "תזרים מזומנים" : "Cash flow"}
      style={{ display: "block", maxWidth: "100%" }}
    >
      {ticks.map((tick) => {
        const y = yZero - tick * yScale;
        const isZero = tick === 0;
        return (
          <g key={`tick-${tick}`}>
            <line
              x1={padL}
              x2={width - padR}
              y1={y}
              y2={y}
              stroke={isZero ? CF_QB_ZERO : CF_QB_GRID}
              strokeWidth={isZero ? 1.5 : 1}
            />
            <text
              x={padL - 10}
              y={y}
              textAnchor="end"
              dominantBaseline="middle"
              fill={CF_QB_AXIS}
              fontSize={10.5}
              fontFamily={font}
            >
              {formatIlsCashFlowAxis(tick)}
            </text>
          </g>
        );
      })}
      {points.map((p, i) => {
        const x = padL + i * slot + barGap;
        const inH = p.inflow * yScale;
        const outH = p.outflow * yScale;
        const month = lang === "he" ? p.monthHe : p.monthEn;
        const labelX = x + barW / 2;
        return (
          <g key={`bar-${p.yearShort}-${p.monthEn}-${i}`}>
            {inH > 0 ? (
              <path
                d={cashFlowBarPath(x, yZero, barW, inH, "up", 3)}
                fill={CF_QB_INFLOW}
                opacity={0.92}
              />
            ) : null}
            {outH > 0 ? (
              <path
                d={cashFlowBarPath(x, yZero, barW, outH, "down", 3)}
                fill={CF_QB_OUTFLOW}
                opacity={0.88}
              />
            ) : null}
            <text
              x={labelX}
              y={p.yearShort ? height - 22 : height - 14}
              textAnchor="middle"
              fill="#2C3640"
              fontSize={10.5}
              fontWeight={600}
              fontFamily={font}
            >
              {month}
            </text>
            {p.yearShort ? (
              <text
                x={labelX}
                y={height - 9}
                textAnchor="middle"
                fill={CF_QB_AXIS}
                fontSize={9.5}
                fontFamily={font}
              >
                {p.yearShort}
              </text>
            ) : null}
          </g>
        );
      })}
      <path
        d={lineD}
        fill="none"
        stroke={CF_QB_LINE}
        strokeWidth={1.25}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
      {netPts.map((p, i) => (
        <circle
          key={`net-${i}`}
          cx={p.cx}
          cy={p.cy}
          r={3.25}
          fill={CF_QB_MARKER}
          stroke="#FFFFFF"
          strokeWidth={1.25}
        />
      ))}
    </svg>
  );
}

