function firmInvoiceStatusLabel(
  lang: UiLang,
  status: FirmInvoiceStatus,
): string {
  switch (status) {
    case "draft":
      return t(lang, "invStatusDraft");
    case "open":
      return t(lang, "invStatusOpen");
    case "paid":
      return t(lang, "invStatusPaid");
    case "overdue":
      return t(lang, "invStatusOverdue");
    case "on_hold":
      return t(lang, "invStatusOnHold");
    case "wont_pay":
      return t(lang, "invStatusWontPay");
    case "partial":
      return t(lang, "invStatusPartial");
  }
}

function isInvoiceSentToClient(inv: FirmInvoice): boolean {
  if (typeof inv.sentToClient === "boolean") return inv.sentToClient;
  return inv.source === "wave";
}

function firmInvoiceSentLabel(lang: UiLang, inv: FirmInvoice): string {
  return isInvoiceSentToClient(inv)
    ? t(lang, "invoiceSentYes")
    : t(lang, "invoiceSentNo");
}

function firmInvoiceSourceLabel(
  lang: UiLang,
  source: FirmInvoiceSource,
): string {
  return source === "wave" ? t(lang, "invSourceWave") : t(lang, "invSourceCrm");
}

function firmInvoiceRowTone(
  status: FirmInvoiceStatus,
): "danger" | "warning" | "success" | undefined {
  if (status === "overdue" || status === "wont_pay") return "danger";
  if (status === "draft" || status === "on_hold" || status === "partial") {
    return "warning";
  }
  if (status === "paid") return "success";
  return undefined;
}

function waveRowStatusLook(inv: FirmInvoice): BillingInvoicesSubTab {
  if (inv.status === "draft") return "draft";
  if (inv.status === "paid") return "paid";
  if (inv.status === "on_hold") return "on_hold";
  if (inv.status === "wont_pay") return "wont_pay";
  if (inv.status === "overdue") return "overdue";
  if (inv.status === "partial") return "partial";
  return isInvoiceSentToClient(inv) ? "sent" : "open";
}

function WaveInvoiceStatusPills({
  lang,
  inv,
}: {
  lang: UiLang;
  inv: FirmInvoice;
}) {
  const theme = useHostTheme();
  const look = waveRowStatusLook(inv);
  const sent = isInvoiceSentToClient(inv);
  const extraSent = look === "overdue" || look === "partial";
  const colors = invoiceScopeChipColors(look, theme, false);
  const label =
    look === "on_hold"
      ? t(lang, "invStatusOnHold")
      : look === "wont_pay"
        ? t(lang, "invStatusWontPay")
        : invoiceScopeChipLabel(lang, look);
  const sentColors = invoiceScopeChipColors(
    sent ? "sent" : "open",
    theme,
    false,
  );
  return (
    <Row gap={6} wrap>
      <span
        style={{
          display: "inline-flex",
          alignItems: "center",
          padding: "2px 8px",
          borderRadius: WAVE_STATUS_CHIP_RADIUS,
          background: colors.background,
          border: `1px solid ${colors.border}`,
          fontSize: 11,
          fontWeight: 600,
          lineHeight: "16px",
          color: colors.label,
          boxSizing: "border-box",
          whiteSpace: "nowrap",
        }}
      >
        {label}
      </span>
      {extraSent ? (
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            padding: "2px 8px",
            borderRadius: WAVE_STATUS_CHIP_RADIUS,
            background: sentColors.background,
            border: `1px solid ${sentColors.border}`,
            fontSize: 11,
            fontWeight: 600,
            lineHeight: "16px",
            color: sentColors.label,
            boxSizing: "border-box",
            whiteSpace: "nowrap",
          }}
        >
          {sent ? t(lang, "invoiceSentYes") : t(lang, "invStatusUnsent")}
        </span>
      ) : null}
    </Row>
  );
}

function waveHistorySourceCell(
  lang: UiLang,
  inv: FirmInvoice,
  all: FirmInvoice[],
) {
  const label = firmInvoiceSourceLabel(lang, inv.source);
  if (inv.source !== "wave") return label;
  const { unpaid, total } = waveUnpaidByCustomer(all, inv.clientId);
  if (total === 0) return label;
  return (
    <Stack gap={4}>
      <ChromeText size="small">{label}</ChromeText>
      <Pill size="sm" tone={unpaid > 0 ? "warning" : "success"}>
        {t(lang, "waveUnpaidOf")
          .replace("{unpaid}", String(unpaid))
          .replace("{total}", String(total))}
      </Pill>
    </Stack>
  );
}

function defaultInvoiceStaffName(lang: PreferredLang): string {
  return lang === "he" ? "חנניה ניאזוף" : "Chananya Niazoff";
}

/** Engagement bucket for Billing pies (one-time wins over base kind). */
function invoiceClientTypeBucket(
  client: DemoRow | undefined,
): "company" | "bookkeeping" | "osek" | "individuals" | "one-time" {
  if (!client) return "company";
  if (isOneTimeClient(client)) return "one-time";
  if (
    client.kind === "bookkeeping" ||
    client.kind === "osek" ||
    client.kind === "individuals" ||
    client.kind === "company"
  ) {
    return client.kind;
  }
  return "company";
}

function invoiceClientTypePieLabel(
  lang: UiLang,
  bucket: ReturnType<typeof invoiceClientTypeBucket>,
): string {
  if (bucket === "one-time") return t(lang, "oneTimeClients");
  return clientTypeLabel(lang, bucket);
}

/** Best-effort service attribution from line text, then client services list. */
function invoiceServiceBucket(
  inv: FirmInvoice,
  client: DemoRow | undefined,
): string {
  const line = (inv.lineDescription ?? "").toLowerCase();
  const catalog = [
    "Bookkeeping",
    "VAT",
    "Audit",
    "Payroll",
    "Tax return",
    "Consulting",
    "Billing",
    "Company secretary",
  ];
  for (const svc of catalog) {
    if (line.includes(svc.toLowerCase())) return svc;
  }
  if (line.includes("tax")) return "Tax return";
  if (line.includes("דוח")) return "Tax return";
  const fromClient = (client?.services ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  if (fromClient.length) return fromClient[0];
  return "Consulting";
}

function aggregateInvoiceAmounts(
  amounts: Record<string, number>,
): Array<{ labelKey: string; value: number }> {
  return Object.entries(amounts)
    .filter(([, v]) => v > 0)
    .sort((a, b) => b[1] - a[1])
    .map(([labelKey, value]) => ({ labelKey, value }));
}

