function staffChatRecipientsForRole(role: Role): ChatRecipient[] {
  if (isWorker(role)) {
    return CHAT_RECIPIENTS.filter((r) => r.id !== DEMO_WORKER.id);
  }
  return CHAT_RECIPIENTS;
}

function visibleStaffThreads(threads: ChatThread[], role: Role): ChatThread[] {
  const staff = threads.filter((t) => t.channel === "internal");
  if (isWorker(role)) {
    return staff.filter((t) =>
      (t.participantIds ?? []).includes(DEMO_WORKER.id),
    );
  }
  return staff;
}

function displayInitials(name: string): string {
  const parts = name.split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  return parts
    .map((part) => part[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function clockNow(): string {
  const now = new Date();
  return `${String(now.getHours()).padStart(2, "0")}:${String(
    now.getMinutes(),
  ).padStart(2, "0")}`;
}

function waRouteAssignmentLabel(
  lang: UiLang,
  route: WaRoute | undefined,
  workers: FirmWorker[] = DEMO_STAFF,
  departments: FirmDepartment[] = DEFAULT_FIRM_DEPARTMENTS,
): string {
  if (!route || route.status !== "routed") {
    return t(lang, "waAiIntakeBadge");
  }
  if (route.kind === "worker" && route.workerId) {
    return staffDisplayName(lang, route.workerId, workers);
  }
  if (route.kind === "department" && route.deptId) {
    return departmentLabel(lang, route.deptId, departments);
  }
  return t(lang, "waAssignedTo");
}

/**
 * True when a WhatsApp thread is labeled/assigned to the current demo viewer
 * (direct worker route, or a department they belong to).
 */
function waThreadLabeledForViewer(
  th: ChatThread,
  signedInWorkerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): boolean {
  const route = th.waRoute;
  if (!route || route.status !== "routed") return false;
  if (route.kind === "worker") return route.workerId === signedInWorkerId;
  if (route.kind === "department" && route.deptId) {
    return workerBelongsToDept(signedInWorkerId, route.deptId, workers);
  }
  return false;
}

/**
 * Workers only see WhatsApp threads routed to them or any of their departments.
 * AI-intake / unrouted threads are hidden from workers.
 * Admins / managers / system admin see all.
 */
function visibleWhatsAppThreads(
  threads: ChatThread[],
  role: Role,
  signedInWorkerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): ChatThread[] {
  const wa = threads.filter((th) => th.channel === "whatsapp");
  if (!isWorker(role)) return wa;
  return wa.filter((th) =>
    waThreadLabeledForViewer(th, signedInWorkerId, workers),
  );
}

