function normalizeDailyTaskStatus(raw: string | undefined): DailyTaskStatus {
  const s = (raw ?? "").trim().toLowerCase().replace(/\s+/g, "-");
  if (s === "in-process" || s === "inprocess" || s === "in-progress") {
    return "in-process";
  }
  if (s === "closed") return "closed";
  if (s === "done" || s === "finished" || s === "complete") return "done";
  if (s === "open") return "open";
  return "open";
}

function normalizeDailyTaskDue(raw: string | undefined): DailyTaskDue {
  const s = (raw ?? "").trim().toLowerCase().replace(/\s+/g, "-");
  if (s === "tomorrow") return "tomorrow";
  if (s === "this-week" || s === "thisweek" || s === "week") return "this-week";
  return "today";
}

function normalizeDailyTasks(
  raw: DailyTask[] | null | undefined,
): DailyTask[] {
  if (!Array.isArray(raw) || raw.length === 0) {
    return DEFAULT_DAILY_TASKS.map((t) => ({ ...t }));
  }
  return raw.map((row, i) => ({
    id: String(row.id || `task-${i + 1}`),
    title: String(row.title ?? "").trim() || `Task ${i + 1}`,
    client: String(row.client ?? "").trim(),
    due: normalizeDailyTaskDue(row.due),
    status: normalizeDailyTaskStatus(row.status),
    assigneeWorkerId: String(row.assigneeWorkerId ?? "").trim(),
    whatsappAssignDemoSent: Boolean(row.whatsappAssignDemoSent),
  }));
}

function dailyTaskStatusLabel(lang: UiLang, status: DailyTaskStatus): string {
  switch (status) {
    case "in-process":
      return t(lang, "taskStatusInProcess");
    case "closed":
      return t(lang, "taskStatusClosed");
    case "done":
      return t(lang, "taskStatusDone");
    default:
      return t(lang, "taskStatusOpen");
  }
}

function dailyTaskDueLabel(lang: UiLang, due: DailyTaskDue): string {
  if (due === "tomorrow") return t(lang, "taskDueTomorrow");
  if (due === "this-week") return t(lang, "taskDueThisWeek");
  return t(lang, "taskDueToday");
}

/** Status Open only — header breakdown. */
function dailyTasksStatusOpenCount(tasks: DailyTask[]): number {
  return tasks.filter((task) => task.status === "open").length;
}

/** Status In process only — header “in work” breakdown. */
function dailyTasksInProcessCount(tasks: DailyTask[]): number {
  return tasks.filter((task) => task.status === "in-process").length;
}

/**
 * Tasks still needing work: Open + In process (not Closed/Done).
 * Shared by Daily tasks tab blob, Work Tasks secondary badge, Work primary
 * rail (tasks portion), TasksBoard header “in work”, and module tile fallback.
 */
function dailyTasksInWorkCount(tasks: DailyTask[]): number {
  return tasks.filter(
    (task) => task.status === "open" || task.status === "in-process",
  ).length;
}

/** Worker role: only tasks assigned to the signed-in worker. Admin sees all. */
function dailyTasksForViewer(
  tasks: DailyTask[],
  role: Role,
  signedInWorkerId: string,
): DailyTask[] {
  if (!isWorker(role)) return tasks;
  const me = signedInWorkerId.trim();
  if (!me) return [];
  return tasks.filter((task) => task.assigneeWorkerId === me);
}

/** Badge alias — same as in-work (not Open-only). */
function dailyTasksOpenCount(tasks: DailyTask[]): number {
  return dailyTasksInWorkCount(tasks);
}

/** Demo phone from worker signature body (e.g. +972-3-000-0011). */
function workerDemoPhone(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): string {
  const row =
    workers.find((w) => w.id === workerId) ??
    DEMO_STAFF.find((w) => w.id === workerId);
  const body = row?.emailSignatureBody ?? "";
  const match = body.match(/\+972[\d\-]+/);
  if (match) return match[0];
  const tag = row?.employeeTag ?? "0000";
  return `+972-50-000-${tag.padStart(4, "0")}`;
}

