/**
 * Known process streams with dedicated workspace / chat panels.
 * Other firm services (Consulting, Company secretary, …) use a generic workspace.
 */
const KNOWN_STREAM_BY_SERVICE: Record<
  string,
  { id: KnownStreamPanel; label: string }
> = {
  bookkeeping: { id: "stream-bookkeeping", label: "Bookkeeping" },
  billing: { id: "stream-billing", label: "Billing" },
  audit: { id: "stream-audit", label: "Audit" },
  "tax return": { id: "stream-tax-return", label: "Tax return" },
  vat: { id: "stream-vat", label: "VAT" },
  payroll: { id: "stream-payroll", label: "Payroll" },
};

function slugifyService(name: string): string {
  const slug = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || "service";
}

function customStreamId(serviceName: string): CustomStreamPanel {
  return `stream-custom:${slugifyService(serviceName)}`;
}

function streamDefForService(serviceName: string): ClientStreamDef {
  const known = KNOWN_STREAM_BY_SERVICE[serviceName.trim().toLowerCase()];
  if (known) {
    return {
      id: known.id,
      label: known.label,
      serviceName,
    };
  }
  return {
    id: customStreamId(serviceName),
    label: serviceName.trim(),
    serviceName: serviceName.trim(),
  };
}

function clientHasService(clientServices: string, serviceName: string): boolean {
  const target = serviceName.trim().toLowerCase();
  return clientServices
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean)
    .includes(target);
}

function isBookkeepingServiceName(svc: string): boolean {
  return svc.trim().toLowerCase() === "bookkeeping";
}

/** Individuals never offer Bookkeeping as a selectable firm service. */
function servicesSelectableForType(
  firmServices: string[],
  type: EngagementType | "" | DemoRow["kind"],
): string[] {
  if (type !== "individuals") return firmServices;
  return firmServices.filter((s) => !isBookkeepingServiceName(s));
}

function withoutBookkeepingService(services: string[]): string[] {
  return services.filter((s) => !isBookkeepingServiceName(s));
}

/**
 * Process tabs = firm Services catalog ∩ services on this client.
 * Order follows the firm catalog. New Services-page entries become tab types;
 * they appear on a card once assigned to that client.
 * VAT is NEVER a top-level tab — skipped here; it lives only under Bookkeeping.
 * Individuals normally skip Bookkeeping, but if they have VAT we still surface
 * Bookkeeping so VAT has a home (inner tab + checklist).
 */
function streamsForClient(
  clientServices: string,
  firmServices: string[],
  clientKind?: DemoRow["kind"],
): ClientStreamDef[] {
  const seen = new Set<string>();
  const out: ClientStreamDef[] = [];
  const hasVat = clientHasService(clientServices, "VAT");
  for (const firmSvc of firmServices) {
    if (!clientHasService(clientServices, firmSvc)) continue;
    const def = streamDefForService(firmSvc);
    if (seen.has(def.id)) continue;
    // Hard rule: VAT is not a sibling of Bookkeeping / Audit on the card.
    if (def.id === "stream-vat") continue;
    if (
      clientKind === "individuals" &&
      def.id === "stream-bookkeeping" &&
      !hasVat
    ) {
      continue;
    }
    seen.add(def.id);
    out.push(def);
  }
  // Ensure Bookkeeping exists whenever VAT does (VAT nests only under BK).
  if (hasVat && !seen.has("stream-bookkeeping")) {
    const bk = streamDefForService("Bookkeeping");
    seen.add(bk.id);
    const auditIdx = out.findIndex((s) => s.id === "stream-audit");
    if (auditIdx >= 0) out.splice(auditIdx, 0, bk);
    else out.unshift(bk);
  }
  return out;
}

/**
 * One-shot navigation intent when opening a client card from a filtered list /
 * module tile / primary-rail shortcut. Cleared after the default tab is applied
 * so manual tab switches are not locked.
 */
type ClientCardEntryContext = ClientFilter | "overview";

/**
 * Map list/module entry context → default Gmail process tab.
 * Falls back to Overview when the preferred stream is not on this client.
 */
function defaultPanelForEntryContext(
  entry: ClientCardEntryContext | "" | null | undefined,
  clientServices: string,
  firmServices: string[],
): ClientCardPanel {
  let preferred: ClientCardPanel = "overview";
  switch (entry) {
    case "bookkeeping":
      preferred = "stream-bookkeeping";
      break;
    case "company":
      preferred = "stream-audit";
      break;
    case "individuals":
      preferred = "stream-tax-return";
      break;
    case "osek":
      // VAT is never top-level — open Bookkeeping (→ VAT via section intent).
      preferred = "stream-bookkeeping";
      break;
    case "trust":
      // No dedicated Trust process tab yet.
      preferred = "overview";
      break;
    default:
      // all | potential | one-time | overview | empty
      preferred = "overview";
  }
  if (preferred === "overview") return "overview";
  const streams = streamsForClient(
    clientServices,
    firmServices,
    entry === "individuals" ? "individuals" : undefined,
  );
  return streams.some((s) => s.id === preferred) ? preferred : "overview";
}

/** Lookup label for a stream panel id (known or custom). */
function streamLabelForPanel(
  panel: ClientCardPanel,
  streams?: ClientStreamDef[],
): string | undefined {
  const fromStreams = streams?.find((s) => s.id === panel)?.label;
  if (fromStreams) return fromStreams;
  const known = Object.values(KNOWN_STREAM_BY_SERVICE).find((k) => k.id === panel);
  if (known) return known.label;
  if (isCustomStreamPanel(panel)) {
    const slug = panel.slice("stream-custom:".length);
    return slug
      .split("-")
      .filter(Boolean)
      .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
      .join(" ");
  }
  return undefined;
}

