/** Year folder tree for Bookkeeping (mirrors firm Company Folder template layout). */
function buildBookkeepingWorkingFolder(
  lang: UiLang,
  client: DemoRow,
  year: string,
  uploaded: PortalDocRequest[],
): TaxReturnFolderNode[] {
  const short = client.name.split(" ")[0] ?? client.name;
  const safe = client.name.replace(/[\\/:*?"<>|]/g, "_");
  const portalUploads: TaxReturnFolderNode[] = uploaded.map((r) => ({
    id: `bk-file-upload-${r.id}`,
    label: r.uploadedFileName ?? `${r.docName}.pdf`,
    kind: "file",
  }));
  const emptyPortal: TaxReturnFolderNode = {
    id: "bk-file-portal-empty",
    label: lang === "he" ? "(אין העלאות עדיין)" : "(no uploads yet)",
    kind: "file",
  };
  return [
    {
      id: `bk-root-${client.id}-${year}`,
      label: `${safe} · ${year}`,
      kind: "folder",
      children: [
        {
          id: "bk-banks",
          label: lang === "he" ? "בנקים" : "Banks",
          kind: "folder",
          children: [
            {
              id: "bk-file-bank-csv",
              label: `Bank_CSV_${short}_${year}.csv`,
              kind: "file",
            },
            {
              id: "bk-file-bank-stmt",
              label:
                lang === "he"
                  ? `דפי_בנק_${short}_${year}.pdf`
                  : `Bank_statements_${short}_${year}.pdf`,
              kind: "file",
            },
          ],
        },
        {
          id: "bk-invoices",
          label: lang === "he" ? "חשבוניות ספקים" : "Supplier invoices",
          kind: "folder",
          children: [
            {
              id: "bk-file-inv-pack",
              label: `Supplier_invoices_${short}_${year}.pdf`,
              kind: "file",
            },
          ],
        },
        {
          id: "bk-reconcile",
          label: lang === "he" ? "התאמות בנק" : "Bank reconcile",
          kind: "folder",
          children: [
            {
              id: "bk-file-recon",
              label: `Bank_reconcile_${short}_${year}.xlsx`,
              kind: "file",
            },
          ],
        },
        {
          id: "bk-working-papers",
          label: lang === "he" ? "ניירות עבודה" : "Working papers",
          kind: "folder",
          children: [
            {
              id: "bk-file-wp-cards",
              label:
                lang === "he"
                  ? `כרטסות_${year}.pdf`
                  : `Account_cards_${year}.pdf`,
              kind: "file",
            },
            {
              id: "bk-file-wp-depr",
              label: lang === "he" ? `פחת_${year}.pdf` : `Depreciation_${year}.pdf`,
              kind: "file",
            },
          ],
        },
        {
          id: "bk-trial-balance",
          label:
            lang === "he" ? "פ.נ הנהלת חשבונות" : "Trial balance (BK)",
          kind: "folder",
          children: [
            {
              id: "bk-file-tb",
              label:
                lang === "he"
                  ? `פ.נ. ${short} - ${year}.pdf`
                  : `TB_${short}_${year}.pdf`,
              kind: "file",
            },
          ],
        },
        {
          id: "bk-portal",
          label: lang === "he" ? "העלאות פורטל" : "Portal uploads",
          kind: "folder",
          children: portalUploads.length > 0 ? portalUploads : [emptyPortal],
        },
        {
          id: "bk-general",
          label: lang === "he" ? "כללי" : "General",
          kind: "folder",
          children: [
            {
              id: "bk-file-general-note",
              label:
                lang === "he"
                  ? `הערות_הנה״ח_${year}.txt`
                  : `BK_notes_${year}.txt`,
              kind: "file",
            },
          ],
        },
      ],
    },
  ];
}

