function demoTaxReturnChecklist(
  lang: UiLang,
  stage: TaxReturnProcessStage,
  doneOverrides: Record<string, boolean> = {},
): WorkspaceChecklistItem[] {
  const activeIdx = taxReturnProcessIndex(stage);
  const rows: {
    id: string;
    stageId: TaxReturnProcessStage;
    labelKey: CrmUiKey;
  }[] = [
    {
      id: "tr-c-materials",
      stageId: "materials",
      labelKey: "taxReturnCheckMaterials",
    },
    {
      id: "tr-c-filing",
      stageId: "filing",
      labelKey: "taxReturnCheckFiling",
    },
    {
      id: "tr-c-signature",
      stageId: "client-signature",
      labelKey: "taxReturnCheckSignature",
    },
    {
      id: "tr-c-transmission",
      stageId: "transmission",
      labelKey: "taxReturnCheckTransmission",
    },
    {
      id: "tr-c-further",
      stageId: "further-handling",
      labelKey: "taxReturnCheckFurther",
    },
  ];
  return rows.map((row) => {
    const autoDone = taxReturnProcessIndex(row.stageId) < activeIdx;
    return {
      id: row.id,
      stageId: row.stageId,
      label: t(lang, row.labelKey),
      done: doneOverrides[row.id] ?? autoDone,
    };
  });
}

