function ModuleCard({
  tile,
  onOpen,
}: {
  tile: ModuleTile;
  onOpen: (tile: ModuleTile) => void;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [androidPreview] = useCanvasState<boolean>(
    ANDROID_PREVIEW_LS_KEY,
    false,
  );
  const badge = tile.badgeCount && tile.badgeCount > 0 ? tile.badgeCount : 0;
  const badgeLabel = badge > 99 ? "99+" : String(badge);
  const iconColor = chromeIconAccent(tile.id, theme.category);
  /** Packed Sumit-style square (~152×152); icon ~42% of side; text clamped (no clip). */
  const tileSide = 152;
  const iconBox = 64;

  /** Android / Sumit mobile: wide row, large icon + label — not a square tile. */
  if (androidPreview) {
    return (
      <button
        type="button"
        onClick={() => onOpen(tile)}
        data-chrome="module-card-android-row"
        style={{
          all: "unset",
          cursor: "pointer",
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          gap: 14,
          boxSizing: "border-box",
          width: "100%",
          minHeight: 76,
          padding: "12px 14px",
          background: chromeCardBg(theme),
          border: `1px solid ${waveChipAlpha(iconColor, "55")}`,
          borderRadius: 12,
          color: theme.text.primary,
        }}
      >
        <div
          style={{
            position: "relative",
            width: 56,
            height: 56,
            flexShrink: 0,
          }}
        >
          <div
            style={{
              width: 56,
              height: 56,
              borderRadius: 14,
              background: waveChipAlpha(iconColor, "28"),
              border: `1px solid ${waveChipAlpha(iconColor, "66")}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxSizing: "border-box",
            }}
          >
            <ModuleTileIcon tileId={tile.id} color={iconColor} size={36} />
          </div>
          {badge > 0 ? (
            <div
              style={{
                position: "absolute",
                top: -4,
                right: -4,
                minWidth: 18,
                height: 18,
                padding: "0 5px",
                borderRadius: 999,
                background: theme.category.red,
                color: theme.text.onAccent,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxSizing: "border-box",
                border: `2px solid ${chromeCardBg(theme)}`,
                fontSize: 10,
                fontWeight: 700,
                lineHeight: 1,
              }}
              aria-label={`${badge} new`}
            >
              {badgeLabel}
            </div>
          ) : null}
        </div>
        <Stack gap={2} style={{ flex: 1, minWidth: 0 }}>
          <ChromeText
            weight="semibold"
            style={{
              fontSize: 16,
              lineHeight: 1.25,
              color: theme.text.primary,
            }}
          >
            {tileLabel(uiLang, tile.id, tile.label)}
          </ChromeText>
          <ChromeText
            size="small"
            style={{
              fontSize: 12,
              lineHeight: 1.25,
              color: chromeInkMuted(theme),
              overflow: "hidden",
              display: "-webkit-box",
              WebkitLineClamp: 2,
              WebkitBoxOrient: "vertical",
            }}
          >
            {tileHint(uiLang, tile.id, tile.hint)}
          </ChromeText>
        </Stack>
      </button>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onOpen(tile)}
      style={{
        all: "unset",
        cursor: "pointer",
        display: "flex",
        flexDirection: "column",
        boxSizing: "border-box",
        width: tileSide,
        height: tileSide,
        minWidth: tileSide,
        minHeight: tileSide,
        maxWidth: tileSide,
        maxHeight: tileSide,
        aspectRatio: "1 / 1",
        background: chromeCardBg(theme),
        border: `1px solid ${waveChipAlpha(iconColor, "55")}`,
        borderRadius: 12,
        padding: "12px 10px 10px",
        textAlign: "center",
        color: theme.text.primary,
        overflow: "hidden",
      }}
    >
      <Stack
        gap={6}
        style={{
          alignItems: "center",
          justifyContent: "center",
          flex: 1,
          minHeight: 0,
          width: "100%",
        }}
      >
        <div
          style={{
            position: "relative",
            width: iconBox,
            height: iconBox,
            flexShrink: 0,
          }}
        >
          <div
            style={{
              width: iconBox,
              height: iconBox,
              borderRadius: 14,
              background: waveChipAlpha(iconColor, "28"),
              border: `1px solid ${waveChipAlpha(iconColor, "66")}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxSizing: "border-box",
            }}
          >
            <ModuleTileIcon tileId={tile.id} color={iconColor} size={44} />
          </div>
          {badge > 0 && (
            <div
              style={{
                position: "absolute",
                top: -5,
                right: -5,
                minWidth: 18,
                height: 18,
                padding: "0 5px",
                borderRadius: 999,
                background: theme.category.red,
                color: theme.text.onAccent,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxSizing: "border-box",
                border: `2px solid ${chromeCardBg(theme)}`,
                fontSize: 10,
                fontWeight: 700,
                lineHeight: 1,
              }}
              aria-label={`${badge} new`}
            >
              {badgeLabel}
            </div>
          )}
        </div>
        <ChromeText
          weight="semibold"
          style={{
            textAlign: "center",
            color: theme.text.primary,
            fontSize: 13,
            lineHeight: 1.2,
            maxWidth: "100%",
            overflow: "hidden",
            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
          }}
        >
          {tileLabel(uiLang, tile.id, tile.label)}
        </ChromeText>
        <ChromeText
          size="small"
          style={{
            textAlign: "center",
            color: chromeInkMuted(theme),
            fontSize: 11,
            lineHeight: 1.2,
            maxWidth: "100%",
            overflow: "hidden",
            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
          }}
        >
          {tileHint(uiLang, tile.id, tile.hint)}
        </ChromeText>
      </Stack>
    </button>
  );
}


/**
 * GMAIL_DUAL_NAV_V3 — sole home chrome.
 * Narrow primary rail (icons) + hamburger-pinned secondary as a normal flex layout column
 * (never absolute/overlay — that is TempTabPopup only).
 * Hover a *different* primary → TempTabPopup flyout (ephemeral overlay); pinned secondary stays docked.
 * Click/hamburger pins. Old single "Categories" HomeSidebar is deleted — do not restore.
 */
/** Slightly wider than Gmail’s 72 so icons/labels/badges aren’t clipped by secondary/main. */
const PRIMARY_RAIL_WIDTH = 80;
const SECONDARY_SIDEBAR_WIDTH = 256;
/** Punch at top of every secondary sidebar (fits SECONDARY_SIDEBAR_WIDTH). */
const SECONDARY_PUNCH_SIZE = 152;

/**
 * Mid-deep plum primary-rail palette — clearly lighter than v455 near-black plum.
 * Colored rail that still carries white/light icons (not pastel, not black).
 */
const CHROME_PRIMARY_RAIL_BG = "#4A3A6B";
const CHROME_PRIMARY_RAIL_BORDER = "#635288";
const CHROME_PRIMARY_RAIL_FG = "#F7F4FC";
/** Idle labels — brighter than prior grey-lavender so Tools/Worker read clearly. */
const CHROME_PRIMARY_RAIL_FG_MUTED = "#E6DFF2";
const CHROME_PRIMARY_RAIL_HOVER_PILL = "rgba(247,244,252,0.10)";
const CHROME_PRIMARY_RAIL_MENU_BG = "rgba(247,244,252,0.12)";
const CHROME_PRIMARY_RAIL_MENU_BORDER = "rgba(247,244,252,0.20)";
/** Fallback only — selected pills prefer RAIL_ICON_COLORS[id]. */
const CHROME_PRIMARY_RAIL_ACCENT = "#8B7AB8";

/**
 * Refined per-nav identity colors — Sumit Crm Decision Board / host category +
 * chartPalette hues (blue, green, cyan, orange, yellow, pink, indigo, teal),
 * lifted slightly for the mid-plum rail. No neon sky/hot-pink/acid-orange.
 */
const RAIL_ICON_COLORS: Record<string, string> = {
  client: "#70B0D8",
  clients: "#70B0D8",
  worker: "#D4A84B",
  billing: "#52B896",
  "tax-return": "#D4784A",
  bookkeeping: "#2A9A8A",
  "audit-companies": "#6BA86B",
  /** Brighter Sumit orange — readable on plum; was muddy #C06028. */
  tools: "#E8923C",
  work: "#5A6CC0",
  tasks: "#5A6CC0",
  boards: "#5A6CC0",
  chats: "#C85898",
  whatsapp: "#25D366",
  workers: "#2E79B5",
  admin: "#7B64B8",
  systemadmin: "#9AAADC",
  help: "#70B0D8",
};

type ChromeCategoryPalette = ReturnType<typeof useHostTheme>["category"];

/** Resolve primary-rail identity color (bold accent on plum). */
function railIconColor(id: string): string {
  const key = normalizePrimaryCategory(id);
  return (
    RAIL_ICON_COLORS[key] ??
    RAIL_ICON_COLORS[id] ??
    CHROME_PRIMARY_RAIL_ACCENT
  );
}

/**
 * Primary-rail icon accents — distinct per nav (not flat lavender).
 * WhatsApp stays recognizable #25D366.
 */
function chromeNavAccent(
  id: string,
  _category: ChromeCategoryPalette,
): string {
  return railIconColor(id);
}

/** Per-item colored capsule (selected) / soft accent wash (hover) on plum rail. */
function chromeRailPillBackground(
  _theme: ReturnType<typeof useHostTheme>,
  selected: boolean,
  hovered: boolean,
  navId?: string,
): string {
  const accent = navId ? railIconColor(navId) : CHROME_PRIMARY_RAIL_ACCENT;
  if (selected) {
    /** Soft wash of that icon’s color — not muddy grey-purple, not solid neon. */
    return waveChipAlpha(accent, "55");
  }
  if (hovered) {
    /** Whisper of the item accent — idle stays transparent. */
    return waveChipAlpha(accent, "28");
  }
  return "transparent";
}

function chromeRailPillBorder(
  _theme: ReturnType<typeof useHostTheme>,
  selected: boolean,
  navId?: string,
): string {
  if (!selected) return "1px solid transparent";
  const accent = navId ? railIconColor(navId) : CHROME_PRIMARY_RAIL_ACCENT;
  return `1px solid ${waveChipAlpha(accent, "AA")}`;
}

