/** System Admin → Template fields — CRUD for {…} merge tokens used across all templates. */
function TemplateMergeFieldsScreen() {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [fieldsRaw, setFields] = useCanvasState<TemplateMergeField[]>(
    "templateMergeFields.v1",
    DEFAULT_TEMPLATE_MERGE_FIELDS,
  );
  const fields = mergeTemplateMergeFieldsWithDefaults(fieldsRaw);
  const [editingId, setEditingId] = useCanvasState(
    "templateMergeFieldsEditingId.v1",
    "",
  );
  const [draftKey, setDraftKey] = useCanvasState(
    "templateMergeFieldsDraftKey.v1",
    "",
  );
  const [draftLabelEn, setDraftLabelEn] = useCanvasState(
    "templateMergeFieldsDraftLabelEn.v1",
    "",
  );
  const [draftLabelHe, setDraftLabelHe] = useCanvasState(
    "templateMergeFieldsDraftLabelHe.v1",
    "",
  );
  const [draftDescription, setDraftDescription] = useCanvasState(
    "templateMergeFieldsDraftDesc.v1",
    "",
  );
  const [draftSource, setDraftSource] = useCanvasState<TemplateMergeFieldSource>(
    "templateMergeFieldsDraftSource.v1",
    "customDefault",
  );
  const [draftDefault, setDraftDefault] = useCanvasState(
    "templateMergeFieldsDraftDefault.v1",
    "",
  );
  const [flash, setFlash] = useCanvasState("templateMergeFieldsFlash.v1", "");
  const [error, setError] = useCanvasState("templateMergeFieldsError.v1", "");

  const persist = (next: TemplateMergeField[]) => {
    setFields(next.map(normalizeTemplateMergeField));
  };

  const startEdit = (row: TemplateMergeField) => {
    setEditingId(row.id);
    setDraftKey(row.key);
    setDraftLabelEn(row.labelEn);
    setDraftLabelHe(row.labelHe);
    setDraftDescription(row.description);
    setDraftSource(row.source);
    setDraftDefault(row.defaultValue);
    setFlash("");
    setError("");
  };

  const startAdd = () => {
    setEditingId("__new__");
    setDraftKey("");
    setDraftLabelEn("");
    setDraftLabelHe("");
    setDraftDescription("");
    setDraftSource("customDefault");
    setDraftDefault("");
    setFlash("");
    setError("");
  };

  const cancelEdit = () => {
    setEditingId("");
    setError("");
  };

  const saveEdit = () => {
    const key = sanitizeMergeFieldKey(draftKey);
    if (!key) {
      setError(t(uiLang, "templateMergeFieldsKeyRequired"));
      return;
    }
    if (!/^[a-zA-Z][a-zA-Z0-9_]*$/.test(key)) {
      setError(t(uiLang, "templateMergeFieldsKeyInvalid"));
      return;
    }
    const conflict = fields.some(
      (f) =>
        f.key === key &&
        (editingId === "__new__" || f.id !== editingId),
    );
    if (conflict) {
      setError(t(uiLang, "templateMergeFieldsKeyDup"));
      return;
    }

    if (editingId === "__new__") {
      const next = normalizeTemplateMergeField({
        id: `mf-custom-${Date.now()}`,
        key,
        labelEn: draftLabelEn.trim() || key,
        labelHe: draftLabelHe.trim() || draftLabelEn.trim() || key,
        description: draftDescription.trim(),
        source: draftSource,
        defaultValue: draftDefault,
        builtIn: false,
      });
      persist([...fields, next]);
    } else {
      const existing = fields.find((f) => f.id === editingId);
      if (!existing) return;
      persist(
        fields.map((f) =>
          f.id === editingId
            ? normalizeTemplateMergeField({
                ...f,
                key: existing.builtIn ? existing.key : key,
                labelEn: draftLabelEn.trim() || key,
                labelHe: draftLabelHe.trim() || draftLabelEn.trim() || key,
                description: draftDescription.trim(),
                source: draftSource,
                defaultValue: draftDefault,
                builtIn: existing.builtIn,
              })
            : f,
        ),
      );
    }
    setEditingId("");
    setError("");
    setFlash(t(uiLang, "templateMergeFieldsSaved"));
  };

  const deleteField = (id: string) => {
    const row = fields.find((f) => f.id === id);
    if (!row) return;
    if (row.builtIn) {
      setError(t(uiLang, "templateMergeFieldsCannotDeleteBuiltIn"));
      return;
    }
    persist(fields.filter((f) => f.id !== id));
    if (editingId === id) setEditingId("");
    setFlash("");
    setError("");
  };

  const sourceOptions = TEMPLATE_MERGE_FIELD_SOURCES.map((src) => ({
    value: src,
    label: t(uiLang, MERGE_SOURCE_UI_KEY[src]),
  }));

  return (
    <Stack gap={16}>
      <Row align="center" gap={12} wrap>
        <Spacer />
        <Pill tone="info">{t(uiLang, "systemAdminPill")}</Pill>
      </Row>

      <Stack gap={4}>
        <H1>{t(uiLang, "templateMergeFieldsTitle")}</H1>
        <ChromeText tone="secondary">{t(uiLang, "templateMergeFieldsHint")}</ChromeText>
      </Stack>

      {flash ? (
        <Callout tone="success" title={t(uiLang, "save")}>
          {flash}
        </Callout>
      ) : null}
      {error ? (
        <Callout tone="danger" title={t(uiLang, "templateMergeFieldsTitle")}>
          {error}
        </Callout>
      ) : null}

      <Row gap={8} wrap>
        <Button variant="primary" onClick={startAdd}>
          {t(uiLang, "templateMergeFieldsAdd")}
        </Button>
        <Button
          variant="secondary"
          onClick={() => {
            persist(mergeTemplateMergeFieldsWithDefaults(fields));
            setFlash(t(uiLang, "templateMergeFieldsSaved"));
          }}
        >
          {t(uiLang, "save")}
        </Button>
      </Row>

      {editingId ? (
        <Stack
          gap={10}
          style={{
            padding: 14,
            borderRadius: 10,
            border: `1px solid ${CHROME_BORDER_BLUE}`,
            background: CHROME_WHITE,
          }}
        >
          <ChromeText weight="semibold">
            {editingId === "__new__"
              ? t(uiLang, "templateMergeFieldsAdd")
              : t(uiLang, "templateSettingsEdit")}
          </ChromeText>
          <Grid columns={2} gap={12}>
            <Stack gap={4}>
              <FieldLabel>{t(uiLang, "templateMergeFieldsTokenKey")}</FieldLabel>
              <ChromeTextInput
                value={draftKey}
                onChange={setDraftKey}
                disabled={
                  editingId !== "__new__" &&
                  Boolean(fields.find((f) => f.id === editingId)?.builtIn)
                }
              />
              <ChromeText size="small" tone="tertiary">
                {t(uiLang, "templateMergeFieldsTokenKeyHint")}
              </ChromeText>
            </Stack>
            <Stack gap={4}>
              <FieldLabel>{t(uiLang, "templateMergeFieldsSource")}</FieldLabel>
              <Select
                value={draftSource}
                onChange={(v) => setDraftSource(v as TemplateMergeFieldSource)}
                options={sourceOptions}
              />
            </Stack>
            <Stack gap={4}>
              <FieldLabel>{t(uiLang, "templateMergeFieldsLabelEn")}</FieldLabel>
              <ChromeTextInput value={draftLabelEn} onChange={setDraftLabelEn} />
            </Stack>
            <Stack gap={4}>
              <FieldLabel>{t(uiLang, "templateMergeFieldsLabelHe")}</FieldLabel>
              <ChromeTextInput value={draftLabelHe} onChange={setDraftLabelHe} />
            </Stack>
            <Stack gap={4} style={{ gridColumn: "1 / -1" }}>
              <FieldLabel>
                {t(uiLang, "templateMergeFieldsDescription")}
              </FieldLabel>
              <ChromeTextInput
                value={draftDescription}
                onChange={setDraftDescription}
              />
            </Stack>
            <Stack gap={4} style={{ gridColumn: "1 / -1" }}>
              <FieldLabel>{t(uiLang, "templateMergeFieldsDefault")}</FieldLabel>
              <ChromeTextInput value={draftDefault} onChange={setDraftDefault} />
            </Stack>
          </Grid>
          <Row gap={8} wrap>
            <Button variant="primary" onClick={saveEdit}>
              {t(uiLang, "save")}
            </Button>
            <Button variant="ghost" onClick={cancelEdit}>
              {t(uiLang, "cancel")}
            </Button>
          </Row>
          <ChromeText size="small" tone="tertiary">
            {t(uiLang, "templateMergeFieldsInsert")}:{" "}
            <span
              style={{
                fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
                color: theme.accent.primary,
              }}
            >
              {mergeFieldToken(sanitizeMergeFieldKey(draftKey) || "token")}
            </span>
            {" → "}
            {demoValueForMergeSource(
              draftSource,
              uiLang,
              draftDefault,
            )}
          </ChromeText>
        </Stack>
      ) : null}

      <FirmDataTable
        headers={[
          t(uiLang, "templateMergeFieldsTokenKey"),
          uiLang === "he" ? "תווית" : "Label",
          t(uiLang, "templateMergeFieldsSource"),
          "",
        ]}
        rows={fields.map((row) => [
          <Stack gap={2} key={`${row.id}-tok`}>
            <ChromeText
              size="small"
              weight="semibold"
              style={{
                fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
                color: theme.accent.primary,
              }}
            >
              {mergeFieldToken(row.key)}
            </ChromeText>
            <Pill tone={row.builtIn ? "info" : "neutral"}>
              {row.builtIn
                ? t(uiLang, "templateMergeFieldsBuiltIn")
                : t(uiLang, "templateMergeFieldsCustom")}
            </Pill>
          </Stack>,
          <Stack gap={2} key={`${row.id}-lab`}>
            <ChromeText size="small">{mergeFieldLabel(uiLang, row)}</ChromeText>
            {row.description ? (
              <ChromeText size="small" tone="tertiary">
                {row.description}
              </ChromeText>
            ) : null}
          </Stack>,
          <ChromeText size="small" key={`${row.id}-src`}>
            {t(uiLang, MERGE_SOURCE_UI_KEY[row.source])}
            {row.defaultValue
              ? ` · ${row.defaultValue}`
              : ""}
          </ChromeText>,
          <Row gap={6} key={`${row.id}-act`} wrap>
            <Button variant="secondary" onClick={() => startEdit(row)}>
              {t(uiLang, "templateSettingsEdit")}
            </Button>
            {!row.builtIn ? (
              <Button variant="ghost" onClick={() => deleteField(row.id)}>
                {t(uiLang, "remove")}
              </Button>
            ) : null}
          </Row>,
        ])}
        stickyHeader={false}
      />
    </Stack>
  );
}

/** Firm default Enter-is-send for staff Chats (Manager / System Admin). Shares desk settings field with WhatsApp. */
function ChatsSettingsScreen({
  role,
  embedded = false,
  onClose,
}: {
  role: Role;
  embedded?: boolean;
  onClose?: () => void;
}) {
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [settings, setSettings] = useCanvasState<WhatsAppDeskSettings>(
    "whatsappDeskSettings.v1",
    DEFAULT_WHATSAPP_DESK_SETTINGS,
  );
  const [saveFlash, setSaveFlash] = useCanvasState(
    "chatsFirmSettingsFlash.v1",
    "",
  );
  const canEdit = isAdminLike(role);

  const patch = (partial: Partial<WhatsAppDeskSettings>) => {
    if (!canEdit) return;
    setSettings((prev) => ({ ...prev, ...partial }));
  };

  const onSave = () => {
    if (!canEdit) return;
    setSaveFlash(t(uiLang, "chatsSettingsSaved"));
  };

  return (
    <Stack gap={16}>
      <Row align="center" gap={12} wrap>
        {embedded && onClose ? (
          <Button variant="ghost" onClick={onClose}>
            {t(uiLang, "backToInbox")}
          </Button>
        ) : null}
        <Spacer />
        {isAdminLike(role) ? (
          <Pill tone="info">
            {isSystemAdmin(role)
              ? t(uiLang, "systemAdminPill")
              : t(uiLang, "manager")}
          </Pill>
        ) : null}
      </Row>

      <Stack gap={4}>
        {embedded ? (
          <H2>{t(uiLang, "chatsSettings")}</H2>
        ) : (
          <H1>{t(uiLang, "chatsSettings")}</H1>
        )}
        <ChromeText tone="secondary">{t(uiLang, "chatsSettingsHint")}</ChromeText>
      </Stack>

      {!canEdit ? (
        <Callout tone="warning" title={t(uiLang, "chatsSettings")}>
          {t(uiLang, "chatsSettingsWorkersReadonly")}
        </Callout>
      ) : null}

      {saveFlash ? (
        <Callout tone="success" title={t(uiLang, "save")}>
          {saveFlash}
        </Callout>
      ) : null}

      <FormSection title={t(uiLang, "chatsSettingsComposerSection")}>
        <Row align="center" gap={10} wrap>
          <Toggle
            checked={waEnterIsSendEnabled(settings)}
            onChange={() =>
              patch({ enterIsSend: !waEnterIsSendEnabled(settings) })
            }
            disabled={!canEdit}
          />
          <Stack gap={2} style={{ minWidth: 0, flex: 1 }}>
            <ChromeText weight="medium">
              {t(uiLang, "waDeskEnterIsSend")}
            </ChromeText>
            <ChromeText size="small" tone="tertiary">
              {t(uiLang, "waDeskEnterIsSendHint")}
            </ChromeText>
          </Stack>
        </Row>
      </FormSection>

      {canEdit ? (
        <Row gap={8} wrap>
          <Button variant="primary" onClick={onSave}>
            {t(uiLang, "save")}
          </Button>
          {embedded && onClose ? (
            <Button variant="secondary" onClick={onClose}>
              {t(uiLang, "backToInbox")}
            </Button>
          ) : null}
        </Row>
      ) : embedded && onClose ? (
        <Row gap={8} wrap>
          <Button variant="secondary" onClick={onClose}>
            {t(uiLang, "backToInbox")}
          </Button>
        </Row>
      ) : null}

      <Callout tone="info" title={t(uiLang, "whoCanOpen")}>
        {t(uiLang, "chatsSettingsWho")}
      </Callout>
    </Stack>
  );
}

