function filesEntryLabel(lang: UiLang, entry: FilesBrowserEntry): string {
  return lang === "he" ? entry.nameHe || entry.name : entry.name;
}

function filesEntryHint(lang: UiLang, entry: FilesBrowserEntry): string {
  if (lang === "he") return entry.hintHe || entry.hint || "—";
  return entry.hint || "—";
}

function filesBreadcrumb(
  entries: FilesBrowserEntry[],
  folderId: string | null,
): FilesBrowserEntry[] {
  const byId = new Map(entries.map((e) => [e.id, e]));
  const chain: FilesBrowserEntry[] = [];
  let cur = folderId ? byId.get(folderId) : undefined;
  while (cur) {
    chain.unshift(cur);
    cur = cur.parentId ? byId.get(cur.parentId) : undefined;
  }
  return chain;
}

/** System Admin → Files root / cloud — Sumit-like share browser + stage A/B settings. */
type HelpFeedbackKind = "help" | "bug" | "suggestion";
type HelpFeedbackStatus =
  | "queued"
  | "ai_replied"
  | "human_replied"
  | "ai_fixed"
  | "closed";

type HelpFeedbackThreadMsg = {
  id: string;
  from: "worker" | "support" | "ai";
  text: string;
  at: string;
  attachmentName?: string;
  /** System Admin who sent a human support reply (for presence ranking). */
  fromWorkerId?: string;
};

type HelpFeedbackItem = {
  id: string;
  kind: HelpFeedbackKind;
  subject: string;
  body: string;
  authorName: string;
  authorWorkerId: string;
  createdAt: string;
  read: boolean;
  /** Worker saw support/AI reply in Help Messages (FAB badge). */
  workerRead?: boolean;
  status: HelpFeedbackStatus;
  aiReply?: string;
  humanReply?: string;
  /** Legacy single human reply author (when threadMessages unset). */
  humanReplyByWorkerId?: string;
  attachmentName?: string;
  threadMessages?: HelpFeedbackThreadMsg[];
  /** When true, scheduled AI fix runs may process this bug/suggestion (demo). */
  aiIncludeInFixes?: boolean;
  aiFixedAt?: string;
};

