type AiScanFindingSeverity = "bug" | "security" | "warning";
type AiScanFindingStatus = "open" | "fixed";

type AiScanFinding = {
  id: string;
  title: string;
  titleHe: string;
  detail: string;
  detailHe: string;
  severity: AiScanFindingSeverity;
  /** When true, included in the next Run fixes pass. */
  fixSelected: boolean;
  status: AiScanFindingStatus;
};

