/** Fill missing approval flags (older canvas state) — default true for safety. */
function normalizeWorkerSettings(
  s: Partial<WorkerExpectedHours> &
    Pick<
      WorkerExpectedHours,
      | "hoursPerDay"
      | "hoursPerWeek"
      | "daysPerWeek"
      | "workDays"
      | "payType"
      | "monthlySalary"
      | "hourlyRate"
    >,
): WorkerExpectedHours {
  return {
    hoursPerDay: s.hoursPerDay,
    hoursPerWeek: s.hoursPerWeek,
    hoursPerWeekManual: s.hoursPerWeekManual,
    daysPerWeek: s.daysPerWeek,
    workDays: [...s.workDays],
    payType: s.payType,
    monthlySalary: s.monthlySalary,
    hourlyRate: s.hourlyRate,
    requireTimeApproval: s.requireTimeApproval !== false,
    requirePunchEditApproval: s.requirePunchEditApproval !== false,
    requireLeaveApproval: s.requireLeaveApproval !== false,
  };
}

function defaultWorkerSettings(workerId: string): WorkerExpectedHours {
  return normalizeWorkerSettings(
    DEFAULT_WORKER_EXPECTED_HOURS[workerId] ?? {
      hoursPerDay: 8,
      hoursPerWeek: 40,
      daysPerWeek: 5,
      workDays: [...DEFAULT_WORK_DAYS],
      payType: "monthly",
      monthlySalary: 0,
      hourlyRate: 0,
      requireTimeApproval: true,
      requirePunchEditApproval: true,
      requireLeaveApproval: true,
    },
  );
}

function cloneWorkerSettings(s: WorkerExpectedHours): WorkerExpectedHours {
  return normalizeWorkerSettings(s);
}

function workerSettingsEqual(
  a: WorkerExpectedHours,
  b: WorkerExpectedHours,
): boolean {
  const na = normalizeWorkerSettings(a);
  const nb = normalizeWorkerSettings(b);
  if (
    na.hoursPerDay !== nb.hoursPerDay ||
    na.hoursPerWeek !== nb.hoursPerWeek ||
    Boolean(na.hoursPerWeekManual) !== Boolean(nb.hoursPerWeekManual) ||
    na.daysPerWeek !== nb.daysPerWeek ||
    na.payType !== nb.payType ||
    na.monthlySalary !== nb.monthlySalary ||
    na.hourlyRate !== nb.hourlyRate ||
    na.requireTimeApproval !== nb.requireTimeApproval ||
    na.requirePunchEditApproval !== nb.requirePunchEditApproval ||
    na.requireLeaveApproval !== nb.requireLeaveApproval ||
    na.workDays.length !== nb.workDays.length
  ) {
    return false;
  }
  return na.workDays.every((d, i) => d === nb.workDays[i]);
}

function expectedHoursForPeriod(
  settings: WorkerExpectedHours | undefined,
  period: HoursPeriod,
  bucketCount: number,
): number | null {
  if (!settings) return null;
  if (period === "week") return settings.hoursPerWeek;
  if (period === "month") return settings.hoursPerWeek * Math.max(1, bucketCount);
  return settings.hoursPerWeek * 52;
}

/** Month id (YYYY-MM) for Overview pay figures from the selected period. */
function payMonthIdForOverview(
  period: HoursPeriod,
  weekId: string,
  monthId: string,
  yearId: string,
): string {
  if (period === "month") return monthId;
  if (period === "week") {
    const week = HOURS_WEEK_OPTIONS.find((w) => w.id === weekId);
    if (week?.start) return week.start.slice(0, 7);
    return CURRENT_HOURS_MONTH_ID;
  }
  if (yearId === CURRENT_HOURS_YEAR) return CURRENT_HOURS_MONTH_ID;
  return `${yearId}-12`;
}

function monthHoursTotal(workerId: string, monthId: string): number {
  const weeks =
    MONTH_WEEK_TOTALS_BY_WORKER[workerId]?.[monthId] ?? [];
  return weeks.reduce((s, w) => s + w.hours, 0);
}

/**
 * Earned this month from Worker settings pay plan.
 * Hourly: rate × month hours. Monthly: salary, prorated when month hours
 * are below expected (hours/week × week buckets in that month).
 */
function calcEarnedThisMonth(
  settings: WorkerExpectedHours,
  monthHours: number,
  monthId: string,
  workerId: string,
): number {
  if (settings.payType === "hourly") {
    return Math.round(settings.hourlyRate * monthHours * 100) / 100;
  }
  const weekBuckets =
    MONTH_WEEK_TOTALS_BY_WORKER[workerId]?.[monthId]?.length ?? 4;
  const expectedHrs = settings.hoursPerWeek * Math.max(1, weekBuckets);
  if (monthHours <= 0) return 0;
  if (monthHours >= expectedHrs * 0.95) return settings.monthlySalary;
  return Math.round(settings.monthlySalary * (monthHours / expectedHrs));
}

function weekHoursTotal(workerId: string, weekId: string): number {
  const days = WEEKLY_HOURS_BY_WORKER[workerId]?.[weekId] ?? [];
  return days.reduce((s, d) => s + d.hours, 0);
}

function yearHoursTotal(workerId: string, yearId: string): number {
  const months = YEAR_MONTH_TOTALS_BY_WORKER[workerId]?.[yearId] ?? [];
  return months.reduce((s, m) => s + m.hours, 0);
}

/** Prorate a salary pot by actual vs expected hours (0.95 ≈ full). */
function prorateSalary(
  salaryPot: number,
  actualHours: number,
  expectedHours: number,
): number {
  if (actualHours <= 0 || expectedHours <= 0) return 0;
  if (actualHours >= expectedHours * 0.95) return Math.round(salaryPot);
  return Math.round(salaryPot * (actualHours / expectedHours));
}

/**
 * Earned for Overview Week / Month / Year — uses selected period hours.
 * Hourly: rate × period hours. Monthly: week≈salary/4, month=salary,
 * year≈salary×12, each prorated when under expected hours.
 */
function calcEarnedForPeriod(
  settings: WorkerExpectedHours,
  period: HoursPeriod,
  weekId: string,
  monthId: string,
  yearId: string,
  workerId: string,
): number {
  if (period === "week") {
    const hours = weekHoursTotal(workerId, weekId);
    if (settings.payType === "hourly") {
      return Math.round(settings.hourlyRate * hours * 100) / 100;
    }
    return prorateSalary(
      settings.monthlySalary / 4,
      hours,
      settings.hoursPerWeek,
    );
  }
  if (period === "month") {
    return calcEarnedThisMonth(
      settings,
      monthHoursTotal(workerId, monthId),
      monthId,
      workerId,
    );
  }
  const hours = yearHoursTotal(workerId, yearId);
  if (settings.payType === "hourly") {
    return Math.round(settings.hourlyRate * hours * 100) / 100;
  }
  return prorateSalary(
    settings.monthlySalary * 12,
    hours,
    settings.hoursPerWeek * 52,
  );
}

function earnedLabelKeyForPeriod(period: HoursPeriod): CrmUiKey {
  if (period === "week") return "earnedThisWeek";
  if (period === "year") return "earnedThisYear";
  return "earnedThisMonth";
}

/**
 * Demo paid-to-date scaled to the selected period so Amount owed
 * stays coherent with earned (week ≪ month ≪ year).
 */
function paidToDateForPeriod(
  monthPaidSample: number,
  period: HoursPeriod,
): number {
  if (period === "week") return Math.round((monthPaidSample / 4) * 100) / 100;
  if (period === "year") return Math.round(monthPaidSample * 8 * 100) / 100;
  return monthPaidSample;
}

