/** Current/upcoming list: To >= today, or still pending. */
function isLeaveCurrentOrPending(r: LeaveRequest, today: string): boolean {
  return r.to >= today || r.status === "pending";
}

/** Past list: leave/holiday already ended before today. */
function isLeavePast(r: LeaveRequest, today: string): boolean {
  return r.to < today;
}

