/**
 * Year range for date choosers (newest first). Wide enough for DOB +
 * billing / leave dates.
 */
const DATE_CHOOSER_YEARS: string[] = (() => {
  const years: string[] = [];
  for (let y = 2035; y >= 1930; y -= 1) years.push(String(y));
  return years;
})();

/** Weekday headers — Sunday first; RTL layout mirrors them for Hebrew. */
const DATE_CHOOSER_WEEKDAYS: { en: string; he: string }[] = [
  { en: "Sun", he: "א" },
  { en: "Mon", he: "ב" },
  { en: "Tue", he: "ג" },
  { en: "Wed", he: "ד" },
  { en: "Thu", he: "ה" },
  { en: "Fri", he: "ו" },
  { en: "Sat", he: "ש" },
];

function daysInCalendarMonth(year: number, month1to12: number): number {
  return new Date(year, month1to12, 0).getDate();
}

function parseIsoDateParts(
  iso: string,
): { y: string; m: string; d: string } | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso.trim());
  if (!match) return null;
  return { y: match[1], m: match[2], d: match[3] };
}

/** Clamp day to valid range for year/month; always returns YYYY-MM-DD. */
function buildIsoDate(y: string, m: string, d: string): string {
  const year = Number(y);
  const month = Number(m);
  let day = Number(d);
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) {
    return `${y}-${m}-${d}`;
  }
  const max = daysInCalendarMonth(year, month);
  if (day < 1) day = 1;
  if (day > max) day = max;
  return `${y}-${m}-${String(day).padStart(2, "0")}`;
}

/** Local calendar today as YYYY-MM-DD. */
function todayLocalIso(): string {
  const now = new Date();
  return buildIsoDate(
    String(now.getFullYear()),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0"),
  );
}

/** Sumit-style DD/MM/YYYY for the calendar footer. */
function formatDdMmYyyy(iso: string): string {
  const parts = parseIsoDateParts(iso);
  if (!parts) return iso;
  return `${parts.d}/${parts.m}/${parts.y}`;
}

function shiftCalendarMonth(
  y: string,
  m: string,
  delta: number,
): { y: string; m: string } {
  const year = Number(y);
  const month = Number(m);
  const shifted = new Date(year, month - 1 + delta, 1);
  return {
    y: String(shifted.getFullYear()),
    m: String(shifted.getMonth() + 1).padStart(2, "0"),
  };
}

type DateChooserCell = {
  iso: string;
  day: number;
  inMonth: boolean;
};

/** Sunday-first month grid including muted leading/trailing days. */
function buildDateChooserCells(y: string, m: string): DateChooserCell[] {
  const year = Number(y);
  const month = Number(m);
  const firstDow = new Date(year, month - 1, 1).getDay();
  const daysHere = daysInCalendarMonth(year, month);
  const prev = shiftCalendarMonth(y, m, -1);
  const daysPrev = daysInCalendarMonth(Number(prev.y), Number(prev.m));
  const cells: DateChooserCell[] = [];
  for (let i = firstDow - 1; i >= 0; i -= 1) {
    const day = daysPrev - i;
    cells.push({
      iso: buildIsoDate(prev.y, prev.m, String(day).padStart(2, "0")),
      day,
      inMonth: false,
    });
  }
  for (let day = 1; day <= daysHere; day += 1) {
    cells.push({
      iso: buildIsoDate(y, m, String(day).padStart(2, "0")),
      day,
      inMonth: true,
    });
  }
  const next = shiftCalendarMonth(y, m, 1);
  let nextDay = 1;
  while (cells.length % 7 !== 0 || cells.length < 42) {
    cells.push({
      iso: buildIsoDate(next.y, next.m, String(nextDay).padStart(2, "0")),
      day: nextDay,
      inMonth: false,
    });
    nextDay += 1;
    if (cells.length >= 42) break;
  }
  return cells;
}

/** Group key YYYY-MM from leave start date. */
function leaveFromYearMonth(r: LeaveRequest): string {
  return r.from.slice(0, 7);
}

function calendarMonthLabel(lang: UiLang, monthNum: string): string {
  const m = CALENDAR_MONTHS.find((x) => x.id === monthNum);
  if (!m) return monthNum;
  return lang === "he" ? m.he : m.en;
}

/** Single-field DateChooser label — localized; ISO fallback if unparsed. */
function formatDateChooserLabel(iso: string, lang: UiLang): string {
  const parts = parseIsoDateParts(iso);
  if (!parts) return iso.trim() || "—";
  const dayNum = String(Number(parts.d));
  const month = calendarMonthLabel(lang, parts.m);
  if (lang === "he") return `${dayNum} ב${month} ${parts.y}`;
  return `${month} ${dayNum}, ${parts.y}`;
}

function leaveHistoryMonthHeading(lang: UiLang, yearMonth: string): string {
  const year = yearMonth.slice(0, 4);
  const monthNum = yearMonth.slice(5, 7);
  return `${calendarMonthLabel(lang, monthNum)} ${year}`;
}

function groupLeaveHistoryByMonth(
  rows: LeaveRequest[],
): { monthId: string; rows: LeaveRequest[] }[] {
  const map = new Map<string, LeaveRequest[]>();
  for (const r of rows) {
    const key = leaveFromYearMonth(r);
    const list = map.get(key);
    if (list) list.push(r);
    else map.set(key, [r]);
  }
  return [...map.entries()]
    .sort((a, b) => b[0].localeCompare(a[0]))
    .map(([monthId, groupRows]) => ({
      monthId,
      rows: groupRows
        .slice()
        .sort((a, b) => b.from.localeCompare(a.from)),
    }));
}

