function shiftHoursIndex(len: number, index: number, delta: number): number {
  return Math.max(0, Math.min(len - 1, index + delta));
}

function formatClockNow(): string {
  const d = new Date();
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}:${String(d.getSeconds()).padStart(2, "0")}`;
}

/** HH:MM for “Since …” labels (drop seconds when present). */
function formatClockHm(hm: string): string {
  const parts = hm.split(":");
  if (parts.length >= 2) {
    return `${parts[0]}:${parts[1]}`;
  }
  return hm;
}

function formatMinutesAsHours(totalMin: number): string {
  const safe = Math.max(0, Math.round(totalMin));
  const h = Math.floor(safe / 60);
  const m = safe % 60;
  return `${h}:${String(m).padStart(2, "0")}`;
}

/** Live elapsed display: M:SS or H:MM:SS. */
function formatElapsedClock(totalSec: number): string {
  const safe = Math.max(0, Math.floor(totalSec));
  const h = Math.floor(safe / 3600);
  const m = Math.floor((safe % 3600) / 60);
  const s = safe % 60;
  if (h > 0) {
    return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  }
  return `${m}:${String(s).padStart(2, "0")}`;
}

/** Resolve punch instant; falls back to day + HH:MM(:SS) local time. */
function parsePunchInstantMs(p: TimePunch): number {
  if (typeof p.atMs === "number" && Number.isFinite(p.atMs)) return p.atMs;
  const parts = p.time.split(":").map((x) => Number(x));
  const h = parts[0] ?? 0;
  const m = parts[1] ?? 0;
  const s = Number.isFinite(parts[2]) ? parts[2] : 0;
  const iso = `${p.day}T${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  const t = new Date(iso).getTime();
  return Number.isFinite(t) ? t : Date.now();
}

/** Local midnight (ms) for an ISO YYYY-MM-DD calendar day. */
function localMidnightMs(dayIso: string): number {
  const parts = parseIsoDateParts(dayIso);
  if (!parts) return 0;
  return new Date(
    Number(parts.y),
    Number(parts.m) - 1,
    Number(parts.d),
    0,
    0,
    0,
    0,
  ).getTime();
}

/**
 * Tick hook — updates every second while `running` (clocked in / on break).
 * Cleans up the interval on unmount or when running becomes false.
 */
function useLiveNowMs(running: boolean): number {
  const [nowMs, setNowMs] = useState(() => Date.now());
  useEffect(() => {
    setNowMs(Date.now());
    if (!running) return;
    const id = setInterval(() => setNowMs(Date.now()), 1000);
    return () => clearInterval(id);
  }, [running]);
  return nowMs;
}

/**
 * Worked seconds for a local calendar day from punch pairs (breaks pause).
 * Default day = local today from `nowMs`. Open overnight sessions only count
 * the slice after local midnight; prior-day closed segments are excluded.
 */
function workedSecondsFromPunches(
  punches: TimePunch[],
  nowMs: number,
  workerId?: string,
  dayIso?: string,
): number {
  const targetDay = dayIso ?? todayLocalIso();
  const dayStart = localMidnightMs(targetDay);
  const dayEnd = dayStart + 86_400_000;
  if (!Number.isFinite(dayStart) || dayStart <= 0) return 0;

  // Walk full worker history so an open "in" from yesterday still contributes
  // only the post-midnight slice toward today.
  const ordered = punches
    .filter((p) => (workerId ? p.workerId === workerId : true))
    .slice()
    .sort((a, b) => parsePunchInstantMs(a) - parsePunchInstantMs(b));

  let total = 0;
  let segmentStart: number | null = null;
  let onBreak = false;

  const addClipped = (fromMs: number, toMs: number) => {
    const a = Math.max(fromMs, dayStart);
    const b = Math.min(toMs, dayEnd, nowMs);
    if (b > a) total += b - a;
  };

  for (const p of ordered) {
    const tMs = parsePunchInstantMs(p);
    if (p.kind === "in") {
      segmentStart = tMs;
      onBreak = false;
    } else if (p.kind === "break-start" && segmentStart != null && !onBreak) {
      addClipped(segmentStart, tMs);
      onBreak = true;
      segmentStart = null;
    } else if (p.kind === "break-end" && onBreak) {
      segmentStart = tMs;
      onBreak = false;
    } else if (p.kind === "out" && segmentStart != null && !onBreak) {
      addClipped(segmentStart, tMs);
      segmentStart = null;
    }
  }
  if (segmentStart != null && !onBreak) {
    addClipped(segmentStart, nowMs);
  }
  return Math.floor(total / 1000);
}

/** Derive clock status from today's punch sequence for a worker. */
function clockStatusFromPunches(
  punches: TimePunch[],
  workerId: string,
  day: string = todayLocalIso(),
): ClockStatus {
  const today = punches
    .filter((p) => p.day === day && p.workerId === workerId)
    .slice()
    .sort((a, b) => parsePunchInstantMs(a) - parsePunchInstantMs(b));
  let next: ClockStatus = "out";
  for (const p of today) {
    if (p.kind === "in" || p.kind === "break-end") next = "in";
    else if (p.kind === "out") next = "out";
    else if (p.kind === "break-start") next = "break";
  }
  return next;
}

function clockStatusLabel(lang: UiLang, status: ClockStatus): string {
  if (status === "in") return t(lang, "clockStatusIn");
  if (status === "break") return t(lang, "clockStatusBreak");
  return t(lang, "clockStatusOut");
}

/** Worked minutes today from punch pairs (breaks pause the clock). */
function workedMinutesFromPunches(
  punches: TimePunch[],
  nowHm: string,
  workerId?: string,
): number {
  return Math.floor(
    workedSecondsFromPunches(
      punches,
      (() => {
        const parts = nowHm.split(":").map((x) => Number(x));
        const h = parts[0] ?? 0;
        const m = parts[1] ?? 0;
        const s = Number.isFinite(parts[2]) ? parts[2] : 0;
        const d = new Date();
        d.setHours(h, m, s, 0);
        return d.getTime();
      })(),
      workerId,
    ) / 60,
  );
}

function punchKindLabel(lang: UiLang, kind: PunchKind): string {
  if (kind === "in") return t(lang, "punchIn");
  if (kind === "out") return t(lang, "punchOut");
  if (kind === "break-start") return t(lang, "punchBreakStart");
  return t(lang, "punchBreakEnd");
}

function leaveKindLabel(lang: UiLang, kind: LeaveKind): string {
  if (kind === "vacation") return t(lang, "leaveVacation");
  if (kind === "sick") return t(lang, "leaveSick");
  if (kind === "reserve") return t(lang, "leaveReserve");
  return t(lang, "leaveHoliday");
}

/** Unique ISO dates, ascending. */
function sortedUniqueLeaveDates(dates: string[]): string[] {
  return [...new Set(dates.map((d) => d.trim()).filter(Boolean))].sort();
}

function leaveFromCell(r: LeaveRequest): string {
  if (r.dates && r.dates.length > 0) {
    return sortedUniqueLeaveDates(r.dates).join(", ");
  }
  return r.from;
}

function leaveToCell(r: LeaveRequest): string {
  if (r.dates && r.dates.length > 0) return "—";
  return r.to;
}

function leaveStatusLabel(lang: UiLang, status: LeaveStatus): string {
  if (status === "pending") return t(lang, "leavePending");
  if (status === "approved") return t(lang, "leaveApproved");
  return t(lang, "leaveRejected");
}

/** History list: approved past leave shows as Taken. */
function leaveHistoryStatusLabel(lang: UiLang, status: LeaveStatus): string {
  if (status === "approved") return t(lang, "leaveTaken");
  if (status === "rejected") return t(lang, "leaveRejected");
  return t(lang, "leavePending");
}

function manualTimeStatusLabel(
  lang: UiLang,
  status: ManualTimeEditStatus,
): string {
  if (status === "pending") return t(lang, "manualTimePendingApproval");
  if (status === "approved") return t(lang, "leaveApproved");
  return t(lang, "leaveRejected");
}

/** Build official punches from an approved manual time edit. */
function punchesFromManualEdit(req: ManualTimeEditRequest): TimePunch[] {
  const stamp = Date.now();
  const instant = (hm: string) => {
    const parts = hm.split(":").map((x) => Number(x));
    const h = parts[0] ?? 0;
    const m = parts[1] ?? 0;
    const s = Number.isFinite(parts[2]) ? parts[2] : 0;
    return new Date(
      `${req.date}T${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`,
    ).getTime();
  };
  const rows: TimePunch[] = [
    {
      id: `tp-mte-${req.id}-in-${stamp}`,
      workerId: req.workerId,
      kind: "in",
      time: req.clockIn,
      day: req.date,
      atMs: instant(req.clockIn),
    },
  ];
  if (req.breakStart.trim() && req.breakEnd.trim()) {
    rows.push(
      {
        id: `tp-mte-${req.id}-bs-${stamp}`,
        workerId: req.workerId,
        kind: "break-start",
        time: req.breakStart.trim(),
        day: req.date,
        atMs: instant(req.breakStart.trim()),
      },
      {
        id: `tp-mte-${req.id}-be-${stamp}`,
        workerId: req.workerId,
        kind: "break-end",
        time: req.breakEnd.trim(),
        day: req.date,
        atMs: instant(req.breakEnd.trim()),
      },
    );
  }
  rows.push({
    id: `tp-mte-${req.id}-out-${stamp}`,
    workerId: req.workerId,
    kind: "out",
    time: req.clockOut,
    day: req.date,
    atMs: instant(req.clockOut),
  });
  return rows;
}

/** JS getDay() → Israeli office WorkDayKey (Sat = null). */
function workDayKeyFromIso(iso: string): WorkDayKey | null {
  const d = new Date(`${iso}T12:00:00`);
  if (!Number.isFinite(d.getTime())) return null;
  const map: Array<WorkDayKey | null> = [
    "Sun",
    "Mon",
    "Tue",
    "Wed",
    "Thu",
    "Fri",
    null,
  ];
  return map[d.getDay()] ?? null;
}

/** Inclusive From–To workdays using worker schedule (fallback Sun–Thu). */
function enumerateWorkDatesInRange(
  fromIso: string,
  toIso: string,
  workDays: WorkDayKey[],
): string[] {
  const from = fromIso.trim();
  const to = toIso.trim();
  if (!from || !to || from > to) return [];
  const days = workDays.length > 0 ? workDays : [...DEFAULT_WORK_DAYS];
  const out: string[] = [];
  let cur = from;
  let guard = 0;
  while (cur <= to && guard < 400) {
    const key = workDayKeyFromIso(cur);
    if (key && days.includes(key)) out.push(cur);
    cur = addIsoDays(cur, 1);
    guard += 1;
  }
  return out;
}

/**
 * Keep In → Break start → Break end → Out coherent after edit/delete.
 * Drops orphan Break end, Break start when not clocked in, Out while on
 * break (also removes the open Break start), duplicate Ins, etc.
 */
function cascadeNormalizeDayPunches(dayPunches: TimePunch[]): {
  punches: TimePunch[];
  autoFixed: boolean;
} {
  const sorted = dayPunches
    .slice()
    .sort((a, b) => parsePunchInstantMs(a) - parsePunchInstantMs(b));
  const kept: TimePunch[] = [];
  let state: "out" | "in" | "break" = "out";
  let autoFixed = false;

  for (const p of sorted) {
    if (p.kind === "in") {
      if (state === "out") {
        kept.push(p);
        state = "in";
      } else {
        autoFixed = true;
      }
    } else if (p.kind === "break-start") {
      if (state === "in") {
        kept.push(p);
        state = "break";
      } else {
        autoFixed = true;
      }
    } else if (p.kind === "break-end") {
      if (state === "break") {
        kept.push(p);
        state = "in";
      } else {
        autoFixed = true;
      }
    } else if (p.kind === "out") {
      if (state === "in") {
        kept.push(p);
        state = "out";
      } else if (state === "break") {
        autoFixed = true;
        for (let i = kept.length - 1; i >= 0; i -= 1) {
          if (kept[i].kind === "break-start") {
            kept.splice(i, 1);
            break;
          }
        }
        kept.push(p);
        state = "out";
      } else {
        autoFixed = true;
      }
    }
  }
  return { punches: kept, autoFixed };
}

/** Apply edit or delete to one worker-day, then cascade-normalize. */
function applyPunchMutationToDay(
  allPunches: TimePunch[],
  workerId: string,
  day: string,
  punchId: string,
  patch: { kind: PunchKind; time: string } | null,
): { nextAll: TimePunch[]; proposedDay: TimePunch[]; autoFixed: boolean } {
  const others = allPunches.filter(
    (p) => !(p.workerId === workerId && p.day === day),
  );
  let dayRows = allPunches.filter(
    (p) => p.workerId === workerId && p.day === day,
  );
  const target = dayRows.find((p) => p.id === punchId);

  if (patch === null) {
    dayRows = dayRows.filter((p) => p.id !== punchId);
    if (target?.kind === "break-start") {
      const afterMs = parsePunchInstantMs(target);
      const orphanEnd = dayRows
        .slice()
        .sort((a, b) => parsePunchInstantMs(a) - parsePunchInstantMs(b))
        .find(
          (p) =>
            p.kind === "break-end" && parsePunchInstantMs(p) >= afterMs,
        );
      if (orphanEnd) {
        dayRows = dayRows.filter((p) => p.id !== orphanEnd.id);
      }
    }
  } else if (target) {
    const parts = patch.time.split(":").map((x) => Number(x));
    const h = parts[0] ?? 0;
    const m = parts[1] ?? 0;
    const s = Number.isFinite(parts[2]) ? parts[2] : 0;
    const atMs = new Date(
      `${day}T${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`,
    ).getTime();
    dayRows = dayRows.map((p) =>
      p.id === punchId
        ? {
            ...p,
            kind: patch.kind,
            time: patch.time,
            atMs: Number.isFinite(atMs) ? atMs : p.atMs,
          }
        : p,
    );
  }

  const { punches: proposedDay, autoFixed } =
    cascadeNormalizeDayPunches(dayRows);
  return {
    nextAll: [...others, ...proposedDay],
    proposedDay,
    autoFixed,
  };
}

/** Shared diameter for Modules-home and Time Clock punch buttons. */
const PUNCH_BUTTON_SIZE = 208;

/**
 * Round punch control for Modules home shell (sidebar).
 * Same UX as TimeClockScreen; shares timeClockStatus.v2 / punches.v2.
 * Optional `size` for sidebar fit (default matches Time Clock 208).
 */
function CompactHomePunchButton({
  size = PUNCH_BUTTON_SIZE,
}: {
  size?: number;
} = {}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [status, setStatus] = useCanvasState<ClockStatus>(
    "timeClockStatus.v2",
    "out",
  );
  const [punches, setPunches] = useCanvasState<TimePunch[]>(
    "timeClockPunches.v2",
    DEFAULT_TIME_PUNCHES,
  );

  const liveRunning = status === "in" || status === "break";
  const nowMs = useLiveNowMs(liveRunning);
  const elapsed = formatElapsedClock(
    workedSecondsFromPunches(punches, nowMs, DEMO_WORKER.id),
  );
  const clockToday = todayLocalIso();
  const lastIn = punches
    .filter(
      (p) =>
        p.workerId === DEMO_WORKER.id &&
        p.kind === "in" &&
        p.day === clockToday,
    )
    .slice()
    .sort((a, b) => parsePunchInstantMs(b) - parsePunchInstantMs(a))[0];
  const statusLabel =
    status === "in"
      ? t(uiLang, "clockStatusIn")
      : status === "break"
        ? t(uiLang, "clockStatusBreak")
        : t(uiLang, "clockStatusOut");

  const scale = size / PUNCH_BUTTON_SIZE;
  const labelSize = Math.max(11, Math.round(13 * scale));
  const elapsedSize = Math.max(24, Math.round(32 * scale));
  const labelMaxWidth = Math.round(176 * scale);
  const breakMinHeight = Math.max(28, Math.round(44 * scale));
  const breakFontSize = Math.max(10, Math.round(12 * scale));
  const breakPadY = Math.max(4, Math.round(7 * scale));
  const breakPadX = Math.max(8, Math.round(14 * scale));
  const breakMarginTop = Math.max(3, Math.round(6 * scale));
  const breakRadius = Math.max(6, Math.round(8 * scale));
  const punchPad = Math.max(8, Math.round(14 * scale));

  const addPunch = (kind: PunchKind) => {
    const atMs = Date.now();
    setPunches((prev) => [
      ...prev,
      {
        id: `tp-${atMs}`,
        workerId: DEMO_WORKER.id,
        kind,
        time: formatClockNow(),
        day: todayLocalIso(),
        atMs,
      },
    ]);
  };

  const onClockIn = () => {
    if (status !== "out") return;
    addPunch("in");
    setStatus("in");
  };

  const onClockOut = () => {
    if (status === "out") return;
    if (status === "break") addPunch("break-end");
    addPunch("out");
    setStatus("out");
  };

  const onStartBreak = () => {
    if (status !== "in") return;
    addPunch("break-start");
    setStatus("break");
  };

  const onEndBreak = () => {
    if (status !== "break") return;
    addPunch("break-end");
    setStatus("in");
  };

  return (
    <button
      type="button"
      onClick={status === "out" ? onClockIn : onClockOut}
      title={`${statusLabel} · ${t(uiLang, "todayElapsed")} ${elapsed}`}
      style={{
        width: size,
        height: size,
        borderRadius: 999,
        border: "none",
        cursor: "pointer",
        background: theme.accent.primary,
        color: "#000000",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: Math.max(2, Math.round(4 * scale)),
        padding: `${punchPad}px ${Math.round(punchPad * 1.1)}px ${Math.max(8, punchPad - 2)}px`,
        textAlign: "center",
        flexShrink: 0,
      }}
    >
      <span
        style={{
          fontSize: labelSize,
          fontWeight: 600,
          lineHeight: 1.2,
          color: "#000000",
        }}
      >
        {statusLabel}
      </span>
      <span
        style={{
          fontSize: labelSize,
          fontWeight: 500,
          lineHeight: 1.3,
          color: "#000000",
          maxWidth: labelMaxWidth,
        }}
      >
        {t(uiLang, "todayElapsed")}
        {status !== "out" && lastIn
          ? ` · ${t(uiLang, "sinceTime")} ${formatClockHm(lastIn.time)}`
          : ""}
      </span>
      <span
        style={{
          fontSize: elapsedSize,
          fontWeight: 700,
          lineHeight: 1.05,
          letterSpacing: "-0.02em",
          marginTop: 2,
          marginBottom: 2,
          color: "#000000",
        }}
      >
        {elapsed}
      </span>
      <span
        style={{
          fontSize: labelSize,
          fontWeight: 600,
          lineHeight: 1.2,
          color: "#000000",
        }}
      >
        {status === "out" ? t(uiLang, "clockIn") : t(uiLang, "clockOut")}
      </span>
      {status === "in" || status === "break" ? (
        <span
          role="button"
          tabIndex={0}
          onClick={(e: {
            stopPropagation: () => void;
            preventDefault: () => void;
          }) => {
            e.stopPropagation();
            e.preventDefault();
            if (status === "in") onStartBreak();
            else onEndBreak();
          }}
          onKeyDown={(e: {
            key: string;
            stopPropagation: () => void;
            preventDefault: () => void;
          }) => {
            if (e.key === "Enter" || e.key === " ") {
              e.stopPropagation();
              e.preventDefault();
              if (status === "in") onStartBreak();
              else onEndBreak();
            }
          }}
          style={{
            marginTop: breakMarginTop,
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            minHeight: breakMinHeight,
            fontSize: breakFontSize,
            fontWeight: 700,
            lineHeight: 1.15,
            color: "#000000",
            cursor: "pointer",
            padding: `${breakPadY}px ${breakPadX}px`,
            borderRadius: breakRadius,
            background: CHROME_SOFT_BLUE,
            border: `1px solid ${CHROME_BORDER_BLUE}`,
            textDecoration: "none",
            userSelect: "none",
          }}
        >
          {status === "break" ? t(uiLang, "endBreak") : t(uiLang, "startBreak")}
        </span>
      ) : null}
    </button>
  );
}

/**
 * Firm Workers module (Manager / System Admin): add, edit, delete directory rows.
 * Separate from Time clock "Team" (attendance) — HR roster CRUD.
 *
 * Edit form renders inline on the row (Add form at top) so Edit is visible
 * even when the directory list is scrolled — top-only form looked broken.
 */
function WorkersModuleScreen() {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [departments] = useCanvasState<FirmDepartment[]>(
    "firmDepartments.v3",
    DEFAULT_FIRM_DEPARTMENTS,
  );
  const [workers, setWorkers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const [editingId, setEditingId] = useCanvasState(
    "firmWorkersEditingId.v2",
    "",
  );
  const [draftName, setDraftName] = useCanvasState(
    "firmWorkersDraftName.v1",
    "",
  );
  const [draftNameHe, setDraftNameHe] = useCanvasState(
    "firmWorkersDraftNameHe.v1",
    "",
  );
  const [draftDeptIds, setDraftDeptIds] = useCanvasState<string[]>(
    "firmWorkersDraftDepts.v2",
    [DEFAULT_FIRM_DEPARTMENTS[0]?.id ?? "reportDeptAccounting"],
  );
  const [draftTag, setDraftTag] = useCanvasState(
    "firmWorkersDraftTag.v1",
    "",
  );
  const [draftEmail, setDraftEmail] = useCanvasState(
    "firmWorkersDraftEmail.v1",
    "",
  );
  const [draftSigName, setDraftSigName] = useCanvasState(
    "firmWorkersDraftSigName.v1",
    "",
  );
  const [draftSigBody, setDraftSigBody] = useCanvasState(
    "firmWorkersDraftSigBody.v1",
    "",
  );
  const [flash, setFlash] = useCanvasState("firmWorkersFlash.v1", "");
  const [workerSearch, setWorkerSearch] = useCanvasState(
    "firmWorkersSearch.v1",
    "",
  );

  /** Persist seed emails/signatures/phones onto legacy firmWorkers.v3 rows once. */
  useEffect(() => {
    setWorkers((prev) => {
      const list = Array.isArray(prev) ? prev : DEMO_STAFF;
      let changed = false;
      const next = list.map((raw) => {
        const n = normalizeFirmWorker(raw);
        const missing =
          !(raw as FirmWorker).email?.trim() ||
          !(raw as FirmWorker).phone?.trim() ||
          !(raw as FirmWorker).emailSignatureName?.trim() ||
          !(raw as FirmWorker).emailSignatureBody?.trim();
        if (missing) changed = true;
        return n;
      });
      return changed ? next : list;
    });
  }, [setWorkers]);

  const defaultDeptId =
    departments[0]?.id ?? DEFAULT_FIRM_DEPARTMENTS[0]?.id ?? "reportDeptAccounting";

  const safeDraftDeptIds = (): string[] => {
    if (!Array.isArray(draftDeptIds)) return [defaultDeptId];
    const cleaned = draftDeptIds.filter(
      (id): id is string => typeof id === "string" && Boolean(id),
    );
    return cleaned.length > 0 ? cleaned : [defaultDeptId];
  };

  const toggleDraftDept = (deptId: string, checked: boolean) => {
    setDraftDeptIds((prev) => {
      const base = Array.isArray(prev)
        ? prev.filter((id): id is string => typeof id === "string" && Boolean(id))
        : [];
      if (checked) {
        if (base.includes(deptId)) return base.length > 0 ? base : [defaultDeptId];
        return [...base, deptId];
      }
      const next = base.filter((id) => id !== deptId);
      return next.length > 0 ? next : base.length > 0 ? base : [defaultDeptId];
    });
  };

  const startEdit = (row: FirmWorker) => {
    const normalized = normalizeFirmWorker(row);
    setEditingId(normalized.id);
    setDraftName(normalized.name);
    setDraftNameHe(normalized.nameHe);
    setDraftDeptIds(
      normalized.deptIds.length > 0 ? normalized.deptIds : [defaultDeptId],
    );
    setDraftTag(normalized.employeeTag);
    setFlash("");
  };

  const startAdd = () => {
    const nextTag = String(
      10 + workers.length + Math.floor(Math.random() * 80),
    ).padStart(2, "0");
    setEditingId("__new__");
    setDraftName("");
    setDraftNameHe("");
    setDraftDeptIds([defaultDeptId]);
    setDraftTag(nextTag);
    setFlash("");
  };

  const cancelEdit = () => {
    setEditingId("");
    setFlash("");
  };

  const saveEdit = () => {
    const name = draftName.trim();
    const nameHe = draftNameHe.trim() || name;
    if (!name) {
      setFlash(t(uiLang, "workersNameEn"));
      return;
    }
    const deptIds = safeDraftDeptIds();
    if (deptIds.length === 0) {
      setFlash(t(uiLang, "workersNeedDepartment"));
      return;
    }
    const normalized = normalizeFirmWorker({
      id: editingId === "__new__" ? "tmp" : editingId,
      name,
      nameHe,
      deptIds,
      deptId: deptIds[0],
      employeeTag: draftTag.trim() || "00",
      email: draftEmail.trim(),
      emailSignatureName: draftSigName.trim(),
      emailSignatureBody: draftSigBody.trim(),
    });
    if (editingId === "__new__") {
      const id = `staff-${Date.now().toString(36)}`;
      setWorkers((prev) => [
        ...normalizeFirmWorkers(Array.isArray(prev) ? prev : DEMO_STAFF),
        {
          ...normalized,
          id,
          employeeTag: draftTag.trim() || "00",
          email:
            draftEmail.trim() ||
            deriveWorkerEmail(id, name),
          emailSignatureName:
            draftSigName.trim() || deriveWorkerSignatureName(name),
          emailSignatureBody:
            draftSigBody.trim() ||
            deriveWorkerSignatureBody(
              name,
              nameHe,
              draftEmail.trim() || deriveWorkerEmail(id, name),
            ),
        },
      ]);
    } else if (editingId) {
      setWorkers((prev) =>
        normalizeFirmWorkers(Array.isArray(prev) ? prev : DEMO_STAFF).map((w) =>
          w.id === editingId
            ? {
                ...w,
                name,
                nameHe,
                deptId: normalized.deptId,
                deptIds: normalized.deptIds,
                employeeTag: draftTag.trim() || w.employeeTag,
                email: draftEmail.trim() || w.email,
                emailSignatureName:
                  draftSigName.trim() || w.emailSignatureName,
                emailSignatureBody:
                  draftSigBody.trim() || w.emailSignatureBody,
              }
            : w,
        ),
      );
    }
    setEditingId("");
    setFlash("");
  };

  const deleteWorker = (id: string) => {
    if (id === DEMO_WORKER.id) {
      setFlash(t(uiLang, "workersCannotDeleteSelf"));
      return;
    }
    setWorkers((prev) =>
      (Array.isArray(prev) ? prev : DEMO_STAFF).filter((w) => w.id !== id),
    );
    if (editingId === id) setEditingId("");
    setFlash("");
  };

  const editorForm = (
    <Stack
      gap={10}
      style={{
        padding: 14,
        borderRadius: 10,
        border: `1px solid ${chromeBorder(theme)}`,
        background: CHROME_WHITE,
        width: "100%",
        boxSizing: "border-box",
      }}
    >
      <Grid columns={2} gap={10}>
        <Stack gap={4}>
          <ChromeText size="small" weight="semibold">
            {t(uiLang, "workersNameEn")}
          </ChromeText>
          <ChromeTextInput value={draftName} onChange={setDraftName} />
        </Stack>
        <Stack gap={4}>
          <ChromeText size="small" weight="semibold">
            {t(uiLang, "workersNameHe")}
          </ChromeText>
          <ChromeTextInput value={draftNameHe} onChange={setDraftNameHe} />
        </Stack>
        <Stack gap={4} style={{ gridColumn: "1 / -1" }}>
          <ChromeText size="small" weight="semibold">
            {t(uiLang, "workersDepartments")}
          </ChromeText>
          <ChromeText size="small" tone="tertiary">
            {t(uiLang, "workersDepartmentsHint")}
          </ChromeText>
          <Row gap={12} wrap>
            {departments.map((d) => {
              const ids = safeDraftDeptIds();
              const checked = ids.includes(d.id);
              const isPrimary = ids[0] === d.id;
              return (
                <Checkbox
                  key={d.id}
                  checked={checked}
                  onChange={(v) => toggleDraftDept(d.id, v)}
                  label={
                    isPrimary && checked
                      ? `${departmentLabel(uiLang, d.id, departments)} ${t(uiLang, "workersPrimarySuffix")}`
                      : departmentLabel(uiLang, d.id, departments)
                  }
                />
              );
            })}
          </Row>
        </Stack>
        <Stack gap={4}>
          <ChromeText size="small" weight="semibold">
            {t(uiLang, "workersEmployeeTag")}
          </ChromeText>
          <ChromeTextInput value={draftTag} onChange={setDraftTag} />
        </Stack>
        <Stack gap={4} style={{ gridColumn: "1 / -1" }}>
          <ChromeText size="small" weight="semibold">
            {t(uiLang, "workersEmail")}
          </ChromeText>
          <ChromeText size="small" tone="tertiary">
            {t(uiLang, "workersEmailHint")}
          </ChromeText>
          <ChromeTextInput
            value={draftEmail}
            onChange={setDraftEmail}
            placeholder="name@intertax.example"
          />
        </Stack>
        <Stack gap={4}>
          <ChromeText size="small" weight="semibold">
            {t(uiLang, "workersEmailSignatureName")}
          </ChromeText>
          <ChromeTextInput value={draftSigName} onChange={setDraftSigName} />
        </Stack>
        <Stack gap={4} style={{ gridColumn: "1 / -1" }}>
          <ChromeText size="small" weight="semibold">
            {t(uiLang, "workersEmailSignatureBody")}
          </ChromeText>
          <ChromeText size="small" tone="tertiary">
            {t(uiLang, "workersEmailSignatureHint")}
          </ChromeText>
          <ChromeTextArea
            value={draftSigBody}
            onChange={setDraftSigBody}
            placeholder={t(uiLang, "workersEmailSignatureBody")}
          />
        </Stack>
      </Grid>
      <Row gap={8}>
        <Button variant="primary" onClick={saveEdit}>
          {t(uiLang, "workersSave")}
        </Button>
        <Button variant="ghost" onClick={cancelEdit}>
          {t(uiLang, "workersCancel")}
        </Button>
      </Row>
    </Stack>
  );

  const roster = normalizeFirmWorkers(
    Array.isArray(workers) ? workers : DEMO_STAFF,
  );
  const workerQ = workerSearch.trim().toLowerCase();
  const filteredRoster = workerQ
    ? roster.filter((row) => {
        const dept = departmentLabels(uiLang, row.deptIds, departments);
        return (
          row.name.toLowerCase().includes(workerQ) ||
          row.nameHe.toLowerCase().includes(workerQ) ||
          row.employeeTag.toLowerCase().includes(workerQ) ||
          row.email.toLowerCase().includes(workerQ) ||
          dept.toLowerCase().includes(workerQ)
        );
      })
    : roster;

  return (
    <Stack gap={14} style={{ ...SHELL_SCROLL, paddingInlineEnd: 4 }}>
      <Stack gap={4}>
        <H1 style={{ margin: 0 }}>{t(uiLang, "workersModule")}</H1>
        <ChromeText tone="secondary">{t(uiLang, "workersModuleHint")}</ChromeText>
      </Stack>

      <Row gap={8} wrap align="center">
        <Button variant="primary" onClick={startAdd}>
          {t(uiLang, "workersAdd")}
        </Button>
        <SearchAutocomplete
          value={workerSearch}
          onChange={setWorkerSearch}
          placeholder={t(uiLang, "workersSearchPlaceholder")}
          lang={uiLang}
          style={{ maxWidth: 320, flex: 1, minWidth: 180 }}
          candidates={uniqSearchCandidates(
            roster.flatMap((row) => [
              row.name,
              row.nameHe,
              row.employeeTag,
              row.email,
              departmentLabels(uiLang, row.deptIds, departments),
            ]),
          )}
        />
      </Row>

      {flash ? (
        <ChromeText size="small" tone="secondary">
          {flash}
        </ChromeText>
      ) : null}

      {editingId === "__new__" ? editorForm : null}

      {roster.length === 0 ? (
        <ChromeText tone="secondary">{t(uiLang, "workersEmpty")}</ChromeText>
      ) : (
        <Stack gap={8}>
          {filteredRoster.map((row) =>
            editingId === row.id ? (
              <Stack key={row.id} gap={8}>
                {editorForm}
              </Stack>
            ) : (
              <Row
                key={row.id}
                align="center"
                gap={12}
                style={{
                  padding: "12px 14px",
                  borderRadius: 10,
                  border: `1px solid ${chromeBorder(theme)}`,
                  background: CHROME_WHITE,
                  width: "100%",
                  boxSizing: "border-box",
                }}
              >
                <Stack gap={2} style={{ flex: 1, minWidth: 0 }}>
                  <ChromeText weight="semibold">
                    {uiLang === "he" ? row.nameHe : row.name}
                  </ChromeText>
                  <ChromeText size="small" tone="secondary">
                    {departmentLabels(uiLang, row.deptIds, departments)}
                    {" · "}
                    {row.employeeTag}
                    {" · "}
                    {row.email}
                  </ChromeText>
                </Stack>
                <Button variant="secondary" onClick={() => startEdit(row)}>
                  {t(uiLang, "workersEdit")}
                </Button>
                <Button variant="ghost" onClick={() => deleteWorker(row.id)}>
                  {t(uiLang, "workersDelete")}
                </Button>
              </Row>
            ),
          )}
        </Stack>
      )}
    </Stack>
  );
}

/**
 * Admin → Departments. System Admin can add/edit/delete; Manager can view the list.
 */
function DepartmentsScreen({ role }: { role: Role }) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const canEdit = isSystemAdmin(role);
  const [departments, setDepartments] = useCanvasState<FirmDepartment[]>(
    "firmDepartments.v3",
    DEFAULT_FIRM_DEPARTMENTS,
  );
  const [workers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const [editingId, setEditingId] = useCanvasState(
    "firmDepartmentsEditingId.v1",
    "",
  );
  const [draftNameEn, setDraftNameEn] = useCanvasState(
    "firmDepartmentsDraftEn.v1",
    "",
  );
  const [draftNameHe, setDraftNameHe] = useCanvasState(
    "firmDepartmentsDraftHe.v1",
    "",
  );
  const [flash, setFlash] = useCanvasState("firmDepartmentsFlash.v1", "");

  const startEdit = (row: FirmDepartment) => {
    if (!canEdit) return;
    setEditingId(row.id);
    setDraftNameEn(row.nameEn);
    setDraftNameHe(row.nameHe);
    setFlash("");
  };

  const startAdd = () => {
    if (!canEdit) return;
    setEditingId("__new__");
    setDraftNameEn("");
    setDraftNameHe("");
    setFlash("");
  };

  const cancelEdit = () => {
    setEditingId("");
    setFlash("");
  };

  const saveEdit = () => {
    if (!canEdit) return;
    const nameEn = draftNameEn.trim();
    const nameHe = draftNameHe.trim() || nameEn;
    if (!nameEn) {
      setFlash(t(uiLang, "departmentsNameEn"));
      return;
    }
    if (editingId === "__new__") {
      const id = `dept-${Date.now().toString(36)}`;
      setDepartments((prev) => [...prev, { id, nameEn, nameHe }]);
    } else {
      setDepartments((prev) =>
        prev.map((d) =>
          d.id === editingId ? { ...d, nameEn, nameHe } : d,
        ),
      );
    }
    setEditingId("");
    setFlash("");
  };

  const deleteDept = (id: string) => {
    if (!canEdit) return;
    if (
      workers.some((w) => normalizeFirmWorker(w).deptIds.includes(id))
    ) {
      setFlash(t(uiLang, "departmentsInUse"));
      return;
    }
    setDepartments((prev) => prev.filter((d) => d.id !== id));
    if (editingId === id) setEditingId("");
    setFlash("");
  };

  return (
    <Stack gap={14} style={{ ...SHELL_SCROLL, paddingInlineEnd: 4 }}>
      <Stack gap={4}>
        <H1 style={{ margin: 0 }}>{t(uiLang, "departments")}</H1>
        <ChromeText tone="secondary">{t(uiLang, "departmentsHint")}</ChromeText>
      </Stack>

      {!canEdit ? (
        <Callout tone="info" title={t(uiLang, "departments")}>
          {t(uiLang, "departmentsSysAdminOnly")}
        </Callout>
      ) : (
        <Row gap={8} wrap>
          <Button variant="primary" onClick={startAdd}>
            {t(uiLang, "departmentsAdd")}
          </Button>
        </Row>
      )}

      {flash ? (
        <ChromeText size="small" tone="secondary">
          {flash}
        </ChromeText>
      ) : null}

      {canEdit && editingId ? (
        <Stack
          gap={10}
          style={{
            padding: 14,
            borderRadius: 10,
            border: `1px solid ${chromeBorder(theme)}`,
            background: CHROME_WHITE,
            width: "100%",
            boxSizing: "border-box",
          }}
        >
          <Grid columns={2} gap={10}>
            <Stack gap={4}>
              <ChromeText size="small" weight="semibold">
                {t(uiLang, "departmentsNameEn")}
              </ChromeText>
              <ChromeTextInput value={draftNameEn} onChange={setDraftNameEn} />
            </Stack>
            <Stack gap={4}>
              <ChromeText size="small" weight="semibold">
                {t(uiLang, "departmentsNameHe")}
              </ChromeText>
              <ChromeTextInput value={draftNameHe} onChange={setDraftNameHe} />
            </Stack>
          </Grid>
          <Row gap={8}>
            <Button variant="primary" onClick={saveEdit}>
              {t(uiLang, "departmentsSave")}
            </Button>
            <Button variant="ghost" onClick={cancelEdit}>
              {t(uiLang, "departmentsCancel")}
            </Button>
          </Row>
        </Stack>
      ) : null}

      {departments.length === 0 ? (
        <ChromeText tone="secondary">{t(uiLang, "departmentsEmpty")}</ChromeText>
      ) : (
        <Stack gap={8}>
          {departments.map((row) => (
            <Row
              key={row.id}
              align="center"
              gap={12}
              style={{
                padding: "12px 14px",
                borderRadius: 10,
                border: `1px solid ${chromeBorder(theme)}`,
                background: CHROME_WHITE,
                width: "100%",
                boxSizing: "border-box",
              }}
            >
              <Stack gap={2} style={{ flex: 1, minWidth: 0 }}>
                <ChromeText weight="semibold">
                  {uiLang === "he" ? row.nameHe : row.nameEn}
                </ChromeText>
                <ChromeText size="small" tone="secondary">
                  {uiLang === "he" ? row.nameEn : row.nameHe}
                </ChromeText>
              </Stack>
              {canEdit ? (
                <>
                  <Button variant="secondary" onClick={() => startEdit(row)}>
                    {t(uiLang, "departmentsEdit")}
                  </Button>
                  <Button variant="ghost" onClick={() => deleteDept(row.id)}>
                    {t(uiLang, "departmentsDelete")}
                  </Button>
                </>
              ) : null}
            </Row>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

/* ─── My Boards (private per signed-in worker; defaults seeded from dept) ─── */

/** Standard ids: todo / doing / done; custom lists use mbcol-… ids. */
type MyBoardColumnId = string;
type MyBoardDueState = "overdue" | "dueSoon" | "none";
type MyBoardsView =
  | "board"
  | "reminders"
  | "settings"
  | FirmDeptBoardView;

type MyBoardExtraColumn = {
  id: string;
  title: string;
};

type MyBoardColumnRef = {
  id: MyBoardColumnId;
  labelKey?: CrmUiKey;
  title?: string;
};

/**
 * Firm board tabs on Work → Boards.
 * Order: one tab per signed-in worker deptIds (position default boards), then My Boards.
 * Active board is NOT a tab — it is a + New board template only.
 */
function FirmBoardsViewTabs({
  active,
  onSelect,
}: {
  active: MyBoardsView;
  onSelect: (next: MyBoardsView) => void;
}) {
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [signedInWorkerId] = useCanvasState(
    "signedInWorkerId.v1",
    DEMO_WORKER.id,
  );
  const [firmWorkers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const deptViews = workerFirmBoardViews(signedInWorkerId, firmWorkers);
  const tabs: { id: string; label: string }[] = [
    ...deptViews.map((view) => ({
      id: view,
      label: firmBoardViewLabel(uiLang, view),
    })),
    { id: "board", label: t(uiLang, "myBoards") },
  ];
  const activeId =
    isFirmDeptBoardView(active) && deptViews.includes(active)
      ? active
      : "board";
  return (
    <RaisedTabBar
      tabs={tabs}
      activeId={activeId}
      onSelect={(id) => {
        if (isFirmDeptBoardView(id) && deptViews.includes(id)) onSelect(id);
        else onSelect("board");
      }}
      ariaLabel={t(uiLang, "myBoardsShort")}
    />
  );
}

type MyBoardComment = {
  id: string;
  author: string;
  authorWorkerId?: string;
  body: string;
  at: string;
};

type TrelloRecurring = "never" | "daily" | "weekly" | "monthly" | "yearly";
type TrelloDueReminder =
  | "none"
  | "atDue"
  | "1day"
  | "2days"
  | "1week";
type TrelloBoardBg =
  | "default"
  | "green"
  | "blue"
  | "yellow"
  | "red"
  | "purple";
type TrelloAttachment = { id: string; name: string };
type TrelloChecklistItem = { id: string; text: string; done: boolean };

type MyBoardCard = {
  id: string;
  clientId: string;
  clientName: string;
  /** Editable card heading (Trello-style title). */
  title: string;
  /** Description / client comment body. */
  commentSnippet: string;
  columnId: MyBoardColumnId;
  /** ISO YYYY-MM-DD when set. */
  dueDate?: string;
  startDate?: string;
  dueTime?: string;
  recurring?: TrelloRecurring;
  dueReminder?: TrelloDueReminder;
  unread: boolean;
  watching?: boolean;
  labels?: string[];
  memberIds?: string[];
  checklist?: TrelloChecklistItem[];
  attachments?: TrelloAttachment[];
  coverColor?: TrelloBoardBg;
  archived?: boolean;
  comments: MyBoardComment[];
};

type MyBoardDef = {
  id: string;
  /** Firm department id (reportDept…). */
  deptId: string;
  titleEn: string;
  titleHe: string;
  /** Optional per-board column renames (overrides CRM_UI defaults). */
  columnLabels?: Partial<Record<string, string>>;
  /** Extra lists after To Do / Doing / Done (+ Add list). */
  extraColumns?: { id: string; title: string }[];
  starred?: boolean;
  description?: string;
  background?: TrelloBoardBg;
  cards: MyBoardCard[];
};

type MyBoardsState = {
  boards: MyBoardDef[];
  activeBoardId: string;
};

type MyBoardCardComposerState = {
  open: boolean;
  columnId: MyBoardColumnId;
  title: string;
  clientName: string;
  dueDate: string;
  body: string;
};

const EMPTY_MY_BOARD_CARD_COMPOSER: MyBoardCardComposerState = {
  open: false,
  columnId: "todo",
  title: "",
  clientName: "",
  dueDate: "",
  body: "",
};

/** Demo “today” for due/overdue blobs (matches canvas clock era). */
const MY_BOARDS_TODAY = "2026-09-18";

const MY_BOARD_COLUMNS: {
  id: MyBoardColumnId;
  labelKey: CrmUiKey;
}[] = [
  { id: "todo", labelKey: "myBoardsColTodo" },
  { id: "doing", labelKey: "myBoardsColDoing" },
  { id: "done", labelKey: "myBoardsColDone" },
];

/** HTML5 DnD payload for moving kanban cards between list columns. */
const KANBAN_CARD_DRAG_TYPE = "application/x-crm-kanban-card";

type KanbanCardDragData = {
  cardId: string;
  fromColumnId: string;
};

type KanbanDragTransfer = {
  setData: (format: string, data: string) => void;
  getData: (format: string) => string;
  effectAllowed: string;
  dropEffect: string;
};

function writeKanbanCardDrag(
  dt: KanbanDragTransfer,
  data: KanbanCardDragData,
): void {
  const raw = JSON.stringify(data);
  try {
    dt.setData(KANBAN_CARD_DRAG_TYPE, raw);
  } catch {
    /* some hosts only allow text/plain */
  }
  dt.setData("text/plain", raw);
  dt.effectAllowed = "move";
}

function readKanbanCardDrag(
  dt: KanbanDragTransfer,
): KanbanCardDragData | null {
  let raw = "";
  try {
    raw = dt.getData(KANBAN_CARD_DRAG_TYPE) || dt.getData("text/plain");
  } catch {
    raw = "";
  }
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as KanbanCardDragData;
    if (
      typeof parsed?.cardId !== "string" ||
      !parsed.cardId ||
      typeof parsed?.fromColumnId !== "string" ||
      !parsed.fromColumnId
    ) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

/** Canvas state key — boards are private per signed-in worker (v3 = tour-visible seed). */
function myBoardsStateKey(workerId: string): string {
  return `myBoards.v3:${workerId}`;
}

/** Canvas state key — email-reminder toggle is private per worker. */
function myBoardsEmailRemindersKey(workerId: string): string {
  return `myBoardsEmailReminders.v1:${workerId}`;
}

type MyBoardsUiPrefs = {
  watchNotify: boolean;
  showLabelColors: boolean;
  defaultCover: TrelloBoardBg;
};

const DEFAULT_MY_BOARDS_UI_PREFS: MyBoardsUiPrefs = {
  watchNotify: true,
  showLabelColors: true,
  defaultCover: "default",
};

function myBoardsUiPrefsKey(workerId: string): string {
  return `myBoardsUiPrefs.v1:${workerId}`;
}

function normalizeMyBoardsUiPrefs(raw: unknown): MyBoardsUiPrefs {
  if (!raw || typeof raw !== "object") return { ...DEFAULT_MY_BOARDS_UI_PREFS };
  const o = raw as Partial<MyBoardsUiPrefs>;
  return {
    watchNotify:
      typeof o.watchNotify === "boolean"
        ? o.watchNotify
        : DEFAULT_MY_BOARDS_UI_PREFS.watchNotify,
    showLabelColors:
      typeof o.showLabelColors === "boolean"
        ? o.showLabelColors
        : DEFAULT_MY_BOARDS_UI_PREFS.showLabelColors,
    defaultCover: normalizeTrelloBoardBg(
      o.defaultCover ?? DEFAULT_MY_BOARDS_UI_PREFS.defaultCover,
    ),
  };
}

function cloneMyBoardsState(state: MyBoardsState): MyBoardsState {
  return {
    activeBoardId: state.activeBoardId,
    boards: state.boards.map((b) => ({
      ...b,
      columnLabels: b.columnLabels ? { ...b.columnLabels } : undefined,
      extraColumns: b.extraColumns?.map((c) => ({ ...c })),
      cards: b.cards.map((c) => ({
        ...c,
        labels: c.labels ? [...c.labels] : undefined,
        memberIds: c.memberIds ? [...c.memberIds] : undefined,
        checklist: c.checklist?.map((item) => ({ ...item })),
        attachments: c.attachments?.map((a) => ({ ...a })),
        comments: c.comments.map((cm) => ({ ...cm })),
      })),
    })),
  };
}

const EMPTY_MY_BOARDS_STATE: MyBoardsState = {
  activeBoardId: "",
  boards: [],
};

/**
 * Trello Outstanding Invoices Intertax list titles — structure only, no cards.
 * Source: Intertax Trello board (see trello-crm-decision-board / product transcript).
 */
const TRELLO_OUTSTANDING_LIST_HEADLINES = [
  "To Do",
  "Paid per month",
  "Follow Up complete, waiting on payment",
  "Paid /WO",
  "On Hold",
  "Potenial Client",
  "Need To Make Receipts",
] as const;

function slugMyBoardExtraColId(title: string, index: number): string {
  const slug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 24);
  return `mbcol-bill-${index}-${slug || index}`;
}

/** True when a Billing private board still has the old Sample To Do/Doing/Done seed. */
function looksLikeLegacyBillingSampleSeed(cards: MyBoardCard[]): boolean {
  return cards.some(
    (c) =>
      c.commentSnippet === "Sample To Do card 1" ||
      c.commentSnippet === "Sample To Do card 2" ||
      c.commentSnippet === "Sample To Do card 3" ||
      c.commentSnippet === "Sample Doing card 1" ||
      c.commentSnippet === "Sample Done card 1",
  );
}

/**
 * Billing private-board default: Outstanding Invoices Intertax list names,
 * empty columns (no Trello cards / no Sample To Do cards).
 */
function seedBillingPrivateBoard(boardId: string): MyBoardDef {
  const headlines = TRELLO_OUTSTANDING_LIST_HEADLINES;
  return {
    id: boardId,
    deptId: "reportDeptBilling",
    titleEn: "Billing",
    titleHe: "גבייה",
    columnLabels: {
      todo: headlines[0],
      doing: headlines[1],
      done: headlines[2],
    },
    extraColumns: headlines.slice(3).map((title, i) => ({
      id: slugMyBoardExtraColId(title, i),
      title,
    })),
    cards: [],
  };
}

