/** True when board still has pre-tour plain Sample To Do seed (no badges). */
function looksLikePlainMyBoardSampleSeed(cards: MyBoardCard[]): boolean {
  const sample = cards.some(
    (c) =>
      c.commentSnippet === "Sample To Do card 1" ||
      c.commentSnippet === "Sample To Do card 2" ||
      c.commentSnippet === "Sample Doing card 1",
  );
  const rich = cards.some(
    (c) =>
      c.watching ||
      !!c.coverColor ||
      (c.labels?.length ?? 0) > 0 ||
      (c.checklist?.length ?? 0) > 0 ||
      (c.attachments?.length ?? 0) > 0,
  );
  return sample && !rich;
}

function seedStandardPrivateBoard(
  boardId: string,
  deptId: string,
  titleEn: string,
  titleHe: string,
): MyBoardDef {
  return {
    id: boardId,
    deptId,
    titleEn,
    titleHe,
    columnLabels: {
      todo: "To Do",
      doing: "Doing",
      done: "Done",
    },
    cards: seedStandardMyBoardCards(boardId),
  };
}

/** Private-board titles scoped to a firm department / position. */
function deptPrivateBoardTitles(deptId: string): {
  titleEn: string;
  titleHe: string;
} {
  switch (deptId) {
    case "reportDeptAccounting":
      return { titleEn: "Bookkeeping", titleHe: "הנהלת חשבונות" };
    case "reportDeptTax":
      return { titleEn: "Tax", titleHe: "מסים" };
    case "reportDeptAuditCompanies":
      return { titleEn: "Audit", titleHe: "ביקורת" };
    case "reportDeptBilling":
      return { titleEn: "Billing", titleHe: "גבייה" };
    case "reportDeptManagement":
      return { titleEn: "Management", titleHe: "ניהול" };
    case "reportDeptSecretariat":
      return { titleEn: "Office", titleHe: "משרד" };
    case "reportDeptIndividualTaxReturn":
      return { titleEn: "Individual tax", titleHe: "מס יחיד" };
    default:
      return { titleEn: "My board", titleHe: "הלוח שלי" };
  }
}

/**
 * Every worker gets private-board default(s) — one per department membership.
 * Billing → Outstanding Invoices Intertax list names (empty). Other depts →
 * To Do / Doing / Done with sample cards. Titles follow department.
 */
function defaultMyBoardsStateForWorker(
  workerId: string,
  workers: FirmWorker[] = DEMO_STAFF,
): MyBoardsState {
  const deptIds = workerDeptIds(workerId, workers);
  const boards = (deptIds.length > 0 ? deptIds : ["reportDeptAccounting"]).map(
    (deptId, i) => {
      const boardId = i === 0 ? "mb-main" : `mb-dept-${deptId}`;
      if (deptId === "reportDeptBilling") {
        return seedBillingPrivateBoard(boardId);
      }
      const { titleEn, titleHe } = deptPrivateBoardTitles(deptId);
      return seedStandardPrivateBoard(boardId, deptId, titleEn, titleHe);
    },
  );
  return cloneMyBoardsState({
    activeBoardId: boards[0]!.id,
    boards,
  });
}

/** Alias (prefer defaultMyBoardsStateForWorker). */
const DEFAULT_MY_BOARDS_STATE: MyBoardsState = defaultMyBoardsStateForWorker(
  DEMO_WORKER.id,
);

function myBoardTitle(lang: UiLang, board: MyBoardDef): string {
  if (lang === "he") return board.titleHe || board.titleEn;
  return board.titleEn || board.titleHe;
}

function myBoardDueState(
  dueDate: string | undefined,
  today: string = MY_BOARDS_TODAY,
): MyBoardDueState {
  if (!dueDate) return "none";
  if (dueDate < today) return "overdue";
  const dueMs = Date.parse(dueDate);
  const todayMs = Date.parse(today);
  if (!Number.isFinite(dueMs) || !Number.isFinite(todayMs)) return "none";
  const days = (dueMs - todayMs) / 86_400_000;
  if (days <= 7) return "dueSoon";
  return "none";
}

function myBoardsUnreadCount(state: MyBoardsState): number {
  return state.boards.reduce(
    (sum, b) => sum + b.cards.filter((c) => c.unread).length,
    0,
  );
}

function myBoardUnreadCount(board: MyBoardDef): number {
  return board.cards.filter((c) => c.unread).length;
}

function myBoardsReminderCards(state: MyBoardsState): {
  boardId: string;
  boardTitle: string;
  card: MyBoardCard;
  due: MyBoardDueState;
}[] {
  const out: {
    boardId: string;
    boardTitle: string;
    card: MyBoardCard;
    due: MyBoardDueState;
  }[] = [];
  for (const board of state.boards) {
    for (const card of board.cards) {
      if (card.columnId === "done" || card.archived) continue;
      const due = myBoardDueState(card.dueDate);
      if (due === "none") continue;
      out.push({
        boardId: board.id,
        boardTitle: board.titleEn,
        card,
        due,
      });
    }
  }
  out.sort((a, b) => {
    if (a.due !== b.due) return a.due === "overdue" ? -1 : 1;
    return (a.card.dueDate ?? "").localeCompare(b.card.dueDate ?? "");
  });
  return out;
}

function myBoardsReminderCount(state: MyBoardsState): number {
  return myBoardsReminderCards(state).length;
}

function normalizeTrelloRecurring(v: unknown): TrelloRecurring {
  if (
    v === "daily" ||
    v === "weekly" ||
    v === "monthly" ||
    v === "yearly"
  ) {
    return v;
  }
  return "never";
}

function normalizeTrelloDueReminder(v: unknown): TrelloDueReminder {
  if (
    v === "atDue" ||
    v === "1day" ||
    v === "2days" ||
    v === "1week"
  ) {
    return v;
  }
  return "none";
}

function normalizeTrelloBoardBg(v: unknown): TrelloBoardBg {
  if (
    v === "green" ||
    v === "blue" ||
    v === "yellow" ||
    v === "red" ||
    v === "purple"
  ) {
    return v;
  }
  return "default";
}

function normalizeMyBoardCard(raw: Partial<MyBoardCard> & { id?: string }): MyBoardCard {
  const clientName = String(raw.clientName ?? "");
  const snippet = String(raw.commentSnippet ?? "");
  const titleRaw = typeof raw.title === "string" ? raw.title.trim() : "";
  const comments = Array.isArray(raw.comments)
    ? raw.comments
        .filter((c) => c && typeof c === "object")
        .map((c, i) => ({
          id: String(c.id || `mb-c-${i}`),
          author: String(c.author ?? ""),
          authorWorkerId:
            typeof c.authorWorkerId === "string" ? c.authorWorkerId : undefined,
          body: String(c.body ?? ""),
          at: String(c.at ?? ""),
        }))
    : [];
  const labels = Array.isArray(raw.labels)
    ? raw.labels.map((x) => String(x ?? "").trim()).filter(Boolean)
    : [];
  const memberIds = Array.isArray(raw.memberIds)
    ? raw.memberIds.map((x) => String(x ?? "").trim()).filter(Boolean)
    : [];
  const checklist = Array.isArray(raw.checklist)
    ? raw.checklist
        .filter((row) => row && typeof row === "object")
        .map((row, j) => {
          const item = row as Partial<TrelloChecklistItem>;
          return {
            id: String(item.id || `chk-${j}`),
            text: String(item.text ?? ""),
            done: Boolean(item.done),
          };
        })
        .filter((row) => row.text.trim())
    : [];
  const attachments = Array.isArray(raw.attachments)
    ? raw.attachments
        .filter((row) => row && typeof row === "object")
        .map((row, j) => {
          const item = row as Partial<TrelloAttachment>;
          return {
            id: String(item.id || `att-${j}`),
            name: String(item.name ?? "").trim(),
          };
        })
        .filter((row) => row.name)
    : [];
  const startRaw = typeof raw.startDate === "string" ? raw.startDate.trim() : "";
  const dueTimeRaw = typeof raw.dueTime === "string" ? raw.dueTime.trim() : "";
  const cover =
    raw.coverColor && raw.coverColor !== "default"
      ? normalizeTrelloBoardBg(raw.coverColor)
      : undefined;
  return {
    id: String(raw.id || `mbc-${Math.random().toString(36).slice(2, 9)}`),
    clientId: String(raw.clientId ?? ""),
    clientName,
    title: titleRaw || clientName || snippet.slice(0, 48) || "Card",
    commentSnippet: snippet,
    columnId: (() => {
      const rawId = String(raw.columnId ?? "");
      if (rawId === "incoming") return "todo";
      if (rawId === "inProgress" || rawId === "waiting") return "doing";
      if (rawId.trim()) return rawId;
      return "todo";
    })(),
    dueDate:
      typeof raw.dueDate === "string" && raw.dueDate.trim()
        ? raw.dueDate.trim()
        : undefined,
    startDate: startRaw || undefined,
    dueTime: dueTimeRaw || undefined,
    recurring: normalizeTrelloRecurring(raw.recurring),
    dueReminder: normalizeTrelloDueReminder(raw.dueReminder),
    unread: Boolean(raw.unread),
    watching: Boolean(raw.watching),
    labels: labels.length > 0 ? labels : undefined,
    memberIds: memberIds.length > 0 ? memberIds : undefined,
    checklist: checklist.length > 0 ? checklist : undefined,
    attachments: attachments.length > 0 ? attachments : undefined,
    coverColor: cover && cover !== "default" ? cover : undefined,
    archived: Boolean(raw.archived),
    comments,
  };
}

function normalizeMyBoardsState(
  raw: MyBoardsState | null | undefined,
  workerId: string = DEMO_WORKER.id,
  workers: FirmWorker[] = DEMO_STAFF,
): MyBoardsState {
  if (raw && typeof raw === "object" && Array.isArray(raw.boards)) {
    /** Empty = missing seed — every worker gets dept-scoped default board(s). */
    if (raw.boards.length === 0) {
      return defaultMyBoardsStateForWorker(workerId, workers);
    }
    const boards = raw.boards.map((b) => {
      const normalized: MyBoardDef = {
        id: String(b.id || `mb-${Math.random().toString(36).slice(2, 8)}`),
        deptId: String(b.deptId ?? ""),
        titleEn: String(b.titleEn ?? ""),
        titleHe: String(b.titleHe ?? ""),
        columnLabels:
          b.columnLabels && typeof b.columnLabels === "object"
            ? { ...b.columnLabels }
            : undefined,
        extraColumns: Array.isArray(b.extraColumns)
          ? b.extraColumns
              .filter((c) => c && typeof c === "object")
              .map((c, i) => ({
                id: String(
                  (c as MyBoardExtraColumn).id || `mbcol-${i}`,
                ),
                title:
                  String((c as MyBoardExtraColumn).title ?? "").trim() ||
                  `List ${i + 1}`,
              }))
          : undefined,
        starred: Boolean(b.starred),
        description:
          typeof b.description === "string" ? b.description : undefined,
        background: normalizeTrelloBoardBg(b.background),
        cards: Array.isArray(b.cards)
          ? b.cards.map((c) => normalizeMyBoardCard(c as Partial<MyBoardCard>))
          : [],
      };
      /** Replace legacy Sample To Do seed on Billing with Trello list structure. */
      if (
        normalized.deptId === "reportDeptBilling" &&
        looksLikeLegacyBillingSampleSeed(normalized.cards)
      ) {
        const fresh = seedBillingPrivateBoard(normalized.id);
        return {
          ...fresh,
          titleEn: normalized.titleEn || fresh.titleEn,
          titleHe: normalized.titleHe || fresh.titleHe,
        };
      }
      /** Upgrade plain Sample To Do seed so tour badges show on card faces. */
      if (
        normalized.deptId !== "reportDeptBilling" &&
        looksLikePlainMyBoardSampleSeed(normalized.cards)
      ) {
        return {
          ...normalized,
          cards: seedStandardMyBoardCards(normalized.id),
        };
      }
      return normalized;
    });
    const active =
      raw.activeBoardId && boards.some((b) => b.id === raw.activeBoardId)
        ? raw.activeBoardId
        : boards[0]!.id;
    return { boards, activeBoardId: active };
  }
  return defaultMyBoardsStateForWorker(workerId, workers);
}

/** To Do / Doing / Done plus any + Add list extras for this board. */
function myBoardResolvedColumns(board: MyBoardDef): MyBoardColumnRef[] {
  const extras = (board.extraColumns ?? []).map((c) => ({
    id: c.id,
    title: c.title,
  }));
  return [...MY_BOARD_COLUMNS, ...extras];
}

function myBoardColumnLabel(
  lang: UiLang,
  board: MyBoardDef,
  col: MyBoardColumnRef,
): string {
  const custom = board.columnLabels?.[col.id]?.trim();
  if (custom) return custom;
  if (col.title?.trim()) return col.title.trim();
  if (col.labelKey) return t(lang, col.labelKey);
  return col.id;
}

