function trelloBoardBgColor(
  theme: ReturnType<typeof useHostTheme>,
  bg: TrelloBoardBg | undefined,
): string | undefined {
  if (!bg || bg === "default") return undefined;
  if (bg === "green") return theme.category.green;
  if (bg === "blue") return theme.accent.primary;
  if (bg === "yellow") return theme.category.yellow;
  if (bg === "red") return theme.category.red;
  if (bg === "purple") return chromeSelectedFill(theme);
  return undefined;
}

/** Parse #rgb / #rrggbb(#a) / rgb()/rgba() into 0–255 channels. */
function parseCssColorRgb(
  color: string | undefined,
): { r: number; g: number; b: number } | null {
  if (!color) return null;
  const c = color.trim();
  if (c.startsWith("#")) {
    let hex = c.slice(1);
    if (hex.length === 3 || hex.length === 4) {
      hex = hex
        .slice(0, 3)
        .split("")
        .map((ch) => ch + ch)
        .join("");
    } else if (hex.length === 8) {
      hex = hex.slice(0, 6);
    }
    if (hex.length !== 6) return null;
    const n = Number.parseInt(hex, 16);
    if (Number.isNaN(n)) return null;
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }
  const m = c.match(
    /^rgba?\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)/i,
  );
  if (!m) return null;
  return {
    r: Math.min(255, Math.max(0, Number(m[1]))),
    g: Math.min(255, Math.max(0, Number(m[2]))),
    b: Math.min(255, Math.max(0, Number(m[3]))),
  };
}

function srgbChannelToLinear(channel: number): number {
  const s = channel / 255;
  return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
}

/** WCAG relative luminance (0–1). */
function relativeLuminance(rgb: { r: number; g: number; b: number }): number {
  return (
    0.2126 * srgbChannelToLinear(rgb.r) +
    0.7152 * srgbChannelToLinear(rgb.g) +
    0.0722 * srgbChannelToLinear(rgb.b)
  );
}

/**
 * Writing color for text on a user-colored board banner.
 * Dark / saturated bg → light onAccent; light bg (e.g. yellow) → chrome ink.
 * Returns null when there is no colored background (default chrome ink).
 */
function textColorsOnBoardBg(
  bg: string | undefined,
  theme: ReturnType<typeof useHostTheme>,
): { title: string; body: string } | null {
  const rgb = parseCssColorRgb(bg);
  if (!rgb) return null;
  if (relativeLuminance(rgb) < 0.45) {
    return {
      title: theme.text.onAccent,
      body: theme.text.onAccent,
    };
  }
  return {
    title: CHROME_INK,
    body: CHROME_INK_MUTED,
  };
}

/** Compact Trello-style background swatches (board theme). */
function TrelloBgSwatchRow({
  value,
  onChange,
}: {
  value: TrelloBoardBg;
  onChange: (next: TrelloBoardBg) => void;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const swatches: { id: TrelloBoardBg; color: string; label: string }[] = [
    {
      id: "default",
      color: theme.bg.chrome,
      label: t(uiLang, "trelloEditableBgDefault"),
    },
    {
      id: "green",
      color: theme.category.green,
      label: t(uiLang, "trelloEditableBgGreen"),
    },
    {
      id: "blue",
      color: theme.accent.primary,
      label: t(uiLang, "trelloEditableBgBlue"),
    },
    {
      id: "yellow",
      color: theme.category.yellow,
      label: t(uiLang, "trelloEditableBgYellow"),
    },
    {
      id: "red",
      color: theme.category.red,
      label: t(uiLang, "trelloEditableBgRed"),
    },
    {
      id: "purple",
      color: chromeSelectedFill(theme),
      label: t(uiLang, "trelloEditableBgPurple"),
    },
  ];
  return (
    <Row gap={6} wrap align="center">
      {swatches.map((s) => {
        const active = value === s.id;
        return (
          <button
            key={s.id}
            type="button"
            title={s.label}
            aria-label={s.label}
            aria-pressed={active}
            onClick={() => onChange(s.id)}
            style={{
              width: 28,
              height: 28,
              borderRadius: 6,
              border: active
                ? `2px solid ${theme.accent.primary}`
                : `1px solid ${chromeBorder(theme)}`,
              background: s.color,
              cursor: "pointer",
              padding: 0,
              boxSizing: "border-box",
            }}
          />
        );
      })}
    </Row>
  );
}

function formatTrelloShortDate(iso: string): string {
  const parts = iso.split("-");
  if (parts.length < 3) return iso;
  const months = [
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "May",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Oct",
    "Nov",
    "Dec",
  ];
  const m = Number(parts[1]);
  const d = Number(parts[2]);
  if (!Number.isFinite(m) || !Number.isFinite(d) || m < 1 || m > 12) return iso;
  return `${months[m - 1]} ${d}`;
}

function TrelloDueDateBadge({
  dueDate,
  dueTime,
  complete,
}: {
  dueDate?: string;
  dueTime?: string;
  complete?: boolean;
}) {
  const theme = useHostTheme();
  if (!dueDate) return null;
  const due = myBoardDueState(dueDate);
  let bg = theme.bg.chrome;
  let fg: string = CHROME_INK_MUTED;
  if (complete) {
    bg = theme.category.green;
    fg = theme.text.onAccent;
  } else if (due === "overdue") {
    bg = theme.category.red;
    fg = theme.text.onAccent;
  } else if (due === "dueSoon") {
    bg = theme.category.yellow;
    fg = theme.text.primary;
  }
  const label = dueTime
    ? `${formatTrelloShortDate(dueDate)}, ${dueTime}`
    : formatTrelloShortDate(dueDate);
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 4,
        padding: "2px 6px",
        borderRadius: 4,
        background: bg,
        color: fg,
        fontSize: 11,
        lineHeight: 1.2,
        fontWeight: 600,
      }}
      title={dueDate}
    >
      <svg
        width={11}
        height={11}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden
      >
        <circle cx="12" cy="12" r="9" />
        <path d="M12 7v5l3 2" />
      </svg>
      {label}
    </span>
  );
}

