/**
 * Worker My Boards — private Trello-style columns of that worker’s comments.
 * State is keyed per signed-in worker; demo seed is worker-specific.
 */
function MyBoardsScreen({
  view = "board",
}: {
  view?: MyBoardsView;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [firmWorkers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const [signedInWorkerId] = useCanvasState(
    "signedInWorkerId.v1",
    DEMO_WORKER.id,
  );
  const [stateRaw, setStateRaw] = useCanvasState<MyBoardsState>(
    myBoardsStateKey(signedInWorkerId),
    defaultMyBoardsStateForWorker(signedInWorkerId, firmWorkers),
  );
  const state = normalizeMyBoardsState(
    stateRaw,
    signedInWorkerId,
    firmWorkers,
  );
  const setState = (
    updater: MyBoardsState | ((prev: MyBoardsState) => MyBoardsState),
  ) => {
    setStateRaw((prev) => {
      const normalized = normalizeMyBoardsState(
        prev,
        signedInWorkerId,
        firmWorkers,
      );
      return typeof updater === "function" ? updater(normalized) : updater;
    });
  };
  const [emailReminders, setEmailReminders] = useCanvasState(
    myBoardsEmailRemindersKey(signedInWorkerId),
    false,
  );
  const [uiPrefsRaw, setUiPrefsRaw] = useCanvasState<MyBoardsUiPrefs>(
    myBoardsUiPrefsKey(signedInWorkerId),
    DEFAULT_MY_BOARDS_UI_PREFS,
  );
  const uiPrefs = normalizeMyBoardsUiPrefs(uiPrefsRaw);
  const patchUiPrefs = (patch: Partial<MyBoardsUiPrefs>) => {
    setUiPrefsRaw((prev) => ({
      ...normalizeMyBoardsUiPrefs(prev),
      ...patch,
    }));
  };
  const [composerOpen, setComposerOpen] = useState(false);
  const [composerName, setComposerName] = useState("");
  /** Draft for + Add board only — never patchActiveBoard until Create. */
  const [composerDescription, setComposerDescription] = useState("");
  const [composerBackground, setComposerBackground] =
    useState<TrelloBoardBg>("default");
  const [settingsOpen, setSettingsOpen] = useState(false);
  /** Ephemeral — do not persist; a leftover open card dims main and makes secondary look like a popup. */
  const [selectedCardId, setSelectedCardId] = useState("");
  const [commentDraft, setCommentDraft] = useState("");
  const [renamingColumnId, setRenamingColumnId] = useCanvasState<
    MyBoardColumnId | ""
  >("myBoardsRenamingColumn.v1", "");
  const [columnRenameDraft, setColumnRenameDraft] = useCanvasState(
    "myBoardsColumnRenameDraft.v1",
    "",
  );
  const [cardComposer, setCardComposer] =
    useCanvasState<MyBoardCardComposerState>(
      "myBoardsCardComposer.v1",
      EMPTY_MY_BOARD_CARD_COMPOSER,
    );
  const [addingColumn, setAddingColumn] = useCanvasState(
    `myBoardsAddingColumn.v1:${signedInWorkerId}`,
    false,
  );
  const [newColumnName, setNewColumnName] = useCanvasState(
    `myBoardsNewColumnName.v1:${signedInWorkerId}`,
    "",
  );
  /** Ephemeral DnD highlight — which list is the current drop target. */
  const [dropColumnId, setDropColumnId] = useState("");
  const columnDragDepthRef = useRef<Record<string, number>>({});
  const suppressCardClickRef = useRef(false);
  const [boardFilter, setBoardFilter] = useCanvasState(
    `myBoardsFilter.v1:${signedInWorkerId}`,
    "",
  );
  const [listMenuColId, setListMenuColId] = useState("");
  const [labelDraft, setLabelDraft] = useState("");
  const [checklistDraft, setChecklistDraft] = useState("");
  const [attachmentDraft, setAttachmentDraft] = useState("");
  const [editingCommentId, setEditingCommentId] = useState("");
  const [editingCommentBody, setEditingCommentBody] = useState("");
  const [cardMoreOpen, setCardMoreOpen] = useState(false);
  const [demoRows] = useCanvasState<DemoRow[]>(
    "demoRows.v10",
    DEFAULT_DEMO_ROWS,
  );
  const boardClientCandidates = uniqSearchCandidates(
    demoRows.flatMap((row) => [
      row.name,
      row.nameHe,
      displayClientName(row, uiLang),
    ]),
  );

  /** Persist dept default seed when stored state is empty/missing. */
  useEffect(() => {
    if (
      stateRaw &&
      typeof stateRaw === "object" &&
      Array.isArray(stateRaw.boards) &&
      stateRaw.boards.length > 0
    ) {
      return;
    }
    setStateRaw(defaultMyBoardsStateForWorker(signedInWorkerId, firmWorkers));
  }, [signedInWorkerId, firmWorkers, stateRaw, setStateRaw]);

  useEffect(() => {
    if (view === "settings") setSettingsOpen(true);
  }, [view, setSettingsOpen]);

  const activeBoard =
    state.boards.find((b) => b.id === state.activeBoardId) ??
    state.boards[0] ??
    null;

  const selectedCard =
    activeBoard?.cards.find((c) => c.id === selectedCardId) ?? null;

  const boardColumns = activeBoard
    ? myBoardResolvedColumns(activeBoard)
    : MY_BOARD_COLUMNS;

  const columnSelectOptions = boardColumns.map((c) => ({
    value: c.id,
    label: activeBoard
      ? myBoardColumnLabel(uiLang, activeBoard, c)
      : c.labelKey
        ? t(uiLang, c.labelKey)
        : c.title ?? c.id,
  }));

  const setActiveBoardId = (id: string) => {
    setState((prev) => ({ ...prev, activeBoardId: id }));
  };

  const openCardComposer = (columnId: MyBoardColumnId) => {
    setSelectedCardId("");
    setCommentDraft("");
    setSettingsOpen(false);
    setComposerOpen(false);
    setCardComposer({
      ...EMPTY_MY_BOARD_CARD_COMPOSER,
      open: true,
      columnId,
    });
  };

  const openCardDetail = (boardId: string, cardId: string) => {
    setSelectedCardId(cardId);
    setCommentDraft("");
    setSettingsOpen(false);
    setComposerOpen(false);
    setCardComposer(EMPTY_MY_BOARD_CARD_COMPOSER);
    setState((prev) => ({
      ...prev,
      activeBoardId: boardId,
      boards: prev.boards.map((b) =>
        b.id !== boardId
          ? b
          : {
              ...b,
              cards: b.cards.map((c) =>
                c.id === cardId ? { ...c, unread: false } : c,
              ),
            },
      ),
    }));
  };

  const closeCardDetail = () => {
    setSelectedCardId("");
    setCommentDraft("");
    setLabelDraft("");
    setChecklistDraft("");
    setAttachmentDraft("");
    setEditingCommentId("");
    setEditingCommentBody("");
    setCardMoreOpen(false);
  };

  const patchCard = (cardId: string, patch: Partial<MyBoardCard>) => {
    if (!activeBoard) return;
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== activeBoard.id
          ? b
          : {
              ...b,
              cards: b.cards.map((c) =>
                c.id === cardId ? { ...c, ...patch, unread: false } : c,
              ),
            },
      ),
    }));
  };

  const patchActiveBoard = (patch: Partial<MyBoardDef>) => {
    if (!activeBoard) return;
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id === activeBoard.id ? { ...b, ...patch } : b,
      ),
    }));
  };

  const archiveCard = (cardId: string) => {
    patchCard(cardId, { archived: true });
    if (selectedCardId === cardId) closeCardDetail();
  };

  const restoreCard = (cardId: string) => {
    patchCard(cardId, { archived: false });
  };

  const deleteMyBoardCard = (cardId: string) => {
    if (!activeBoard) return;
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== activeBoard.id
          ? b
          : { ...b, cards: b.cards.filter((c) => c.id !== cardId) },
      ),
    }));
    if (selectedCardId === cardId) closeCardDetail();
  };

  const copyCard = (cardId: string) => {
    if (!activeBoard) return;
    const src = activeBoard.cards.find((c) => c.id === cardId);
    if (!src) return;
    const id = `mbc-${Date.now().toString(36)}`;
    const next: MyBoardCard = {
      ...src,
      id,
      title: `${src.title} (copy)`,
      unread: true,
      archived: false,
      comments: (src.comments ?? []).map((c, i) => ({
        ...c,
        id: `mb-c-${id}-${i}`,
      })),
      checklist: (src.checklist ?? []).map((c, i) => ({
        ...c,
        id: `chk-${id}-${i}`,
      })),
      attachments: (src.attachments ?? []).map((a, i) => ({
        ...a,
        id: `att-${id}-${i}`,
      })),
      labels: src.labels ? [...src.labels] : undefined,
      memberIds: src.memberIds ? [...src.memberIds] : undefined,
    };
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== activeBoard.id
          ? b
          : { ...b, cards: [next, ...b.cards] },
      ),
    }));
  };

  const archiveAllInColumn = (columnId: MyBoardColumnId) => {
    if (!activeBoard) return;
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== activeBoard.id
          ? b
          : {
              ...b,
              cards: b.cards.map((c) =>
                c.columnId === columnId && !c.archived
                  ? { ...c, archived: true }
                  : c,
              ),
            },
      ),
    }));
    setListMenuColId("");
  };

  const moveAllInColumn = (
    fromColumnId: MyBoardColumnId,
    toColumnId: MyBoardColumnId,
  ) => {
    if (!activeBoard || fromColumnId === toColumnId) return;
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== activeBoard.id
          ? b
          : {
              ...b,
              cards: b.cards.map((c) =>
                c.columnId === fromColumnId && !c.archived
                  ? { ...c, columnId: toColumnId }
                  : c,
              ),
            },
      ),
    }));
    setListMenuColId("");
  };

  const moveCard = (
    boardId: string,
    cardId: string,
    columnId: MyBoardColumnId,
  ) => {
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== boardId
          ? b
          : {
              ...b,
              cards: b.cards.map((c) =>
                c.id === cardId ? { ...c, columnId, unread: false } : c,
              ),
            },
      ),
    }));
  };

  const addComment = () => {
    if (!selectedCard || !activeBoard) return;
    const body = commentDraft.trim();
    if (!body) return;
    const comment: MyBoardComment = {
      id: `mb-c-${Date.now().toString(36)}`,
      author: staffDisplayName(uiLang, signedInWorkerId, firmWorkers),
      authorWorkerId: signedInWorkerId,
      body,
      at: clockNow(),
    };
    patchCard(selectedCard.id, {
      comments: [...(selectedCard.comments ?? []), comment],
    });
    setCommentDraft("");
  };

  const saveColumnRename = (columnId: MyBoardColumnId) => {
    if (!activeBoard) return;
    const name = columnRenameDraft.trim();
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) => {
        if (b.id !== activeBoard.id) return b;
        const isExtra = (b.extraColumns ?? []).some((c) => c.id === columnId);
        if (isExtra) {
          return {
            ...b,
            extraColumns: (b.extraColumns ?? []).map((c) =>
              c.id === columnId
                ? { ...c, title: name || c.title }
                : c,
            ),
          };
        }
        const nextLabels = { ...(b.columnLabels ?? {}) };
        if (name) nextLabels[columnId] = name;
        else delete nextLabels[columnId];
        return {
          ...b,
          columnLabels:
            Object.keys(nextLabels).length > 0 ? nextLabels : undefined,
        };
      }),
    }));
    setRenamingColumnId("");
    setColumnRenameDraft("");
  };

  const createColumn = () => {
    if (!activeBoard) return;
    const name = newColumnName.trim();
    if (!name) return;
    const id = `mbcol-${Date.now().toString(36)}`;
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== activeBoard.id
          ? b
          : {
              ...b,
              extraColumns: [
                ...(b.extraColumns ?? []),
                { id, title: name },
              ],
            },
      ),
    }));
    setNewColumnName("");
    setAddingColumn(false);
  };

  const resetBoardComposerDraft = () => {
    setComposerName("");
    setComposerDescription("");
    setComposerBackground("default");
  };

  const createBoard = () => {
    const name = composerName.trim();
    if (!name) return;
    const id = `mb-${Date.now().toString(36)}`;
    /** Private custom board — name only; no department ownership. */
    const seeded = seedStandardPrivateBoard(id, "", name, name);
    const desc = composerDescription.trim();
    const next: MyBoardDef = {
      ...seeded,
      ...(desc ? { description: desc } : {}),
      background: composerBackground,
    };
    setState((prev) => ({
      boards: [...prev.boards, next],
      activeBoardId: id,
    }));
    resetBoardComposerDraft();
    setComposerOpen(false);
  };

  const renameBoard = (boardId: string, name: string) => {
    const next = name.trim();
    if (!next) return;
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== boardId
          ? b
          : { ...b, titleEn: next, titleHe: next },
      ),
    }));
  };

  const createReminderCard = () => {
    if (!activeBoard || !cardComposer.open) return;
    /** Card title = client name (no separate “Reminder title” field). */
    const clientName = cardComposer.clientName.trim();
    if (!clientName) return;
    const body = cardComposer.body.trim();
    const dueTrimmed = cardComposer.dueDate.trim();
    const allowedIds = new Set(
      (activeBoard ? myBoardResolvedColumns(activeBoard) : MY_BOARD_COLUMNS).map(
        (c) => c.id,
      ),
    );
    const columnId = allowedIds.has(cardComposer.columnId)
      ? cardComposer.columnId
      : "todo";
    const id = `mbc-${Date.now().toString(36)}`;
    const comments: MyBoardComment[] = body
      ? [
          {
            id: `mb-c-${Date.now().toString(36)}`,
            author: staffDisplayName(uiLang, signedInWorkerId, firmWorkers),
            authorWorkerId: signedInWorkerId,
            body,
            at: clockNow(),
          },
        ]
      : [];
    const next: MyBoardCard = {
      id,
      clientId: "",
      clientName,
      title: clientName,
      commentSnippet: body,
      columnId,
      dueDate: dueTrimmed || undefined,
      unread: true,
      watching: false,
      recurring: "never",
      dueReminder: "none",
      labels: [],
      memberIds: [],
      checklist: [],
      attachments: [],
      comments,
      coverColor:
        uiPrefs.defaultCover !== "default" ? uiPrefs.defaultCover : undefined,
    };
    setState((prev) => ({
      ...prev,
      boards: prev.boards.map((b) =>
        b.id !== activeBoard.id
          ? b
          : { ...b, cards: [next, ...b.cards] },
      ),
    }));
    setCardComposer(EMPTY_MY_BOARD_CARD_COMPOSER);
  };

  const sideBoards: TrelloBoardSideTabItem[] = state.boards.map((b) => ({
    id: b.id,
    label: myBoardTitle(uiLang, b),
    badgeCount: myBoardUnreadCount(b) || undefined,
  }));

  const reminderRows = myBoardsReminderCards(state);

  const showBoardColumns = view !== "reminders" && activeBoard != null;

  const selectedDue = selectedCard
    ? myBoardDueState(selectedCard.dueDate)
    : "none";

  const filterQ = boardFilter.trim().toLowerCase();
  const boardCardsActive = activeBoard
    ? activeBoard.cards.filter((c) => {
        if (c.archived) return false;
        if (!filterQ) return true;
        const hay = [
          c.title,
          c.clientName,
          c.commentSnippet,
          ...(c.labels ?? []),
        ]
          .join(" ")
          .toLowerCase();
        return hay.includes(filterQ);
      })
    : [];
  const archivedBoardCards = activeBoard
    ? activeBoard.cards.filter((c) => c.archived)
    : [];
  const boardBg = trelloBoardBgColor(theme, activeBoard?.background);
  const onBoardText = textColorsOnBoardBg(boardBg, theme);
  const workerOptions = firmWorkers.map((w) => ({
    value: w.id,
    label: staffDisplayName(uiLang, w.id, firmWorkers),
  }));
  const isMemberOfSelected = selectedCard
    ? (selectedCard.memberIds ?? []).includes(signedInWorkerId)
    : false;

  return (
    <Stack
      gap={12}
      style={{
        ...SHELL_SCROLL,
        paddingInlineEnd: 4,
        /** Anchor for card/settings overlays — keep them in main, not over rails. */
        position: "relative",
        ...(boardBg
          ? {
              background: boardBg,
              borderRadius: 12,
              padding: 12,
              boxSizing: "border-box" as const,
            }
          : null),
      }}
    >
      <Row align="center" gap={12} style={{ flexShrink: 0, width: "100%" }}>
        <Spacer />
        <ChromeTitlePill>{t(uiLang, "myBoards")}</ChromeTitlePill>
        <IconButton
          title={t(uiLang, "myBoardsSettings")}
          variant="circle"
          size="sm"
          onClick={() => setSettingsOpen(true)}
        >
          <svg
            width={16}
            height={16}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={1.6}
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden
          >
            <circle cx="12" cy="12" r="3.2" />
            <path d="M12 3.5v2.2M12 18.3v2.2M3.5 12h2.2M18.3 12h2.2M6.1 6.1l1.6 1.6M16.3 16.3l1.6 1.6M17.9 6.1l-1.6 1.6M7.7 16.3l-1.6 1.6" />
          </svg>
        </IconButton>
      </Row>
      <Stack gap={4}>
        <H1
          style={{
            margin: 0,
            ...(onBoardText ? { color: onBoardText.title } : null),
          }}
        >
          {t(uiLang, "myBoardsHomeTitle")}
        </H1>
        <ChromeText
          tone="secondary"
          style={onBoardText ? { color: onBoardText.body } : undefined}
        >
          {t(uiLang, "myBoardsHomeHint")}
        </ChromeText>
      </Stack>

      <TrelloBoardSideTabs
        boards={sideBoards}
        activeId={activeBoard?.id ?? state.activeBoardId}
        addBoardActive={composerOpen}
        onSelect={(id) => {
          setComposerOpen(false);
          setSettingsOpen(false);
          setAddingColumn(false);
          setNewColumnName("");
          setActiveBoardId(id);
          setCardComposer(EMPTY_MY_BOARD_CARD_COMPOSER);
          closeCardDetail();
          setRenamingColumnId("");
        }}
        onAddBoard={() => {
          setComposerOpen(true);
          resetBoardComposerDraft();
          setAddingColumn(false);
          setCardComposer(EMPTY_MY_BOARD_CARD_COMPOSER);
          closeCardDetail();
        }}
        onRenameBoard={renameBoard}
        ariaLabel={t(uiLang, "myBoards")}
      />

      {composerOpen ? (
        <NewBoardTabComposer
          name={composerName}
          onNameChange={setComposerName}
          onCreate={createBoard}
          onCancel={() => {
            setComposerOpen(false);
            resetBoardComposerDraft();
          }}
          boardSettings={{
            description: composerDescription,
            onDescriptionChange: setComposerDescription,
            background: composerBackground,
            onBackgroundChange: setComposerBackground,
          }}
        />
      ) : null}

      {showBoardColumns && activeBoard ? (
        <Row gap={8} align="center" wrap style={{ flexShrink: 0 }}>
          <Button
            variant={activeBoard.starred ? "primary" : "secondary"}
            onClick={() =>
              patchActiveBoard({ starred: !activeBoard.starred })
            }
            style={
              activeBoard.starred
                ? undefined
                : {
                    background: CHROME_SOFT_BLUE,
                    color: CHROME_INK,
                    border: `1px solid ${CHROME_BORDER_BLUE}`,
                  }
            }
          >
            {activeBoard.starred
              ? t(uiLang, "myBoardsUnstarBoard")
              : t(uiLang, "myBoardsStarBoard")}
          </Button>
          <div style={{ flex: "1 1 160px", minWidth: 140, maxWidth: 280 }}>
            <ChromeTextInput
              value={boardFilter}
              onChange={setBoardFilter}
              placeholder={t(uiLang, "myBoardsFilterPlaceholder")}
              style={{
                width: "100%",
                background: CHROME_WHITE,
                color: CHROME_INK,
                border: `1px solid ${CHROME_BORDER_BLUE}`,
                borderRadius: 8,
              }}
            />
          </div>
        </Row>
      ) : null}

      {view === "reminders" ? (
        <Stack gap={10}>
          <ChromeText tone="secondary">{t(uiLang, "myBoardsRemindersHint")}</ChromeText>
          {reminderRows.length === 0 ? (
            <ChromeText tone="secondary">{t(uiLang, "myBoardsEmptyReminders")}</ChromeText>
          ) : (
            <Stack gap={8}>
              {reminderRows.map(({ boardId, boardTitle, card, due }) => (
                <button
                  key={`${boardId}-${card.id}`}
                  type="button"
                  onClick={() => openCardDetail(boardId, card.id)}
                  style={{
                    all: "unset",
                    cursor: "pointer",
                    display: "block",
                    width: "100%",
                    boxSizing: "border-box",
                    padding: 12,
                    borderRadius: 10,
                    border: `1px solid ${chromeBorder(theme)}`,
                    background: CHROME_WHITE,
                  }}
                >
                  <Stack gap={6}>
                    <Row align="center" gap={8}>
                      <ChromeText weight="semibold" style={{ flex: 1 }}>
                        {card.title || card.clientName}
                      </ChromeText>
                      <MyBoardDueBlob due={due} />
                      {card.unread ? (
                        <Pill tone="warning">{t(uiLang, "myBoardsUnread")}</Pill>
                      ) : null}
                    </Row>
                    <ChromeText size="small" tone="secondary">
                      {boardTitle}
                      {card.clientName ? ` · ${card.clientName}` : ""}
                      {card.dueDate ? ` · ${card.dueDate}` : ""}
                    </ChromeText>
                    <ChromeText size="small">{card.commentSnippet}</ChromeText>
                  </Stack>
                </button>
              ))}
            </Stack>
          )}
        </Stack>
      ) : null}

      {showBoardColumns && activeBoard ? (
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            gap: 10,
            overflowX: "auto",
            WebkitOverflowScrolling: "touch",
            paddingBottom: 4,
            alignItems: "flex-start",
          }}
        >
          {boardColumns.map((col) => {
            const colCards = boardCardsActive.filter(
              (c) => c.columnId === col.id,
            );
            const isRenaming = renamingColumnId === col.id;
            const isDropTarget = dropColumnId === col.id;
            const listMenuOpen = listMenuColId === col.id;
            return (
              <div
                key={col.id}
                onDragEnter={(e: {
                  preventDefault: () => void;
                }) => {
                  e.preventDefault();
                  const depth =
                    (columnDragDepthRef.current[col.id] ?? 0) + 1;
                  columnDragDepthRef.current[col.id] = depth;
                  setDropColumnId(col.id);
                }}
                onDragLeave={() => {
                  const depth =
                    (columnDragDepthRef.current[col.id] ?? 1) - 1;
                  columnDragDepthRef.current[col.id] = Math.max(0, depth);
                  if (depth <= 0) {
                    setDropColumnId((cur) => (cur === col.id ? "" : cur));
                  }
                }}
                onDragOver={(e: {
                  preventDefault: () => void;
                  dataTransfer: { dropEffect: string };
                }) => {
                  e.preventDefault();
                  e.dataTransfer.dropEffect = "move";
                }}
                onDrop={(e: {
                  preventDefault: () => void;
                  dataTransfer: KanbanDragTransfer;
                }) => {
                  e.preventDefault();
                  columnDragDepthRef.current[col.id] = 0;
                  setDropColumnId("");
                  const data = readKanbanCardDrag(e.dataTransfer);
                  if (!data || data.fromColumnId === col.id) return;
                  moveCard(activeBoard.id, data.cardId, col.id);
                }}
                style={{
                  width: 240,
                  minWidth: 240,
                  flexShrink: 0,
                  padding: 10,
                  borderRadius: 10,
                  border: `1px solid ${
                    isDropTarget
                      ? theme.accent.primary
                      : chromeBorder(theme)
                  }`,
                  background: isDropTarget
                    ? theme.bg.chrome
                    : CHROME_WHITE,
                  boxSizing: "border-box",
                  display: "flex",
                  flexDirection: "column",
                  gap: 8,
                }}
              >
                {isRenaming ? (
                  <Stack gap={6}>
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsRenameColumn")}
                    </ChromeText>
                    <ChromeTextInput
                      value={columnRenameDraft}
                      onChange={setColumnRenameDraft}
                      placeholder={t(uiLang, "myBoardsColumnNamePlaceholder")}
                    />
                    <Row gap={6} wrap>
                      <Button
                        variant="primary"
                        onClick={() => saveColumnRename(col.id)}
                      >
                        {t(uiLang, "myBoardsSaveColumn")}
                      </Button>
                      <Button
                        variant="ghost"
                        onClick={() => {
                          setRenamingColumnId("");
                          setColumnRenameDraft("");
                        }}
                      >
                        {t(uiLang, "cancel")}
                      </Button>
                    </Row>
                  </Stack>
                ) : (
                  <Row align="center" gap={8}>
                    <button
                      type="button"
                      title={t(uiLang, "myBoardsRenameColumn")}
                      onClick={() => {
                        setRenamingColumnId(col.id);
                        setColumnRenameDraft(
                          myBoardColumnLabel(uiLang, activeBoard, col),
                        );
                      }}
                      style={{
                        all: "unset",
                        cursor: "pointer",
                        flex: 1,
                        minWidth: 0,
                      }}
                    >
                      <ChromeText weight="semibold" size="small">
                        {myBoardColumnLabel(uiLang, activeBoard, col)}
                      </ChromeText>
                    </button>
                    <Pill active={false}>{String(colCards.length)}</Pill>
                    <Button
                      variant="ghost"
                      onClick={() =>
                        setListMenuColId((cur) =>
                          cur === col.id ? "" : col.id,
                        )
                      }
                    >
                      ···
                    </Button>
                  </Row>
                )}
                {listMenuOpen ? (
                  <Stack
                    gap={6}
                    style={{
                      padding: 8,
                      borderRadius: 8,
                      border: `1px solid ${chromeBorder(theme)}`,
                      background: theme.bg.chrome,
                    }}
                  >
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsListMenu")}
                    </ChromeText>
                    <Select
                      value=""
                      options={[
                        {
                          value: "",
                          label: t(uiLang, "myBoardsMoveAllCards"),
                        },
                        ...columnSelectOptions.filter(
                          (o) => o.value !== col.id,
                        ),
                      ]}
                      onChange={(v) => {
                        if (!v) return;
                        moveAllInColumn(col.id, v as MyBoardColumnId);
                      }}
                    />
                    <Button
                      variant="secondary"
                      onClick={() => archiveAllInColumn(col.id)}
                    >
                      {t(uiLang, "myBoardsArchiveAllCards")}
                    </Button>
                  </Stack>
                ) : null}
                {colCards.map((card) => {
                  const due = myBoardDueState(card.dueDate);
                  const active = card.id === selectedCardId;
                  const coverBg = trelloBoardBgColor(theme, card.coverColor);
                  return (
                    <div
                      key={card.id}
                      style={{
                        width: "100%",
                        boxSizing: "border-box",
                        padding: 0,
                        borderRadius: 8,
                        border: `1px solid ${
                          active
                            ? theme.accent.primary
                            : card.unread
                              ? theme.accent.primary
                              : chromeBorder(theme)
                        }`,
                        background: theme.bg.chrome,
                        display: "flex",
                        flexDirection: "column",
                        gap: 0,
                        overflow: "hidden",
                      }}
                    >
                      {coverBg ? (
                        <div
                          style={{
                            height: 32,
                            background: coverBg,
                            width: "100%",
                          }}
                          aria-hidden
                        />
                      ) : null}
                      <div
                        style={{
                          padding: 10,
                          display: "flex",
                          flexDirection: "column",
                          gap: 6,
                        }}
                      >
                      <div
                        draggable
                        onDragStart={(e: {
                          dataTransfer: KanbanDragTransfer;
                        }) => {
                          writeKanbanCardDrag(e.dataTransfer, {
                            cardId: card.id,
                            fromColumnId: col.id,
                          });
                        }}
                        onDragEnd={() => {
                          setDropColumnId("");
                          columnDragDepthRef.current = {};
                          suppressCardClickRef.current = true;
                          if (typeof window !== "undefined") {
                            window.setTimeout(() => {
                              suppressCardClickRef.current = false;
                            }, 50);
                          }
                        }}
                        style={{ cursor: "grab" }}
                      >
                      <button
                        type="button"
                        onClick={() => {
                          if (suppressCardClickRef.current) {
                            suppressCardClickRef.current = false;
                            return;
                          }
                          openCardDetail(activeBoard.id, card.id);
                        }}
                        style={{
                          all: "unset",
                          cursor: "grab",
                          display: "block",
                          width: "100%",
                          boxSizing: "border-box",
                          textAlign: uiLang === "he" ? "right" : "left",
                        }}
                      >
                        <Stack gap={6}>
                          <Row align="center" gap={6}>
                            <ChromeText
                              weight="semibold"
                              size="small"
                              style={{ flex: 1, minWidth: 0 }}
                            >
                              {card.title || card.clientName}
                            </ChromeText>
                            {card.unread ? (
                              <span
                                style={{
                                  width: 8,
                                  height: 8,
                                  borderRadius: 999,
                                  background: theme.category.red,
                                  flexShrink: 0,
                                }}
                                title={t(uiLang, "myBoardsUnread")}
                                aria-label={t(uiLang, "myBoardsUnread")}
                              />
                            ) : null}
                          </Row>
                          {card.clientName &&
                          card.title &&
                          card.clientName !== card.title ? (
                            <ChromeText size="small" tone="tertiary">
                              {card.clientName}
                            </ChromeText>
                          ) : null}
                          <TrelloCardFaceBadges
                            watching={card.watching}
                            hasDescription={!!card.commentSnippet?.trim()}
                            commentCount={card.comments?.length ?? 0}
                            checklistDone={(card.checklist ?? []).filter(
                              (x) => x.done,
                            ).length}
                            checklistTotal={card.checklist?.length ?? 0}
                            attachmentCount={card.attachments?.length ?? 0}
                            dueDate={card.dueDate}
                            dueTime={card.dueTime}
                            complete={card.columnId === "done"}
                            labels={
                              uiPrefs.showLabelColors ? card.labels : undefined
                            }
                          />
                          {due !== "none" ? <MyBoardDueBlob due={due} /> : null}
                        </Stack>
                      </button>
                      </div>
                      <Select
                        value={card.columnId}
                        options={columnSelectOptions}
                        onChange={(v) =>
                          moveCard(
                            activeBoard.id,
                            card.id,
                            v as MyBoardColumnId,
                          )
                        }
                      />
                      </div>
                    </div>
                  );
                })}
                {cardComposer.open && cardComposer.columnId === col.id ? (
                  <Stack
                    gap={8}
                    style={{
                      width: "100%",
                      boxSizing: "border-box",
                      padding: 10,
                      borderRadius: 8,
                      border: `1px solid ${theme.accent.primary}`,
                      background: theme.bg.chrome,
                    }}
                  >
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsCardComposerTitle")}
                    </ChromeText>
                    <Stack gap={4}>
                      <ChromeText size="small" weight="semibold">
                        {t(uiLang, "myBoardsCardClient")}
                      </ChromeText>
                      <SearchAutocomplete
                        value={cardComposer.clientName}
                        onChange={(v) =>
                          setCardComposer({
                            ...cardComposer,
                            clientName: v,
                            title: v,
                          })
                        }
                        placeholder={t(
                          uiLang,
                          "myBoardsCardClientPlaceholder",
                        )}
                        lang={uiLang}
                        candidates={boardClientCandidates}
                      />
                    </Stack>
                    <Stack gap={4}>
                      <ChromeText size="small" weight="semibold">
                        {t(uiLang, "myBoardsDueDate")}
                      </ChromeText>
                      <DateChooser
                        value={cardComposer.dueDate}
                        onChange={(v) =>
                          setCardComposer({ ...cardComposer, dueDate: v })
                        }
                        lang={uiLang}
                        allowEmpty
                        placeholder={t(uiLang, "dateChooserPick")}
                      />
                    </Stack>
                    <Stack gap={4}>
                      <ChromeText size="small" weight="semibold">
                        {t(uiLang, "myBoardsCardDesc")}
                      </ChromeText>
                      <ChromeTextArea
                        value={cardComposer.body}
                        onChange={(v) =>
                          setCardComposer({ ...cardComposer, body: v })
                        }
                        placeholder={t(uiLang, "myBoardsCardBodyPlaceholder")}
                        rows={2}
                      />
                    </Stack>
                    <Row gap={6} wrap>
                      <Button
                        variant="primary"
                        onClick={createReminderCard}
                        disabled={!cardComposer.clientName.trim()}
                      >
                        {t(uiLang, "myBoardsCreateCard")}
                      </Button>
                      <Button
                        variant="ghost"
                        onClick={() =>
                          setCardComposer(EMPTY_MY_BOARD_CARD_COMPOSER)
                        }
                      >
                        {t(uiLang, "cancel")}
                      </Button>
                    </Row>
                  </Stack>
                ) : (
                  <Button
                    variant="secondary"
                    onClick={() => openCardComposer(col.id)}
                  >
                    {t(uiLang, "myBoardsAddCard")}
                  </Button>
                )}
              </div>
            );
          })}
          <Stack
            gap={8}
            style={{
              minWidth: 220,
              flex: "0 0 220px",
              minHeight: 120,
              padding: 10,
              borderRadius: 10,
              border: `1px dashed ${chromeBorder(theme)}`,
              background: theme.bg.chrome,
              boxSizing: "border-box",
            }}
          >
            {addingColumn ? (
              <>
                <ChromeText size="small" weight="semibold">
                  {t(uiLang, "trelloEditableAddColumn")}
                </ChromeText>
                <ChromeTextInput
                  value={newColumnName}
                  onChange={setNewColumnName}
                  placeholder={t(uiLang, "trelloEditableNewColumnPlaceholder")}
                />
                <Row gap={6} wrap>
                  <Button variant="primary" onClick={createColumn}>
                    {t(uiLang, "trelloEditableCreateColumn")}
                  </Button>
                  <Button
                    variant="ghost"
                    onClick={() => {
                      setAddingColumn(false);
                      setNewColumnName("");
                    }}
                  >
                    {t(uiLang, "cancel")}
                  </Button>
                </Row>
              </>
            ) : (
              <Button
                variant="secondary"
                onClick={() => {
                  setAddingColumn(true);
                  setNewColumnName("");
                  setComposerOpen(false);
                  setCardComposer(EMPTY_MY_BOARD_CARD_COMPOSER);
                  setRenamingColumnId("");
                }}
              >
                {t(uiLang, "trelloEditableAddColumn")}
              </Button>
            )}
          </Stack>
        </div>
      ) : null}

      {selectedCard && activeBoard ? (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={
            selectedCard.title.trim() || t(uiLang, "myBoardsCardUntitled")
          }
          style={{
            /**
             * Dialog stays inside main only. No dark backdrop — a main-only dim
             * next to an undimmed AppSecondarySidebar reads as “secondary is a popup”.
             * Transparent scrim still catches outside clicks to dismiss.
             */
            position: "absolute",
            inset: 0,
            zIndex: 85,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: "transparent",
            padding: 16,
            boxSizing: "border-box",
          }}
          onClick={closeCardDetail}
        >
          <div
            onClick={(e) => {
              e.stopPropagation();
            }}
            style={{
              width: "min(780px, 100%)",
              maxHeight: "min(90%, 780px)",
              overflowY: "auto",
              borderRadius: 10,
              border: `1px solid ${theme.stroke.primary}`,
              background: CHROME_WHITE,
              padding: 16,
              boxSizing: "border-box",
            }}
          >
            <Stack gap={12}>
              <Row align="center" gap={8} wrap>
                <div style={{ flex: 1, minWidth: 160 }}>
                  <Select
                    value={selectedCard.columnId}
                    options={columnSelectOptions}
                    onChange={(v) =>
                      moveCard(
                        activeBoard.id,
                        selectedCard.id,
                        v as MyBoardColumnId,
                      )
                    }
                  />
                </div>
                <Button
                  variant={selectedCard.watching ? "primary" : "secondary"}
                  onClick={() =>
                    patchCard(selectedCard.id, {
                      watching: !selectedCard.watching,
                    })
                  }
                >
                  {selectedCard.watching
                    ? t(uiLang, "myBoardsUnwatch")
                    : t(uiLang, "myBoardsWatch")}
                </Button>
                <Button
                  variant="ghost"
                  onClick={() => setCardMoreOpen((o) => !o)}
                >
                  {t(uiLang, "myBoardsMoreActions")}
                </Button>
                <IconButton
                  title={t(uiLang, "myBoardsCloseDetail")}
                  variant="circle"
                  size="sm"
                  onClick={closeCardDetail}
                >
                  <span aria-hidden style={{ fontSize: 14, lineHeight: 1 }}>
                    ×
                  </span>
                </IconButton>
              </Row>

              {cardMoreOpen ? (
                <Row gap={6} wrap>
                  <Button
                    variant="secondary"
                    onClick={() => {
                      copyCard(selectedCard.id);
                      setCardMoreOpen(false);
                    }}
                  >
                    {t(uiLang, "myBoardsCopyCard")}
                  </Button>
                  <Button
                    variant="secondary"
                    onClick={() => {
                      archiveCard(selectedCard.id);
                      setCardMoreOpen(false);
                    }}
                  >
                    {t(uiLang, "myBoardsArchiveCard")}
                  </Button>
                  <Button
                    variant="ghost"
                    onClick={() => {
                      deleteMyBoardCard(selectedCard.id);
                      setCardMoreOpen(false);
                    }}
                  >
                    {t(uiLang, "myBoardsDeleteCard")}
                  </Button>
                </Row>
              ) : null}

              <Row align="center" gap={8} wrap>
                <H2 style={{ margin: 0, flex: 1 }}>
                  {selectedCard.title.trim() ||
                    t(uiLang, "myBoardsCardUntitled")}
                </H2>
                <Button
                  variant="secondary"
                  onClick={() => {
                    const ids = selectedCard.memberIds ?? [];
                    patchCard(selectedCard.id, {
                      memberIds: isMemberOfSelected
                        ? ids.filter((id) => id !== signedInWorkerId)
                        : [...ids, signedInWorkerId],
                    });
                  }}
                >
                  {isMemberOfSelected
                    ? t(uiLang, "myBoardsLeaveCard")
                    : t(uiLang, "myBoardsJoinCard")}
                </Button>
              </Row>

              <Row gap={6} wrap>
                <Pill active={false}>{t(uiLang, "myBoardsLabels")}</Pill>
                <Pill active={false}>{t(uiLang, "myBoardsChecklist")}</Pill>
                <Pill active={false}>{t(uiLang, "myBoardsMembers")}</Pill>
                <Pill active={false}>{t(uiLang, "myBoardsAttachments")}</Pill>
                <Pill active={false}>{t(uiLang, "myBoardsDates")}</Pill>
              </Row>

              <Stack gap={4}>
                <ChromeText size="small" weight="semibold">
                  {t(uiLang, "myBoardsCardTitle")}
                </ChromeText>
                <ChromeTextInput
                  value={selectedCard.title}
                  onChange={(v) => patchCard(selectedCard.id, { title: v })}
                />
              </Stack>

              <Stack gap={4}>
                <ChromeText size="small" weight="semibold">
                  {t(uiLang, "myBoardsCardClient")}
                </ChromeText>
                <SearchAutocomplete
                  value={selectedCard.clientName}
                  onChange={(v) =>
                    patchCard(selectedCard.id, { clientName: v })
                  }
                  placeholder={t(uiLang, "myBoardsCardClientPlaceholder")}
                  lang={uiLang}
                  candidates={boardClientCandidates}
                />
              </Stack>

              <Stack gap={6}>
                <ChromeText size="small" weight="semibold">
                  {t(uiLang, "myBoardsDates")}
                </ChromeText>
                <Row gap={8} align="center" wrap>
                  <Stack gap={4} style={{ flex: 1, minWidth: 140 }}>
                    <ChromeText size="small">{t(uiLang, "myBoardsStartDate")}</ChromeText>
                    <DateChooser
                      value={selectedCard.startDate ?? ""}
                      onChange={(v) =>
                        patchCard(selectedCard.id, {
                          startDate: v.trim() || undefined,
                        })
                      }
                      lang={uiLang}
                      allowEmpty
                      placeholder={t(uiLang, "dateChooserPick")}
                    />
                  </Stack>
                  <Stack gap={4} style={{ flex: 1, minWidth: 140 }}>
                    <ChromeText size="small">{t(uiLang, "myBoardsDueDate")}</ChromeText>
                    <DateChooser
                      value={selectedCard.dueDate ?? ""}
                      onChange={(v) => {
                        const trimmed = v.trim();
                        patchCard(selectedCard.id, {
                          dueDate: trimmed || undefined,
                        });
                      }}
                      lang={uiLang}
                      allowEmpty
                      placeholder={t(uiLang, "dateChooserPick")}
                    />
                  </Stack>
                </Row>
                <Row gap={8} wrap>
                  <Stack gap={4} style={{ flex: 1, minWidth: 120 }}>
                    <ChromeText size="small">{t(uiLang, "myBoardsDueTime")}</ChromeText>
                    <ChromeTextInput
                      value={selectedCard.dueTime ?? ""}
                      onChange={(v) =>
                        patchCard(selectedCard.id, {
                          dueTime: v.trim() || undefined,
                        })
                      }
                      placeholder="5:19 AM"
                    />
                  </Stack>
                  <Stack gap={4} style={{ flex: 1, minWidth: 120 }}>
                    <ChromeText size="small">{t(uiLang, "myBoardsRecurring")}</ChromeText>
                    <Select
                      value={selectedCard.recurring ?? "never"}
                      options={TRELLO_RECURRING_OPTIONS(uiLang)}
                      onChange={(v) =>
                        patchCard(selectedCard.id, {
                          recurring: normalizeTrelloRecurring(v),
                        })
                      }
                    />
                  </Stack>
                </Row>
                <Stack gap={4}>
                  <ChromeText size="small">{t(uiLang, "myBoardsDueReminder")}</ChromeText>
                  <Select
                    value={selectedCard.dueReminder ?? "none"}
                    options={TRELLO_REMINDER_OPTIONS(uiLang)}
                    onChange={(v) =>
                      patchCard(selectedCard.id, {
                        dueReminder: normalizeTrelloDueReminder(v),
                      })
                    }
                  />
                  <ChromeText size="small" tone="secondary">
                    {t(uiLang, "myBoardsReminderHint")}
                  </ChromeText>
                </Stack>
                <Row gap={6} wrap>
                  <MyBoardDueBlob due={selectedDue} />
                  <TrelloDueDateBadge
                    dueDate={selectedCard.dueDate}
                    dueTime={selectedCard.dueTime}
                    complete={selectedCard.columnId === "done"}
                  />
                  <Button
                    variant="ghost"
                    onClick={() =>
                      patchCard(selectedCard.id, {
                        dueDate: undefined,
                        startDate: undefined,
                        dueTime: undefined,
                        recurring: "never",
                        dueReminder: "none",
                      })
                    }
                  >
                    {t(uiLang, "myBoardsRemoveDates")}
                  </Button>
                </Row>
              </Stack>

              <Stack gap={4}>
                <ChromeText size="small" weight="semibold">
                  {t(uiLang, "myBoardsCover")}
                </ChromeText>
                <Select
                  value={selectedCard.coverColor ?? "default"}
                  options={TRELLO_BG_OPTIONS(uiLang)}
                  onChange={(v) => {
                    const next = normalizeTrelloBoardBg(v);
                    patchCard(selectedCard.id, {
                      coverColor: next === "default" ? undefined : next,
                    });
                  }}
                />
              </Stack>

              <Stack gap={6}>
                <ChromeText size="small" weight="semibold">
                  {t(uiLang, "myBoardsLabels")}
                </ChromeText>
                <Row gap={4} wrap>
                  {(selectedCard.labels ?? []).map((label) => (
                    <Button
                      key={label}
                      variant="secondary"
                      onClick={() =>
                        patchCard(selectedCard.id, {
                          labels: (selectedCard.labels ?? []).filter(
                            (x) => x !== label,
                          ),
                        })
                      }
                    >
                      {label} ×
                    </Button>
                  ))}
                </Row>
                <Row gap={6} wrap>
                  <div style={{ flex: 1, minWidth: 140 }}>
                    <ChromeTextInput
                      value={labelDraft}
                      onChange={setLabelDraft}
                      placeholder={t(uiLang, "myBoardsAddLabel")}
                    />
                  </div>
                  <Button
                    variant="secondary"
                    onClick={() => {
                      const label = labelDraft.trim();
                      if (!label) return;
                      const cur = selectedCard.labels ?? [];
                      if (cur.includes(label)) {
                        setLabelDraft("");
                        return;
                      }
                      patchCard(selectedCard.id, {
                        labels: [...cur, label],
                      });
                      setLabelDraft("");
                    }}
                    disabled={!labelDraft.trim()}
                  >
                    {t(uiLang, "add")}
                  </Button>
                </Row>
              </Stack>

              <Stack gap={6}>
                <ChromeText size="small" weight="semibold">
                  {t(uiLang, "myBoardsMembers")}
                </ChromeText>
                <Stack gap={4}>
                  {workerOptions.map((w) => (
                    <Checkbox
                      key={w.value}
                      checked={(selectedCard.memberIds ?? []).includes(
                        w.value,
                      )}
                      onChange={() => {
                        const cur = selectedCard.memberIds ?? [];
                        const next = cur.includes(w.value)
                          ? cur.filter((id) => id !== w.value)
                          : [...cur, w.value];
                        patchCard(selectedCard.id, { memberIds: next });
                      }}
                      label={w.label}
                    />
                  ))}
                </Stack>
              </Stack>

              {/* Trello-style: Description + checklist | Comments */}
              <div
                style={{
                  display: "flex",
                  flexDirection: "row",
                  flexWrap: "wrap",
                  gap: 16,
                  alignItems: "flex-start",
                  width: "100%",
                  boxSizing: "border-box",
                }}
              >
                <Stack gap={12} style={{ flex: "1 1 280px", minWidth: 0 }}>
                  <Stack gap={4}>
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsCardDesc")}
                    </ChromeText>
                    <ChromeTextArea
                      value={selectedCard.commentSnippet}
                      onChange={(v) =>
                        patchCard(selectedCard.id, { commentSnippet: v })
                      }
                      rows={4}
                    />
                  </Stack>

                  <Stack gap={6}>
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsChecklist")}
                    </ChromeText>
                    {(selectedCard.checklist ?? []).map((item) => (
                      <Checkbox
                        key={item.id}
                        checked={item.done}
                        onChange={(done) =>
                          patchCard(selectedCard.id, {
                            checklist: (selectedCard.checklist ?? []).map(
                              (row) =>
                                row.id === item.id ? { ...row, done } : row,
                            ),
                          })
                        }
                        label={item.text}
                      />
                    ))}
                    <Row gap={6} wrap>
                      <div style={{ flex: 1, minWidth: 140 }}>
                        <ChromeTextInput
                          value={checklistDraft}
                          onChange={setChecklistDraft}
                          placeholder={t(uiLang, "myBoardsAddChecklistItem")}
                        />
                      </div>
                      <Button
                        variant="secondary"
                        onClick={() => {
                          const text = checklistDraft.trim();
                          if (!text) return;
                          patchCard(selectedCard.id, {
                            checklist: [
                              ...(selectedCard.checklist ?? []),
                              {
                                id: `chk-${Date.now().toString(36)}`,
                                text,
                                done: false,
                              },
                            ],
                          });
                          setChecklistDraft("");
                        }}
                        disabled={!checklistDraft.trim()}
                      >
                        {t(uiLang, "add")}
                      </Button>
                    </Row>
                  </Stack>

                  <Stack gap={6}>
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsAttachments")}
                    </ChromeText>
                    {(selectedCard.attachments ?? []).map((a) => (
                      <Row key={a.id} gap={6} align="center">
                        <ChromeText size="small" style={{ flex: 1 }}>
                          {a.name}
                        </ChromeText>
                        <Button
                          variant="ghost"
                          onClick={() =>
                            patchCard(selectedCard.id, {
                              attachments: (
                                selectedCard.attachments ?? []
                              ).filter((x) => x.id !== a.id),
                            })
                          }
                        >
                          ×
                        </Button>
                      </Row>
                    ))}
                    <Row gap={6} wrap>
                      <div style={{ flex: 1, minWidth: 140 }}>
                        <ChromeTextInput
                          value={attachmentDraft}
                          onChange={setAttachmentDraft}
                          placeholder={t(uiLang, "myBoardsAddAttachment")}
                        />
                      </div>
                      <Button
                        variant="secondary"
                        onClick={() => {
                          const name = attachmentDraft.trim();
                          if (!name) return;
                          patchCard(selectedCard.id, {
                            attachments: [
                              ...(selectedCard.attachments ?? []),
                              {
                                id: `att-${Date.now().toString(36)}`,
                                name,
                              },
                            ],
                          });
                          setAttachmentDraft("");
                        }}
                        disabled={!attachmentDraft.trim()}
                      >
                        {t(uiLang, "add")}
                      </Button>
                    </Row>
                  </Stack>
                </Stack>

                <Stack gap={8} style={{ flex: "1 1 280px", minWidth: 0 }}>
                  <ChromeText weight="semibold">
                    {t(uiLang, "myBoardsCommentsActivity")}
                  </ChromeText>
                  {(selectedCard.comments ?? []).map((c) => (
                    <Stack
                      key={c.id}
                      gap={4}
                      style={{
                        padding: "8px 10px",
                        borderRadius: 8,
                        border: `1px solid ${chromeBorder(theme)}`,
                        background: CHROME_WHITE,
                      }}
                    >
                      <Row gap={8} align="center">
                        <ChromeText size="small" weight="semibold">
                          {c.author}
                        </ChromeText>
                        <ChromeText size="small" tone="tertiary">
                          {c.at}
                        </ChromeText>
                      </Row>
                      {editingCommentId === c.id ? (
                        <Stack gap={6}>
                          <ChromeTextArea
                            value={editingCommentBody}
                            onChange={setEditingCommentBody}
                            rows={2}
                          />
                          <Row gap={6} wrap>
                            <Button
                              variant="primary"
                              onClick={() => {
                                const body = editingCommentBody.trim();
                                if (!body) return;
                                patchCard(selectedCard.id, {
                                  comments: (selectedCard.comments ?? []).map(
                                    (row) =>
                                      row.id === c.id ? { ...row, body } : row,
                                  ),
                                });
                                setEditingCommentId("");
                                setEditingCommentBody("");
                              }}
                            >
                              {t(uiLang, "myBoardsSaveDates")}
                            </Button>
                            <Button
                              variant="ghost"
                              onClick={() => {
                                setEditingCommentId("");
                                setEditingCommentBody("");
                              }}
                            >
                              {t(uiLang, "cancel")}
                            </Button>
                          </Row>
                        </Stack>
                      ) : (
                        <>
                          <ChromeText size="small">{c.body}</ChromeText>
                          <Row gap={6} wrap>
                            <Button
                              variant="ghost"
                              onClick={() => {
                                setEditingCommentId(c.id);
                                setEditingCommentBody(c.body);
                              }}
                            >
                              {t(uiLang, "myBoardsEditComment")}
                            </Button>
                            <Button
                              variant="ghost"
                              onClick={() =>
                                patchCard(selectedCard.id, {
                                  comments: (
                                    selectedCard.comments ?? []
                                  ).filter((row) => row.id !== c.id),
                                })
                              }
                            >
                              {t(uiLang, "myBoardsDeleteComment")}
                            </Button>
                          </Row>
                        </>
                      )}
                    </Stack>
                  ))}
                  <ChromeTextArea
                    value={commentDraft}
                    onChange={setCommentDraft}
                    placeholder={t(uiLang, "myBoardsCommentPlaceholder")}
                    rows={2}
                  />
                  <Row gap={8} wrap>
                    <Button
                      variant="primary"
                      onClick={addComment}
                      disabled={!commentDraft.trim()}
                    >
                      {t(uiLang, "myBoardsAddComment")}
                    </Button>
                    <Button variant="ghost" onClick={closeCardDetail}>
                      {t(uiLang, "myBoardsCloseDetail")}
                    </Button>
                  </Row>
                </Stack>
              </div>
            </Stack>
          </div>
        </div>
      ) : null}

      {archivedBoardCards.length > 0 && showBoardColumns ? (
        <Stack
          gap={8}
          style={{
            padding: 12,
            borderRadius: 10,
            border: `1px solid ${chromeBorder(theme)}`,
            background: CHROME_WHITE,
            width: "100%",
            boxSizing: "border-box",
          }}
        >
          <ChromeText weight="semibold">
            {`${t(uiLang, "myBoardsArchived")} (${archivedBoardCards.length})`}
          </ChromeText>
          {archivedBoardCards.map((card) => (
            <Row key={card.id} gap={8} align="center" wrap>
              <ChromeText size="small" style={{ flex: 1, minWidth: 120 }}>
                {card.title || card.clientName}
              </ChromeText>
              <Button
                variant="secondary"
                onClick={() => restoreCard(card.id)}
              >
                {t(uiLang, "myBoardsRestoreCard")}
              </Button>
              <Button
                variant="ghost"
                onClick={() => deleteMyBoardCard(card.id)}
              >
                {t(uiLang, "myBoardsDeleteCard")}
              </Button>
            </Row>
          ))}
        </Stack>
      ) : null}

      {settingsOpen ? (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={t(uiLang, "myBoardsSettings")}
          style={{
            /** Main-scoped dialog; no dim — avoids secondary-as-popup illusion. */
            position: "absolute",
            inset: 0,
            zIndex: 80,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: "transparent",
            padding: 16,
            boxSizing: "border-box",
          }}
          onClick={() => setSettingsOpen(false)}
        >
          <div
            onClick={(e) => {
              e.stopPropagation();
            }}
            style={{
              width: "min(460px, 100%)",
              maxHeight: "min(90vh, 640px)",
              overflowY: "auto",
              borderRadius: 10,
              border: `1px solid ${theme.stroke.primary}`,
              background: CHROME_WHITE,
              padding: 16,
              boxSizing: "border-box",
            }}
          >
            <Stack gap={14}>
              <Row align="center" gap={8}>
                <H2 style={{ margin: 0, flex: 1 }}>
                  {t(uiLang, "myBoardsSettings")}
                </H2>
                <IconButton
                  title={t(uiLang, "userSettingsClose")}
                  variant="circle"
                  size="sm"
                  onClick={() => setSettingsOpen(false)}
                >
                  <span aria-hidden style={{ fontSize: 14, lineHeight: 1 }}>
                    ×
                  </span>
                </IconButton>
              </Row>

              {activeBoard ? (
                <Stack gap={10}>
                  <ChromeText weight="semibold">
                    {t(uiLang, "myBoardsSettingsBoardSection")}
                    {activeBoard.titleEn || activeBoard.titleHe
                      ? ` · ${myBoardTitle(uiLang, activeBoard)}`
                      : ""}
                  </ChromeText>
                  <Stack gap={4}>
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsAboutBoard")}
                    </ChromeText>
                    <ChromeTextArea
                      value={activeBoard.description ?? ""}
                      onChange={(v) =>
                        patchActiveBoard({ description: v })
                      }
                      placeholder={t(uiLang, "myBoardsBoardDescPlaceholder")}
                      rows={2}
                    />
                  </Stack>
                  <Stack gap={6}>
                    <ChromeText size="small" weight="semibold">
                      {t(uiLang, "myBoardsChangeBackground")}
                    </ChromeText>
                    <TrelloBgSwatchRow
                      value={activeBoard.background ?? "default"}
                      onChange={(v) =>
                        patchActiveBoard({ background: v })
                      }
                    />
                    <Select
                      value={activeBoard.background ?? "default"}
                      options={TRELLO_BG_OPTIONS(uiLang)}
                      onChange={(v) =>
                        patchActiveBoard({
                          background: normalizeTrelloBoardBg(v),
                        })
                      }
                    />
                  </Stack>
                </Stack>
              ) : null}

              <Stack
                gap={10}
                style={{
                  paddingTop: 4,
                  borderTop: `1px solid ${chromeBorder(theme)}`,
                }}
              >
                <ChromeText weight="semibold">
                  {t(uiLang, "myBoardsSettingsNotifySection")}
                </ChromeText>
                <Row align="center" gap={10}>
                  <Toggle
                    checked={emailReminders}
                    onChange={setEmailReminders}
                  />
                  <ChromeText>{t(uiLang, "myBoardsEmailReminders")}</ChromeText>
                </Row>
                <ChromeText size="small" tone="secondary">
                  {t(uiLang, "myBoardsEmailRemindersHint")}
                </ChromeText>
                <Row align="center" gap={10}>
                  <Toggle
                    checked={uiPrefs.watchNotify}
                    onChange={(v) => patchUiPrefs({ watchNotify: v })}
                  />
                  <ChromeText>{t(uiLang, "myBoardsWatchNotify")}</ChromeText>
                </Row>
                <ChromeText size="small" tone="secondary">
                  {t(uiLang, "myBoardsWatchNotifyHint")}
                </ChromeText>
              </Stack>

              <Stack
                gap={10}
                style={{
                  paddingTop: 4,
                  borderTop: `1px solid ${chromeBorder(theme)}`,
                }}
              >
                <ChromeText weight="semibold">
                  {t(uiLang, "myBoardsSettingsCardsSection")}
                </ChromeText>
                <Row align="center" gap={10}>
                  <Toggle
                    checked={uiPrefs.showLabelColors}
                    onChange={(v) => patchUiPrefs({ showLabelColors: v })}
                  />
                  <ChromeText>{t(uiLang, "myBoardsShowLabelColors")}</ChromeText>
                </Row>
                <ChromeText size="small" tone="secondary">
                  {t(uiLang, "myBoardsShowLabelColorsHint")}
                </ChromeText>
                <Stack gap={6}>
                  <ChromeText size="small" weight="semibold">
                    {t(uiLang, "myBoardsDefaultCover")}
                  </ChromeText>
                  <TrelloBgSwatchRow
                    value={uiPrefs.defaultCover}
                    onChange={(v) => patchUiPrefs({ defaultCover: v })}
                  />
                  <ChromeText size="small" tone="secondary">
                    {t(uiLang, "myBoardsDefaultCoverHint")}
                  </ChromeText>
                </Stack>
              </Stack>

              <Row gap={8} style={{ justifyContent: "flex-end" }}>
                <Button
                  variant="primary"
                  onClick={() => setSettingsOpen(false)}
                >
                  {t(uiLang, "userSettingsClose")}
                </Button>
              </Row>
            </Stack>
          </div>
        </div>
      ) : null}
    </Stack>
  );
}

/** Built-in column ids; custom columns use `col-…` ids. */
type SecretariatColumnId = string;

type SecretariatPriority = "low" | "normal" | "high";

type SecretariatComment = {
  id: string;
  author: string;
  authorWorkerId?: string;
  at: string;
  body: string;
};

type SecretariatCard = {
  id: string;
  title: string;
  description: string;
  columnId: SecretariatColumnId;
  priority: SecretariatPriority;
  assigneeWorkerId: string;
  comments: SecretariatComment[];
  createdAt: string;
};

type SecretariatColumnDef = {
  id: SecretariatColumnId;
  titleEn: string;
  titleHe: string;
};

/** Persisted shape for `secretariatBoard.v1` (migrates from legacy card[]). */
type SecretariatBoardState = {
  columns: SecretariatColumnDef[];
  cards: SecretariatCard[];
};

const DEFAULT_SECRETARIAT_COLUMNS: SecretariatColumnDef[] = [
  {
    id: "requested",
    titleEn: "Requested",
    titleHe: "התבקש",
  },
  {
    id: "ordered",
    titleEn: "Ordered",
    titleHe: "הוזמן",
  },
  {
    id: "inProgress",
    titleEn: "In progress",
    titleHe: "בטיפול",
  },
  {
    id: "done",
    titleEn: "Done",
    titleHe: "הושלם",
  },
];

function secretariatColumnTitle(
  lang: UiLang,
  column: SecretariatColumnDef,
): string {
  if (lang === "he") return column.titleHe || column.titleEn;
  return column.titleEn || column.titleHe;
}

/** Built-in i18n fallback when a column id is known but titles are empty. */
function secretariatColumnLabel(
  lang: UiLang,
  columnId: SecretariatColumnId,
): string {
  switch (columnId) {
    case "requested":
      return t(lang, "secretariatColRequested");
    case "ordered":
      return t(lang, "secretariatColOrdered");
    case "inProgress":
      return t(lang, "secretariatColInProgress");
    case "done":
      return t(lang, "secretariatColDone");
    default:
      return columnId;
  }
}

function resolveSecretariatColumnTitle(
  lang: UiLang,
  column: SecretariatColumnDef,
): string {
  const custom = secretariatColumnTitle(lang, column).trim();
  if (custom) return custom;
  return secretariatColumnLabel(lang, column.id);
}

function secretariatPriorityLabel(
  lang: UiLang,
  priority: SecretariatPriority,
): string {
  if (priority === "low") return t(lang, "secretariatPriorityLow");
  if (priority === "high") return t(lang, "secretariatPriorityHigh");
  return t(lang, "secretariatPriorityNormal");
}

function normalizeSecretariatBoard(
  raw: SecretariatBoardState | SecretariatCard[] | null | undefined,
): SecretariatBoardState {
  if (Array.isArray(raw)) {
    return {
      columns: DEFAULT_SECRETARIAT_COLUMNS.map((c) => ({ ...c })),
      cards: raw,
    };
  }
  if (raw && typeof raw === "object" && Array.isArray(raw.cards)) {
    const columns =
      Array.isArray(raw.columns) && raw.columns.length > 0
        ? raw.columns.map((c) => ({
            id: String(c.id || `col-${Math.random().toString(36).slice(2, 8)}`),
            titleEn: String(c.titleEn ?? ""),
            titleHe: String(c.titleHe ?? c.titleEn ?? ""),
          }))
        : DEFAULT_SECRETARIAT_COLUMNS.map((c) => ({ ...c }));
    return { columns, cards: raw.cards };
  }
  return {
    columns: DEFAULT_SECRETARIAT_COLUMNS.map((c) => ({ ...c })),
    cards: [],
  };
}

function canEditSecretariatBoard(
  role: Role,
  signedInWorkerId: string,
  firmWorkers: FirmWorker[],
): boolean {
  return (
    isAdminLike(role) ||
    workerBelongsToDept(
      signedInWorkerId,
      "reportDeptSecretariat",
      firmWorkers,
    )
  );
}

