type EditableKanbanCard = {
  id: string;
  title: string;
  description: string;
  columnId: string;
  dueDate?: string;
  startDate?: string;
  dueTime?: string;
  recurring?: TrelloRecurring;
  dueReminder?: TrelloDueReminder;
  labels: string[];
  memberIds: string[];
  checklist: EditableKanbanChecklistItem[];
  comments: EditableKanbanComment[];
  attachments?: TrelloAttachment[];
  watching?: boolean;
  coverColor?: TrelloBoardBg;
  archived?: boolean;
  clientName?: string;
  invoiceNumber?: string;
  billingComms?: BillingBoardComm[];
};
type EditableKanbanState = {
  boardName: string;
  columns: EditableKanbanColumn[];
  cards: EditableKanbanCard[];
  starred?: boolean;
  description?: string;
  background?: TrelloBoardBg;
};

function emptyEditableKanbanExtras(): Pick<
  EditableKanbanCard,
  | "labels"
  | "memberIds"
  | "checklist"
  | "comments"
  | "attachments"
  | "watching"
  | "recurring"
  | "dueReminder"
> {
  return {
    labels: [],
    memberIds: [],
    checklist: [],
    comments: [],
    attachments: [],
    watching: false,
    recurring: "never",
    dueReminder: "none",
  };
}

function billingBoardCardMatchesClient(
  card: EditableKanbanCard,
  client: DemoRow,
  lang: UiLang,
): boolean {
  const linked = resolveBoardCardClient(
    card.clientName,
    card.title,
    [client],
    lang,
  );
  if (linked?.id === client.id) return true;
  const labels = [
    client.name,
    client.nameHe,
    displayClientName(client, lang),
  ]
    .map((s) => String(s ?? "").trim().toLowerCase())
    .filter(Boolean);
  const hay = `${card.clientName ?? ""} ${card.title ?? ""}`.toLowerCase();
  return labels.some((label) => hay.includes(label));
}

function sortBillingCommsNewestFirst(
  rows: BillingBoardComm[],
): BillingBoardComm[] {
  return [...rows].sort((a, b) => b.at.localeCompare(a.at));
}

function countBillingCommsForInvoice(
  comms: BillingBoardComm[],
  invoiceNumber: string,
): number {
  const needle = invoiceNumber.trim().toLowerCase();
  if (!needle) return 0;
  return comms.filter(
    (c) => (c.invoiceNumber ?? "").trim().toLowerCase() === needle,
  ).length;
}

/**
 * Resolve invoice communications for a client from the Billing firm board.
 * Same `billingComms` rows as Billing board card → Communications.
 */
function resolveClientBillingComms(
  board: EditableKanbanState,
  client: DemoRow,
  lang: UiLang,
): {
  cardId: string | null;
  comms: BillingBoardComm[];
  usedFallback: boolean;
} {
  const cards = board.cards.filter(
    (c) => !c.archived && billingBoardCardMatchesClient(c, client, lang),
  );
  if (cards.length > 0) {
    return {
      cardId: cards[0]!.id,
      comms: sortBillingCommsNewestFirst(
        cards.flatMap((c) => c.billingComms ?? []),
      ),
      usedFallback: false,
    };
  }
  const fallback = demoBillingCommsForClient(client);
  return {
    cardId: null,
    comms: sortBillingCommsNewestFirst(fallback),
    usedFallback: fallback.length > 0,
  };
}

function appendClientBillingCommToBoard(
  board: EditableKanbanState,
  client: DemoRow,
  lang: UiLang,
  next: BillingBoardComm,
  fallback: BillingBoardComm[],
): EditableKanbanState {
  const cards = board.cards.filter(
    (c) => !c.archived && billingBoardCardMatchesClient(c, client, lang),
  );
  if (cards.length > 0) {
    const targetId = cards[0]!.id;
    return {
      ...board,
      cards: board.cards.map((c) =>
        c.id === targetId
          ? {
              ...c,
              clientName: c.clientName || displayClientName(client, lang),
              billingComms: [...(c.billingComms ?? []), next],
            }
          : c,
      ),
    };
  }
  const colId = board.columns[0]?.id ?? "ecol-0";
  const seedCard: EditableKanbanCard = {
    id: `billing-client-${client.id}`,
    title: `${displayClientName(client, lang)} — invoices`,
    description: "Client invoice follow-up (from client Invoices tab).",
    columnId: colId,
    ...emptyEditableKanbanExtras(),
    clientName: displayClientName(client, lang),
    invoiceNumber: next.invoiceNumber,
    billingComms: [...fallback, next],
  };
  return { ...board, cards: [...board.cards, seedCard] };
}

function normalizeEditableKanbanCard(
  c: Partial<EditableKanbanCard> & Record<string, unknown>,
  i: number,
  fallbackColumnId: string,
): EditableKanbanCard {
  const labels = Array.isArray(c.labels)
    ? c.labels.map((x) => String(x ?? "").trim()).filter(Boolean)
    : [];
  const memberIds = Array.isArray(c.memberIds)
    ? c.memberIds.map((x) => String(x ?? "").trim()).filter(Boolean)
    : [];
  const checklist = Array.isArray(c.checklist)
    ? c.checklist
        .filter((row) => row && typeof row === "object")
        .map((row, j) => {
          const item = row as Partial<EditableKanbanChecklistItem>;
          return {
            id: String(item.id || `chk-${i}-${j}`),
            text: String(item.text ?? ""),
            done: Boolean(item.done),
          };
        })
        .filter((row) => row.text.trim())
    : [];
  const comments = Array.isArray(c.comments)
    ? c.comments
        .filter((row) => row && typeof row === "object")
        .map((row, j) => {
          const item = row as Partial<EditableKanbanComment>;
          return {
            id: String(item.id || `cmt-${i}-${j}`),
            author: String(item.author ?? ""),
            at: String(item.at ?? ""),
            body: String(item.body ?? ""),
          };
        })
        .filter((row) => row.body.trim())
    : [];
  const billingComms = Array.isArray(c.billingComms)
    ? c.billingComms
        .filter((row) => row && typeof row === "object")
        .map((row, j) => {
          const item = row as Partial<BillingBoardComm>;
          const kind: BillingBoardCommKind =
            item.kind === "call" || item.kind === "email" ? item.kind : "note";
          return {
            id: String(item.id || `bcom-${i}-${j}`),
            kind,
            at: String(item.at ?? ""),
            author: String(item.author ?? ""),
            bodyEn: String(item.bodyEn ?? ""),
            bodyHe: String(item.bodyHe ?? item.bodyEn ?? ""),
            invoiceNumber: item.invoiceNumber
              ? String(item.invoiceNumber)
              : undefined,
          };
        })
        .filter((row) => row.bodyEn.trim() || row.bodyHe.trim())
    : [];
  const dueRaw = typeof c.dueDate === "string" ? c.dueDate.trim() : "";
  const startRaw = typeof c.startDate === "string" ? c.startDate.trim() : "";
  const dueTimeRaw = typeof c.dueTime === "string" ? c.dueTime.trim() : "";
  const clientName =
    typeof c.clientName === "string" ? c.clientName.trim() : "";
  const invoiceNumber =
    typeof c.invoiceNumber === "string" ? c.invoiceNumber.trim() : "";
  const attachments = Array.isArray(c.attachments)
    ? c.attachments
        .filter((row) => row && typeof row === "object")
        .map((row, j) => {
          const item = row as Partial<TrelloAttachment>;
          return {
            id: String(item.id || `att-${i}-${j}`),
            name: String(item.name ?? "").trim(),
          };
        })
        .filter((row) => row.name)
    : [];
  const cover =
    c.coverColor && c.coverColor !== "default"
      ? normalizeTrelloBoardBg(c.coverColor)
      : undefined;
  return {
    id: String(c.id || `ecard-${i}`),
    title: String(c.title ?? ""),
    description: String(c.description ?? ""),
    columnId: String(c.columnId ?? fallbackColumnId),
    dueDate: dueRaw || undefined,
    startDate: startRaw || undefined,
    dueTime: dueTimeRaw || undefined,
    recurring: normalizeTrelloRecurring(c.recurring),
    dueReminder: normalizeTrelloDueReminder(c.dueReminder),
    labels,
    memberIds,
    checklist,
    comments,
    attachments,
    watching: Boolean(c.watching),
    coverColor: cover && cover !== "default" ? cover : undefined,
    archived: Boolean(c.archived),
    clientName: clientName || undefined,
    invoiceNumber: invoiceNumber || undefined,
    billingComms: billingComms.length > 0 ? billingComms : undefined,
  };
}

