function WorkerFilesScreen({ role }: { role: Role }) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const [files, setFiles] = useCanvasState<WorkerFileRow[]>(
    "workerFiles.v1",
    DEFAULT_WORKER_FILES,
  );
  const [requests, setRequests] = useCanvasState<ChecklistRequest[]>(
    "workerFilesChecklist.v1",
    DEFAULT_CHECKLIST_REQUESTS,
  );
  const [uploadBucket, setUploadBucket] = useCanvasState<WorkerFileBucket>(
    "workerFilesUploadBucket",
    "general",
  );
  const [uploadNotice, setUploadNotice] = useCanvasState(
    "workerFilesUploadNotice",
    "",
  );
  const isAdmin = isAdminLike(role);

  const generalFiles = files.filter((f) => f.bucket === "general");
  const years: WorkerFileBucket[] = ["2026", "2025", "2024"];

  const fileLabel = (f: WorkerFileRow) =>
    uiLang === "he" ? f.nameHe || f.name : f.name;
  const kindLabel = (f: WorkerFileRow) =>
    uiLang === "he" ? f.kindHe || f.kind : f.kind;

  const demoUpload = () => {
    const stamp = Date.now();
    const row: WorkerFileRow = {
      id: `wf-up-${stamp}`,
      name:
        uploadBucket === "general"
          ? `Uploaded doc ${stamp}.pdf`
          : `Uploaded ${uploadBucket} file.pdf`,
      nameHe:
        uploadBucket === "general"
          ? `מסמך שהועלה ${stamp}.pdf`
          : `קובץ שהועלה ${uploadBucket}.pdf`,
      kind: "Upload",
      kindHe: "העלאה",
      added: "2026-09-15",
      bucket: uploadBucket,
    };
    setFiles((prev) => [row, ...prev]);
    setUploadNotice(t(uiLang, "workerFilesDemoAdded"));
  };

  const requestChecklist = () => {
    setRequests((prev) => [
      {
        id: `cr-${Date.now()}`,
        note:
          uiLang === "he"
            ? "בקשת רשימת מסמכים מהמנהל"
            : "Please send document checklist",
        status: "pending",
        requestedAt: "2026-09-15",
      },
      ...prev,
    ]);
  };

  const markDone = (id: string) => {
    setRequests((prev) =>
      prev.map((r) => (r.id === id ? { ...r, status: "done" } : r)),
    );
  };

  const renderFileTable = (rows: WorkerFileRow[]) => (
    <FirmDataTable
      headers={[
        t(uiLang, "workerFilesColName"),
        t(uiLang, "workerFilesColKind"),
        t(uiLang, "workerFilesColDate"),
      ]}
      rows={rows.map((f) => [fileLabel(f), kindLabel(f), f.added])}
      emptyMessage={t(uiLang, "workerFilesEmptyYear")}
      stickyHeader={false}
    />
  );

  return (
    <Stack gap={18}>
      <Row align="center" gap={12} wrap>
        <Spacer />
        <Pill tone="info">{DEMO_WORKER.name}</Pill>
        {isAdmin ? <Pill active>{roleLabel(uiLang, role)}</Pill> : null}
      </Row>

      <Stack gap={4}>
        <H1>{t(uiLang, "workerFilesTitle")}</H1>
        <ChromeText tone="secondary">{t(uiLang, "workerFilesHint")}</ChromeText>
      </Stack>

      <Stack
        gap={10}
        style={{
          padding: 14,
          borderRadius: 10,
          border: `1px solid ${chromeBorder(theme)}`,
          background: CHROME_WHITE,
        }}
      >
        <Row align="center" gap={8} wrap>
          <ChromeText weight="semibold">{t(uiLang, "workerFilesUpload")}</ChromeText>
          <Spacer />
          <Select
            value={uploadBucket}
            onChange={(v) => setUploadBucket(v as WorkerFileBucket)}
            options={[
              { value: "general", label: t(uiLang, "workerFilesGeneral") },
              { value: "2026", label: "2026" },
              { value: "2025", label: "2025" },
              { value: "2024", label: "2024" },
            ]}
          />
          <Button variant="primary" onClick={demoUpload}>
            {t(uiLang, "upload")}
          </Button>
        </Row>
        {uploadNotice ? (
          <ChromeText size="small" tone="secondary">
            {uploadNotice}
          </ChromeText>
        ) : (
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "workerFilesUploadTo")}:{" "}
            {uploadBucket === "general"
              ? t(uiLang, "workerFilesGeneral")
              : uploadBucket}
          </ChromeText>
        )}
      </Stack>

      <Stack gap={8}>
        <H2>{t(uiLang, "workerFilesGeneral")}</H2>
        <ChromeText size="small" tone="secondary">
          {t(uiLang, "workerFilesGeneralHint")}
        </ChromeText>
        {renderFileTable(generalFiles)}
      </Stack>

      <Stack gap={8}>
        <H2>{t(uiLang, "workerFilesByYear")}</H2>
        {years.map((year) => {
          const yearFiles = files.filter((f) => f.bucket === year);
          return (
            <CollapsibleSection
              key={year}
              title={year}
              count={yearFiles.length}
              defaultOpen={year === "2026"}
            >
              {renderFileTable(yearFiles)}
            </CollapsibleSection>
          );
        })}
      </Stack>

      <Stack gap={10}>
        <H2>{t(uiLang, "workerFilesRequests")}</H2>
        <ChromeText tone="secondary">{t(uiLang, "workerFilesRequestHint")}</ChromeText>
        {!isAdmin ? (
          <Stack gap={8}>
            <Button variant="secondary" onClick={requestChecklist}>
              {t(uiLang, "workerFilesRequestChecklist")}
            </Button>
            <Callout tone="info" title={t(uiLang, "workerFilesTitle")}>
              {t(uiLang, "workerFilesAdminWillSend")}
            </Callout>
          </Stack>
        ) : null}
        <FirmDataTable
          headers={[
            t(uiLang, "leaveNote"),
            t(uiLang, "workerFilesColDate"),
            t(uiLang, "status"),
            "",
          ]}
          rows={requests.map((r) => [
            r.note,
            r.requestedAt,
            r.status === "done"
              ? t(uiLang, "workerFilesChecklistDone")
              : t(uiLang, "workerFilesChecklistPending"),
            isAdmin && r.status === "pending" ? (
              <Button variant="secondary" onClick={() => markDone(r.id)}>
                {t(uiLang, "workerFilesMarkDone")}
              </Button>
            ) : (
              "—"
            ),
          ])}
          stickyHeader={false}
        />
      </Stack>
    </Stack>
  );
}

/** CRM-wide signature packets (Tools primary tab). */
type SignDocModule = "audit" | "bookkeeping" | "tax-return" | "general";
type SignDocStatus = "waiting" | "sent" | "signed";
type SignDocChannel = "portal" | "email" | "whatsapp";

type SignDocBox = {
  xPct: number;
  yPct: number;
  wPct: number;
  hPct: number;
};

type SignDocPacket = {
  id: string;
  title: string;
  clientId: string;
  clientName: string;
  module: SignDocModule;
  status: SignDocStatus;
  fileName: string;
  box: SignDocBox;
  channel?: SignDocChannel;
  /** Email used when sending / for email channel. */
  recipientEmail?: string;
  /** Signed return not yet opened in Tools → Signed (rail blop). */
  unreadReturn?: boolean;
  createdAt: string;
  sentAt?: string;
  signedAt?: string;
};

