function aiChatBundleForWorker(
  store: AiChatByWorker | null | undefined,
  workerId: string,
): AiChatWorkerBundle {
  const row = store?.[workerId];
  const developments = Array.isArray(row?.developments)
    ? row!.developments
        .map((d) => normalizeAiDevEntry(d))
        .filter((d): d is AiDevEntry => d != null)
    : [];
  return {
    messages: Array.isArray(row?.messages) ? row!.messages : [],
    developments,
  };
}

/** Tools → AI chat — Chat tab + private My development file tab per worker. */
function AiChatToolsPanel({ uiLang }: { uiLang: UiLang }) {
  const theme = useHostTheme();
  const accent = theme.accent.primary;
  const [signedInWorkerId] = useCanvasState(
    "signedInWorkerId.v1",
    DEMO_WORKER.id,
  );
  const [firmWorkers] = useCanvasState<FirmWorker[]>(
    "firmWorkers.v3",
    DEMO_STAFF,
  );
  const [byWorker, setByWorker] = useCanvasState<AiChatByWorker>(
    "toolsAiChatByWorker.v2",
    DEFAULT_AI_CHAT_BY_WORKER,
  );
  const [draft, setDraft] = useCanvasState("toolsAiChatDraft.v1", "");
  const [aiTab, setAiTab] = useCanvasState<AiChatPanelTabId>(
    "toolsAiChatPanelTab.v1",
    "chat",
  );
  const workerId = signedInWorkerId || DEMO_WORKER.id;
  const bundle = aiChatBundleForWorker(byWorker, workerId);
  const workerName = staffDisplayName(uiLang, workerId, firmWorkers);
  const activeTab: AiChatPanelTabId =
    aiTab === "dev-file" ? "dev-file" : "chat";

  const patchWorker = (partial: Partial<AiChatWorkerBundle>) => {
    setByWorker((prev) => {
      const cur = aiChatBundleForWorker(prev, workerId);
      return {
        ...(prev ?? {}),
        [workerId]: {
          messages: partial.messages ?? cur.messages,
          developments: partial.developments ?? cur.developments,
        },
      };
    });
  };

  const sendChat = () => {
    const msg = draft.trim();
    if (!msg) return;
    const now = Date.now();
    const detected = detectAiDownloadRequest(msg);
    let reply = t(uiLang, "toolsAiChatStubReply");
    let nextDevelopments = bundle.developments;
    if (detected) {
      const stamp = new Date(now).toISOString().slice(0, 10);
      const base = detected.fileName.replace(/(\.[^.]+)$/, `-${stamp}$1`);
      const fileName =
        base === detected.fileName ? `${stamp}-${detected.fileName}` : base;
      const entry: AiDevEntry = {
        id: `d-${workerId}-${now}`,
        fileName,
        kind: detected.kind,
        mime: detected.mime,
        content: demoAiArtifactContent(fileName, detected.kind, msg),
        note: msg.slice(0, 160),
        sourcePrompt: msg,
        at: now + 1,
      };
      nextDevelopments = [entry, ...bundle.developments];
      reply = t(uiLang, "toolsAiChatStubReplyWithFile").replace(
        "{fileName}",
        fileName,
      );
    }
    patchWorker({
      messages: [
        ...bundle.messages,
        { id: `u-${workerId}-${now}`, role: "user", text: msg, at: now },
        {
          id: `a-${workerId}-${now}`,
          role: "assistant",
          text: reply,
          at: now + 1,
        },
      ],
      developments: nextDevelopments,
    });
    setDraft("");
  };

  const fmtWhen = (at: number) => {
    try {
      return new Date(at).toLocaleString(uiLang === "he" ? "he-IL" : "en-GB", {
        dateStyle: "medium",
        timeStyle: "short",
      });
    } catch {
      return String(at);
    }
  };

  const downloadEntry = (entry: AiDevEntry) => {
    downloadBlobFile(entry.fileName, entry.content, entry.mime);
  };

  return (
    <Stack gap={12}>
      <div
        style={{
          padding: 12,
          paddingBottom: 28,
          borderRadius: 10,
          border: `1px solid ${chromeBorder(theme)}`,
          background: CHROME_WHITE,
          overflowY: "auto",
          maxHeight: "calc(100vh - 220px)",
          minHeight: 0,
        }}
      >
        <Stack gap={14}>
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "toolsAiChatDemoNote")}
          </ChromeText>
          <ChromeText size="small" weight="semibold" style={{ color: accent }}>
            {workerName}
          </ChromeText>
          <RaisedTabBar
            ariaLabel={t(uiLang, "toolsToolAiChat")}
            activeId={activeTab}
            onSelect={(id) => {
              setAiTab(id === "dev-file" ? "dev-file" : "chat");
            }}
            variant="raised"
            compact
            tabs={[
              {
                id: "chat",
                label: t(uiLang, "toolsAiChatTabChat"),
              },
              {
                id: "dev-file",
                label: t(uiLang, "toolsAiChatDevFileTitle"),
                badgeCount:
                  bundle.developments.length > 0
                    ? bundle.developments.length
                    : undefined,
              },
            ]}
          />
          {activeTab === "chat" ? (
            <Stack gap={12}>
              <Stack
                gap={8}
                style={{
                  padding: 12,
                  borderRadius: 10,
                  border: `1px solid ${chromeBorder(theme)}`,
                  background: chromeSoftFill(theme),
                  minHeight: 140,
                  maxHeight: 320,
                  overflowY: "auto",
                }}
              >
                {bundle.messages.length === 0 ? (
                  <ChromeText size="small" tone="secondary">
                    {t(uiLang, "toolsAiChatEmpty")}
                  </ChromeText>
                ) : (
                  bundle.messages.map((m) => (
                    <Stack
                      key={m.id}
                      gap={2}
                      style={{
                        alignSelf:
                          m.role === "user" ? "flex-end" : "flex-start",
                        maxWidth: "92%",
                        padding: "8px 10px",
                        borderRadius: 8,
                        border: `1px solid ${chromeBorder(theme)}`,
                        background:
                          m.role === "user"
                            ? CHROME_SELECTED_BLUE
                            : CHROME_WHITE,
                      }}
                    >
                      <ChromeText size="small" weight="semibold">
                        {m.role === "user"
                          ? t(uiLang, "toolsAiChatYou")
                          : t(uiLang, "toolsAiChatAssistant")}
                      </ChromeText>
                      <ChromeText size="small">{m.text}</ChromeText>
                      <ChromeText size="small" tone="tertiary">
                        {fmtWhen(m.at)}
                      </ChromeText>
                    </Stack>
                  ))
                )}
              </Stack>
              <ChromeTextArea
                value={draft}
                onChange={setDraft}
                placeholder={t(uiLang, "toolsAiChatPlaceholder")}
                rows={3}
              />
              <Row gap={8} wrap>
                <Button variant="primary" onClick={sendChat}>
                  {t(uiLang, "toolsAiChatSend")}
                </Button>
              </Row>
            </Stack>
          ) : (
            <Stack gap={10}>
              <ChromeText size="small" tone="secondary">
                {t(uiLang, "toolsAiChatDevFileHint")}
              </ChromeText>
              {bundle.developments.length === 0 ? (
                <ChromeText size="small" tone="secondary">
                  {t(uiLang, "toolsAiChatDevEmpty")}
                </ChromeText>
              ) : (
                <Stack gap={8}>
                  {bundle.developments.map((d) => (
                    <Stack
                      key={d.id}
                      gap={6}
                      style={{
                        padding: 10,
                        borderRadius: 8,
                        border: `1px solid ${chromeBorder(theme)}`,
                        background: chromeSoftFill(theme),
                      }}
                    >
                      <Row gap={10} wrap style={{ alignItems: "center" }}>
                        <ChromeText
                          size="small"
                          weight="semibold"
                          style={{ flex: "1 1 160px" }}
                        >
                          {d.fileName}
                        </ChromeText>
                        <ChromeText size="small" tone="secondary">
                          {aiDevKindLabel(uiLang, d.kind)}
                        </ChromeText>
                        <ChromeText size="small" tone="tertiary">
                          {fmtWhen(d.at)}
                        </ChromeText>
                        <Button
                          variant="secondary"
                          onClick={() => downloadEntry(d)}
                        >
                          {t(uiLang, "toolsAiChatDownload")}
                        </Button>
                      </Row>
                      {d.note ? (
                        <ChromeText size="small" tone="secondary">
                          {d.note}
                        </ChromeText>
                      ) : null}
                    </Stack>
                  ))}
                </Stack>
              )}
            </Stack>
          )}
        </Stack>
      </div>
    </Stack>
  );
}


function ToolsScreen({
  clients,
  hideSideRail = false,
  onSecondaryBack = null,
}: {
  clients: DemoRow[];
  hideSideRail?: boolean;
  onSecondaryBack?: (() => void) | null;
}) {
  const theme = useHostTheme();
  const [uiLang] = useCanvasState<UiLang>("crmUiLang", "en");
  const accent = theme.accent.primary;
  const [companySettingsRaw] = useCanvasState<CompanySettings>(
    "crmCompanySettings.v1",
    DEFAULT_COMPANY_SETTINGS,
  );
  const aiIntegrationOn = firmAiIntegrationEnabled(companySettingsRaw);
  const toolsVisible = visibleToolsModules(aiIntegrationOn);
  const [toolsModule, setToolsModule] = useCanvasState<ToolsModuleId>(
    "toolsModule.v1",
    "catalog",
  );
  const [toolsNav, setToolsNav] = useCanvasState<ToolsNavId>(
    "toolsNav.v1",
    "prepare",
  );
  useEffect(() => {
    if (toolsModule === "ai-chat" && !aiIntegrationOn) {
      setToolsModule("catalog");
    }
  }, [toolsModule, aiIntegrationOn]);
  const [packets, setPackets] = useCanvasState<SignDocPacket[]>(
    "signDocPackets.v2",
    DEFAULT_SIGN_DOC_PACKETS,
  );
  const [flash, setFlash] = useCanvasState("toolsFlash.v1", "");
  const [prepClientId, setPrepClientId] = useCanvasState(
    "toolsPrepClientId.v1",
    clients[0]?.id ?? "",
  );
  const [prepModule, setPrepModule] = useCanvasState<SignDocModule>(
    "toolsPrepModule.v1",
    "audit",
  );
  const [prepTitle, setPrepTitle] = useCanvasState(
    "toolsPrepTitle.v1",
    "",
  );
  const [prepFileName, setPrepFileName] = useCanvasState(
    "toolsPrepFile.v1",
    "",
  );
  const [prepBox, setPrepBox] = useCanvasState<SignDocBox | null>(
    "toolsPrepBox.v1",
    null,
  );
  const [prepChannel, setPrepChannel] = useCanvasState<SignDocChannel>(
    "toolsPrepChannel.v1",
    "portal",
  );
  const [prepOtherName, setPrepOtherName] = useCanvasState(
    "toolsPrepOtherName.v1",
    "",
  );
  const [prepEmail, setPrepEmail] = useCanvasState(
    "toolsPrepEmail.v1",
    "",
  );

  const isOtherRecipient = prepClientId === TOOLS_OTHER_CLIENT_ID;
  const clientOpts: ClientPickerOption[] = [
    ...clients.map((c) => clientPickerOptionFromRow(c, uiLang)),
    {
      value: TOOLS_OTHER_CLIENT_ID,
      label: t(uiLang, "toolsOtherRecipient"),
      searchText: clientSearchBlob([
        t(uiLang, "toolsOtherRecipient"),
        "other",
        "אחר",
        "manual",
        "שם",
      ]),
    },
  ];
  const selectedClient = isOtherRecipient
    ? null
    : (clients.find((c) => c.id === prepClientId) ?? null);
  const recipientDisplayName = isOtherRecipient
    ? prepOtherName.trim()
    : selectedClient
      ? displayClientName(selectedClient, uiLang)
      : "";
  const clientEmailOptions = clientEmailsForTools(selectedClient);

  useEffect(() => {
    if (isOtherRecipient) {
      setPrepEmail("");
      return;
    }
    if (clientEmailOptions.length === 0) return;
    if (!prepEmail.trim() || !clientEmailOptions.includes(prepEmail.trim())) {
      setPrepEmail(clientEmailOptions[0]!);
    }
  }, [prepClientId, isOtherRecipient]);

  useEffect(() => {
    if (toolsNav !== "signed") return;
    setPackets((prev) => {
      if (!prev.some((p) => p.status === "signed" && p.unreadReturn)) {
        return prev;
      }
      return prev.map((p) =>
        p.status === "signed" && p.unreadReturn
          ? { ...p, unreadReturn: false }
          : p,
      );
    });
  }, [toolsNav]);

  const waiting = packets.filter((p) => p.status === "waiting");
  const sent = packets.filter((p) => p.status === "sent");
  const signed = packets.filter((p) => p.status === "signed");

  const uploadDemoPdf = () => {
    const base =
      recipientDisplayName.replace(/\s+/g, "") ||
      (uiLang === "he" ? "חתימה" : "Sign");
    const name = `${base}-Sign.pdf`;
    setPrepFileName(name);
    if (!prepTitle.trim()) {
      setPrepTitle(
        uiLang === "he" ? `חבילת חתימה — ${name}` : `Signature pack — ${name}`,
      );
    }
  };

  const placeBoxAt = (xPct: number, yPct: number) => {
    setPrepBox({
      xPct: Math.max(2, Math.min(70, Math.round(xPct))),
      yPct: Math.max(8, Math.min(72, Math.round(yPct))),
      wPct: 28,
      hPct: 10,
    });
  };

  const saveToWaiting = () => {
    if (!prepFileName || !prepBox) {
      setFlash(t(uiLang, "toolsNeedPdfAndBox"));
      return;
    }
    if (isOtherRecipient && !prepOtherName.trim()) {
      setFlash(t(uiLang, "toolsNeedOtherName"));
      return;
    }
    if (!isOtherRecipient && !selectedClient) {
      setFlash(t(uiLang, "toolsNeedPdfAndBox"));
      return;
    }
    if (!prepEmail.trim()) {
      setFlash(t(uiLang, "toolsNeedEmail"));
      return;
    }
    const clientName = isOtherRecipient
      ? prepOtherName.trim()
      : selectedClient!.name;
    const clientId = isOtherRecipient
      ? `other-${Date.now()}`
      : selectedClient!.id;
    const packet: SignDocPacket = {
      id: `sd-${Date.now()}`,
      title: prepTitle.trim() || prepFileName,
      clientId,
      clientName,
      module: prepModule,
      status: "waiting",
      fileName: prepFileName,
      box: prepBox,
      recipientEmail: prepEmail.trim(),
      createdAt: new Date().toISOString().slice(0, 10),
    };
    setPackets((prev) => [packet, ...prev]);
    setPrepFileName("");
    setPrepBox(null);
    setPrepTitle("");
    if (isOtherRecipient) {
      setPrepOtherName("");
      setPrepEmail("");
    }
    setFlash(t(uiLang, "toolsSavedFlash"));
    setToolsNav("waiting");
  };

  const sendPacket = (id: string, channel: SignDocChannel) => {
    const packet = packets.find((p) => p.id === id);
    if (channel === "email" && !(packet?.recipientEmail ?? "").trim()) {
      setFlash(t(uiLang, "toolsNeedEmail"));
      return;
    }
    const today = new Date().toISOString().slice(0, 10);
    setPackets((prev) =>
      prev.map((p) =>
        p.id === id
          ? { ...p, status: "sent" as const, channel, sentAt: today }
          : p,
      ),
    );
    setFlash(
      t(uiLang, "toolsSentFlash").replace(
        "{channel}",
        signDocChannelLabel(uiLang, channel),
      ),
    );
    setToolsNav("sent");
  };

  const markSigned = (id: string) => {
    const today = new Date().toISOString().slice(0, 10);
    setPackets((prev) =>
      prev.map((p) =>
        p.id === id
          ? {
              ...p,
              status: "signed" as const,
              signedAt: today,
              unreadReturn: true,
            }
          : p,
      ),
    );
    setFlash(t(uiLang, "toolsSignedFlash"));
    /** Stay on Sent so the Tools rail blop remains until Signed is opened. */
  };

  const renderPacketCard = (p: SignDocPacket) => (
    <Stack
      key={p.id}
      gap={8}
      style={{
        padding: 12,
        borderRadius: 10,
        border: `1px solid ${chromeBorder(theme)}`,
        background: chromeSoftFill(theme),
      }}
    >
      <Row align="center" gap={8} wrap>
        <ChromeText weight="semibold" style={{ flex: 1, minWidth: 120 }}>
          {p.title}
        </ChromeText>
        <Pill size="sm" tone="neutral">
          {signDocModuleLabel(uiLang, p.module)}
        </Pill>
        {p.channel ? (
          <Pill size="sm" tone="info">
            {signDocChannelLabel(uiLang, p.channel)}
          </Pill>
        ) : null}
      </Row>
      <ChromeText size="small" tone="secondary">
        {p.clientName} · {p.fileName}
      </ChromeText>
      {p.recipientEmail ? (
        <ChromeText size="small" tone="tertiary">
          {t(uiLang, "toolsSendToEmail")}: {p.recipientEmail}
        </ChromeText>
      ) : (
        <ChromeText size="small" tone="secondary">
          {t(uiLang, "toolsNeedEmail")}
        </ChromeText>
      )}
      <ChromeText size="small" tone="tertiary">
        {p.createdAt}
        {p.sentAt ? ` · sent ${p.sentAt}` : ""}
        {p.signedAt ? ` · signed ${p.signedAt}` : ""}
        {p.unreadReturn ? ` · ${uiLang === "he" ? "חדש" : "new"}` : ""}
      </ChromeText>
      <div
        style={{
          position: "relative",
          height: 120,
          borderRadius: 8,
          background: CHROME_WHITE,
          border: `1px solid ${chromeBorder(theme)}`,
          overflow: "hidden",
        }}
      >
        <ChromeText
          size="small"
          tone="tertiary"
          style={{ position: "absolute", top: 8, insetInlineStart: 10 }}
        >
          {t(uiLang, "toolsPdfPreview")}
        </ChromeText>
        <div
          style={{
            position: "absolute",
            left: `${p.box.xPct}%`,
            top: `${p.box.yPct}%`,
            width: `${p.box.wPct}%`,
            height: `${p.box.hPct}%`,
            border: `2px dashed ${accent}`,
            background: "rgba(39, 120, 193, 0.12)",
            borderRadius: 4,
            boxSizing: "border-box",
          }}
        />
      </div>
      <Row gap={8} wrap>
        {p.status === "waiting" ? (
          <>
            <Button
              variant="primary"
              onClick={() => sendPacket(p.id, prepChannel)}
            >
              {t(uiLang, "toolsSendPacket")}
            </Button>
            <Select
              value={prepChannel}
              onChange={(v) => {
                if (v === "portal" || v === "email" || v === "whatsapp") {
                  setPrepChannel(v);
                }
              }}
              options={[
                { value: "portal", label: t(uiLang, "toolsChannelPortal") },
                { value: "email", label: t(uiLang, "toolsChannelEmail") },
                {
                  value: "whatsapp",
                  label: t(uiLang, "toolsChannelWhatsApp"),
                },
              ]}
              style={{ width: 140 }}
            />
          </>
        ) : null}
        {p.status === "sent" ? (
          <Button variant="primary" onClick={() => markSigned(p.id)}>
            {t(uiLang, "toolsMarkSigned")}
          </Button>
        ) : null}
      </Row>
    </Stack>
  );

  const renderMain = () => {
    if (toolsNav === "waiting") {
      return (
        <Stack gap={12}>
          {waiting.length === 0 ? (
            <ChromeText tone="secondary">{t(uiLang, "toolsEmptyWaiting")}</ChromeText>
          ) : (
            waiting.map(renderPacketCard)
          )}
        </Stack>
      );
    }
    if (toolsNav === "sent") {
      return (
        <Stack gap={12}>
          {sent.length === 0 ? (
            <ChromeText tone="secondary">{t(uiLang, "toolsEmptySent")}</ChromeText>
          ) : (
            sent.map(renderPacketCard)
          )}
        </Stack>
      );
    }
    if (toolsNav === "signed") {
      return (
        <Stack gap={12}>
          {signed.length === 0 ? (
            <ChromeText tone="secondary">{t(uiLang, "toolsEmptySigned")}</ChromeText>
          ) : (
            signed.map(renderPacketCard)
          )}
        </Stack>
      );
    }

    return (
      <Stack gap={14}>
        <ChromeText size="small" tone="secondary">
          {t(uiLang, "toolsHint")}
        </ChromeText>
        <Stack gap={4} style={{ width: "100%" }}>
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "toolsPickClient")}
          </ChromeText>
          <ClientSearchSelect
            value={prepClientId}
            onChange={setPrepClientId}
            options={clientOpts}
            placeholder={t(uiLang, "clientSearchPlaceholder")}
            style={{ width: "100%" }}
          />
          {isOtherRecipient ? (
            <ChromeTextInput
              value={prepOtherName}
              onChange={setPrepOtherName}
              placeholder={t(uiLang, "toolsOtherNamePh")}
            />
          ) : null}
        </Stack>
        <Stack gap={4} style={{ width: "100%" }}>
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "toolsSendToEmail")}
          </ChromeText>
          {clientEmailOptions.length > 1 ? (
            <Select
              value={
                clientEmailOptions.includes(prepEmail)
                  ? prepEmail
                  : clientEmailOptions[0]!
              }
              onChange={setPrepEmail}
              options={clientEmailOptions.map((e) => ({
                value: e,
                label: e,
              }))}
              style={{ width: "100%" }}
            />
          ) : null}
          <ChromeTextInput
            value={prepEmail}
            onChange={setPrepEmail}
            placeholder={t(uiLang, "toolsSendToEmailPh")}
          />
          <ChromeText size="small" tone="tertiary">
            {t(uiLang, "toolsSendToEmailHint")}
          </ChromeText>
        </Stack>
        <Row gap={12} wrap>
          <Stack gap={4} style={{ minWidth: 160, flex: 1 }}>
            <ChromeText size="small" tone="secondary">
              {t(uiLang, "toolsPickModule")}
            </ChromeText>
            <Select
              value={prepModule}
              onChange={(v) => {
                if (
                  v === "audit" ||
                  v === "bookkeeping" ||
                  v === "tax-return" ||
                  v === "general"
                ) {
                  setPrepModule(v);
                }
              }}
              options={[
                { value: "audit", label: t(uiLang, "toolsModuleAudit") },
                {
                  value: "bookkeeping",
                  label: t(uiLang, "toolsModuleBookkeeping"),
                },
                {
                  value: "tax-return",
                  label: t(uiLang, "toolsModuleTaxReturn"),
                },
                { value: "general", label: t(uiLang, "toolsModuleGeneral") },
              ]}
              style={{ width: "100%" }}
            />
          </Stack>
        </Row>
        <Stack gap={4}>
          <ChromeText size="small" tone="secondary">
            {t(uiLang, "toolsDocTitle")}
          </ChromeText>
          <ChromeTextInput
            value={prepTitle}
            onChange={setPrepTitle}
          />
        </Stack>
        <Row gap={8} wrap align="center">
          <Button variant="secondary" onClick={uploadDemoPdf}>
            {t(uiLang, "toolsUploadPdf")}
          </Button>
          {prepFileName ? (
            <ChromeText size="small" weight="semibold">
              {prepFileName}
            </ChromeText>
          ) : null}
        </Row>
        <Stack gap={6}>
          <ChromeText size="small" tone="secondary">
            {prepBox
              ? t(uiLang, "toolsBoxPlaced")
              : t(uiLang, "toolsPlaceBox")}
          </ChromeText>
          <div
            role="button"
            tabIndex={0}
            onClick={(e) => {
              const rect = (
                e.currentTarget as HTMLDivElement
              ).getBoundingClientRect();
              const x = ((e.clientX - rect.left) / rect.width) * 100;
              const y = ((e.clientY - rect.top) / rect.height) * 100;
              placeBoxAt(x - 14, y - 5);
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") placeBoxAt(55, 62);
            }}
            style={{
              position: "relative",
              height: 200,
              maxHeight: "32vh",
              borderRadius: 10,
              background: chromeSoftFill(theme),
              border: `1px solid ${chromeBorder(theme)}`,
              cursor: "crosshair",
              overflow: "hidden",
              flexShrink: 0,
            }}
          >
            <ChromeText
              size="small"
              tone="tertiary"
              style={{ position: "absolute", top: 12, insetInlineStart: 14 }}
            >
              {t(uiLang, "toolsPdfPreview")}
              {prepFileName ? ` · ${prepFileName}` : ""}
            </ChromeText>
            {prepBox ? (
              <div
                style={{
                  position: "absolute",
                  left: `${prepBox.xPct}%`,
                  top: `${Math.min(prepBox.yPct, 78)}%`,
                  width: `${prepBox.wPct}%`,
                  height: `${prepBox.hPct}%`,
                  border: `2px solid ${accent}`,
                  background: "rgba(39, 120, 193, 0.15)",
                  borderRadius: 4,
                  boxSizing: "border-box",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  pointerEvents: "none",
                }}
              >
                <ChromeText size="small" weight="semibold" style={{ color: accent }}>
                  Sign
                </ChromeText>
              </div>
            ) : null}
          </div>
        </Stack>
        <Row gap={8} wrap style={{ paddingBottom: 24, flexShrink: 0 }}>
          <Button variant="primary" onClick={saveToWaiting}>
            {t(uiLang, "toolsSaveWaiting")}
          </Button>
        </Row>
      </Stack>
    );
  };

  return (
    <Stack
      gap={12}
      style={{
        minHeight: 0,
        height: "100%",
        overflowY: "auto",
        paddingBottom: 32,
        boxSizing: "border-box",
      }}
    >
      <ModuleChromeBar
        pill={
          toolsModule === "catalog"
            ? t(uiLang, "tools")
            : toolsModuleLabel(uiLang, toolsModule)
        }
        onSecondaryBack={onSecondaryBack}
      />
      {toolsModule !== "catalog" ? (
        <Row align="center" gap={8} wrap>
          <Button
            variant="ghost"
            onClick={() => setToolsModule("catalog")}
          >
            {`← ${t(uiLang, "toolsBackToCatalog")}`}
          </Button>
          <ChromeText size="small" tone="secondary" style={{ flex: 1 }}>
            {toolsModuleHint(uiLang, toolsModule)}
          </ChromeText>
        </Row>
      ) : (
        <ChromeText size="small" tone="secondary">
          {t(uiLang, "toolsCatalogHint")}
        </ChromeText>
      )}
      {flash && toolsModule === "signature" ? (
        <Callout tone="success" title={t(uiLang, "toolsToolSignature")}>
          {flash}
        </Callout>
      ) : null}

      {toolsModule === "catalog" ? (
        /**
         * Same big-square grid as Clients HomeScreen (`ModuleCard` tiles):
         * Grid columns ≤4, stretch cells, centered icon + label + hint; whole tile opens.
         */
        <Grid
          columns={Math.min(Math.max(toolsVisible.length, 1), 4)}
          gap={12}
          align="stretch"
          style={{ width: "100%" }}
        >
          {toolsVisible.map((tool) => {
            const iconAccent = chromeIconAccent(tool.id, theme.category);
            const badge = toolsModuleBadgeCount(tool.id, packets);
            const badgeLabel = badge > 99 ? "99+" : String(badge);
            /** Same destination as Tools secondary sidebar tile / prior Open. */
            const openTool = () => {
              setToolsModule(tool.id);
              setToolsNav("prepare");
            };
            return (
              <div
                key={tool.id}
                style={{
                  width: "100%",
                  minWidth: 0,
                  height: "100%",
                  display: "flex",
                }}
              >
                <button
                  type="button"
                  onClick={openTool}
                  style={{
                    all: "unset",
                    cursor: "pointer",
                    display: "block",
                    boxSizing: "border-box",
                    width: "100%",
                    height: "100%",
                    background: chromeCardBg(theme),
                    border: `1px solid ${waveChipAlpha(iconAccent, "55")}`,
                    borderRadius: 12,
                    padding: "20px 16px",
                    minHeight: 112,
                    textAlign: "center",
                    color: theme.text.primary,
                  }}
                >
                  <Stack gap={8} style={{ alignItems: "center" }}>
                    <div
                      style={{
                        position: "relative",
                        width: 44,
                        height: 44,
                      }}
                    >
                      <div
                        style={{
                          width: 44,
                          height: 44,
                          borderRadius: 12,
                          background: waveChipAlpha(iconAccent, "28"),
                          border: `1px solid ${waveChipAlpha(iconAccent, "66")}`,
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          boxSizing: "border-box",
                        }}
                      >
                        <ModuleTileIcon
                          tileId={tool.id}
                          color={iconAccent}
                        />
                      </div>
                      {badge > 0 ? (
                        <div
                          style={{
                            position: "absolute",
                            top: -5,
                            right: -5,
                            minWidth: 18,
                            height: 18,
                            padding: "0 5px",
                            borderRadius: 999,
                            background: theme.category.red,
                            color: theme.text.onAccent,
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            boxSizing: "border-box",
                            border: `2px solid ${chromeCardBg(theme)}`,
                            fontSize: 10,
                            fontWeight: 700,
                            lineHeight: 1,
                          }}
                          aria-label={`${badge} new`}
                        >
                          {badgeLabel}
                        </div>
                      ) : null}
                    </div>
                    <ChromeText
                      weight="semibold"
                      style={{ textAlign: "center", color: theme.text.primary }}
                    >
                      {t(uiLang, tool.labelKey)}
                    </ChromeText>
                    <ChromeText
                      size="small"
                      style={{
                        textAlign: "center",
                        color: chromeInkMuted(theme),
                      }}
                    >
                      {t(uiLang, tool.hintKey)}
                    </ChromeText>
                  </Stack>
                </button>
              </div>
            );
          })}
        </Grid>
      ) : toolsModule === "ai-chat" ? (
        <AiChatToolsPanel uiLang={uiLang} />
      ) : toolsModule === "converter" ? (
        <ConverterToolsPanel uiLang={uiLang} />
      ) : toolsModule === "sumit-dapi" ? (
        <SumitDapiToolsPanel uiLang={uiLang} />
      ) : toolsModule === "section46" ? (
        <Section46ToolsPanel uiLang={uiLang} />
      ) : toolsModule === "masav" ? (
        <MasavToolsPanel uiLang={uiLang} />
      ) : (
        <Stack gap={12}>
          <RaisedTabBar
            ariaLabel={t(uiLang, "toolsToolSignature")}
            activeId={toolsNav}
            onSelect={(id) => {
              if (
                id === "prepare" ||
                id === "waiting" ||
                id === "sent" ||
                id === "signed"
              ) {
                setToolsNav(id);
              }
            }}
            tabs={TOOLS_NAV_IDS.map((id) => {
              const count =
                id === "waiting"
                  ? waiting.length
                  : id === "sent"
                    ? sent.length
                    : id === "signed"
                      ? signed.length
                      : 0;
              return {
                id,
                label:
                  count > 0
                    ? `${toolsNavLabel(uiLang, id)} (${count})`
                    : toolsNavLabel(uiLang, id),
              };
            })}
          />
          <div
            style={{
              padding: 12,
              paddingBottom: 28,
              borderRadius: 10,
              border: `1px solid ${chromeBorder(theme)}`,
              background: CHROME_WHITE,
              overflowY: "auto",
              maxHeight: "calc(100vh - 220px)",
              minHeight: 0,
            }}
          >
            {renderMain()}
          </div>
        </Stack>
      )}
    </Stack>
  );
}

